var documenterSearchIndex = {"docs":
[{"title":"src/helpers.jl","page":"src/helpers.jl","location":"code/src-helpers-jl.html#src/helpers.jl","category":"section","text":"View on GitHub (commit 2cfaacd).\n\n# helpers.jl (copied from applications/jtcam/plot_helpers.jl)\n# Shared plotting helpers for the JTCAM figures: the paper theme (fonts,\n# dimensions, palette, margins), the axis-tick helper `edge_ticks`, and the\n# time-series panels with their hand-drawn legends. Merged from jtcam_theme.jl\n# and time_series.jl so a section only includes one file.\nimport Plots\nusing Plots\nusing Plots.PlotMeasures\nusing PyFormattedStrings: @f_str\n\nusing KEEP: PointMass4 as PM4\nusing KEEP: PointMassPara as PMP\nusing KEEP: Visualization as VIZ\nusing KEEP.TorqueFunction: torque_function\n\nPlots.gr()\n\n# --- Font Setup ---\nfunction setup_font(font_filename=\"LinLibertine_R.ttf\")\n    otf = replace(font_filename, \".ttf\" => \".otf\")\n    dirs = [@__DIR__, expanduser(\"~/Library/Fonts\"), get(ENV, \"JTCAM_FONT_DIR\", \".\"),\n        \"/usr/share/fonts/truetype/linux-libertine\", \"/usr/share/fonts/opentype/linux-libertine\"]\n    # .ttf or .otf (Debian/Ubuntu fonts-linuxlibertine ships the .otf in opentype/)\n    paths = [joinpath(d, f) for d in dirs for f in (font_filename, otf)]\n    # the TeX Live copy of the font (the one LaTeX uses for the paper), when kpsewhich knows it\n    for name in (font_filename, otf)\n        try\n            found = readchomp(pipeline(`kpsewhich $name`; stderr=devnull))\n            isempty(found) || push!(paths, found)\n        catch\n        end\n    end\n\n    idx = findfirst(isfile, paths)\n    if idx !== nothing\n        font_id = Plots.GR.loadfont(abspath(paths[idx]))\n        if font_id >= 0\n            Plots.gr_font_family[\"linux libertine\"] = font_id\n            return \"linux libertine\"\n        end\n    end\n\n    # in CI, a silent fallback would commit figures in the wrong font\n    get(ENV, \"CI\", \"\") == \"true\" && error(\"$font_filename (or .otf) not found\")\n    @warn \"$font_filename not found. Drop it in ~/Library/Fonts/ or beside this script, or set JTCAM_FONT_DIR. Falling back to 'times'.\"\n    return \"times\"\nend\n\nconst FONT = setup_font(\"LinLibertine_R.ttf\")\n\n# --- Dimensions ---\n# LaTeX DPI is 72.27 pt/in; JTCAM textwidth is 155 mm (~441 pt), half-width is 75 mm (~213 pt)\n\n# W = \\showthe\\textwidth = \\showthe\\columnwidth = \\showthe\\hsize\n# WIDTH_FULL_INCH = W\nconst PT_PER_INCH = 72.27  # Latex constant\nconst DPI = 72  # Plots.jl constant\n\nconst WIDTH_PT = 415.41025\n\n# --- Typography ---\nconst FONTSIZE = 12\nconst LABELFONTSIZE = FONTSIZE\nconst TITLEFONTSIZE = FONTSIZE\nconst TICKFONTSIZE = 10\nconst LEGENDFONTSIZE = 10\nconst ANNOTATIONFONTSIZE = 10\n\n# --- Sizing Functions & Global Objects ---\n\"\"\"\nOne width unit is half the text width and one height unit 3/8 of it, so\n`plot_size(1, 1)` is a half-width 4/3 plot and `plot_size(1, 2)` spans the text\nwidth at the same height.\n\"\"\"\nfunction plot_size(height=1, width=1; dpi=DPI)\n    width_in = width * WIDTH_PT / 2 / PT_PER_INCH\n    height_in = height * 3 * WIDTH_PT / 8 / PT_PER_INCH\n    width_px = round(Int, width_in * dpi)\n    height_px = round(Int, height_in * dpi)\n    return (width_px, height_px)\nend\n\nconst SIZE_FULL = plot_size(1, 2)\nconst SIZE_HALF = plot_size(1, 1)\n\n# --- Palette ---\nconst PALETTE = Plots.palette(:auto)\n# Standard 8-color Okabe-Ito (Wong) palette\n# const PALETTE = okabe_ito = [\n#     colorant\"#E69F00\",  # Orange\n#     colorant\"#56B4E9\",  # Sky Blue\n#     colorant\"#009E73\",  # Bluish Green\n#     colorant\"#F0E442\",  # Yellow\n#     colorant\"#0072B2\",  # Blue\n#     colorant\"#D55E00\",  # Vermilion\n#     colorant\"#CC79A7\",  # Reddish Purple\n#     colorant\"#000000\",  # Black\n# ]\n\n# const PALETTE = Plots.palette(:Dark2_8)\n\n# JTCAM primary dark blue RGB(10, 40, 80) with harmonious accents\n# const PALETTE = [\n#     # Plots.RGB(10/255, 40/255, 80/255),  # Main accent color is too dark\n#     Plots.RGB(0/255, 140/255, 185/255),  # Opting for the brighter one\n#     Plots.RGB(0.85, 0.35, 0.15),\n#     Plots.RGB(0.15, 0.60, 0.45),\n#     Plots.RGB(0.70, 0.20, 0.50),\n#     Plots.RGB(0.40, 0.40, 0.40),\n# ]\n\n# const PALETTE = [\n#     RGB(0/255, 140/255, 185/255),  # 1. Cerulean Blue (Your anchor)\n#     RGB(235/255, 105/255, 65/255),  # 2. Coral Orange\n#     RGB(45/255, 170/255, 110/255),  # 3. Emerald Green\n#     RGB(165/255, 90/255, 195/255),  # 4. Amethyst Violet\n#     RGB(235/255, 175/255, 30/255),  # 5. Marigold Amber\n#     RGB(225/255, 70/255, 125/255),  # 6. Raspberry Rose\n#     RGB(30/255, 180/255, 175/255),  # 7. Bright Teal\n#     RGB(90/255, 110/255, 195/255),  # 8. Cornflower Indigo\n# ]\n\n\n# --- Publication Defaults ---\nfunction my_defaults()\n    Plots.default()\n    Plots.default(\n        thickness_scaling=0.5,\n        dpi=DPI,\n        fontfamily=FONT,\n        size=SIZE_HALF,\n        palette=PALETTE,\n        formatter=:plain,\n        label=\"\",\n\n        # Font sizes\n        labelfontsize=LABELFONTSIZE,\n        tickfontsize=TICKFONTSIZE,\n        legendfontsize=LEGENDFONTSIZE,\n        titlefontsize=TITLEFONTSIZE,\n        annotationfontsize=ANNOTATIONFONTSIZE,\n\n        # Line & Marker aesthetics\n        linewidth=3,\n        markersize=7,\n        markerstrokewidth=0,\n\n        # Axes & Grid layout\n        framestyle=:box,\n        grid=true,\n        gridalpha=0.1,\n        gridlinewidth=1,\n        minorgrid=false,\n        tick_direction=:none,\n\n        # Margins & Legends\n        margin=0Plots.mm, # 4Plots.mm,\n        legend=:topright,\n        legend_background_color=Plots.RGBA(1.0, 1.0, 1.0, 0.85),\n        widen=true\n    )\nend\n\n# Outputs of the paper: figures (pdf + png) in figs/, tables (tex) in tables/,\n# both next to main.tex.\n# JTCAM_OUT_DIR redirects both (smoke tests, CI dry runs) without touching the paper files.\nconst OUT_ROOT = get(ENV, \"JTCAM_OUT_DIR\", dirname(@__DIR__))\nconst FIGS_DIR = mkpath(joinpath(OUT_ROOT, \"figs\"))\nconst TABLES_DIR = mkpath(joinpath(OUT_ROOT, \"tables\"))\nconst PNG_DPI = 300\n\n\"\"\"\nSave `fig` as `figs/<name>.pdf` and `figs/<name>.png`; return the list of paths.\n\"\"\"\nfunction save_figure(fig, name::AbstractString)\n    paths = String[]\n    for ext in (\"pdf\", \"png\")\n        path = joinpath(FIGS_DIR, \"$name.$ext\")\n        if ext == \"png\"\n            plot!(fig; dpi=PNG_DPI)  # high-resolution raster, after the (vector) pdf\n            Plots.png(fig, path)\n        else\n            Plots.pdf(fig, path)\n        end\n        push!(paths, path)\n    end\n    @info \"figure written\" name\n    return paths\nend\n\n\"Write the LaTeX string `str` to `tables/<name>.tex`; return the path.\"\nfunction write_table(name::AbstractString, str::AbstractString)\n    path = joinpath(TABLES_DIR, \"$name.tex\")\n    write(path, endswith(str, \"\\n\") ? str : str * \"\\n\")\n    @info \"table written\" name\n    return path\nend\n\nmy_defaults()\n\n# --- Axes ---\n\"\"\"\nFirst and last of the default ticks of the axis `axis` (`:x`, `:y` or `:z`) of\nsubplot `sp`, plus zero when `include_zero` and zero lies strictly between them.\n\"\"\"\nfunction edge_ticks(sp, axis; include_zero=false)\n    ticks = first(Plots.get_ticks(sp, sp[Symbol(axis, :axis)]))\n    lo, hi = first(ticks), last(ticks)\n    return include_zero && lo < 0 < hi ? [lo, 0.0, hi] : [lo, hi]\nend\n\n\"Tick label without trailing zeros: `0.9` instead of `0.900`, `1` instead of `1.0`.\"\nplain_tick(x) = f\"{x:g}\"\n\n# --- Time series ---\n# One simulation, three panels (states, average power, line tension), shared by\n# the numerical-analysis and optimization sections. The legends are drawn by\n# hand, one per row, in a dedicated column so every panel keeps the same width\n# and the x axes can be linked. In a grid, the y limits of a row are shared by\n# all columns.\n\n\"\"\"\nWrapped-τ series: main polyline on the grid with a NaN sample at each 2π\ncrossing, plus the crossings as NaN-separated vertical segments (crossing\ntime twice, values π and -π) to be drawn dashed.\n\"\"\"\nfunction tau_wrap(ts, τm)\n    Δt = Base.step(ts)\n    tcross = [ts[i] + Δt * (π - τm[i]) / (τm[i+1] + 2π - τm[i])\n              for i in findall(diff(τm) .< -π)]\n    t_jump, y_jump = Float64[], Float64[]\n    for tc in tcross\n        append!(t_jump, (tc, tc, NaN))\n        append!(y_jump, (π, -π, NaN))\n    end\n    perm = sortperm(vcat(ts, tcross))\n    t_main = vcat(ts, tcross)[perm]\n    y_main = vcat(τm, fill(NaN, length(tcross)))[perm]\n    return t_main, y_main, t_jump, y_jump\nend\n\n\"\"\"\nSame as `VIZ.plot_avg_power_4D`, but plotting in kW instead of W. Returns the\npanel and the y data range, so several simulations can share one power axis.\n\"\"\"\nfunction plot_avg_power_kW(sol, ts)\n    p = sol.prob.p\n    L, M, T = PMP.lmt(p)\n    t0, tf = first(ts), last(ts)\n    dα = sol.(ts, idxs=3)\n    power = dα .* torque_function.(dα .* T, (p,)) .* (M * L^2 * T^-2) ./ 1000\n    avg_power = sol(tf, idxs=5) / (tf - t0) / 1000\n    plt = plot(ts, power; c=:black, xlabel=\"t (s)\", ylabel=\"Power (kW)\", yticks=0:10:100)\n    plot!([t0, tf], [avg_power, avg_power]; c=:red)\n    return (; plt, lo=min(0.0, minimum(power)), hi=max(maximum(power), avg_power))\nend\n\n\"\"\"\nThree panels of one simulation `sol` (a transient or a limit cycle): the states\n(α, D(α), D(τ), with τ mod 2π), the instantaneous and average power, and the\nline tension, whose y ticks are 0 and the two extrema. Returns the panels and\nthe data ranges used to share the y axes.\n\"\"\"\nfunction time_series_panels(sol; N=500)\n    ts = range(sol.t[1], sol.t[end], N)\n    q_ts = reduce(hcat, sol.(ts))'  # interpolated states on the grid\n    τm = mod.(q_ts[:, 2], 2π) .- π\n    @assert all(-π .<= τm .< π)\n    @assert all(diff(τm) .< π)  # τ is monotonically increasing through the wraps\n    one_period = abs(abs(q_ts[end, 2] - q_ts[1, 2]) - 2π) <= 1e-3\n\n    t_main, y_main, t_jump, y_jump = tau_wrap(ts, τm)\n    q_deg = rad2deg.(q_ts[:, [1, 3, 4]])\n    p_wts = plot(ts, q_deg; c=[1 3 4], ylabel=\"x (deg, deg/s)\", xlabel=\"\", xformatter=x -> \"\", yticks=-720:180:720)\n    plot!(t_main, rad2deg.(y_main); c=2)\n    one_period || plot!(t_jump, rad2deg.(y_jump); c=2, ls=:dot, label=false)\n\n    pw_stats = plot_avg_power_kW(sol, ts)\n    pw = pw_stats.plt\n    plot!(pw, xlabel=\"\", xformatter=x -> \"\")\n\n    # Line tension; the ticks are the two extrema and zero. Skip samples where\n    # the geometry degenerates (aligned arm and kite), which give a NaN tension\n    # and would poison the axis limits.\n    tension = PM4.compute_line_tension.(sol.(ts), Ref(sol.prob.p)) ./ 1000\n    ok = isfinite.(tension)\n    tmin, tmax = extrema(tension[ok])\n    tmin = min(0.0, tmin)\n    p_t = plot(ts[ok], tension[ok]; c=5, ylabel=\"Tension (kN)\", xlabel=\"t (s)\", yticks=-100:5:100, ylim=(tmin, tmax), widen=true)\n\n    y_wts = vcat(vec(q_deg), rad2deg.(filter(isfinite, y_main)),\n        one_period ? Float64[] : rad2deg.(filter(isfinite, y_jump)))\n    return (; wts=p_wts, pw, tension=p_t,\n        ylims=(states=extrema(y_wts), power=(pw_stats.lo, pw_stats.hi),\n            tension=(tmin, tmax)))\nend\n\n\"\"\"\nLegend tile: one fixed-width box per row (the same axis fraction in every row,\nso all three legends match), a handle long enough to read, and a label per\nentry. The entry spacing is set in points from `row_px`, the height of one\nlayout row in pixels, so the entries stay clear of the text at any `plot_size`\n(a fixed axis-fraction spacing overlaps at small heights). Plots' GR legend\nwould instead size the box from its labels and the handle from the subplot\nwidth, which is why the entries are drawn by hand.\n\"\"\"\nfunction time_series_legend(names, styles, row_px)\n    p = plot(; framestyle=:none, showaxis=false, grid=false,\n        xlims=(0, 1), ylims=(0, 1), xticks=[], yticks=[], margin=0Plots.mm)\n    n = length(names)\n    dy = 1.25 * LEGENDFONTSIZE / row_px\n    ys = 0.5 .+ dy .* ((n + 1) / 2 .- (1:n))\n    pad = 0.65dy\n    plot!(p, Shape([(0.02, last(ys) - pad), (0.98, last(ys) - pad),\n        (0.98, first(ys) + pad), (0.02, first(ys) + pad)]); c=:black, lw=1, fillcolor=:white)\n    for (y, style, name) in zip(ys, styles, names)\n        plot!(p, [0.08, 0.28], [y, y]; style...)\n        annotate!(p, 0.32, y, text(name; family=FONT, pointsize=LEGENDFONTSIZE, halign=:left))\n    end\n    return p\nend\n\n\"One hand-drawn legend per row: states, power, tension.\"\nfunction time_series_legends(row_px)\n    return (states=time_series_legend((\"α\", \"τ mod 360°\", \"D(α)\", \"D(τ)\"),\n        ((; c=1), (; c=2), (; c=3), (; c=4)), row_px),\n        power=time_series_legend((\"P\", \"Avg(P)\"), ((; c=:black), (; c=:red)), row_px),\n        tension=time_series_legend((\"T\",), ((; c=5),), row_px))\nend\n\n\"Time series of one simulation `sol`, one hand-drawn legend per row.\"\nfunction plot_time_series(sol; kwargs...)\n    return plot_time_series_grid((sol,); kwargs...)  # same layout, so the same legend width\nend\n\n\"\"\"\nSeveral simulations side by side: one column per solution, one row per panel\n(states, power, tension). The hand-drawn legend of each row sits in a dedicated\nlast column, so every panel keeps the same width; the x axes are linked inside\neach column. The y limits of a row are shared by all columns, and only the\nleftmost column labels the y ticks (the others keep the ticks, so the gridlines\nstay). `legend_width` is the fraction of the figure width given to the legend\ncolumn. With `titles` (one per solution) a shallow first row carries a title\nover each column; the legend column of that row stays empty.\n\"\"\"\nfunction plot_time_series_grid(sols; N=500, legend_width=0.22, titles=false)\n    n = length(sols)\n    @assert titles === false || length(titles) == n \"one title per solution\"\n    panels = [time_series_panels(sol; N) for sol in sols]\n\n    # one y range per row, common to every column\n    states_lims = (minimum(first(q.ylims.states) for q in panels),\n        maximum(last(q.ylims.states) for q in panels))\n    power_lims = (0.0, maximum(last(q.ylims.power) for q in panels))\n    tension_lims = (0.0, maximum(last(q.ylims.tension) for q in panels))\n    for q in panels\n        plot!(q.wts, ylims=states_lims, widen=true)\n        plot!(q.pw, ylims=power_lims, widen=true)\n        plot!(q.tension, ylims=tension_lims, widen=true)\n    end\n\n    for q in panels[2:end], p in (q.wts, q.pw, q.tension)\n        plot!(p, ylabel=\"\", yformatter=x -> \"\")  # ticks stay, for the gridlines\n    end\n    for (j, q) in enumerate(panels)\n        for p in (q.wts, q.pw, q.tension)\n            # the leftmost column carries the y labels, the others only ticks\n            plot!(p, leftmargin=(j == 1 ? 20 : 3)Plots.mm)\n        end\n        plot!(q.tension, bottommargin=6Plots.mm)\n    end\n\n    sz = plot_size(4 / 3, 2)\n\n    # one relative height per row: the first entry sizes the title row\n    heights = Float64[1, 1, 1]\n    titles === false || prepend!(heights, 0.01)\n    leg = time_series_legends(sz[2] / sum(heights))  # one panel row, in px\n    widths = vcat(fill((1 - legend_width) / n, n), legend_width)\n    heights ./= sum(heights)\n\n    # title row: one hidden panel per column and an empty legend cell\n    header = titles === false ? () :\n             (map(t -> plot(; title=t, framestyle=:none, showaxis=false, margin=-10Plots.mm),\n        titles)..., plot(; framestyle=:none, showaxis=false))\n\n    return plot(header...,\n        [q.wts for q in panels]..., leg.states,\n        [q.pw for q in panels]..., leg.power,\n        [q.tension for q in panels]..., leg.tension;\n        layout=grid(length(heights), n + 1; heights=heights, widths=widths),\n        link=:x, size=sz)\nend"},{"title":"KEEP functions used by the paper","page":"KEEP functions","location":"api.html#KEEP-functions-used-by-the-paper","category":"section","text":"The docstrings of the main functions of KEEP.jl called by main.jl."},{"title":"KEEP.PointMass4","page":"KEEP functions","location":"api.html#KEEP.PointMass4","category":"section","text":""},{"title":"KEEP.LimitCycle","page":"KEEP functions","location":"api.html#KEEP.LimitCycle","category":"section","text":""},{"title":"KEEP.SteadyState","page":"KEEP functions","location":"api.html#KEEP.SteadyState","category":"section","text":""},{"title":"KEEP.Optimization","page":"KEEP functions","location":"api.html#KEEP.Optimization","category":"section","text":""},{"title":"KEEP.PointMassPara","page":"KEEP functions","location":"api.html#KEEP.PointMassPara","category":"section","text":""},{"title":"KEEP.PointMass4.dynamics","page":"KEEP functions","location":"api.html#KEEP.PointMass4.dynamics","category":"function","text":"Compute du, the evolution of the state — closed-form implementation (default).\n\nSame model as _dynamics_verified, with the explicit formulas of applications/jtcam/scratch/pm2-model-derivation-reworked.tex instead of six ForwardDiff calls per evaluation: 2.33× cheaper per evaluation, 2.1× on a limit-cycle solve, identical to the verified version to 1e-15 (test/04a, run by verify_fast_rhs.jl in the benchmark).\n\nu = (α, τ, dα, dτ) du = (dα, dτ, ddα, ddτ)\n\n\n\n\n\n"},{"title":"KEEP.PointMass4._accelerations_tension","page":"KEEP functions","location":"api.html#KEEP.PointMass4._accelerations_tension","category":"function","text":"Accelerations and line tension from the kinematics k, the external force F = F_a + F_g on the kite, the generator torque and dot R. Returns (ddα, ddτ, Fℓ).\n\nThe three unknowns satisfy the projections of Newton's law for the kite on hat r and hat r (the tangent plane of the cone), and the arm balance Iddotalpha = alambda F_ell - texttorque, where alambda = ahatellcdot(hat ztimeshat a) is the lever arm of the lines. It vanishes on the fold curves alpha = varphi varphi + pi, so the arm balance is solved for ddotalpha (dividing by I  0), never for F_ell: the remaining 2times 2 system in (ddottau F_ell) has determinant -m r hat r^2 Rell - m R r_tau^2(rell) - m^2 a^2 ell r hat r^2lambda^2(I R)  0 everywhere, so the vector field and the tension are smooth on the whole state space.\n\n\n\n\n\n"},{"title":"KEEP.PointMass4.compute_line_tension","page":"KEEP functions","location":"api.html#KEEP.PointMass4.compute_line_tension","category":"function","text":"[For post-processing]\n\nGiven u and p, compute the line tension Fℓ (N), exact everywhere, including on the fold curves where the lever arm of the lines vanishes (see _accelerations_tension).\n\n\n\n\n\n"},{"title":"KEEP.PointMass4.jacobian","page":"KEEP functions","location":"api.html#KEEP.PointMass4.jacobian","category":"function","text":"Compute the jacobian of f at x.\n\n\n\n\n\n"},{"title":"KEEP.LimitCycle.compute_limit_cycle","page":"KEEP functions","location":"api.html#KEEP.LimitCycle.compute_limit_cycle","category":"function","text":"Compute a limite cycle by integrating from u0.\n\nThe shooting obtained by settling is refined by refine_shooting unless refine = false.\n\nReturn its shooting parameters [α0, dα0, dτ0, T].\n\n\n\n\n\nCompute the attracting limit cycle with sense(dτ) > 0, by integrating from the Poincaré-section state u0 = (α, τ, dα, dτ) = (0, TAU0, 0, sense(1)).\n\nBoth pumping cycles are attracting, so the sign of dτ selects one and the magnitude of the seed only needs to be a reasonable guess. Use all_limit_cycles for an inventory of every cycle in a box; the two calls are independent.\n\n\n\n\n\n"},{"title":"KEEP.LimitCycle.refine_shooting","page":"KEEP functions","location":"api.html#KEEP.LimitCycle.refine_shooting","category":"function","text":"refine_shooting(shooting, vbp; sense, tol, maxiter=8, target=tol / 100)\n\nRefine shooting = [α0, dα0, dτ0, T] by Newton's method on the closure residual endpoint_residuals(shoot(shooting)) (4 equations, 4 unknowns, Jacobian by ForwardDiff through the integrator), with a backtracking line search on the max norm of the residual. Stop below target, after maxiter iterations, or when no step decreases the residual.\n\nSettling by integration converges only linearly to the cycle, and stops on the distance between two successive crossings, not on the distance to the cycle: the shooting it gives closes up to an error that depends on the contraction rate and on floating-point details. Newton converges quadratically from it, so the refined cycle closes at the level of the integration tolerance (issue #79).\n\nReturn (shooting, residual). The refined shooting is only kept if it decreases the residual, keeps the sign of dτ0 and has T > 0; otherwise the input is returned, so that refining never makes a cycle worse.\n\n\n\n\n\n"},{"title":"KEEP.LimitCycle.all_limit_cycles","page":"KEEP functions","location":"api.html#KEEP.LimitCycle.all_limit_cycles","category":"function","text":"Comptue all limit cycles by sampling N initial conditions within a region of the Poincarré section.\n\nA rough integration with low precision (sqrt(tol))\nClusterize and take centroids\nIntegrate each centroid with high precision (tol)\n\n\n\n\n\n"},{"title":"KEEP.LimitCycle.average_power","page":"KEEP functions","location":"api.html#KEEP.LimitCycle.average_power","category":"function","text":"shooting -> average power\n\n\n\n\n\n"},{"title":"KEEP.SteadyState.all_steady_states","page":"KEEP functions","location":"api.html#KEEP.SteadyState.all_steady_states","category":"function","text":"Find all steady states using aligned_and_opposite_steady_states where α is guessed from τ\n\n\n\n\n\n"},{"title":"KEEP.Optimization.optimize","page":"KEEP functions","location":"api.html#KEEP.Optimization.optimize","category":"function","text":"Performs optimization to find optimal limit cycle parameters using Ipopt.\n\nArguments\n\np: An initial VBPara (physical units) used to establish base parameters and characteristic dimensions.\noptim_para_syms: A vector of Symbols for the VBPara parameters that will be optimized.\noptim_para_lower: A vector of Float64 specifying the lower bounds for the optim_para_syms in their physical units.\noptim_para_upper: A vector of Float64 specifying the upper bounds for the optim_para_syms in their physical units.\nsense: + for rising on the sides of the lemniscate, - for kite dropping on the sides\ntol: Absolute/relative tolerance for the ODE solver. The dynamics inside the non-linear constraints is integrated at tol / 10, and Ipopt is called with tolerance tol.\nmax_wall_time: Maximum wall-clock time in seconds for the Ipopt solver.\nmax_iter: Maximum number of Ipopt iterations (nothing, the default, keeps Ipopt's own limit). Unlike max_wall_time it does not depend on the machine, so results are reproducible. Ignored by solver=:madnlp.\nlinear_solver: The linear solver to use for the Ipopt solver, cf. https://coin-or.github.io/Ipopt/OPTIONS.html#OPTLinearSolver. Defaults to \"mumps\".\nsolver: :ipopt (default) or :madnlp; the latter needs using MadNLP (KEEP ships it as a package extension, so Ipopt-only users pay nothing).\nhessian: :exact (default) uses the exact Hessian. :lbfgs uses a limited-memory quasi-Newton Hessian — cheaper per iteration but it wanders on bad starts, so it retries with the exact Hessian when the cheap attempt fails or throws. :auto leaves the solver default (exact). On the whole paper.jl the exact Hessian is 1.9x faster (154 s against 287 s), because failed L-BFGS attempts dominate the sweeps.\nrhs: :auto (default, the closed-form PointMass4.dynamics) or :verified (the AD reference _dynamics_verified). :fast/:ad are accepted as aliases.\nsymmetry: exploit the invariance S(α,τ,dα,dτ) = (-α, τ+π, -dα, dτ) and integrate only half a period, imposing x(tf) = S x(0). Returns the full period in tf. Faster, but fragile: the symmetric formulation has more than one stationary point and a seed a fraction off the symmetric manifold can settle on the wrong one (measured: 4.2 kW against 12.25 kW). Check the returned power before trusting it.\ninitial_guess: A NamedTuple, Dict, or ComponentArray specifying initial starting values in physical units. This can partially or fully overwrite the baseline limit cycle guess. Because it accepts and returns physical dimensions, the returned solution can be passed directly into this argument for iterative refinements. Defaults to an empty NamedTuple (;).\n\nReturns\n\nsolution: A ComponentArray containing the optimized variables (states, time, power, and optimized parameters) mapped to their physical dimensions.\nstats: The statistics object from the Ipopt solver.\nmodel: The ADNLPModel object used for the optimization.\n\nNotes\n\nThe optimization is performed in a normalized (dimensionless) space to improve solver conditioning. The optim_para_lower, optim_para_upper, and initial_guess inputs are expected in physical units and are converted to normalized units internally. While the raw stats.solution remains in normalized units, the returned solution ComponentArray is automatically scaled back to physical units.\n\n\n\n\n\n"},{"title":"KEEP.PointMassPara.optimal_torque_slope","page":"KEEP functions","location":"api.html#KEEP.PointMassPara.optimal_torque_slope","category":"function","text":"optimal_torque_slope(p = build_para(); sense = +, tol = 1e-3, maxiter = 5, rtol = 1e-4)\n\nTorque slope b that satisfies the kinetic criterion b = I ω, with ω the angular frequency of the limit cycle (ω = 2π/period, period in seconds from a simulation). The period depends on b, so the value is a fixed point: solve the cycle, set b = I 2π/period, solve again until b stops moving. Returns b in the units of p.b and prints nothing.\n\np0 = build_para()\np0.b = optimal_torque_slope(p0)\nvbp = build_vbpara(p0)\n\nThe limit cycle solver lives in KEEP.LimitCycle, which is included after this module, hence the runtime lookup.\n\n\n\n\n\n"},{"title":"3 Analysis of the dynamics: equilibria and periodic orbits","page":"3 Analysis of the dynamics: equilibria and periodic orbits","location":"section-3.html#sec:analysis","category":"section","text":"<p>This section describes the dynamics of the four-dimensional system <span class=\"math inline\">\\(\\dot{\\vb x} = f(\\vb x)\\)</span> of Section <a href=\"section-1.html#sec:model-eom\">1.4</a> for one set of parameters, the one of Table <a href=\"section-2.html#tab:params\">1</a>. The inertia of the arm is <span class=\"math inline\">\\(I = 1300\\,\\mathrm{kg}\\,\\mathrm{m}^{2}\\)</span>, the initial guess of the optimization of Section <a href=\"section-4.html#sec:optimization\">4</a>: the results of this section describe the device before optimization, which the optimized design of Section <a href=\"section-4.html#sec:optimization\">4</a> is compared with. At this inertia, the braking coefficient <span class=\"math inline\">\\(b\\)</span> satisfies the condition <a href=\"section-2.html#pto_optimality_constraint\">(47)</a>, <span class=\"math inline\">\\(b = I\\omega\\)</span>, that maximizes the average power <a href=\"section-2.html#eq:power_PTO\">(41)</a> of the one-dimensional model at fixed <span class=\"math inline\">\\(I\\)</span>, where <span class=\"math inline\">\\(\\omega = 2\\pi/T\\)</span> is now the angular frequency of the limit cycle of the full system with <span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span> (see Section <a href=\"#sec:analysis-cycles\">3.2</a>) rather than the estimate <a href=\"section-2.html#eq:Omega_PTO\">(45)</a>. As the period <span class=\"math inline\">\\(T\\)</span> depends on <span class=\"math inline\">\\(b\\)</span>, this condition is a fixed-point equation, solved by iterating <span class=\"math inline\">\\(b \\leftarrow 2\\pi I/T(b)\\)</span>. All the trajectories are integrated with the order-9 Verner method <span class=\"citation\" data-cites=\"Verner2010\">(<a href=\"references.html#ref-Verner2010\">Verner 2010</a>)</span>, as implemented in DifferentialEquations.jl <span class=\"citation\" data-cites=\"rackauckas2017differentialequations\">(<a href=\"references.html#ref-rackauckas2017differentialequations\">Rackauckas and Nie 2017</a>)</span>, with absolute and relative tolerances <span class=\"math inline\">\\(10^{-9}\\)</span> unless specified otherwise.</p>"},{"title":"3.1 Equilibria","page":"3 Analysis of the dynamics: equilibria and periodic orbits","location":"section-3.html#sec:analysis-equilibria","category":"section","text":"<p>The equilibria, or steady states, of the system are the states <span class=\"math inline\">\\(\\vb x_0 = (\\vb q_0, 0)\\)</span> with zero velocity and zero acceleration, that is the solutions of <a id=\"eq:equilibria\"></a><span class=\"math display\">\\begin{equation}\n \\tag{52}\n    \\ddot{\\vb q}(\\vb q_0, \\dot{\\vb q}= 0) = 0 \\in \\mathbf{R}^2.\n\\end{equation}</span> At such a state, the arm is at rest and the generator exerts no torque, so that <a href=\"section-1.html#eq:ddalpha\">(31)</a> reduces to <span class=\"math inline\">\\(a\\lambda F_\\ell = 0\\)</span>: either the lines are slack, or the lever arm <a href=\"section-1.html#eq:lever-arm\">(28)</a> of the tension vanishes. In the latter case, the kite lies on one of the edges <span class=\"math inline\">\\(\\Gamma_\\pm\\)</span> of the band of reachable positions, the fold curves <span class=\"math inline\">\\(\\alpha = \\phi(\\tau)\\)</span> (arm pointing towards the kite, downwind arm) and <span class=\"math inline\">\\(\\alpha = \\phi(\\tau) + \\pi\\)</span> (arm pointing away from the kite, upwind arm) of Section <a href=\"section-1.html#sec:model-geometry\">1.1</a>. The arm and the lines are then in the same vertical plane. Slack lines are excluded: off the fold curves, <span class=\"math inline\">\\(F_\\ell = 0\\)</span> at rest requires, by <a href=\"appendix-B.html#eq:K1\">(115)</a>–<a href=\"appendix-B.html#eq:K2\">(116)</a>, that the force <span class=\"math inline\">\\(\\vb F_a + \\vb F_g\\)</span> on the kite be normal to the cone, whereas on a grid of <span class=\"math inline\">\\(721\\times721\\)</span> configurations its tangential part is at least <span class=\"math inline\">\\(0.56\\)</span> times its norm. The equilibria therefore lie on the fold curves, which are nullclines of <span class=\"math inline\">\\(\\ddot\\alpha\\)</span> at zero velocity, since <span class=\"math inline\">\\(\\lambda = 0\\)</span> there. Along each fold curve, the equilibria are the zeros of the single function <span class=\"math inline\">\\(g_\\pm(\\tau) = \\ddot\\tau(\\vb q(\\tau), 0)\\)</span>, with <span class=\"math inline\">\\(\\vb q(\\tau) = (\\phi(\\tau), \\tau)\\)</span> or <span class=\"math inline\">\\((\\phi(\\tau)+\\pi, \\tau)\\)</span>; by <a href=\"appendix-B.html#eq:K1\">(115)</a>–<a href=\"appendix-B.html#eq:K2\">(116)</a> with <span class=\"math inline\">\\(\\lambda = 0\\)</span>, they are the configurations where the weight and the aerodynamic force are balanced by the tension of the lines and the reaction of the cone. They are bracketed by the sign changes of <span class=\"math inline\">\\(g_\\pm\\)</span> on a grid of <span class=\"math inline\">\\(3600\\)</span> values of <span class=\"math inline\">\\(\\tau\\)</span>, and refined by a scalar root finder; the same <span class=\"math inline\">\\(8\\)</span> equilibria are found by a nonlinear solver on the full system <a href=\"#eq:equilibria\">(52)</a> started from <span class=\"math inline\">\\(100\\)</span> values of <span class=\"math inline\">\\(\\tau\\)</span> on each fold curve and completed by symmetry. Their tensions, given by <a href=\"section-1.html#eq:eom_regular\">(32)</a>, lie between 144 N and 266 N.</p>\n<p>The solutions of <a href=\"#eq:equilibria\">(52)</a> lie at the intersections of the nullclines of <span class=\"math inline\">\\(\\ddot\\alpha\\)</span> and of <span class=\"math inline\">\\(\\ddot\\tau\\)</span>, shown in Fig. <a href=\"#fig:equilibria-phase-space\">5</a>: the nullclines of <span class=\"math inline\">\\(\\ddot\\tau\\)</span> cross the torus <span class=\"math inline\">\\(\\mathbf{T}^2\\)</span> of configurations horizontally, those of <span class=\"math inline\">\\(\\ddot\\alpha\\)</span> vertically, and they meet at <span class=\"math inline\">\\(8\\)</span> points. The symmetry <a href=\"section-1.html#eq:symmetry\">(34)</a> maps an equilibrium <span class=\"math inline\">\\((\\alpha, \\tau)\\)</span> onto the equilibrium <span class=\"math inline\">\\((-\\alpha, \\tau + \\pi)\\)</span>, with the kite on the other side of the plane of the wind, so that the equilibria come in <span class=\"math inline\">\\(8/2\\)</span> pairs. They realize the eight combinations of three binary features: the arm points downwind or upwind; the kite is near the centre of the eight or near one of its tips; it is on the left or on the right of the plane of the wind. Their configurations are drawn in Fig. <a href=\"#fig:equilibria-eight-circle\">6</a>, and Table <a href=\"#tab:equilibria\">2</a> gives their positions and the eigenvalues of the Jacobian of <span class=\"math inline\">\\(f\\)</span>. The two members of a pair have the same spectrum, since <span class=\"math inline\">\\(\\sigma\\)</span> is linear and conjugates the vector field to itself; as the vector field is analytic, the Jacobians are computed by <span data-acronym-label=\"ad\" data-acronym-form=\"singular+short\">ad</span> at the equilibria themselves, and the spectra of the two members agree to rounding error.</p>\n<p>All the equilibria are unstable. The two pairs with the kite near the centre of the eight have a real eigenvalue between <span class=\"math inline\">\\(11.4\\)</span> and 12.9  s, which repels the trajectories on a time scale of a tenth of a second; the two pairs with the kite near a tip have a pair of complex eigenvalues with real part between <span class=\"math inline\">\\(1.49\\)</span> and 1.53  s, an unstable oscillation. With an upwind arm, each equilibrium has one more unstable eigenvalue, real and small, than its downwind counterpart. None of the equilibria is a possible operating point of the device, which motivates the study of the periodic motions below. At every equilibrium, the eigenvector of the most unstable eigenvalue moves the kite along the eight, in <span class=\"math inline\">\\(\\tau\\)</span> and <span class=\"math inline\">\\(\\dot\\tau\\)</span>, while the arm stays at rest to first order: the main instability is that of the kite on its prescribed path, not that of the arm. The additional, slow, unstable eigenvalue of the upwind equilibria is, on the contrary, a mode of the arm: the lines pull the tip of an arm pointing upwind, away from the kite, towards the pivot, and a small rotation of the arm is amplified, as for an inverted pendulum, whereas they stabilize an arm pointing downwind, towards the kite. Indeed, with the kite frozen and the tension held at its value at rest, linearizing <a href=\"section-1.html#eq:ddalpha\">(31)</a> at the fold curve with <a href=\"section-1.html#eq:lever-arm\">(28)</a> gives <span class=\"math inline\">\\(I\\,\\delta\\ddot\\alpha + b\\,\\delta\\dot\\alpha = k\\,\\delta\\alpha\\)</span>, with <span class=\"math inline\">\\(k = -a F_\\ell\\,(r/\\ell)\\sin\\theta\\cos(\\phi-\\alpha)\\)</span>, positive for an upwind arm (<span class=\"math inline\">\\(\\alpha = \\phi+\\pi\\)</span>) and negative for a downwind one (<span class=\"math inline\">\\(\\alpha = \\phi\\)</span>). The largest root of <span class=\"math inline\">\\(I s^2 + b s - k = 0\\)</span> is positive in the first case and negative in the second, and it matches the corresponding real eigenvalue of Table <a href=\"#tab:equilibria\">2</a> within <span class=\"math inline\">\\(9\\%\\)</span> at the four pairs of equilibria; with the small tension at rest and the large inertia of the arm, this instability is slow. Near the centre of the eight, it is static: the tangential component of the aerodynamic force and of the weight vanishes at the equilibrium, and a small displacement of the kite along the eight creates a tangential component in the direction of the displacement, which amplifies it on a time scale of a tenth of a second. Near a tip, it is an unstable oscillation along the eight: the motion of the kite changes its apparent wind, hence its aerodynamic force, in phase with its velocity, so that the aerodynamic force feeds the motion, as in crosswind flight.</p>\n<table id=\"tab:equilibria\">\n<caption><strong>Table 2:</strong> Equilibria of the system for the parameters of Table <a href=\"section-2.html#tab:params\">1</a>, by pairs exchanged by the symmetry <a href=\"section-1.html#eq:symmetry\">(34)</a>: one representative <span class=\"math inline\">\\((\\alpha, \\tau)\\)</span> of each pair (in degrees, <span class=\"math inline\">\\(0 \\leq \\tau &lt; 180\\)</span>), eigenvalues of the Jacobian of <span class=\"math inline\">\\(f\\)</span> (in  s) and number of eigenvalues with positive real part.</caption>\n<thead>\n<tr>\n<th style=\"text-align: left;\"><span>Arm</span></th>\n<th style=\"text-align: left;\"><span>Kite</span></th>\n<th style=\"text-align: center;\"><span><span class=\"math inline\">\\((\\alpha, \\tau)\\)</span></span></th>\n<th style=\"text-align: left;\"><span>Eigenvalues</span></th>\n<th style=\"text-align: center;\"><span>Unstable</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: left;\">downwind</td>\n<td style=\"text-align: left;\">centre</td>\n<td style=\"text-align: center;\"><span class=\"math inline\">\\((5.0, 5.7)\\)</span></td>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(-2.12,\\ -0.34,\\ -0.10,\\ 11.38\\)</span></td>\n<td style=\"text-align: center;\">1</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">downwind</td>\n<td style=\"text-align: left;\">tip</td>\n<td style=\"text-align: center;\"><span class=\"math inline\">\\((50.0, 89.7)\\)</span></td>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(-2.03,\\ -0.19,\\ 1.49 \\pm 3.17\\,i\\)</span></td>\n<td style=\"text-align: center;\">2</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">upwind</td>\n<td style=\"text-align: left;\">centre</td>\n<td style=\"text-align: center;\"><span class=\"math inline\">\\((-175.6, 5.1)\\)</span></td>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(-2.30,\\ -0.33,\\ 0.09,\\ 12.89\\)</span></td>\n<td style=\"text-align: center;\">2</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">upwind</td>\n<td style=\"text-align: left;\">tip</td>\n<td style=\"text-align: center;\"><span class=\"math inline\">\\((-130.0, 89.0)\\)</span></td>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(-2.36,\\ 0.14,\\ 1.53 \\pm 3.42\\,i\\)</span></td>\n<td style=\"text-align: center;\">3</td>\n</tr>\n</tbody>\n</table>\n\n<details class=\"web-code\"><summary>Code that produced this table</summary>\n\nsrc/analysis.jl (region table5), see also the full file.\n\n    pairs = equilibrium_spectra(ss, vbp; is_down, is_center)\n    push!(files, write_table(\"table5\", equilibria_table(pairs)))\n\n</details>\n\n<figure id=\"fig:equilibria-phase-space\" data-latex-placement=\"thpb\">\n<img src=\"figs/equilibria_phase_space.png\" />\n<figcaption><strong>Figure 5:</strong> Zero-velocity accelerations and equilibria. The grey arrows show the direction of the field <span class=\"math inline\">\\(\\ddot{\\vb q}(\\vb q, \\dot{\\vb q}= 0)\\)</span>; the orange and blue curves are the nullclines of <span class=\"math inline\">\\(\\ddot\\alpha\\)</span> and of <span class=\"math inline\">\\(\\ddot\\tau\\)</span>, respectively. The equilibria lie at their intersections: white markers for a downwind arm, black ones for an upwind arm, circles when the kite is near the centre of the eight and diamonds when it is near a tip. The background is light grey when the arm points downwind and light red when it points upwind.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/analysis.jl (region setup_analysis), see also the full file.\n\n    ## Determine optimal parameters using kinetic model\n    p0 = PMP.build_para()\n    p0.b = PMP.optimal_torque_slope(p0; sense=(+), tol=1e-9, rtol=1e-9, maxiter=50)  # errors if not converged\n    vbp = PMP.build_vbpara(p0)\n\nsrc/analysis.jl (region equilibria_style), see also the full file.\n\n    #! format: off\n    my_theme = (;\n        downwind        = (; c=plot_color(:grey, 0.08)),\n        upwind          = (; c=plot_color(:red, 0.08)),\n        streamlines     = (; c=:black, alpha=0.7, lw=default(:lw) / 6),\n        heads           = (; c=:black, alpha=0.5, lw=0),\n        nullcline_tau   = (; c=1, ls=:solid),\n        nullcline_alpha = (; c=2, ls=:solid),\n        eq_legend       = (; c=:black, shape=:circle, ms=default(:ms), msw=20),\n    )\n\n    # Equilibrium characteristics: the symmetry (α, τ) -> (-α, τ+π) flips the kite\n    # left↔right (φ = φ0 + Δφ·sin(τ)) and preserves the arm wind region and the\n    # center/side zone, so the 8 equilibria realize all 2×2×2 combinations.\n    φkite(τ) = vbp.φ0 + vbp.Δφ * sin(τ)                     # kite azimuth (PM4.τ_to_θφ)\n    is_down(q) = cos(q[1]) > 0                              # arm downwind\n    is_left(q) = φkite(q[2]) > vbp.φ0                       # kite left of window center\n    is_center(q) = abs(φkite(q[2]) - vbp.φ0) < vbp.Δφ / 2   # closer to φ0 than to ±Δφ\n\n    \"Marker style from the equilibrium characteristics: fill = arm wind, shape = zone, stroke = kite side.\"\n    ss_style(q) = (\n        c = is_down(q) ? :white : :black,\n        markerstrokecolor = is_down(q) ? :black : :white,\n        shape = is_center(q) ? :circle : :diamond,\n        ms = default(:ms),\n        markerstrokewidth = is_down(q) ? 8 : 10,\n        # markerstrokewidth = 10,\n    )\n    #! format: on\n\n    theme = my_theme\n\n    f = q -> SteadyState.ddq_partial(q, vbp)\n\nsrc/analysis.jl (region equilibriaphasespace), see also the full file.\n\n    # Canvas & Layout\n    δ = 0\n    plot(xlims=(-180 - δ, 180 + δ), ylims=(-180 - δ, 180 + δ), aspect_ratio=:equal,\n        xticks=([-180, 0, 180], [\"-180\", \"0\", \"180\"]),\n        yticks=([-180, 0, 180], [\"-180\", \"0\", \"180\"]),\n        xlabel=\"α (deg)\", ylabel=\"τ (deg)\",\n        grid=false, framestyle=:semi, legend=:outerright, colorbar=false)\n    # Background wind spans\n    vspan!([-180, -90]; theme.upwind..., label=\"Upwind arm\")\n    vspan!([90, 180]; theme.upwind...)\n    vspan!([-90, 90]; theme.downwind...) #, label=\"Downwind arm\")\n\n    # Streamlines & Arrowheads\n    line_x, line_y, ax, ay, au, av = streamlines(f, (-π, π), (-π, π))\n    plot!(rad2deg.(line_x), rad2deg.(line_y); theme.streamlines...)\n\n    ax, ay = rad2deg.(ax), rad2deg.(ay)\n    L, W = rad2deg(0.2), rad2deg(0.06)\n    heads = [Shape([(s[1] + L / 2 * u, s[2] + L / 2 * v),\n        (s[1] - L / 2 * u - W * v, s[2] - L / 2 * v + W * u),\n        (s[1] - L / 2 * u + W * v, s[2] - L / 2 * v - W * u)])\n             for (s, u, v) in zip(zip(ax, ay), au, av)]\n    plot!(heads; theme.heads...)\n\n    # Nullclines (splatting reuses line properties for both contour and the GR legend fix)\n    N = 20\n    αs = range(-π, π, N + 1)\n    τs = range(-π, π, 2N + 1)\n    dd = [f((α, τ)) for τ in τs, α in αs]\n\n    contour!(rad2deg.(αs), rad2deg.(τs), last.(dd); levels=[0], theme.nullcline_tau...)\n    contour!(rad2deg.(αs), rad2deg.(τs), first.(dd); levels=[0], theme.nullcline_alpha...)\n    plot!([NaN], [NaN]; theme.nullcline_tau..., label=\"D²(τ) = 0\")\n    plot!([NaN], [NaN]; theme.nullcline_alpha..., label=\"D²(α) = 0\")\n\n    # Equilibria\n    ss = SteadyState.all_steady_states(vbp; N=EQ_SEEDS)\n\n    styles = ss_style.(ss)\n    scatter!(rad2deg.(first.(ss)), rad2deg.(last.(ss));\n        c=getproperty.(styles, :c),\n        markerstrokecolor=getproperty.(styles, :markerstrokecolor),\n        shape=getproperty.(styles, :shape),\n        ms=getproperty.(styles, :ms),\n        markerstrokewidth=getproperty.(styles, :markerstrokewidth))\n    scatter!([NaN], [NaN]; theme.eq_legend..., label=\"Equilibrium\")\n    plot!(widen=1.06)\n    plot!(leftmargin=6Plots.mm, bottommargin=5Plots.mm, rightmargin=5Plots.mm,\n        topmargin=5Plots.mm, size=plot_size(1, 1.14))\n    append!(files, save_figure(current(), \"equilibria_phase_space\"))\n\n</details>\n\n<figure id=\"fig:equilibria-eight-circle\" data-latex-placement=\"thpb\">\n<img src=\"figs/equilibria_eight_circle.png\" />\n<figcaption><strong>Figure 6:</strong> Configurations of the equilibria, top view, for a downwind (left) and an upwind (right) arm, with the markers of Fig. <a href=\"#fig:equilibria-phase-space\">5</a>. The eight is projected on the horizontal plane without the correction of the radial distance <span class=\"math inline\">\\(r\\)</span> by the angle of the arm. At every equilibrium, the projections of the arm and of the lines on the horizontal plane are aligned.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/analysis.jl (region equilibriaeightcircle), see also the full file.\n\n    ss_downwind = [_ss for _ss in ss if cos(_ss[1]) > 0]\n    ss_upwind = [_ss for _ss in ss if cos(_ss[1]) <= 0]\n    p_downwind = VIZ.plot_eight_circle(ss_downwind, vbp; plot_kwargs=(; color=:black, lw=2),\n        marker_kwargs=ss_style.(ss_downwind), project_eight=true)\n    plot!(title=\"Downwind arm\", background_color_subplot=theme.downwind.c)\n    p_upwind = VIZ.plot_eight_circle(ss_upwind, vbp; plot_kwargs=(; color=:black, lw=2),\n        marker_kwargs=ss_style.(ss_upwind), project_eight=true)\n    plot!(title=\"Upwind arm\", background_color_subplot=theme.upwind.c)\n\n    plot(p_downwind, p_upwind; layout=(1, 2), size=plot_size(16 / 15, 2))\n    append!(files, save_figure(current(), \"equilibria_eight_circle\"))\n\n</details>"},{"title":"3.2 Periodic orbits","page":"3 Analysis of the dynamics: equilibria and periodic orbits","location":"section-3.html#sec:analysis-cycles","category":"section","text":"<p>Starting from the configuration <span class=\"math inline\">\\(\\vb q= (0, 0)\\)</span> at rest except for the kite, <span class=\"math inline\">\\(\\vb x_0^\\pm = (0, 0, 0, \\pm1\\,\\mathrm{rad}\\,\\mathrm{s}^{-1})\\)</span>, the trajectory settles after a few seconds into a periodic motion, along which the kite runs indefinitely along the eight in the direction given by the sign of <span class=\"math inline\">\\(\\dot\\tau(0)\\)</span> and the arm swings back and forth (Fig. <a href=\"#fig:timeseries\">7</a>). The angle <span class=\"math inline\">\\(\\tau\\)</span> is then monotone, and a period is a lap of the eight, along which <span class=\"math inline\">\\(\\tau\\)</span> increases or decreases by <span class=\"math inline\">\\(2\\pi\\)</span> while <span class=\"math inline\">\\(\\alpha\\)</span>, <span class=\"math inline\">\\(\\dot\\alpha\\)</span> and <span class=\"math inline\">\\(\\dot\\tau\\)</span> return to their initial values.</p>\n<figure id=\"fig:timeseries\" data-latex-placement=\"thpb\">\n<img src=\"figs/time_series_4D.png\" />\n<figcaption><strong>Figure 7:</strong> Time series of the state over 10 s from <span class=\"math inline\">\\(\\vb x_0^+\\)</span>. After a few seconds the same pattern repeats: the trajectory approaches a limit cycle.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/analysis.jl (region timeseries4D), see also the full file.\n\n    u0 = PM4.build_u(; dτ=DTAU_INIT)\n    sol = PM4.integrate(u0, TS_DURATION, vbp; save_everystep=true)\n\n    sim_4D_fig = plot_time_series(sol)\n    append!(files, save_figure(sim_4D_fig, \"time_series_4D\"))\n\n</details>\n\n<p>We study these motions on the Poincaré section <span class=\"math display\">\\begin{equation}\n    \\Sigma = \\{\\vb x \\in \\mathbf{T}^2 \\times \\mathbf{R}^2 \\mid \\tau = 0 \\bmod 2\\pi\\},\n\\tag{53}\\end{equation}</span> which every trajectory along which <span class=\"math inline\">\\(\\tau\\)</span> is monotone crosses once per lap. Let <span class=\"math inline\">\\(\\varphi^t\\)</span> be the flow of <span class=\"math inline\">\\(f\\)</span>, and <span class=\"math inline\">\\(\\Delta t(\\vb x) = \\min\\{t &gt; 0 \\mid \\varphi^t(\\vb x) \\in \\Sigma\\}\\)</span> the time to the next crossing; the first return map is <span class=\"math display\">\\begin{equation}\n    P : \\vb x \\in \\Sigma \\mapsto \\varphi^{\\Delta t(\\vb x)}(\\vb x) \\in \\Sigma,\n\\tag{54}\\end{equation}</span> and <span class=\"math inline\">\\(\\Sigma\\)</span> is parametrized by <span class=\"math inline\">\\((\\alpha, \\dot\\alpha, \\dot\\tau)\\)</span>. A periodic orbit with one lap per period is a fixed point of <span class=\"math inline\">\\(P\\)</span>; equivalently, its initial state <span class=\"math inline\">\\(\\vb x(0) = (\\alpha_0, 0, \\dot\\alpha_0, \\dot\\tau_0)\\)</span> and its period <span class=\"math inline\">\\(T\\)</span> solve the boundary value problem <a id=\"eq:cycle-bvp\"></a><span class=\"math display\">\\begin{equation}\n \\tag{55}\n    \\vb x(T) = \\vb x(0) + (0, \\pm 2\\pi, 0, 0), \\qquad \\dot{\\vb x} = f(\\vb x),\n\\end{equation}</span> four equations for the four unknowns <span class=\"math inline\">\\((\\alpha_0, \\dot\\alpha_0, \\dot\\tau_0, T)\\)</span>, the sign being that of <span class=\"math inline\">\\(\\dot\\tau_0\\)</span>. The crossings of <span class=\"math inline\">\\(\\Sigma\\)</span> are located during the integration by an event function (the continuous callbacks of DifferentialEquations.jl) and evaluated on the dense output of the integrator. A limit cycle is computed in two steps: the trajectory from <span class=\"math inline\">\\(\\vb x_0^\\pm\\)</span> is integrated until two successive crossings agree within <span class=\"math inline\">\\(10\\times10^{-9}\\)</span>, and this approximation of the fixed point is refined by Newton’s method on <a href=\"#eq:cycle-bvp\">(55)</a>, the Jacobian being obtained by forward-mode <span data-acronym-label=\"ad\" data-acronym-form=\"singular+short\">ad</span> through the integrator.</p>\n<p>The iterates <span class=\"math inline\">\\(\\vb x_{i+1} = P(\\vb x_i)\\)</span> converge to the fixed point <span class=\"math inline\">\\(\\vb x_\\infty\\)</span> exponentially (Fig. <a href=\"#fig:limit_cycle_convergence\">8</a>): the distance to the limit is divided by about <span class=\"math inline\">\\(10^{2.13}\\)</span> (<span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span>) or <span class=\"math inline\">\\(10^{2.16}\\)</span> (<span class=\"math inline\">\\(\\dot\\tau &lt; 0\\)</span>) at each lap, until it stalls at the integration tolerance. This rate is explained by the Floquet multipliers of the cycles, the eigenvalues of the monodromy matrix <span class=\"math inline\">\\(\\partial\\varphi^T/\\partial\\vb x\\)</span> at <span class=\"math inline\">\\(\\vb x_\\infty\\)</span>, computed by <span data-acronym-label=\"ad\" data-acronym-form=\"singular+short\">ad</span> through the integrator. One multiplier is trivially <span class=\"math inline\">\\(1\\)</span>, the derivative along the flow, which the computation recovers to within <span class=\"math inline\">\\(10^{-8}\\)</span>; the other three are the eigenvalues of the derivative of <span class=\"math inline\">\\(P\\)</span>. The largest of them is real, of modulus <span class=\"math inline\">\\(8.5 \\times 10^{-3}\\)</span> (<span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span>) and <span class=\"math inline\">\\(8.0 \\times 10^{-3}\\)</span> (<span class=\"math inline\">\\(\\dot\\tau &lt; 0\\)</span>), that is <span class=\"math inline\">\\(10^{-2.07}\\)</span> and <span class=\"math inline\">\\(10^{-2.10}\\)</span>: it sets the asymptotic rate of convergence. The other two form a complex pair of smaller modulus, <span class=\"math inline\">\\(10^{-2.40}\\)</span> and <span class=\"math inline\">\\(10^{-2.36}\\)</span>; over the few laps before the distance reaches the tolerance, this faster, oscillating component still contributes, so that the observed rates are slightly above the asymptotic ones and vary from one lap to the next. Both cycles are therefore strongly attracting: a perturbation is damped by more than two orders of magnitude at each lap.</p>\n<figure id=\"fig:limit_cycle_convergence\" data-latex-placement=\"thpb\">\n<img src=\"figs/limit_cycle_convergence.png\" />\n<figcaption><strong>Figure 8:</strong> Convergence to the fixed point of the first return map, for <span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span> (left) and <span class=\"math inline\">\\(\\dot\\tau &lt; 0\\)</span> (right): distance from the <span class=\"math inline\">\\(i\\)</span>-th crossing of <span class=\"math inline\">\\(\\Sigma\\)</span> to the limit, as a function of the number of laps of the eight (a lap is a sweep of <span class=\"math inline\">\\(\\tau\\)</span> over <span class=\"math inline\">\\(2\\pi\\)</span>). The linear trend in log scale shows an exponential convergence: at each lap, the distance to the limit is divided by about <span class=\"math inline\">\\(10^{2.13}\\)</span> (<span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span>) or <span class=\"math inline\">\\(10^{2.16}\\)</span> (<span class=\"math inline\">\\(\\dot\\tau &lt; 0\\)</span>), until it stalls near the integration tolerance, set at <span class=\"math inline\">\\(10^{-13}\\)</span>.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/analysis.jl (region limitcycleconvergence), see also the full file.\n\n    (p_conv_p, slope_p) = plot_convergence_panel(vbp, +1, 1; ntrace=0, legend=false)\n    (p_conv_m, slope_m) = plot_convergence_panel(vbp, -1, 2; ntrace=0)\n    plot!(p_conv_p, leftmargin=11Plots.mm)\n    plot!(p_conv_m, leftmargin=5Plots.mm)\n    plot!(p_conv_p, ylabel=\"Distance to limit\")\n    conv_two = plot(p_conv_p, p_conv_m; layout=(1, 2), size=SIZE_FULL)\n    plot!(bottommargin=7Plots.mm)\n    append!(files, save_figure(conv_two, \"limit_cycle_convergence\"))\n\n</details>\n\n<p>The two limit cycles, one for each direction of travel of the kite along the eight, are close but distinct (Fig. <a href=\"#fig:yz_limit_cycle\">9</a>). Their periods are 2.83 s (<span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span>) and 2.71 s (<span class=\"math inline\">\\(\\dot\\tau &lt; 0\\)</span>), and their average powers 9.64 kW and 9.03 kW. Along them, the arm swings by at most 67° and 63° from the downwind direction, within the operating limit <span class=\"math inline\">\\(\\abs{\\alpha} \\leq \\pi/2\\)</span> of Section <a href=\"section-2.html#sec:1D-PTO\">2</a>. The cycle with <span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span> is the starting point of the optimization of Section <a href=\"section-4.html#sec:optimization\">4</a>. The symmetry <a href=\"section-1.html#eq:symmetry\">(34)</a> preserves the sign of <span class=\"math inline\">\\(\\dot\\tau\\)</span>, so that it maps each cycle onto a cycle with the same direction of travel, and does not exchange the two cycles. No other symmetry of the system relates them. A spatial symmetry of the model is an isometry that fixes the pivot <span class=\"math inline\">\\(O\\)</span> and preserves gravity, the wind field <span class=\"math inline\">\\(\\vb w(z)\\)</span>, the circle <span class=\"math inline\">\\(\\mathscr{A}\\)</span> of the arm and the eight <span class=\"math inline\">\\(\\mathscr{E}\\)</span>. Preserving <span class=\"math inline\">\\(\\vu z\\)</span> and the altitude <span class=\"math inline\">\\(z\\)</span>, on which the shear depends, it is a rotation about <span class=\"math inline\">\\(\\vu z\\)</span> or a reflection through a vertical plane; preserving the direction <span class=\"math inline\">\\(\\vu x\\)</span> of the wind, it is the identity or the reflection through <span class=\"math inline\">\\((O,\\vu x,\\vu z)\\)</span>, which induces <span class=\"math inline\">\\(\\sigma\\)</span>. Both keep the direction of travel along <span class=\"math inline\">\\(\\mathscr{E}\\)</span>, since <span class=\"math inline\">\\(\\sigma\\)</span> shifts <span class=\"math inline\">\\(\\tau\\)</span> by <span class=\"math inline\">\\(\\pi\\)</span>. A map of <span class=\"math inline\">\\(\\mathscr{E}\\)</span> onto itself that reverses its direction, <span class=\"math inline\">\\(\\tau\\mapsto\\pi-\\tau\\)</span> or <span class=\"math inline\">\\(\\tau\\mapsto-\\tau\\)</span>, exchanges <span class=\"math inline\">\\(\\theta_0+\\delta\\)</span> with <span class=\"math inline\">\\(\\theta_0-\\delta\\)</span>, that is a kite climbing through the centre of the eight with a kite diving through it; it is not induced by an isometry, as gravity and the shear distinguish the two. Time reversal, <span class=\"math inline\">\\(t\\mapsto-t\\)</span>, which also reverses the direction of travel, is not a symmetry either, because of the dissipation by the generator and by the aerodynamic drag. Each cycle is in fact invariant under <span class=\"math inline\">\\(\\sigma\\)</span>: <span class=\"math inline\">\\(\\sigma(\\vb x(t)) = \\vb x(t + T/2)\\)</span>, to within <span class=\"math inline\">\\(10^{-9}\\)</span> along the cycle, so that the second half of a lap is the mirror image of the first through the plane of the wind. The lines remain taut along both cycles, as required in Section <a href=\"section-1.html#sec:model-forces\">1.3</a>, with a tension between 3.36 kN and 8.86 kN (<span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span>), and between 3.42 kN and 9.59 kN (<span class=\"math inline\">\\(\\dot\\tau &lt; 0\\)</span>). The cycle with <span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span>, along which the kite dives through the centre of the eight and climbs on its sides, has the longer period and produces the larger power. Over a lap, gravity does no net work, so that the power of the generator equals that of the aerodynamic force, <span class=\"math inline\">\\(\\vb F_a\\vdot\\dot{\\vb r} = \\vb F_a\\vdot\\vb w - \\vb F_a\\vdot\\vb w_a\\)</span>: the power taken from the wind minus the power dissipated by the drag (the lift is normal to the apparent wind). Diving at the tips of the eight, the kite of the cycle with <span class=\"math inline\">\\(\\dot\\tau &lt; 0\\)</span> is accelerated there by gravity: its mean speed near the tips is 35.7 m s<sup>−1</sup>, against 32.9 m s<sup>−1</sup> for <span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span>, and 40.5 m s<sup>−1</sup> against 38.7 m s<sup>−1</sup> over the lap. The faster kite meets a stronger apparent wind, and takes more power from the wind, 49.3 kW against 44.8 kW, but its drag dissipates more, 40.3 kW against 35.2 kW: the extra speed costs more than it brings, and the slower cycle, with <span class=\"math inline\">\\(\\dot\\tau &gt; 0\\)</span>, delivers the larger power.</p>\n<figure id=\"fig:yz_limit_cycle\" data-latex-placement=\"thpb\">\n<img src=\"figs/yz_limit_cycles.png\" />\n<figcaption><strong>Figure 9:</strong> Projection of the trajectory of the kite on the <span class=\"math inline\">\\(YZ\\)</span> plane for the two limit cycles, with opposite directions of travel (the arrows give the direction of motion of the kite). The inset, a zoom, shows that the two paths are distinct.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/analysis.jl (region yzlimitcycles), see also the full file.\n\n    r_vec = (t, sol) -> PM4.compute_OK(PM4.compute_Rτ(sol(t), sol.prob.p), sol.prob.p)\n    lc_p = LC.compute_limit_cycle(PM4.build_u(; dτ=+DTAU_INIT), vbp; save_everystep=true)\n    lc_m = LC.compute_limit_cycle(PM4.build_u(; dτ=-DTAU_INIT), vbp; save_everystep=true)\n    (lc_p === nothing || lc_m === nothing) && error(\"no limit cycle from x0±\")\n    function compute_lens(lc_p, lc_m, τ, δ_factor; idxs=2:3)\n        # τ(t) is monotone along a cycle and spans TAU0 ± 2π: find the time where\n        # the τ state hits τ mod 2π, mapped into the cycle's τ range.\n        function phase_time(sol, τ)\n            t0, t1 = sol.prob.tspan\n            lo, hi = minmax(sol(t0)[2], sol(t1)[2])\n            τ_target = clamp(τ + 2π * ceil((lo - τ) / 2π), lo, hi)\n            return find_zero(t -> sol(t)[2] - τ_target, (t0, t1))\n        end\n        yz(sol, t) = r_vec(t, sol)[idxs]\n        r_p = yz(lc_p, phase_time(lc_p, τ))\n        r_m = yz(lc_m, phase_time(lc_m, τ))\n        c = (r_p + r_m) / 2\n        δ = δ_factor * norm(r_p - r_m)\n        return c, δ\n    end\n\n    function yz_split(sol, n_splits)\n        t = range(sol.prob.tspan..., 300)\n        yz = [r_vec(t, sol)[2:3] for t in t]\n        Δt = (t[end] - t[1]) / (n_splits + 1)\n        for i in 1:n_splits\n            t_split = (i - 0.2) * Δt\n            ind = searchsortedfirst(t, t_split)\n            insert!(yz, ind + i - 1, [NaN, NaN])\n        end\n        return yz\n    end\n    n_splits = 4\n    # arrows = [permutedims(repeat([true], n_splits - 1)) false]\n    plot(aspect_ratio=:equal, xlabel=\"y (m)\", ylabel=\"z (m)\", xtick=-40:10:40, ytick=10:5:20)\n    plot!(invert(yz_split(lc_m, n_splits))..., lw=4, c=2, arrows=true)\n    plot!(invert(yz_split(lc_p, n_splits))..., lw=2, c=1, arrows=true)\n    plot!([NaN], [NaN], c=1, label=\"D(τ) > 0\")\n    plot!([NaN], [NaN], c=2, label=\"D(τ) < 0\")\n    plot!([0], [26])\n    c, δ = compute_lens(lc_p, lc_m, 2.6, 3)  # lens focus phase τ was set by hand\n    lens!([c[1] - δ, c[1] + δ], [c[2] - δ, c[2] + δ], inset=(1, bbox(0.3, 0.05, 0.3, 0.4)), lw=1.5, lc=:grey)\n    l = plot!().inset_subplots[1]\n    xticks_ = (c[1]-δ):δ:(c[1]+δ)\n    yticks_ = (c[2]-δ):δ:(c[2]+δ)\n    xticks!(l, xticks_, [f\"{t:.1f}\" for t in xticks_])\n    yticks!(l, yticks_, [f\"{t:.1f}\" for t in yticks_])\n    plot!(l, tickfontsize=TICKFONTSIZE - 1)\n    plot!(; leftmargin=5Plots.mm, bottommargin=5Plots.mm, size=plot_size(2 / 3, 1))\n    append!(files, save_figure(current(), \"yz_limit_cycles\"))\n\n</details>\n\n<p>No other limit cycle was found. 200 initial states sampled on <span class=\"math inline\">\\(\\Sigma\\)</span> by a Halton sequence, with <span class=\"math inline\">\\(\\alpha \\in [-\\pi, \\pi]\\)</span> and <span class=\"math inline\">\\(\\abs{\\dot\\alpha}, \\abs{\\dot\\tau} \\leq 10\\,\\mathrm{rad}\\,\\mathrm{s}^{-1}\\)</span>, are integrated with the coarser tolerance <span class=\"math inline\">\\(\\sqrt{10^{-9}}\\)</span> until their crossings of <span class=\"math inline\">\\(\\Sigma\\)</span> settle; the settled states are clustered, and the centroid of each cluster is refined as above. This yields <span class=\"math inline\">\\(2\\)</span> limit cycles, the two above. The bound on the velocities corresponds to speeds of the arm and of the kite that the generator and the aerodynamic drag quickly damp. The search only finds fixed points of the first return map: it does not detect cycles with several laps of the eight per period, nor cycles along which <span class=\"math inline\">\\(\\tau\\)</span> is not monotone and that do not cross <span class=\"math inline\">\\(\\Sigma\\)</span> once per lap. This inventory is a numerical exploration, not a proof of uniqueness.</p>"},{"title":"src/modelling.jl","page":"src/modelling.jl","location":"code/src-modelling-jl.html#src/modelling.jl","category":"section","text":"View on GitHub (commit 2cfaacd).\n\n# Section 1 figures: the spindle torus of the possible kite positions, and the\n# parametrisation of the eight in tau.\n#\n#   arm tip  A(α) = a * (cos α, sin α, 0)\n#   kite     K(α, β) = A(α) + l * (cos β * (cos α, sin α, 0) + sin β * ẑ)\n#\n# The line of length l points anywhere in the radial-vertical plane. Revolving\n# the sphere of radius l about the arm axis gives a torus; l > a => spindle.\n#\n# Outputs: figs/spindle_torus.{pdf,png}, figs/eight_plot.{pdf,png}.\nusing Plots\nusing LinearAlgebra: norm\n\ninclude(joinpath(@__DIR__, \"helpers.jl\"))\n\nfunction run_modelling(; fast::Bool=false)\n    #region spindle_torus\n    ## Spindle torus\n    a, l = 2, 3\n\n    # sanity check: a sampled point is exactly l from its arm tip\n    β0 = deg2rad(30)  # line elevation\n    kite_pos = [a + l * cos(β0), 0, l * sin(β0)]\n    @assert isapprox(norm(kite_pos - [a, 0, 0]), l; atol=1e-8)\n\n    # mesh as flat line segments (GR's wireframe chokes on matrix grids); a mesh\n    # rather than a surface so the self-intersecting interior stays visible\n    lg = range(0, 2π, length=120)  # points along each grid line\n    lk = range(0, 2π, length=40)   # grid lines\n    xs = Float64[]\n    ys = Float64[]\n    zs = Float64[]\n    for βj in lk\n        for αi in lg\n            push!(xs, (a + l * cos(βj)) * cos(αi))\n            push!(ys, (a + l * cos(βj)) * sin(αi))\n            push!(zs, l * sin(βj))\n        end\n        push!(xs, NaN)\n        push!(ys, NaN)\n        push!(zs, NaN)\n    end\n    for αj in lk\n        for βi in lg\n            push!(xs, (a + l * cos(βi)) * cos(αj))\n            push!(ys, (a + l * cos(βi)) * sin(αj))\n            push!(zs, l * sin(βi))\n        end\n        push!(xs, NaN)\n        push!(ys, NaN)\n        push!(zs, NaN)\n    end\n\n    fig = plot(xs, ys, zs; c=:black, alpha=0.4, lw=0.5, aspect_ratio=:equal,\n        xlabel=\"x (m)\", ylabel=\"y (m)\", zlabel=\"z (m)\",\n        title=\"Spindle torus, not to scale\", label=\"\", legend=:outerright)\n\n    # set of possible arm-tip positions: circle of radius a in the xy-plane\n    θc = range(0, 2π, length=200)\n    arm_tip_pars = (; c=:blue, lw=3, label=\"Arm-tip locus\")\n    plot!(fig, a * cos.(θc), a * sin.(θc), zero(θc); arm_tip_pars..., label=\"\")\n\n    # example arm and kite at α = 0, β = 30°\n    arm_and_lines_pars = (; c=:black, lw=3, label=\"Arm and lines\")\n    plot!(fig, [0, a], [0, 0], [0, 0]; arm_and_lines_pars..., label=\"\")\n    plot!(fig, [a, kite_pos[1]], [0, 0], [0, kite_pos[3]]; arm_and_lines_pars..., label=\"\")\n\n    longitude_pars = (; c=:orange, lw=2, label=\"Kite longitude\")\n    latitude_pars = (; c=:green, lw=2, label=\"Kite latitude\")\n    plot!(fig, a .+ l .* cos.(θc), zero(θc), l .* sin.(θc); longitude_pars..., label=\"\")\n    plot!(fig, (a + l * cos(β0)) .* cos.(θc), (a + l * cos(β0)) .* sin.(θc), fill(l * sin(β0), length(θc)); latitude_pars..., label=\"\")\n\n    kite_pars = (; c=:red, ms=7, label=\"Kite\")\n    scatter!(fig, [kite_pos[1]], [0], [kite_pos[3]]; kite_pars..., label=\"\")\n\n    scatter!([]; kite_pars..., msw=20, msc=:red)\n    plot!([]; arm_and_lines_pars..., lw=default(:lw))\n    plot!([]; arm_tip_pars..., lw=default(:lw))\n    plot!([]; longitude_pars..., lw=default(:lw))\n    plot!([]; latitude_pars..., lw=default(:lw))\n    plot!(leftmargin=-4Plots.mm, rightmargin=-20Plots.mm)\n    plot!(size=plot_size(1, 1.06))\n    # one tick at each end of each axis, plus 0 when it is interior\n    plot!(fig, xticks=edge_ticks(fig[1], :x; include_zero=true),\n        yticks=edge_ticks(fig[1], :y; include_zero=true),\n        zticks=edge_ticks(fig[1], :z; include_zero=true))\n\n    files = save_figure(fig, \"spindle_torus\")\n    #endregion\n\n    #region eight_plot\n    ## Parametrisation in tau\n    τ_φ = 90.0\n    τ_θ = 225.0\n    dx, dy = 1 / 4, 1 / 2\n    up_col, down_col = 1, 2\n\n    τ = range(0, 360, length=501)\n    θ = τ -> sind(2 * τ)\n    φ = τ -> sind(τ)\n\n    plot(xmirror=true)\n    plot!(xticks=([-1, 0, 1], (raw\"$-Δφ$\", raw\"$φ = 0$\", raw\"$Δφ$\")),\n        yticks=([-1, 0, 1], (raw\"$θ_0 + Δθ$\", raw\"$θ = θ_0$\", raw\"$θ_0 - Δθ$\"))\n    )\n\n    plot!(φ.(τ), θ.(τ), c=:grey)\n\n    plot!(φ.([0, τ_φ]), θ.([τ_φ, τ_φ]), color=:black)\n    annotate!(sum(φ.([0, τ_φ])) / 2, sum(θ.([τ_φ, τ_φ])) / 2 - 0.1, (raw\"$Δφ$\", ANNOTATIONFONTSIZE, :black, :top))\n\n    plot!(φ.([τ_θ, τ_θ]), θ.([τ_θ, 0]), color=:black)\n    annotate!(sum(φ.([τ_θ, τ_θ])) / 2 + 0.05, sum(θ.([τ_θ, 0])) / 2, (raw\"$Δθ$\", ANNOTATIONFONTSIZE, :black, :left))\n    quiver!([0], [0], quiver=([dx], [-dy]), c=up_col)\n    quiver!([0], [0], quiver=([-dx], [dy]), c=down_col)\n    annotate!(dx - 0.05, -dy - 0.25, (raw\"$\\dot{\\tau} > 0$\", ANNOTATIONFONTSIZE, :center, PALETTE[up_col]))\n    annotate!(-dx + 0.05, dy + 0.25, (raw\"$\\dot{\\tau} < 0$\", ANNOTATIONFONTSIZE, :center, PALETTE[down_col]))\n    plot!(size=SIZE_HALF .* (1, 0.5), topmargin=1Plots.mm, leftmargin=5Plots.mm)\n    append!(files, save_figure(current(), \"eight_plot\"))\n    #endregion\n    return files\nend\n\nif abspath(PROGRAM_FILE) == @__FILE__\n    run_modelling()\nend"},{"title":"src/numerics_10d.jl","page":"src/numerics_10d.jl","location":"code/src-numerics_10d-jl.html#src/numerics_10d.jl","category":"section","text":"View on GitHub (commit 2cfaacd).\n\n# Appendix A figures (10D model): drift of the raw 10D model and the effect of the\n# manifold projection callback.\n#\n# Outputs: figs/trajectory_10D_short_long_cb.{pdf,png}, figs/residuals_10D_interp.{pdf,png}.\nusing KEEP: PointMass10 as PM10\nusing KEEP: PointMass4 as PM4\nusing KEEP: PointMassPara as PMP\nusing KEEP: Visualization as VIZ\n\nusing OrdinaryDiffEqTsit5: Tsit5\n\nusing Plots\nusing PyFormattedStrings\nusing LinearAlgebra: norm\n\ninclude(joinpath(@__DIR__, \"helpers.jl\"))\n\nfunction run_10d(; fast::Bool=false)\n    #region setup_10d\n    ## Setup\n    p = PMP.build_para()\n    τ0, dτ0 = 1e-10, 10\n    u0_10 = PM10.init_u(τ0, dτ0, p)\n\n    # Projection callback: its tolerance is independent of the integrator tolerance.\n    cb_tol = 1e-10\n    callback = PM10.build_manifold_projection(u0_10; save=true, tol=cb_tol)\n    callback_no_save = PM10.build_manifold_projection(u0_10; save=false, tol=cb_tol)\n    #endregion\n\n    #region traj_10d\n    # Physical plots at loose tolerance, to exaggerate the drift of the raw 10D model.\n    tf_short, tf, tol = 20, 100, 1e-3\n    sol10 = PM10.integrate(u0_10, tf, p, Tsit5(); save_everystep=true, tol)\n    sol10_cb = PM10.integrate(u0_10, tf, p, Tsit5(); save_everystep=true, tol, callback=callback_no_save)\n\n    ## 10D, Tsit5, tol=1e-3, tf = 20 vs 100 s vs callback\n    points_per_second = 30\n    fig_traj_short = VIZ.plot_trajectory_10D(sol10; tspan=(0, tf_short), points_per_second)\n    fig_traj = VIZ.plot_trajectory_10D(sol10; points_per_second)\n    fig_traj_cb = VIZ.plot_trajectory_10D(sol10_cb; points_per_second)\n    params = (; xlabel=\"x (m)\", ylabel=\"y (m)\", zlabel=\"z (m)\", legend=false, widen=false)\n    plot!(fig_traj_short; title=\"tf = 20 s\", params..., legend=:topleft)\n    plot!(fig_traj; title=\"tf = 100 s\", params...)\n    plot!(fig_traj_cb; title=\"tf = 100 s + callback\", params...)\n    tf_fig = plot(fig_traj_short, fig_traj, fig_traj_cb, layout=(1, 3), size=SIZE_FULL)\n    # one tick at each end of each axis, plus 0 when it is interior\n    for i in 1:3\n        plot!(tf_fig, subplot=i,\n            xticks=edge_ticks(tf_fig[i], :x; include_zero=true),\n            yticks=edge_ticks(tf_fig[i], :y; include_zero=true),\n            zticks=edge_ticks(tf_fig[i], :z; include_zero=true))\n    end\n    files = save_figure(tf_fig, \"trajectory_10D_short_long_cb\")\n    #endregion\n\n    #region residuals_10d\n    ## Interpolated residuals\n    tf_long = fast ? 100 : 1000\n    sol10 = PM10.integrate(u0_10, tf_long, p, Tsit5(); save_everystep=true, tol=1e-6)\n    sol10_cb_t = PM10.integrate(u0_10, tf_long, p, Tsit5(); save_everystep=true, tol=1e-6, callback=callback_no_save)\n\n    ts = logrange(1, sol10.prob.tspan[2], 501)\n    res = [PM10.manifold_residuals!(similar(u0_10, 6), sol10(t), p) for t in ts]\n    res_cb = [PM10.manifold_residuals!(similar(u0_10, 6), sol10_cb_t(t), p) for t in ts]\n    ylim = exp10.((-9.5, 0.5))\n    xticks_ = exp10.(-18:1:10)\n    yticks_ = exp10.(-18:3:10)\n\n    plot(; xscale=:log10, xticks=xticks_, xformatter=x -> \"\", ylim, yscale=:log10, yticks=yticks_, ylabel=\"Residual on position (m)\", legend=:topleft)\n    plot!(ts, norm.(getindex.(res, Ref(1:3))), label=\"Without callback\")\n    fig_pos = plot!(ts, norm.(getindex.(res_cb, Ref(1:3))), label=\"With callback\")\n\n    plot(; xscale=:log10, xticks=xticks_, xlabel=\"Time (s)\", ylim, yscale=:log10, yticks=yticks_, ylabel=\"Residual on speed (m/s)\")\n    plot!(ts, norm.(getindex.(res, Ref(4:6))))\n    fig_speed = plot!(ts, norm.(getindex.(res_cb, Ref(4:6))))\n    plot(fig_pos, fig_speed, layout=(2, 1), size=SIZE_HALF .* (1, 1.5))\n    plot!(bottommargin=3Plots.mm, leftmargin=6Plots.mm)\n    append!(files, save_figure(current(), \"residuals_10D_interp\"))\n    #endregion\n    return files\nend\n\nif abspath(PROGRAM_FILE) == @__FILE__\n    run_10d()\nend"},{"title":"figs/cone_eight.tex","page":"figs/cone_eight.tex","location":"code/figs-cone_eight-tex.html#figs/cone_eight.tex","category":"section","text":"View on GitHub (commit 2cfaacd).\n\n\\documentclass[tikz,border=2pt]{standalone}\n\\usepackage[dvipsnames]{xcolor}\n\\usepackage{mathrsfs}\n\\usepackage{tikz-3dplot}\n\\begin{document}\n% Cone over the spherical eight, and a kite trajectory drawn on it (not to scale).\n\\tdplotsetmaincoords{78}{100}\n\\begin{tikzpicture}[tdplot_main_coords, scale=2.4, line join=round]\n\n% ---- parameters (angles in degrees; exaggerated for readability) ----\n\\def\\thetaZero{55} \\def\\DeltaTheta{16} \\def\\DeltaPhi{42}\n\\def\\ell{1.9} \\def\\a{0.7} \\def\\Rmax{2.9}\n\n\\pgfmathdeclarefunction{thf}{1}{\\pgfmathparse{\\thetaZero + \\DeltaTheta*sin(2*#1)}}\n\\pgfmathdeclarefunction{phf}{1}{\\pgfmathparse{\\DeltaPhi*sin(#1)}}\n\\pgfmathdeclarefunction{ux}{1}{\\pgfmathparse{sin(thf(#1))*cos(phf(#1))}}\n\\pgfmathdeclarefunction{uy}{1}{\\pgfmathparse{sin(thf(#1))*sin(phf(#1))}}\n\\pgfmathdeclarefunction{uz}{1}{\\pgfmathparse{cos(thf(#1))}}\n% arm angle along the orbit (any smooth law; only the shape of r matters here)\n\\pgfmathdeclarefunction{alf}{1}{\\pgfmathparse{40 + 60*sin(#1) + 0.14*#1}}\n\\pgfmathdeclarefunction{pf}{1}{\\pgfmathparse{\\a*sin(thf(#1))*cos(phf(#1)-alf(#1))}}\n\\pgfmathdeclarefunction{rf}{1}{\\pgfmathparse{pf(#1) + sqrt(pf(#1)*pf(#1) + \\ell*\\ell - \\a*\\a)}}\n\n% ---- axes ----\n\\draw[->,gray] (0,0,0) -- (1.5,0,0) node[below left,black]{$x$};\n\\draw[->,gray] (0,0,0) -- (0,1.5,0) node[right,black]{$y$};\n\\draw[->,gray] (0,0,0) -- (0,0,1.6) node[above,black]{$z$};\n\n% ---- the unit sphere carrying the eight (very light) ----\n\\begin{scope}[tdplot_screen_coords]\n  \\shade[ball color=gray!35,opacity=0.28] (0,0) circle (1);\n  \\draw[gray!55,opacity=0.5,thin] (0,0) circle (1);\n\\end{scope}\n\\foreach \\p in {-60,-30,...,60}{\n  \\draw[gray!60,opacity=0.35,very thin,domain=0:360,samples=121,variable=\\t]\n    plot ({cos(\\p)*cos(\\t)},{cos(\\p)*sin(\\t)},{sin(\\p)});\n}\n\\foreach \\m in {0,30,...,150}{\n  \\draw[gray!60,opacity=0.35,very thin,domain=0:360,samples=121,variable=\\t]\n    plot ({cos(\\t)*cos(\\m)},{cos(\\t)*sin(\\m)},{sin(\\t)});\n}\n\n% ---- cone: one translucent fill (no seams) and generators ----\n\\foreach \\ta/\\tb in {0/180,180/360}{\n  \\fill[SkyBlue,opacity=0.22]\n    (0,0,0) -- plot[domain=\\ta:\\tb,samples=361,variable=\\t]\n    ({\\Rmax*ux(\\t)},{\\Rmax*uy(\\t)},{\\Rmax*uz(\\t)}) -- cycle;\n}\n% generators\n\\foreach \\t in {0,6,...,354}{\n  \\draw[SkyBlue!80!black,opacity=0.5,very thin]\n    (0,0,0) -- ({\\Rmax*ux(\\t)},{\\Rmax*uy(\\t)},{\\Rmax*uz(\\t)});\n}\n% rim of the cone at r = Rmax\n\\draw[SkyBlue!80!black,opacity=0.7]\n  plot[domain=0:360,samples=721,variable=\\t] ({\\Rmax*ux(\\t)},{\\Rmax*uy(\\t)},{\\Rmax*uz(\\t)});\n\n% ---- the eight on the unit sphere ----\n\\draw[very thick,black]\n  plot[domain=0:360,samples=721,variable=\\t] ({ux(\\t)},{uy(\\t)},{uz(\\t)});\n\\node[black] at ({ux(270)},{uy(270)},{uz(270)-0.13}) {$\\mathscr{E}$};\n\n% ---- kite trajectory on the cone ----\n\\draw[very thick,BrickRed,-latex]\n  plot[domain=0:500,samples=1001,variable=\\t] ({rf(\\t)*ux(\\t)},{rf(\\t)*uy(\\t)},{rf(\\t)*uz(\\t)});\n\n% one generator highlighted: eight point, kite position\n\\def\\tk{62}\n\\draw[dashed,black] (0,0,0) -- ({rf(\\tk)*ux(\\tk)},{rf(\\tk)*uy(\\tk)},{rf(\\tk)*uz(\\tk)});\n\\fill[black]  ({ux(\\tk)},{uy(\\tk)},{uz(\\tk)}) circle (0.7pt);\n\\fill[BrickRed] ({rf(\\tk)*ux(\\tk)},{rf(\\tk)*uy(\\tk)},{rf(\\tk)*uz(\\tk)}) circle (1.2pt)\n  node[above right]{$K$};\n\\fill (0,0,0) circle (0.8pt) node[below left]{$O$};\n\n% label of the cone\n\\node[SkyBlue!60!black] at ({1.04*\\Rmax*ux(120)},{1.04*\\Rmax*uy(120)},{1.04*\\Rmax*uz(120)}) {$\\mathscr{C}$};\n\\end{tikzpicture}\n\\end{document}"},{"title":"figs/configuration.tex","page":"figs/configuration.tex","location":"code/figs-configuration-tex.html#figs/configuration.tex","category":"section","text":"View on GitHub (commit 2cfaacd).\n\n\\documentclass{standalone}\n\\usepackage[dvipsnames]{xcolor}\n\\usepackage{tikz}\n\\usetikzlibrary{3d}\n\\usepackage{tikz-3dplot}\n\\begin{document}\n\n% Set main 3D view (z-up, y-in)\n\\tdplotsetmaincoords{70}{-10}\n\n\\begin{tikzpicture}[tdplot_main_coords, scale=2]\n\n% ==== ORIGIN AND AXES ====\n\\coordinate (O) at (0,0,0);\n\\node[circle,fill,inner sep=1pt] at (O) {};\n\\node[below] at (O) {O};\n\n\\draw[->] (0,0,0) -- (3,0,0) node[anchor=west]{$x$};\n\\draw[->] (0,0,0) -- (0,1,0) node[anchor=south]{$y$};\n\\draw[->] (0,0,0) -- (0,0,2) node[anchor=west]{$z$};\n\n% ==== POINT A IN XY-PLANE ====\n\\def\\a{2}\n\\def\\alphaA{20}\n\\pgfmathsetmacro{\\xA}{\\a*cos(\\alphaA)}\n\\pgfmathsetmacro{\\yA}{\\a*sin(\\alphaA)}\n\\coordinate (A) at (\\xA, \\yA, 0);\n\\node[circle,fill,inner sep=1pt] at (A) {};\n\\node[below] at (A) {A};\n\n% Projections of A\n\\coordinate (Ax) at (\\xA, 0, 0);\n\\coordinate (Ay) at (0, \\yA, 0);\n\n% Lines from O\n\\draw (O) -- (A) node[midway, sloped, above] {$a$};\n\\draw (O) -- (Ax);\n\\draw (O) -- (Ay);\n\n% ==== POINT K ====\n\\def\\l{2}\n\\def\\thetaZero{70}\n\\def\\DeltaTheta{5}\n\\def\\DeltaPhi{30}\n\\def\\tauK{90}\n\n\\pgfmathdeclarefunction{thetaFunc}{1}{\\pgfmathparse{\\thetaZero + \\DeltaTheta * sin(2*#1)}}\n\\pgfmathdeclarefunction{phiFunc}{1}  {\\pgfmathparse{\\DeltaPhi * sin(#1)}}\n\\pgfmathdeclarefunction{xTauFunc}{1} {\\pgfmathparse{sin(thetaFunc(#1)) * cos(phiFunc(#1))}}\n\\pgfmathdeclarefunction{yTauFunc}{1} {\\pgfmathparse{sin(thetaFunc(#1)) * sin(phiFunc(#1))}}\n\\pgfmathdeclarefunction{zTauFunc}{1} {\\pgfmathparse{cos(thetaFunc(#1))}}\n\n\\pgfmathsetmacro{\\dotprod}{\\xA * xTauFunc(\\tauK) + \\yA * yTauFunc(\\tauK)}\n\\pgfmathsetmacro{\\rK}{\\dotprod + sqrt(\\dotprod * \\dotprod + \\l^2 - \\a^2)}\n\n\\pgfmathsetmacro{\\xK}{\\rK * xTauFunc(\\tauK)}\n\\pgfmathsetmacro{\\yK}{\\rK * yTauFunc(\\tauK)}\n\\pgfmathsetmacro{\\zK}{\\rK * zTauFunc(\\tauK)}\n\n\\coordinate (K) at (\\xK, \\yK, \\zK);\n\\coordinate (K_xy) at (\\xK, \\yK, 0);\n\n% Helper points from A\n\\pgfmathsetmacro{\\xAel}{\\xA}\n\\pgfmathsetmacro{\\yAel}{\\yA}\n\\pgfmathsetmacro{\\zAel}{1.5}\n\\coordinate (A_el) at (\\xAel, \\yAel, \\zAel);\n\n\\pgfmathsetmacro{\\xAext}{1.5*\\xA}\n\\pgfmathsetmacro{\\yAext}{1.5*\\yA}\n\\coordinate (A_ext) at (\\xAext, \\yAext, 0);\n\n% Draw K and lines\n\\node[circle,fill,inner sep=1pt] at (K) {};\n\\node[above] at (K) {K};\n\n\\draw (A) -- (K) node[midway, sloped, below] {$\\ell$};\n\\draw[dotted, blue] (O) -- (K) node[pos=0.5, sloped, above] {$r(\\alpha, \\tau)$};\n\n%\\draw[dotted] (A) -- (A_ext);\n\\draw[dotted] (K) -- (K_xy) -- (A);\n\\draw[dotted, blue] (K_xy) -- (O);\n%\\draw[dotted] (A) -- (A_el);\n\n% ==== ANGLES ====\n% alpha\n\\tdplotdefinepoints(0,0,0)(1,0,0)(\\xA,\\yA,0)\n\\tdplotdrawpolytopearc[->, OrangeRed, thick]{1.3}{right, OrangeRed}{$\\alpha$}\n\n% phi\n\\tdplotdefinepoints(0,0,0)(1,0,0)(\\xK,\\yK,0)\n\\tdplotdrawpolytopearc[->, blue, thick]{2.7}{above right, blue}{$\\phi(\\tau)$}\n\n% theta\n\\tdplotdefinepoints(0,0,0)(0,0,1)(\\xK,\\yK,\\zK)\n\\tdplotdrawpolytopearc[->, blue, thick]{1}{above, blue}{$\\theta(\\tau)$}\n\n% % phi_ℓ\n% \\tdplotdefinepoints(\\xA,\\yA,0)(\\xAext,\\yAext,0)(\\xK,\\yK,0)\n% \\tdplotdrawpolytopearc[->]{1}{anchor=south west}{$\\phi_\\ell$}\n\n% % theta_ℓ\n% \\tdplotdefinepoints(\\xA,\\yA,0)(\\xAel,\\yAel,\\zAel)(\\xK,\\yK,\\zK)\n% \\tdplotdrawpolytopearc[->]{0.8}{anchor=north}{$\\theta_\\ell$}\n\n\\newcommand{\\KCoord}[2]{({#1 * xTauFunc(#2)}, {#1 * yTauFunc(#2)}, {#1 * zTauFunc(#2)})}\n\n% tau and eight\n\\draw[domain = 0:360, samples = 20, smooth, dashed, variable = \\t]\n    plot (\\KCoord{\\rK}{\\t});\n\\draw[->, domain = 0:\\tauK, samples = 10, smooth, OrangeRed, thick, variable = \\t]\n    plot (\\KCoord{\\rK}{\\t});\n\n\n\\node[below, OrangeRed] at \\KCoord{\\rK}{\\tauK/2} {$\\tau$};\n\n\n\\end{tikzpicture}\n\n\\end{document}"},{"title":"src/optimization.jl","page":"src/optimization.jl","location":"code/src-optimization-jl.html#src/optimization.jl","category":"section","text":"View on GitHub (commit 2cfaacd).\n\n# Section 3 figures and Tables 2-4: optimization of the design parameters\n# Θ = (ℓ, I, b, Δφ) (tether length, arm inertia, braking coefficient, lemniscate\n# half-width) at the reference wind speed, then at each wind speed, and the\n# sensitivity to the lemniscate half-height Δθ (held fixed in the optimization).\n#\n# The reference is the default parameters with the torque slope set by the\n# kinetic criterion b = I ω (`PMP.optimal_torque_slope`, one limit cycle per\n# iteration), not the default torque slope. The optimizations are limited by an\n# iteration count (not by wall-clock time), so the results do not depend on the\n# machine; `fast=true` shrinks the limits and the grids to test the workflow.\n#\n# Outputs: figs/{optimization_wind_sweep_{power,tension,params},optimization_dtheta,\n# optimization_landscape,optimization_timeseries_all}.{pdf,png} and\n# tables/table{2,3,4}.tex.\n#\n# Not part of the paper build (kept in applications/jtcam/Section_Optimization.jl):\n# the 10×10 shape map and the console report.\nusing KEEP: PointMass4 as PM4\nusing KEEP: PointMassPara as PMP\nusing KEEP: LimitCycle as LC\nusing KEEP: Optimization as OPT\n\nusing Plots\nusing PyFormattedStrings: @f_str\nusing SplitApplyCombine: invert\nusing Logging: with_logger, NullLogger\nusing LinearAlgebra: norm, eigvals\nimport ForwardDiff\n\ninclude(joinpath(@__DIR__, \"helpers.jl\"))\n\n\n## Settings\nconst TOL = 1e-5\n# Ipopt iteration limits (a converged solve takes a few dozen iterations); the\n# wall-clock time is only a safety net that is not expected to bind.\nconst MAX_ITER = 300\nconst SWEEP_MAX_ITER = 150\nconst DTHETA_MAX_ITER = 300   # per continuation step of `dtheta_opt_sweep` (warm start)\nconst DTHETA_STEP = 0.5       # largest continuation step in Δθ (deg)\nconst DTHETA_MIN_STEP = 0.05  # a step that fails is halved down to this (deg)\nconst WALL_SAFETY = 3600.0\nconst WIND_REF = 9.0\nconst SENSE = +\nconst SYMS = [:l, :I, :b, :Δφ]  # ℓ, I, b and the half-width\nconst L_BOUNDS = (15.0, 200.0)               # tether length ℓ (m)\nconst B_BOUNDS = (1.0, 1.0e6)                # braking slope b\n# Assumptions for I lower bound :\n# Maximum line tension T ≈ 34 kN at w0 = 15 m/s\n# Moment is then M = T a = 68 kN m. For 6061-T6 (σy ≈ 276 MPa) with a safety factor 2,\n# W = M/σallow ≈ 491 cm³, met by a Ø250 mm tube with an 11.5 mm wall (47 kg).\n# Its inertia about the pivot is I = m p.a²/3 ≈ 62 kg m² (solid bar: 165 kg m²).\n# No upper bound: extra mass is allowed if it buys power.\nconst I_BOUNDS = (62.0, 1.0e6)               # arm inertia I (kg m²)\nconst DPHI_BOUNDS = deg2rad.((10.0, 90.0))   # fixed shape box, in radians\nconst DTHETA_RANGE = (2.0, 20.0)              # Δθ sweep, in degrees\nconst GLIDE_LOW = 5                           # glide ratio of the sensitivity remark (soft kites: 4-6)\nconst PTO_TS = 1000.0                         # max wing loading T_s (N/m²) of the PTO estimate\n\n# Marks shared by the wind sweep, the landscape and the Δθ plots: the floor of\n# the landscape's y axis, the translucent band that marks the reference\n# condition (the same as at the reference wind speed) and the thin line of the\n# horizontal floor. Built here and passed to the plot functions.\nconst GUIDES = (; ymin=0.9, line=(; c=:black, lw=5, alpha=0.3),\n    floor=(; c=:black, lw=1, alpha=1))\n\n# Parameter names, units and scales from the stored value to the displayed one.\n# An angle is rad2deg; a per-angle unit is the inverse, so that b·dα stays a\n# torque when dα is read in deg/s.\nconst TEX = Dict(:l => (raw\"$\\ell$\", raw\"\\si{\\meter}\", identity),\n    :I => (raw\"$I$\", raw\"\\si{\\kilogram\\meter\\squared}\", identity),\n    :b => (raw\"$b$\", raw\"\\si{\\newton\\meter\\second\\per\\degree}\", x -> x / rad2deg(1)),\n    :Δφ => (raw\"$\\Delta\\varphi$\", raw\"\\si{\\degree}\", rad2deg))\n\n# Parameter names and units for the axis titles and the legends\nconst LABELS = Dict(:l => \"ℓ\", :I => \"I\", :b => \"b\",\n    :Δθ => \"Δθ\", :Δφ => \"Δφ\")\nconst UNITS = Dict(:l => \"m\", :I => \"kg m²\", :b => \"N m deg s⁻¹\",\n    :Δθ => \"deg\", :Δφ => \"deg\")\n\n## Helpers\n## Helpers\n\"\"\"\nAverage power, line-tension extrema, peak kite acceleration and period of a cycle.\"\"\"\nfunction cycle_stats(sol; n=2001)\n    # `compute_limit_cycle` returns `nothing` when no periodic orbit was found: report\n    # NaN instead of crashing, so the caller treats the point as a failure.\n    sol === nothing && return (; P=NaN, Tmin=NaN, Tmax=NaN, amax=NaN, period=NaN)\n    ts = range(sol.t[1], sol.t[end], n)\n    us = sol.(ts)\n    p = sol.prob.p\n    tension = PM4.compute_line_tension.(us, Ref(p))\n    # the tension is exact everywhere (regular form, PM4._accelerations_tension)\n    all(isfinite, tension) || error(\"cycle_stats: non-finite line tension along the cycle\")\n    acceleration = norm.(PM4.kite_acceleration.(us, Ref(p)))\n    return (; P=sol.u[end][5] / sol.t[end],\n        Tmin=minimum(tension), Tmax=maximum(tension),\n        amax=maximum(acceleration), period=sol.t[end])\nend\n\n# Limit cycle, optimization, and limit cycle of the optimized system, for one\n# value of one parameter. `lower`/`upper` are the box constraints of `syms`.\n# `p_fixed` is the parameter set the no-optimization cycle is taken at, so a\n# continuation can start from a neighbour's optimum `p0` without moving the\n# reference curve. `guess` is Ipopt's initial guess (see `clamp_guess`), which\n# lets a retry start from the neighbouring cycle states instead of cold.\nfunction compute_results(param, value; syms, p0, p_fixed=p0, lower, upper, sense, tol,\n    iters=MAX_ITER, guess=(;))\n    p_fixed = copy(p_fixed)\n    p_fixed[param] = value\n\n    # Limit cycle at the reference parameters, before re-optimizing\n    vbp0 = PMP.build_vbpara(p_fixed)\n    lc0 = LC.compute_limit_cycle(vbp0; sense=sense, save_everystep=true, tol=tol)\n    stats_no_opt = cycle_stats(lc0)\n\n    # Optimize the selected parameters, starting from `p0`\n    p0 = copy(p0)\n    p0[param] = value\n    solution, stats, _ = with_logger(NullLogger()) do\n        OPT.optimize(p0, syms, lower, upper; sense, tol, max_iter=iters,\n            max_wall_time=WALL_SAFETY, initial_guess=guess)\n    end\n    p_opt = copy(p0)\n    p_opt[syms] .= solution.params[syms]  # physical units\n\n    # Limit cycle at the optimized parameters. A start that drifts to a corner of the\n    # box can return parameters whose cycle does not close (CI run 45900062200, 7 m/s:\n    # period 8 s): report the start as failed instead of stopping the whole sweep.\n    vbp = PMP.build_vbpara(p_opt)\n    lc = try\n        LC.compute_limit_cycle(vbp; sense=sense, save_everystep=true, tol=tol)\n    catch e\n        @warn \"no limit cycle at the optimized parameters: start discarded\" param value status = stats.status exception = e\n        return nothing\n    end\n    stats_opt = cycle_stats(lc)\n\n    return stats_no_opt, stats_opt, collect(p_opt[syms]), stats, solution\nend\n\n\"\"\"\nWind sweep: hold `p_ref` fixed, or re-optimize `syms` inside `lower`/`upper` at\neach wind speed, marching outward from the reference wind `i_ref`.\n\nKeeping `p_ref` is a feasible point of the optimization at every wind speed, so\na re-optimization that converges *below* the fixed curve is not the maximum\nthere: it is a different branch. Each wind speed therefore tries its starts in\norder (the reference, then the neighbouring wind's optimum with its cycle states\nas Ipopt's initial guess), keeps the best of them, and stops as soon as one\nbeats the fixed curve; if none does, the point is kept and a warning is emitted.\nThe wide boxes make the objective multimodal, so no single start succeeds at\nevery wind speed.\n\nReturns the statistics with and without re-optimization and the optimized\nparameters.\n\"\"\"\nfunction wind_sweep(syms, p_ref, winds, lower, upper, i_ref; rtol=1e-3, iters=SWEEP_MAX_ITER, strict=true)\n    n = length(winds)\n    no_opt = Vector{Any}(undef, n)\n    opt = Vector{Any}(undef, n)\n    theta = Vector{Vector{Float64}}(undef, n)\n    sols = Vector{Any}(undef, n)\n    ok = falses(n)\n    from_theta(θ) = (p=copy(p_ref); p[syms].=θ; p)\n    guess_of(j) = isassigned(sols, j) ? clamp_guess(sols[j]) : (;)\n\n    \"Starts at wind speed `i`: the reference, then the already-solved neighbour.\"\n    function starts(i)\n        i == i_ref && return ((p_ref, (;)),)\n        j = i < i_ref ? i + 1 : i - 1\n        isassigned(theta, j) || return ((p_ref, (;)),)\n        return ((p_ref, (;)), (from_theta(theta[j]), guess_of(j)), (p_ref, guess_of(j)))\n    end\n\n    function solve!(i)\n        best = nothing\n        for (p0, guess) in starts(i)\n            r = compute_results(:w0, winds[i];\n                syms, p0, p_fixed=p_ref, lower, upper, sense=SENSE, tol=TOL,\n                iters=iters, guess=guess)\n            r === nothing && continue  # no cycle at the optimized parameters\n            (!strict || r[4].status == :first_order) || continue  # strict=false: smoke tests keep unconverged points\n            (best === nothing || r[2].P > best[2].P) && (best = r)\n            # Keeping `p_ref` is always feasible, so the optimum cannot be below the\n            # fixed curve: a converged point below it is another branch, try the next start.\n            r[2].P >= r[1].P * (1 - rtol) && break\n        end\n        best === nothing && return (ok[i] = false)\n        no_opt[i], opt[i], theta[i], sols[i] = best[1], best[2], best[3], best[5]\n        ok[i] = opt[i].P >= no_opt[i].P * (1 - rtol)\n        return nothing\n    end\n\n    for i in i_ref:-1:1\n        @info \"  wind sweep $(i)/$(n): $(winds[i]) m/s\"\n        solve!(i)\n    end\n    for i in (i_ref+1):n\n        @info \"  wind sweep $(i)/$(n): $(winds[i]) m/s\"\n        solve!(i)\n    end\n    for i in eachindex(winds)\n        ok[i] && continue\n        isassigned(opt, i) || (@warn \"wind sweep at $(winds[i]) m/s: no converged re-optimization\"; continue)\n        @warn \"wind sweep at $(winds[i]) m/s: best re-optimization ($(round(opt[i].P / 1000; digits=3)) kW) does not beat the fixed parameters ($(round(no_opt[i].P / 1000; digits=3)) kW)\"\n    end\n    return (; syms, no_opt, opt, theta)\nend\n\nmaxnormalize(x) = x ./ maximum(x)\n\n\"\"\"\nNeighbour solution as an Ipopt initial guess. The cycle states are clamped just\ninside the box `OPT.optimize` asserts on: a cycle that starts at α = ±π puts the\nguess on the bound, which `optimize` rejects.\n\"\"\"\nclamp_guess(::Nothing) = (;)\nclamp_guess(s) = (; α0=clamp(s.α0, -π + 1e-6, π - 1e-6),\n    dα0=clamp(s.dα0, -100 + 1e-6, 100 - 1e-6),\n    dτ0=clamp(s.dτ0, 1e-6, 100 - 1e-6),\n    tf=clamp(s.tf, 1.1e-3, 99.0), P=clamp(s.P, 1.1e-3, 9.9e4))\n\n\"\"\"\nOne optimization step, limited to `iters` Ipopt iterations.\n\"\"\"\nfunction opt_step(p, syms, lower, upper; iters=MAX_ITER, strict=false)\n    solution, stats, _ = with_logger(NullLogger()) do\n        OPT.optimize(p, syms, lower, upper; sense=SENSE, tol=TOL, max_iter=iters,\n            max_wall_time=WALL_SAFETY)\n    end\n    if stats.status != :first_order\n        msg = \"opt_step($(join(syms, \", \"))) did not converge: $(stats.status) after $(stats.iter) iterations\"\n        strict ? error(msg) : @warn msg\n    end\n    p_next = copy(p)\n    p_next[syms] .= solution.params[syms]  # physical units\n    return (; p=p_next, P=solution.P, iter=stats.iter)\nend\n\n\"\"\"\nΔθ sweep at the optimum: take the limit cycle at each absolute angle (in\ndegrees) in `angles_deg` with Θ fixed. Starting from the same\n`u0 = (α, τ, dα, dτ) = (0, τ0, 0, 1)` picks the same (dτ > 0) pumping cycle at\nevery point.\n\"\"\"\nfunction dtheta_study(p, angles_deg; n=2001)\n    u0 = PM4.build_u(; dτ=1)\n    return map(angles_deg) do a\n        q = copy(p)\n        q.Δθ = deg2rad(a)\n        sol = LC.compute_limit_cycle(u0, PMP.build_vbpara(q);\n            tol=TOL, save_everystep=true, tf=100.0)\n        (; Δθ=a, cycle_stats(sol; n)...)\n    end\nend\n\n\"\"\"\nΔθ sweep with re-optimization, by continuation: march outward from the nominal\nangle `nominal` (degrees, where `p_ref` is the optimum) to each angle of\n`angles_deg`, in steps of at most `step` degrees, and re-optimize `syms` inside\n`lower`/`upper` at every step from the previous optimum, with its cycle states as\nIpopt's initial guess. Cold starts away from the nominal drift to the corners of\nthe loose `Θ` box (I, b up to 1e6) and fail; small warm-started steps stay on\nthe nominal branch. A failed step is retried with half the step, down to\n`min_step`; below it, the remaining angles on that side are reported as `NaN`,\nnot as a gain, and the angles where it is lost are returned (`NaN` if it is not).\n`iters` is the per-step iteration limit. Holding `Θ` at the\nnominal is always feasible, so a converged point below the fixed-`Θ` value is\nflagged (another branch). Statistics come from `dtheta_study` at the solved\npoint, i.e. from the same dτ > 0 cycle as the fixed curve.\n\"\"\"\nfunction dtheta_opt_sweep(p_ref, syms, angles_deg, lower, upper; nominal,\n    step=DTHETA_STEP, min_step=DTHETA_MIN_STEP, iters=DTHETA_MAX_ITER, rtol=1e-3)\n    function attempt(a, p0, g)\n        q = copy(p0)\n        q.Δθ = deg2rad(a)\n        try\n            solution, st, _ = with_logger(NullLogger()) do\n                OPT.optimize(q, syms, lower, upper; sense=SENSE, tol=TOL,\n                    max_iter=iters, max_wall_time=WALL_SAFETY, initial_guess=g)\n            end\n            p = copy(q)\n            p[syms] .= solution.params[syms]\n            return (p=p, ok=st.status == :first_order, sol=solution, P=solution.P, iter=st.iter)\n        catch\n            return (p=copy(p0), ok=false, sol=nothing, P=NaN, iter=0)\n        end\n    end\n    failed(a) = (; Δθ=a, P=NaN, Tmin=NaN, Tmax=NaN, amax=NaN, period=NaN)\n    function record(a, cur)\n        fixed = only(dtheta_study(p_ref, [a]))   # Θ held at the nominal\n        cur.P < fixed.P * (1 - rtol) &&\n            @warn \"re-optimization at Δθ = $(a)° is below the fixed Θ ($(round(fixed.P / 1000; digits=3)) kW): another branch\" cur.P\n        return only(dtheta_study(cur.p, [a]))\n    end\n    # the nominal point itself: p_ref is the optimum there, solve once for its cycle states\n    start = attempt(nominal, p_ref, (;))\n    start.ok || @warn \"Δθ continuation: the nominal re-optimization at $(nominal)° does not converge\"\n    stats = Vector{Any}(undef, length(angles_deg))\n    lost_at = Dict(-1 => NaN, +1 => NaN)  # where the continuation is lost, per side\n    for side in (-1, +1)\n        # the nominal angle itself (zero steps) goes with the right side\n        idx = findall(a -> side < 0 ? a < nominal - 1e-9 : a >= nominal - 1e-9, angles_deg)\n        sort!(idx; by=i -> abs(angles_deg[i] - nominal))\n        cur, a, h, lost = start, nominal, step, !start.ok\n        for i in idx\n            target = angles_deg[i]\n            while !lost && abs(target - a) > 1e-9\n                next = a + side * min(h, abs(target - a))\n                r = attempt(next, cur.p, clamp_guess(cur.sol))\n                if r.ok\n                    cur, a, h = r, next, min(step, 2h)\n                else\n                    h /= 2\n                    h < min_step && (lost = true; lost_at[side] = next;\n                        @warn \"Δθ continuation lost at $(round(next; digits=3))° (from $(a)°)\")\n                end\n            end\n            stats[i] = lost ? failed(target) : try\n                record(target, cur)\n            catch e  # no closed cycle at the solved point: a gap, not a crash\n                @warn \"Δθ = $(target)°: no limit cycle at the re-optimized parameters\" exception = e\n                failed(target)\n            end\n            @info \"  Δθ = $(target)°: \" * (lost ? \"failed\" : \"P = $(round(stats[i].P / 1000; digits=3)) kW\")\n        end\n    end\n    return (; stats, lost_below=lost_at[-1], lost_above=lost_at[+1])\nend\n\n\"\"\"\nObjective landscape around the optimal point `p`, one parameter at a time:\nscale one parameter by each factor `x ∈ [1 - window, 1 + window]`, keep the\nother parameters at their optimum, and take the power of the limit cycle at\nthose fixed parameters — the objective the optimizer maximizes once the cycle\nis solved. Powers are normalized by their value at `x = 1`, so the optimum\nplots at `(1, 1)`. `lower` and `upper` are the box constraints of `syms`\n(physical units), returned as normalized factors so the caller can mark them.\n\"\"\"\nfunction landscape(p, syms; lower, upper, window=0.1, npoints=21, tol=TOL)\n    xs = range(1 - window, 1 + window, length=npoints)\n    power(sym, x) = begin\n        q = copy(p)\n        q[sym] = x * p[sym]\n        lc = try\n            LC.compute_limit_cycle(PMP.build_vbpara(q); sense=SENSE, tol=tol)\n        catch\n            nothing        # no closed cycle with this sign: report a gap, not a crash\n        end\n        return lc === nothing ? NaN : lc.u[end][5] / lc.t[end]\n    end\n    vals = [power(sym, x) for sym in syms, x in xs]\n    k0 = findmin(abs.(xs .- 1))[2]  # the optimum, where the landscape is normalized\n    return (; xs=collect(xs), syms=collect(syms), window,\n        ys=[row ./ row[k0] for row in eachrow(vals)],\n        center=collect(p[syms]),  # the optimum in physical units, for the x axis\n        box=[(lo / p[sym], up / p[sym]) for (sym, lo, up) in zip(syms, lower, upper)])\nend\n\n## Tables\n\"One optimized parameter, in the units shown in the table.\"\nstruct OptVar\n    sym::String\n    unit::String\n    low::Float64\n    up::Float64\n    guess::Float64\n    sol::Float64\nend\n\n\"Limit-cycle statistics of one parameter set, plus the norm of its endpoint residual.\"\nfunction cycle_report(p)\n    sol = LC.compute_limit_cycle(PMP.build_vbpara(p); sense=SENSE, tol=TOL,\n        save_everystep=true)\n    return (; cycle_stats(sol)..., residual=norm(LC.endpoint_residuals(sol; sense=SENSE)))\nend\n\n\"Math-mode scientific notation, e.g. `\\$3.7\\\\times10^{-9}\\$`.\"\nfunction latex_sci(x)\n    x == 0 && return raw\"$0$\"\n    e = floor(Int, log10(abs(x)))\n    return raw\"$\" * string(round(x / exp10(e); digits=1)) * raw\"\\times10^{\" *\n        string(e) * raw\"}$\"\nend\n\n\"\"\"\nThe two siunitx tables of the optimization section: the boxes of Θ = (ℓ, I, b,\nΔφ) and the optimization results at `WIND_REF`, initial guess against solution.\nEvery number comes from `p_init`, `p_opt` and their limit cycles; Δφ is shown in\ndegrees and b per degree. Δθ is held fixed, so it only enters the first caption.\n\"\"\"\nfunction latex_tables(p_init, p_opt, lower, upper)\n    s0, s1 = cycle_report(p_init), cycle_report(p_opt)\n    data = [\n        let (sym, unit, scale) = TEX[k]\n            OptVar(sym, unit, scale(lower[i]), scale(upper[i]),\n                scale(p_init[k]), scale(p_opt[k]))\n        end for (i, k) in enumerate(SYMS)\n    ]\n\n    # b per degree has a small lower bound (1 N m s/rad -> 0.0175)\n    num(x) = abs(x) < 0.1 ? f\"{x:.4f}\" : f\"{x:.1f}\"\n    bounds_rows = [f\"    {v.sym} ({v.unit}) & {num(v.low)} & {num(v.up)} \\\\\\\\ \" for v in data]\n    results_rows = [f\"    {v.sym} ({v.unit}) & {v.guess:.1f} & {v.sol:.1f} \\\\\\\\ \" for v in data]\n    push!(results_rows, raw\"    \\midrule\")\n    push!(results_rows, f\"    Average power (\\\\si{{\\\\kilo\\\\watt}}) & {s0.P / 1000:.2f} & {s1.P / 1000:.2f} \\\\\\\\ \")\n    push!(results_rows, f\"    Period (\\\\si{{\\\\second}}) & {s0.period:.2f} & {s1.period:.2f} \\\\\\\\ \")\n    push!(results_rows, f\"    Min line tension (\\\\si{{\\\\kilo\\\\newton}}) & {s0.Tmin / 1000:.2f} & {s1.Tmin / 1000:.2f} \\\\\\\\ \")\n    push!(results_rows, f\"    Max line tension (\\\\si{{\\\\kilo\\\\newton}}) & {s0.Tmax / 1000:.2f} & {s1.Tmax / 1000:.2f} \\\\\\\\ \")\n    push!(results_rows, \"    Norm of residual & {\" * latex_sci(s0.residual) * \"} & {\" *\n        latex_sci(s1.residual) * \"} \\\\\\\\ \")\n\n    table_descr = join([\n        raw\"\\begin{table}[thpb]\",\n        raw\"\\centering\",\n        raw\"\\caption{Description of the optimized parameters ($\\Delta\\theta = \\SI{\" *\n            string(round(rad2deg(p_init.Δθ); digits=2)) * raw\"}{\\degree}$ fixed).}\",\n        raw\"\\begin{tabular}{l S S}\",\n        raw\"    \\toprule\",\n        \"    {Symbol (Unit)} & {Lower bound} & {Upper bound} \\\\\\\\\",\n        raw\"    \\midrule\",\n        bounds_rows...,\n        raw\"    \\bottomrule\",\n        raw\"\\end{tabular}\",\n        raw\"\\label{tab:opt_descr}\",\n        raw\"\\end{table}\",\n    ], \"\\n\")\n\n    table_opt = join([\n        raw\"\\begin{table}[thpb]\",\n        raw\"\\centering\",\n        raw\"\\caption{Optimization results at $w_0 = \\SI{\" *\n            string(round(Int, WIND_REF)) * raw\"}{\\meter\\per\\second}$.}\",\n        raw\"\\begin{tabular}{l S S}\",\n        raw\"    \\toprule\",\n        \"    {Symbol (Unit)} & {Initial Guess} & {Solution} \\\\\\\\\",\n        raw\"    \\midrule\",\n        results_rows...,\n        raw\"    \\bottomrule\",\n        raw\"\\end{tabular}\",\n        raw\"\\label{tab:opt_results}\",\n        raw\"\\end{table}\",\n    ], \"\\n\")\n\n    return table_descr, table_opt\nend\n\n\"\"\"\nCurvature of the kite trajectory without arm (a = 0), for the eight of `p`: the\ngeodesic curvature κ_g of the spherical eight (section \"Curvature of the kite\ntrajectory\") and ℓκ = √(1 + κ_g²), at the lobe tip τ = π/2 and maximized over a\nfine τ grid.\n\"\"\"\nfunction curvature_stats(p; n=200_000)\n    Δθ, Δφ, θ0 = p.Δθ, p.Δφ, p.θ0\n    function κg(τ)\n        θ = θ0 + Δθ * sin(2τ)\n        v = sqrt(4Δθ^2 * cos(2τ)^2 + Δφ^2 * sin(θ)^2 * cos(τ)^2)\n        return (2Δθ * Δφ * sin(θ) * sin(τ) * (2 + cos(2τ)) +\n                Δφ * cos(θ) * cos(τ) * (8Δθ^2 * cos(2τ)^2 + Δφ^2 * sin(θ)^2 * cos(τ)^2)) / v^3\n    end\n    K(τ) = sqrt(1 + κg(τ)^2)\n    τs = range(0, 2π, n + 1)[1:end-1]\n    Ks = K.(τs)\n    i = argmax(Ks)\n    # κ(τ + π) = κ(τ) (κ_g changes sign): report the maximizer modulo π, independent of\n    # which of the two symmetric grid points argmax picks\n    return (; kg_tip=κg(π / 2), K_tip=K(π / 2), K_max=Ks[i], τ_max=mod(τs[i], π))\nend\n\n\"\"\"\nFloquet multipliers of the dτ > 0 cycle of `p`: the largest modulus among the three\nnon-trivial ones (`μ`) and the error on the trivial multiplier 1 (`err`), from the\nmonodromy matrix computed by forward-mode AD through the integrator.\n\"\"\"\nfunction floquet(p)\n    vbp = PMP.build_vbpara(p)\n    lc = LC.compute_limit_cycle(vbp; sense=SENSE, save_everystep=true)\n    T = lc.t[end]\n    flow = y -> PM4.integrate(PM4.build_u(y[1], y[2], y[3], y[4], zero(y[1])), T, vbp).u[end][1:4]\n    μ = eigvals(ForwardDiff.jacobian(flow, collect(lc.u[1][1:4])))\n    itriv = argmin(abs.(μ .- 1))\n    return (; μ=maximum(abs, μ[setdiff(eachindex(μ), itriv)]), err=abs(μ[itriv] - 1))\nend\n\n\"\"\"\nA posteriori curvature check on the optimized cycle of `p` (dτ > 0), with the arm: the\ncurvature κ = ‖ṙ × r̈‖/‖ṙ‖³ of the kite trajectory, maximized over the cycle; the bounds\nA₁ = max|α'|, A₂ = max|α''| (prime = d/dτ) of the arm law along the cycle; and the upper\nbound (eq:curv-bound) evaluated with the box of the optimization (ℓ ≥ ℓ₋ = L_BOUNDS[1],\nΔφ in DPHI_BOUNDS, Δθ and θ0 fixed), and at the design point itself (ℓ₋ = ℓ, Δφ₋ = Δφ₊ =\nΔφ), with these A₁, A₂. Returns radii (m): `rmin` the smallest radius of curvature of\nthe cycle, `rbox` and `rpt` the radii guaranteed by the bound (both ≤ `rmin`, checked).\n\"\"\"\nfunction curvature_check(p; n=4000)\n    vbp = PMP.build_vbpara(p)\n    lc = LC.compute_limit_cycle(vbp; sense=SENSE, tol=TOL, save_everystep=true)\n    vel(u) = (k = PM4._kinematics(u[1], u[2], vbp);\n              (k.R_α * u[3] + k.R_τ * u[4]) * k.rhat + k.R * u[4] * k.rhatp)\n    cross3(x, y) = (x[2]y[3] - x[3]y[2], x[3]y[1] - x[1]y[3], x[1]y[2] - x[2]y[1])\n    rows = map(range(0, lc.t[end], n + 1)[1:end-1]) do t\n        u = collect(lc(t)[1:4])\n        du = PM4.dynamics(u, vbp)[1:4]\n        v = vel(u)\n        acc = ForwardDiff.derivative(s -> vel(u .+ s .* du), 0.0)\n        κ = norm(collect(cross3(v, acc))) / norm(v)^3\n        α1 = u[3] / u[4]                                   # α' = α̇/τ̇\n        α2 = (du[3] * u[4] - u[3] * du[4]) / u[4]^3          # α'' = (α̈τ̇ - α̇τ̈)/τ̇³\n        (; κ, α1, α2)\n    end\n    κmax = maximum(r -> r.κ, rows)\n    A1, A2 = maximum(r -> abs(r.α1), rows), maximum(r -> abs(r.α2), rows)\n    # bound (eq:curv-bound) on a box: ℓ ≥ ℓm, Δφ in [Δφm, Δφp], Δθ and θ0 fixed\n    function κbound(ℓm, Δφm, Δφp)\n        a, Δθm, Δθp = p.a, p.Δθ, p.Δθ\n        J = (p.θ0 - Δθp, p.θ0 + Δθp)\n        0 < J[1] && J[2] < π || error(\"curvature bound: J not in (0, π)\")\n        js = range(J..., 10_001)\n        m, M, C = minimum(sin, js), maximum(sin, js), maximum(x -> abs(cos(x)), js)\n        vstar = m * Δφm >= 4Δθm ? 2Δθm : m * Δφm * sqrt(1 / 2 - m^2 * Δφm^2 / (64 * Δθm^2))\n        κg = 2sqrt(2) * M * Δθp * Δφp / vstar^3 + 2C / m\n        Γ1 = 2Δθp + Δφp + A1\n        Γ2 = Γ1^2 + 4Δθp + Δφp + A2\n        V1 = 4Δθp + Δφp + Δφp^2 / 2 + 4Δθp * Δφp\n        εp = a / sqrt(ℓm^2 - a^2)\n        U = εp * (Γ2 + εp^2 * Γ1^2) / vstar^2 + εp * Γ1 * V1 / vstar^3\n        return sqrt(κg^2 + (1 + U)^2) / (ℓm - a)\n    end\n    κbox = κbound(first(L_BOUNDS), DPHI_BOUNDS...)   # the box of the optimization\n    κpt = κbound(p.l, p.Δφ, p.Δφ)                     # the design point itself\n    κmax <= min(κbox, κpt) || @warn \"curvature: the a posteriori bound is violated\" κmax κbox κpt\n    return (; rmin=1 / κmax, rbox=1 / κbox, rpt=1 / κpt, A1, A2)\nend\n\n\"\"\"\nPower take-off estimate of section \"Estimation of power take-off\" (Alain Nême's 1D\nmodel) for the parameters `p` of Table 1, with the maximum wing loading `Ts` (N/m²),\nwhich is not a model parameter: kite speed at the centre of the eight, length of the\neight, pulsation ω, then the optimal design under the amplitude constraint |α| ≤ π/2 and\n`I ≥ Imin` (the lower bound of the optimization box): `I = Imin`, `b` on the constraint,\nand the power per unit kite area (`pto`; `pto0` is its supremum as `Imin → 0`; `Iseq` the\ninertia of the sequential argument \"b = Iω, then smallest admissible I\").\n\"\"\"\nfunction pto_estimate(p; Ts=PTO_TS, Imin=I_BOUNDS[1], n=100_000)\n    G = p.C_L / p.C_D\n    Vk = p.w0 * (p.l * cos(p.θ0) / p.z0)^(1 / p.n_wind) * sqrt((1 + G^2) * sin(p.θ0)^2 - 1)\n    τs = range(0, 2π, n + 1)[1:end-1]\n    L81 = 2π / n * sum(τ -> sqrt((2p.Δθ * cos(2τ))^2 +\n                                 sin(p.θ0 + p.Δθ * sin(2τ))^2 * (p.Δφ * cos(τ))^2), τs)\n    ω = 2π * Vk / (p.l * L81)\n    CM = Ts * p.S * p.a * sin(p.θ0)\n    # max of W = b CM² / (2(I²ω² + b²)) under the amplitude constraint\n    # CM / (ω √(I²ω² + b²)) ≤ π/2 and I ≥ Imin: at fixed I the best b is Iω while the\n    # constraint allows it (I ≥ √2 CM/(πω²)); below, the constraint is active and W\n    # increases as I decreases, so the optimum is I = Imin with the constraint active\n    I = Imin\n    ε = π * ω^2 * I / (2CM)\n    ε < 1 / sqrt(2) || error(\"PTO estimate: Imin above √2 CM/(πω²), the optimum is not on the constraint\")\n    b = 2CM / (π * ω) * sqrt(1 - ε^2)\n    W = b * CM^2 / (2 * (I^2 * ω^2 + b^2))\n    W ≈ π * CM * ω / 4 * sqrt(1 - ε^2) || error(\"PTO estimate: closed form\")\n    return (; I, b, ε, pto=W / p.S, pto0=π * CM * ω / 4 / p.S, Iseq=sqrt(2) * CM / (π * ω^2))\nend\n\n\"\"\"\n`tables/numbers.tex`: every number the text of the optimization section quotes, as\nLaTeX macros, so that the text cannot drift from the generated tables and figures.\n\"\"\"\nfunction numbers_tex(; p_start, p_ref, opt_iter, winds, sweep, dtheta, dtheta_opt, dtheta_lost)\n    s0, s1 = cycle_report(p_start), cycle_report(p_ref)\n    ok = [isassigned(sweep.opt, i) && isassigned(sweep.no_opt, i) && isassigned(sweep.theta, i)\n          for i in eachindex(winds)]\n    w = collect(winds)[ok]\n    P(v) = getproperty.(v, :P)\n    o, fx = sweep.opt[ok], sweep.no_opt[ok]\n    loss = maximum(100 .* (P(o) .- P(fx)) ./ P(o))\n    dT = maximum(100 .* (getproperty.(fx, :Tmax) ./ getproperty.(o, :Tmax) .- 1))\n    Tmin = minimum(min.(getproperty.(o, :Tmin), getproperty.(fx, :Tmin)))\n    # power-law exponents along the optimized sweep (least squares in log-log)\n    slope(y) = ([ones(length(w)) log.(w)] \\ log.(y))[2]\n    b_opt = [θ[findfirst(==(:b), SYMS)] for θ in sweep.theta[ok]]\n    c = curvature_stats(p_ref)\n    # Δθ sweep (caption of fig:opt-dtheta): power relative to the nominal with Θ fixed\n    ang = [d.Δθ for d in dtheta]\n    i0 = argmin(abs.(ang .- rad2deg(p_ref.Δθ)))\n    Pfix, Popt = P(dtheta) ./ dtheta[i0].P, P(dtheta_opt) ./ dtheta[i0].P\n    # the caption claims: Θ fixed peaks at the nominal; re-optimized decreases\n    # steadily above the nominal; the continuation is lost below the nominal and\n    # converges up to the largest angle\n    argmax(Pfix) == i0 || @warn \"Δθ caption: with Θ fixed the power no longer peaks at the nominal angle\"\n    all(isfinite, Popt[i0:end]) && all(diff(Popt[i0:end]) .< 0) ||\n        @warn \"Δθ caption: the re-optimized power no longer decreases steadily above the nominal angle\"\n    # below the nominal angle, the continuation is fragile: depending on the host, it is\n    # lost near 4° (CI runs 46139319516, 45912488604) or reaches 2° with a peak at 4°\n    # (run 46137278622). The caption fragment `DthetaBelow` states what this run gives.\n    ibest = argmax(i -> isfinite(Popt[i]) ? Popt[i] : -Inf, eachindex(Popt))  # an index\n    below = if isfinite(dtheta_lost)\n        \"below the nominal angle, the continuation is lost at \\\\(\" * f\"{dtheta_lost:.1f}\" *\n        \"^\\\\circ\\\\), so that no re-optimized value is shown at smaller angles\"\n    else\n        all(isfinite, Popt) || @warn \"Δθ caption: re-optimized values missing\" Popt\n        \"the continuation reaches the whole range, and the re-optimized power peaks, among \" *\n        \"the sampled angles, at \\\\(\" * f\"{ang[ibest]:.1f}\" * \"^\\\\circ\\\\), \" *\n        f\"{100 * (Popt[ibest] - 1):.1f}\" * \"\\\\,\\\\% above its nominal value\"\n    end\n    pto = pto_estimate(p_start)\n    cc = curvature_check(p_ref)\n    fq0, fq1 = floquet(p_start), floquet(p_ref)\n    # sensitivity to the glide ratio G = C_L/C_D: the optimized design and the PTO\n    # estimate with the lower G of soft kites (the value the parameters' comments cite)\n    pG = copy(p_ref); pG.C_D = pG.C_L / GLIDE_LOW\n    sG = cycle_report(pG)\n    ptoG = pto_estimate(let q = copy(p_start); q.C_D = q.C_L / GLIDE_LOW; q end)\n    isfinite(sG.P) || @warn \"glide-ratio sensitivity: no cycle at G = $GLIDE_LOW\" \n    fq1.μ < 1 && fq1.err < 1e-6 || @warn \"the text says the optimized cycle is attracting\" fq1\n    fq1.μ > fq0.μ || @warn \"the text says the optimized cycle is less strongly attracting than the initial one\" fq0 fq1\n    r1(x) = f\"{x:.1f}\"\n    sciq(x) = (e = floor(Int, log10(x)); f\"{x / exp10(e):.1f} \\\\times 10^{{{e}}}\")  # math mode\n    r2(x) = f\"{x:.2f}\"\n    macros = [\n        \"WindRef\" => string(round(Int, WIND_REF)),\n        \"IpoptTol\" => \"10^{$(round(Int, log10(TOL)))}\",\n        \"IvpTol\" => \"10^{$(round(Int, log10(TOL / 10)))}\",\n        \"PostTol\" => \"10^{$(round(Int, log10(TOL)))}\",\n        \"IpoptIter\" => string(opt_iter),\n        \"PowerInit\" => r2(s0.P / 1000), \"PowerOpt\" => r2(s1.P / 1000),\n        \"PowerGain\" => string(round(Int, 100 * (s1.P / s0.P - 1))),\n        \"PeriodInit\" => r2(s0.period), \"PeriodOpt\" => r2(s1.period),\n        \"EllOpt\" => r1(p_ref.l), \"DphiOpt\" => r1(rad2deg(p_ref.Δφ)),\n        \"DthetaFixed\" => r1(rad2deg(p_ref.Δθ)), \"ThetaZero\" => r1(rad2deg(p_ref.θ0)),\n        \"SweepWindMin\" => string(round(Int, first(w))), \"SweepWindMax\" => string(round(Int, last(w))),\n        \"SweepMaxLoss\" => r1(loss), \"SweepMaxTensionIncrease\" => r1(dT),\n        \"SweepMinTension\" => r2(Tmin / 1000),\n        \"ExpPower\" => r1(slope(P(o))), \"ExpTension\" => r1(slope(getproperty.(o, :Tmax))),\n        \"ExpBrake\" => r1(slope(b_opt)), \"ExpPeriod\" => r1(slope(getproperty.(o, :period))),\n        \"CurvTipKg\" => r2(c.kg_tip), \"CurvTipK\" => r2(c.K_tip),\n        \"CurvMaxK\" => r2(c.K_max), \"CurvMaxTau\" => f\"{c.τ_max:.3f}\",\n        \"CurvMaxRadius\" => r1(p_ref.l / c.K_max),\n        \"GlideRef\" => string(round(Int, p_ref.C_L / p_ref.C_D)), \"GlideLow\" => string(GLIDE_LOW),\n        \"PowerOptGlideLow\" => r2(sG.P / 1000), \"PtoPowerGlideLow\" => r1(ptoG.pto / 1000),\n        \"FloquetInit\" => sciq(fq0.μ), \"FloquetOpt\" => sciq(fq1.μ),\n        \"CurvArmRadius\" => r2(cc.rmin), \"CurvBoxRadius\" => f\"{1000 * cc.rbox:.1f}\",\n        \"CurvPointRadius\" => r2(cc.rpt),\n        \"CurvAOne\" => r2(cc.A1), \"CurvATwo\" => r2(cc.A2),\n        \"PtoTs\" => string(round(Int, PTO_TS)),\n        \"PtoI\" => string(round(Int, pto.I)), \"PtoB\" => r1(deg2rad(pto.b)),  # b per degree, as in the tables\n        \"PtoPower\" => r1(pto.pto / 1000), \"PtoPowerZero\" => r1(pto.pto0 / 1000),\n        \"PtoEps\" => f\"{pto.ε:.3f}\", \"PtoISeq\" => string(round(Int, pto.Iseq)),\n        \"PtoGainSeq\" => string(round(Int, 100 * (pto.pto / (pto.pto0 / sqrt(2)) - 1))),\n        \"DthetaStep\" => string(DTHETA_STEP),\n        \"DthetaMax\" => string(round(Int, last(ang))),\n        \"DthetaFixedLoss\" => string(round(Int, 100 * (1 - last(Pfix)))),\n        \"DthetaBelow\" => below,\n        \"DthetaOptLoss\" => r1(100 * (1 - last(Popt))),\n    ]\n    return join([\"% Generated by main.jl (optimization section): numbers quoted in the text.\";\n        [\"\\\\newcommand{\\\\$k}{$v}\" for (k, v) in macros]], \"\\n\")\nend\n\n\"\"\"\nTable 4: the initial guess (I = 1300, b = I ω: not the PTO optimum of the 1D estimate) against\nthe dynamic optimum, with the statistics of their limit cycles.\n\"\"\"\nfunction comparison_table(p_init, p_opt)\n    stats(p) = cycle_stats(LC.compute_limit_cycle(PMP.build_vbpara(p); sense=SENSE, tol=TOL, save_everystep=true))\n    s0, s1 = stats(p_init), stats(p_opt)\n    g(x) = string(round(x; sigdigits=6))\n    param_rows = [f\"    {TEX[k][1]} ({TEX[k][2]}) & {g(TEX[k][3](p_init[k]))} & {g(TEX[k][3](p_opt[k]))} \\\\\\\\ \" for k in SYMS]\n    rows = [\n        param_rows...,\n        raw\"    \\midrule\",\n        f\"    Period (\\\\si{{\\\\second}}) & {g(s0.period)} & {g(s1.period)} \\\\\\\\ \",\n        \"    Objective \" * raw\"$P$\" * raw\" (\\si{\\kilo\\watt}) & \" * g(s0.P / 1000) * \" & \" * g(s1.P / 1000) * raw\" \\\\ \",\n        f\"    Min tension (\\\\si{{\\\\kilo\\\\newton}}) & {g(s0.Tmin / 1000)} & {g(s1.Tmin / 1000)} \\\\\\\\ \",\n        f\"    Max tension (\\\\si{{\\\\kilo\\\\newton}}) & {g(s0.Tmax / 1000)} & {g(s1.Tmax / 1000)} \\\\\\\\ \",\n        f\"    Max acceleration (\\\\si{{\\\\meter\\\\per\\\\square\\\\second}}) & {g(s0.amax)} & {g(s1.amax)} \\\\\\\\ \",\n    ]\n    return join([\n        raw\"% WARNING: values: to be checked vs. Alain's computation\",\n        raw\"\\begin{table}[htbp]\",\n        raw\"  \\centering\",\n        raw\"  \\caption{Comparison of initial and optimized parameters}\",\n        raw\"  \\label{tab:parameter_comparison}\",\n        raw\"  \\begin{tabular}{lrr}\",\n        raw\"    \\toprule\",\n        raw\"    Parameter & \\multicolumn{1}{c}{Initial guess} & \\multicolumn{1}{c}{Dynamic optimization} \\\\ \",\n        raw\"    \\midrule\",\n        rows...,\n        raw\"    \\bottomrule\",\n        raw\"  \\end{tabular}\",\n        raw\"\\end{table}\",\n    ], \"\\n\")\nend\n\n\n## Plots\n## Plot: wind sweep over Θ\n\"\"\"\nThree half-width panels of the wind sweep: average power, line tension (min–max\nenvelope), and the re-optimized parameters normalized by their maximum over the\nwind range. The dotted black curve is the 9 m/s reference held fixed, and a\ntranslucent black band marks that reference wind speed in every panel. The\nparameter panel has no legend: the braking coefficient is annotated at the lower\nleft, where its curve is, and the other three are stacked on the right in their\nvertical order at the last wind speed.\n\"\"\"\nfunction plot_wind_sweep(winds, sweep, i_ref, guides)\n    (; syms, no_opt, opt, theta) = sweep\n    power_vec = [s.P for s in opt]\n    min_tension_vec = [s.Tmin for s in opt]\n    max_tension_vec = [s.Tmax for s in opt]\n    power0 = [s.P for s in no_opt]\n    min_tension0 = [s.Tmin for s in no_opt]\n    max_tension0 = [s.Tmax for s in no_opt]\n    theta_norm = [maxnormalize(θ) for θ in invert(theta)]\n    ref = \"Fixed at $(round(Int, WIND_REF)) m/s\"\n    ref_style = (; ls=:dot, c=:black)\n\n    # Average power\n    f1 = plot(ylabel=\"Power (kW)\", legend=:topleft, xformatter=:plain, xlabel=\"Wind speed (m/s)\", ylims=(0, 60), yticks=0:20:100, widen=true)\n    plot!(f1, winds, power0 ./ 1000; ref_style...)\n    plot!(f1, winds, power_vec ./ 1000; c=1)\n\n    # Line tension, min–max envelope (lower is better for wearing the lines out)\n    f2 = plot(ylabel=\"Line tension (kN)\", legend=:topleft, xformatter=:plain, xlabel=\"Wind speed (m/s)\", ylims=(0, 40), yticks=0:20:100, widen=true)\n    plot!(f2, winds, [max_tension0 ./ 1000, min_tension0 ./ 1000]; ref_style...)\n    plot!(f2, winds, max_tension_vec ./ 1000; fillrange=min_tension_vec ./ 1000, c=1, fillalpha=0.1)\n    plot!(f2, winds, min_tension_vec ./ 1000; c=1)\n\n    # Optimized parameters, normalized by their maximum over the wind range\n    n = length(syms)\n    f3 = plot(yticks=((0, 1), (\"0\", \"max\")), ylim=(0, 1), ylabel=\"Parameters\", xformatter=:plain, xlabel=\"Wind speed (m/s)\", legend=false, widen=true)\n    # plot!(f3, winds, [[p for _ in winds] for p in invert(theta_norm)[i_ref]]; lw=1.5, ref_style...)\n    plot!(f3, winds, theta_norm; c=permutedims(collect(1:n)))\n\n    # the reference wind speed is marked by the same band as the other guide\n    # lines; the backend draws series in list order, so moving it in front of\n    # the data keeps the band under the curves\n    for f in (f1, f2, f3)\n        vline!(f, [WIND_REF]; guides.line...)\n        pushfirst!(f[1].series_list, pop!(f[1].series_list))\n    end\n\n    # annotations instead of a legend: the braking coefficient at the lower\n    # left (its curve is the lowest there), then the other three stacked on the\n    # right below the curves, in their vertical order at the last wind speed\n    names = Dict(:l => \"Line length\", :I => \"Arm inertia\",\n        :b => \"Arm braking coefficient\", :Δφ => \"Lemniscate width\")\n    ib = findfirst(==(:b), syms)\n    annotate!(f3, first(winds) + 0.25, theta_norm[ib][1] - 0.14,\n        (names[:b], ANNOTATIONFONTSIZE, :left, PALETTE[ib]))\n    y = 0.62\n    for i in sortperm([theta_norm[i][end] for i in eachindex(syms)]; rev=true)\n        i == ib && continue\n        annotate!(f3, last(winds) - 0.25, y,\n            (names[syms[i]], ANNOTATIONFONTSIZE, :right, PALETTE[i]))\n        y -= 0.10\n    end\n\n    # three panels of a third of the text height, half text width; the margins\n    # leave room for the axis labels (the theme sets margin = 0)\n    fig = plot(f1, f2, f3; layout=(3, 1), size=plot_size(2, 1),\n        leftmargin=10Plots.mm, bottommargin=4Plots.mm)\n    # the three panels share one x axis: only the bottom panel labels it\n    foreach(i -> plot!(fig, subplot=i, xformatter=x -> \"\", xlabel=\"\"), (1, 2))\n    return (; fig, panels=(f1, f2, f3))\nend\n\n## Plot: Δθ sensitivity (justifies holding Δθ fixed)\n\"\"\"\nThe power and line-tension panels of the Δθ sweep, side by side: Δθ in degrees,\n2° to 20° in steps of 2°, which includes the nominal angle. The power is\nnormalized by its value at the nominal with Θ fixed, so the two conditions meet\nat 1 there and the gap between them is what holding Θ costs. Θ held at the\noptimum is drawn as black points, Θ re-optimized at each angle as a black line\nwith triangles (no legend: see the caption);\nthe tension panel draws both min–max envelopes, the fixed one as points and the\nre-optimized one filled. A `guides.line` band marks the nominal angle.\n\"\"\"\nfunction plot_dtheta(dtheta, dopt, guides, mark)\n    ang = [d.Δθ for d in dtheta]\n    i0 = argmin(abs.(ang .- mark))\n    style = (; c=:black)\n\n    Pn = [d.P for d in dtheta] ./ dtheta[i0].P\n    Pn_opt = [d.P for d in dopt] ./ dtheta[i0].P\n    Tmin0 = [d.Tmin / 1000 for d in dtheta]\n    Tmax0 = [d.Tmax / 1000 for d in dtheta]\n    Tmin1 = [d.Tmin / 1000 for d in dopt]\n    Tmax1 = [d.Tmax / 1000 for d in dopt]\n\n    # power relative to its value at the nominal Δθ with Θ fixed, so the nominal\n    # sits at 1 on both curves and the axis runs from 0 to the peak\n    # no legend: GR draws legend markers at 0.8 × the legend font size, whatever\n    # `markersize`, so with `thickness_scaling` they dwarf the data; the caption\n    # gives the encoding instead\n    f1 = plot(ang, Pn; style..., seriestype=:scatter, ms=4, label=\"\",\n        ylabel=\"P / P*\", xlabel=\"Δθ (deg)\", ylims=(0, 1.03max(1, maximum(filter(isfinite, Pn_opt); init=1))),\n        yticks=([0, 0.5, 1], [\"0\", \"0.5\", \"1\"]), legend=false)\n    # markers: a converged angle between two failed ones (NaN) still shows\n    plot!(f1, ang, Pn_opt; style..., markershape=:utriangle, ms=4, label=\"\")\n\n    f2 = plot(ang, Tmax0; style..., seriestype=:scatter, ms=4, label=\"\",\n        ylabel=\"Line tension (kN)\", xlabel=\"Δθ (deg)\")\n    scatter!(f2, ang, Tmin0; style..., ms=4, label=\"\")\n    plot!(f2, ang, Tmax1; style..., label=\"\", fillrange=Tmin1, fillalpha=0.1)\n    plot!(f2, ang, Tmin1; style..., label=\"\")\n\n    foreach(f -> vline!(f, [mark]; guides.line...), (f1, f2))\n    foreach(f -> plot!(f, xticks=2:2:20, xlim=extrema(ang)), (f1, f2))\n    # the backend draws the series in list order, so moving the band in front of\n    # the data keeps it under the curves\n    for f in (f1, f2)\n        pushfirst!(f[1].series_list, pop!(f[1].series_list))\n    end\n\n    # the margins are per panel (the theme sets margin = 0): only the left one\n    # carries a y label and y tick labels\n    plot!(f1, leftmargin=18Plots.mm, bottommargin=10Plots.mm)\n    plot!(f2, leftmargin=6Plots.mm, bottommargin=10Plots.mm)\n    return plot(f1, f2; layout=(1, 2), size=plot_size(1, 2))\nend\n\n## Plot: objective landscape around the Θ optimum\n\"\"\"\nPlot a normalized landscape from `landscape`: one row of four panels, one per\nparameter, with a single `P / P*` label on the left. Each panel is drawn in the\ncolour of its parameter in the wind-sweep parameter panel. The x axis is the\nparameter in its own units, spanning ±`window` around the optimum, whose value\nis the middle tick (`-10%`, value, `+10%`). The y axis is the same in every\npanel, `(guides.ymin, 1)`, labelled on the leftmost panel only, with ticks at\n`guides.ymin` and 1 (the power curve of a parameter that loses more than 10 % is\nclipped at the floor). The cost function (still normalized by its optimum) is a\nline, solid inside the box constraint and dotted outside it, the crossing\ninterpolated linearly between the two samples that bracket the bound. Each box\nconstraint is a black double vertical line, always drawn (clipped when it falls\noutside the window) and on top of the line. A `guides.line` band marks the\noptimum vertically and a `guides.floor` line the power floor horizontally; both\nare drawn under the data.\n\"\"\"\nfunction plot_landscape(land, guides)\n    (; xs, syms, ys, window, box, center) = land\n    lo, hi = 1 - window, 1 + window\n\n    # the margins are per panel (the theme sets margin = 0) and leave room for\n    # the tick labels, which sit outside the axis in every panel\n    panels = [\n        begin\n            x0 = TEX[syms[i]][3](center[i])  # the optimum, in display units\n            ticks = ([x0 * lo, x0, x0 * hi],\n                [f\"-{100window:.0f}%\", f\"{x0:.2f}\", f\"+{100window:.0f}%\"])\n            plt = plot(; xlims=(x0 * lo, x0 * hi), ylims=(guides.ymin, 1),\n                xticks=ticks, title=\"$(LABELS[sym])\",\n                ylabel=(i == 1 ? \"P / P*\" : \"\"),\n                # only the leftmost panel labels its two ticks\n                yticks=(i == 1 ? ([guides.ymin, 1], [plain_tick(guides.ymin), \"1\"]) :\n                        ([guides.ymin, 1], [\"\", \"\"])),\n                leftmargin=(i == 1 ? 18 : 3)Plots.mm, rightmargin=4Plots.mm,\n                bottommargin=5Plots.mm, topmargin=2.5Plots.mm)\n            # value of the sampled curve at a factor x, linearly interpolated\n            interp(x) = begin\n                k = clamp(searchsortedlast(xs, x), 1, length(xs) - 1)\n                ys[i][k] + (x - xs[k]) / (xs[k+1] - xs[k]) * (ys[i][k+1] - ys[i][k])\n            end\n            # factors from a to b, with the ends inserted (they need not be samples)\n            piece(a, b) = vcat(a, xs[(a .< xs) .& (xs .< b)], b)\n            xa, xb = max(box[i][1], lo), min(box[i][2], hi)  # box ∩ window\n            xa < xb && plot!(plt, x0 .* piece(xa, xb), interp.(piece(xa, xb));\n                c=i, ls=:solid)\n            for (a, b) in ((lo, min(xa, hi)), (max(xb, lo), hi))\n                a < b && plot!(plt, x0 .* piece(a, b), interp.(piece(a, b)); c=i, ls=:dot)\n            end\n            for edge in box[i], k in (-1, 1)  # box constraint: double line, on top\n                vline!(plt, [x0 * (edge + k * window / 40)]; c=:black, lw=1.2)\n            end\n            # every panel draws the shared floor and the optimum line\n            hline!([guides.ymin]; guides.floor...)\n            vline!([x0]; guides.line...)\n            # the backend draws the series in list order, so move the two guide\n            # lines in front of the data to keep them underneath it\n            series = plt[1].series_list\n            pushfirst!(series, pop!(series), pop!(series))\n            plt\n        end for (i, sym) in enumerate(syms)\n    ]\n\n    return plot(panels...; layout=(1, length(syms)), size=plot_size(1/2, 2),\n        framestyle=:grid, grid=false)\nend\n\nfunction run_optimization(; fast::Bool=false)\n    my_defaults()\n    # fast: tiny iteration limits and grids, only to test the workflow (results are not the paper's)\n    it_ref, it_sweep, it_dtheta = fast ? (40, 25, 25) : (MAX_ITER, SWEEP_MAX_ITER, DTHETA_MAX_ITER)\n    files = String[]\n\n    #region opt_setup\n    p_start = PMP.build_para(w0=WIND_REF)\n    p_start.b = PMP.optimal_torque_slope(p_start; tol=1e-9, rtol=1e-9, maxiter=50)  # b = I ω\n    lower = [first(L_BOUNDS), first(I_BOUNDS), first(B_BOUNDS), first(DPHI_BOUNDS)]\n    upper = [last(L_BOUNDS), last(I_BOUNDS), last(B_BOUNDS), last(DPHI_BOUNDS)]\n\n    @info \"opt: reference at $(WIND_REF) m/s over Θ = ($(join(SYMS, \", \")))\"\n    opt_ref = opt_step(p_start, SYMS, lower, upper; iters=it_ref, strict=!fast)\n    p_ref = opt_ref.p  # the Θ optimum at the reference wind speed\n    # the power of the solver's orbit must be that of the cycle recomputed from p_ref\n    # (settling + Newton), which every table and figure uses\n    let Pc = cycle_report(p_ref).P, gap = abs(opt_ref.P - Pc) / abs(Pc)\n        msg = \"optimum: solver power $(opt_ref.P) vs recomputed cycle $Pc (rel. gap $gap)\"\n        gap < 1e-3 || (fast ? @warn(msg) : error(msg))\n    end\n    #endregion\n\n    #region opt_wind_sweep\n    winds = range(5, 15, length=fast ? 3 : 11)\n    i_ref = findfirst(x -> x >= WIND_REF, winds)\n    @info \"opt: wind sweep, $(length(winds)) speeds from $(first(winds)) to $(last(winds)) m/s\"\n    sweep = wind_sweep(SYMS, p_ref, winds, lower, upper, i_ref; iters=it_sweep, strict=!fast)\n    #endregion\n\n    #region opt_dtheta\n    dtheta_angles = collect(range(DTHETA_RANGE..., length=fast ? 3 : 10))\n    @info \"opt: Δθ sweep with Θ fixed, $(length(dtheta_angles)) angles\"\n    dtheta = dtheta_study(p_ref, dtheta_angles)\n\n    dsweep = dtheta_opt_sweep(p_ref, SYMS, dtheta_angles, lower, upper;\n        nominal=rad2deg(p_ref.Δθ), iters=it_dtheta, step=fast ? 3.0 : DTHETA_STEP)\n    dtheta_opt, dtheta_lost = dsweep.stats, dsweep.lost_below\n    #endregion\n\n    #region opt_landscape\n    LANDSCAPE = landscape(p_ref, SYMS; lower, upper, npoints=fast ? 5 : 21)\n    #endregion\n\n    #region opt_tables\n    ## Tables\n    table_descr, table_opt = latex_tables(p_start, p_ref, lower, upper)\n    push!(files, write_table(\"table2\", table_descr), write_table(\"table3\", table_opt))\n    @warn \"table4: values to be checked vs. Alain's computation\"\n    push!(files, write_table(\"table4\", comparison_table(p_start, p_ref)))\n    push!(files, write_table(\"numbers\", numbers_tex(; p_start, p_ref, opt_iter=opt_ref.iter, winds, sweep, dtheta, dtheta_opt, dtheta_lost)))\n    #endregion\n\n    ## Figures\n    my_defaults()\n    #region fig_wind_sweep\n    (; fig, panels) = plot_wind_sweep(winds, sweep, i_ref, GUIDES)\n    for (f, panel) in zip(panels, (\"power\", \"tension\", \"params\"))\n        plot!(f, size=plot_size(1, 1), leftmargin=10Plots.mm, bottommargin=6Plots.mm)\n        append!(files, save_figure(f, \"optimization_wind_sweep_$(panel)\"))\n    end\n    #endregion\n\n    my_defaults()\n    #region fig_dtheta\n    fig_dtheta = plot_dtheta(dtheta, dtheta_opt, GUIDES, rad2deg(p_ref.Δθ))\n    append!(files, save_figure(fig_dtheta, \"optimization_dtheta\"))\n    #endregion\n\n    my_defaults()\n    #region fig_landscape\n    fig_land = plot_landscape(LANDSCAPE, GUIDES)\n    append!(files, save_figure(fig_land, \"optimization_landscape\"))\n    #endregion\n\n    my_defaults()\n    #region fig_timeseries\n    sols = map((p_start, p_ref)) do p\n        LC.compute_limit_cycle(PMP.build_vbpara(p); sense=SENSE, tol=TOL, save_everystep=true)\n    end\n    # initial guess (I = 1300, b = Iω; not the PTO optimum of section C) and the same\n    # system optimized for average power\n    fig_ts = plot_time_series_grid(sols; titles=(\"Initial guess\", \"Dynamic optimum\"))\n    append!(files, save_figure(fig_ts, \"optimization_timeseries_all\"))\n    #endregion\n    return files\nend\n\nif abspath(PROGRAM_FILE) == @__FILE__\n    run_optimization()\nend"},{"title":"Introduction","page":"Introduction","location":"intro.html#sec:intro","category":"section","text":"<p>Wind speed increases with altitude, and above the first hundred metres it is both stronger and steadier than at the height of the hub of a conventional turbine. Airborne wind energy aims at harvesting this resource with tethered wings instead of towers and blades: a kite flown in crosswind motion sweeps a large area of the sky with little structural mass, and most of the material of a turbine, the tower and the outer part of the blades, is replaced by a few lines. The power is either produced on board and sent to the ground through a conducting tether, or produced on the ground from the traction of the lines. In the most studied ground-based concept, the pumping cycle, the kite pulls the lines off a drum coupled to a generator during a traction phase, and the lines are reeled in during a recovery phase that consumes part of the energy; quasi-steady models of such systems are now well established <span class=\"citation\" data-cites=\"vanderVlugt2019RE\">(<a href=\"references.html#ref-vanderVlugt2019RE\">Vlugt et al. 2019</a>)</span>. Pumping systems are thus intermittent by design: power is only produced during the traction phase, and the recovery phase has to be made as short and as cheap as possible.</p>\n<p>This project is part of improving the performance of technologies that meet the challenges of the law concerning the energy transition. The innovative KEEP (Kite Electrical Energy Production) technology developed at ENSTA enables the production of electrical energy from a kite capturing wind energy. The project originated at ENSTA Bretagne, now part of ENSTA Paris, from the work of its kite team on the structure of leading edge inflatable kites <span class=\"citation\" data-cites=\"Desenclos2023MCM\">(<a href=\"references.html#ref-Desenclos2023MCM\">Desenclos et al. 2023</a>)</span>. In KEEP, the kite is attached by four lines, about thirty metres long, to the tip of an arm, about two metres long, which turns a platform about a vertical axis, in one direction and then in the other; the platform drives a generator through a dedicated gear train <span class=\"citation\" data-cites=\"Bavoil2024KEEP\">(<a href=\"references.html#ref-Bavoil2024KEEP\">Bavoil 2024</a>)</span>. The kite flies a figure of eight in the sky, downwind of the arm; the tension of the lines exerts a torque on the arm, which drives the generator, and the generator brakes the arm in return. There is no reeling phase: the motion is periodic, and power is produced continuously over the cycle, at the price of a strong coupling between the motion of the kite and that of the arm. The design of the device matters: for the model of this paper, optimizing the geometry, the inertia of the arm and the braking of the generator increases the average power by <span class=\"math inline\">\\(27\\%\\)</span> (Section <a href=\"section-4.html#sec:optimization\">4</a>). In the short and medium term, onshore and ship applications with a power production ranging from a few tens to hundreds of kilowatts are targeted, and the extension to offshore production at the megawatt scale, with kites of 1000 m<sup>2</sup>, is an objective. The development of the technology also builds on the know-how of the kite community in the modelling of kites as auxiliary propulsion for ships <span class=\"citation\" data-cites=\"Leloup2014OE\">(<a href=\"references.html#ref-Leloup2014OE\">Leloup et al. 2014</a>)</span>. To reach these targets, the mechanical model of the complete system has to be improved, and its dynamics has to be analysed theoretically, which is the purpose of this paper. It builds on the technical report of the project <span class=\"citation\" data-cites=\"Bavoil2024KEEP\">(<a href=\"references.html#ref-Bavoil2024KEEP\">Bavoil 2024</a>)</span>, which sets the modelling assumptions used here (rigid lines of constant length, and a point-mass kite, whose attitude is not modelled, moving on a cone over a figure of eight), starts from a model with ten state variables, and reduces it to six and then to four variables, the angle of the arm and the position of the kite along the eight, together with their velocities.</p>\n<p>We model the kite as a point mass whose trajectory is constrained to a spherical figure of eight, prescribed by its centre and its two half-amplitudes, and whose distance to the tip of the arm is the length of the lines. The motion then has two degrees of freedom, the angle <span class=\"math inline\">\\(\\alpha\\)</span> of the arm and the parameter <span class=\"math inline\">\\(\\tau\\)</span> of the kite along the eight, and the dynamics is a smooth system of ordinary differential equations on the tangent bundle of the torus <span class=\"math inline\">\\(\\mathbf{T}^2\\)</span>. This reduction is exact for the constraints, has a clear geometric content, and is cheap enough to be integrated many times, which is what the analysis and the optimization below require. We study the equilibria and the periodic orbits of this system, show that it has two attracting limit cycles, one for each direction of travel of the kite along the eight, and take the cycle along which <span class=\"math inline\">\\(\\tau\\)</span> increases as the operating regime of the device. We then optimize the design of the device (line length, inertia of the arm, braking coefficient of the generator and width of the eight) for the average power of the limit cycle, by a direct shooting formulation solved with Ipopt <span class=\"citation\" data-cites=\"WachterBiegler2006\">(<a href=\"references.html#ref-WachterBiegler2006\">Wächter and Biegler 2006</a>)</span>, and study how the optimal design depends on the wind speed and on the shape of the eight. At the reference wind speed of 9 m s<sup>−1</sup>, the optimization increases the average power by <span class=\"math inline\">\\(27\\%\\)</span> with respect to the initial design. All figures and tables of the paper are generated by the open-source Julia package KEEP.jl, built on DifferentialEquations.jl <span class=\"citation\" data-cites=\"rackauckas2017differentialequations\">(<a href=\"references.html#ref-rackauckas2017differentialequations\">Rackauckas and Nie 2017</a>)</span>, so that every number quoted in the text can be reproduced.</p>\n<p>Section <a href=\"section-1.html#sec:model\">1</a> derives the mathematical model. It first describes the geometry of the configuration: the spherical eight and the cone it spans from the centre of rotation, the spindle torus swept by the sphere of radius <span class=\"math inline\">\\(\\ell\\)</span> centred at the tip of the arm, which confines the kite, and the kinematic map from the configuration <span class=\"math inline\">\\((\\alpha,\\tau)\\)</span> to the position of the kite. It then gives the velocities, the force model (aerodynamic lift and drag of the kite, drag of the lines, gravity, torque of the generator, and the reaction of the cone, which enforces the constraint), and the equations of motion of the arm and of the kite, together with the instantaneous and average power.</p>\n<p>Section <a href=\"section-2.html#sec:1D-PTO\">2</a> estimates the power take-off with a simple one-dimensional model of the arm, forced by a harmonic torque that averages the traction of the kite along the eight. This model gives closed-form optimal values of the inertia of the arm and of the braking coefficient, and an estimate of the maximum power per unit area of the kite under a structural constraint on the wing loading.</p>\n<p>Section <a href=\"section-3.html#sec:analysis\">3</a> analyses the dynamics. It locates the equilibria of the system at the intersections of the nullclines of the two accelerations, eight in total, all unstable, and describes the corresponding configurations of the arm and the kite. Numerical integration exhibits periodic motions; a Poincaré section at <span class=\"math inline\">\\(\\tau=0\\)</span> turns them into fixed points of the first return map, which converges exponentially, and two attracting limit cycles, one for each direction of travel of the kite, are computed by shooting and Newton’s method; their Floquet multipliers explain the convergence rate, and a sampling of the section finds no other limit cycle.</p>\n<p>Section <a href=\"section-4.html#sec:optimization\">4</a> formulates the design optimization as a boundary value problem: the average power over one period is maximized with respect to the design parameters, under the constraint that the trajectory closes on itself after one lap of the eight, the period being an unknown. It reports the optimal design at the reference wind speed and the corresponding limit cycle, the optimal design as a function of the wind speed compared with a design fixed at the reference optimum, and the sensitivity to the half-height of the eight, which is held fixed in the optimization. It also bounds the curvature of the trajectory of the kite, which limits how sharply the kite has to turn: exact values at the tips of the eight without arm, an upper bound uniform over a box of parameters, and the first-order effect of the arm.</p>\n<p>The appendices collect the material that is not needed to follow the main text. Appendix <a href=\"appendix-A.html#sec:model10D\">A</a> presents a ten-dimensional model in which the kite and the arm are described by redundant coordinates, the constraints being algebraic equations that are differentiated to obtain an ordinary differential equation; it explains why the drift of the algebraic constraints makes it unsuitable for long integrations, which motivates the reduced model of Section <a href=\"section-1.html#sec:model\">1</a>. Appendix <a href=\"appendix-B.html#sec:explicit-ddq\">B</a> gives the explicit expression of the accelerations of the reduced model. Appendix <a href=\"appendix-C.html#app8\">C</a> computes the length of the spherical eight, in closed form with elliptic functions and as an expansion for a small half-height, which enters the power take-off estimate of Section <a href=\"section-2.html#sec:1D-PTO\">2</a>. Appendix <a href=\"appendix-D.html#app:curv\">D</a> contains the computations and proofs of the curvature results of Section <a href=\"section-4.html#sec:optimization\">4</a>.</p>\n<p>The control of the kite, which removes the constraint that it moves along a prescribed eight and steers it through its aerodynamic force, and eventually through the lengths of its left and right lines, is the final objective of the project <span class=\"citation\" data-cites=\"Bavoil2024KEEP\">(<a href=\"references.html#ref-Bavoil2024KEEP\">Bavoil 2024</a>)</span> and is left for future work.</p>"},{"title":"D Curvature of the kite trajectory: computations and proofs","page":"D Curvature of the kite trajectory: computations and proofs","location":"appendix-D.html#app:curv","category":"section","text":"<p>This appendix gathers the computations and proofs behind Section <a href=\"section-4.html#sec:opt-curvature\">4.3</a>, whose notation is used throughout. Primes denote derivatives with respect to <span class=\"math inline\">\\(\\tau\\)</span>, and the subscript <span class=\"math inline\">\\(\\sigma\\)</span> a derivative with respect to the arclength <span class=\"math inline\">\\(\\sigma\\)</span> of the spherical eight.</p>\n<p>From <span class=\"math inline\">\\(\\norm{\\vb r - \\vb a}^2 = \\ell^2\\)</span> with <span class=\"math inline\">\\(\\vb r = r\\,\\vu r\\)</span>, one gets <span class=\"math inline\">\\(r^2 - 2pr + a^2 - \\ell^2 = 0\\)</span>, where <span class=\"math inline\">\\(p = \\vu r \\vdot \\vb a\\)</span>. Since <span class=\"math inline\">\\(a&lt;\\ell\\)</span>, the roots have opposite signs, and the positive one is <span class=\"math inline\">\\(r = p + R\\)</span>, <span class=\"math inline\">\\(R = \\sqrt{p^2+\\ell^2-a^2}\\)</span>. As <span class=\"math inline\">\\(r\\)</span> increases with <span class=\"math inline\">\\(p\\in[-a,a]\\)</span>, <span class=\"math inline\">\\(\\ell-a\\le r\\le\\ell+a\\)</span>. Moreover <span class=\"math inline\">\\(\\dv*{r}{p} = 1 + p/R = r/R\\)</span>, so that, with <span class=\"math inline\">\\(u = \\ln r\\)</span>, <span class=\"math display\">\\begin{equation}\n    u_p = \\frac1R, \\qquad u_{pp} = -\\frac{p}{R^3}, \\qquad R \\ge \\sqrt{\\ell^2-a^2}.\n\\tag{124}\\end{equation}</span></p>\n<p>With <span class=\"math inline\">\\(\\vu e_\\theta, \\vu e_\\phi\\)</span> the coordinate unit vectors, <span class=\"math display\">\\begin{equation}\n\\begin{split}\n    \\vu r' &amp;= \\theta'\\,\\vu e_\\theta + \\sin\\theta\\,\\phi'\\,\\vu e_\\phi, \\\\\n    \\vu r'' &amp;= -(\\theta'^2 + \\sin^2\\theta\\,\\phi'^2)\\,\\vu r + (\\theta'' - \\sin\\theta\\cos\\theta\\,\\phi'^2)\\,\\vu e_\\theta + (\\sin\\theta\\,\\phi'' + 2\\cos\\theta\\,\\theta'\\phi')\\,\\vu e_\\phi.\n\\end{split}\n\\tag{125}\\end{equation}</span> Hence <span class=\"math inline\">\\(v^2 = \\theta&#39;^2 + \\sin^2\\theta\\,\\phi&#39;^2\\)</span>, and <span class=\"math inline\">\\(\\kappa_g = \\det(\\vu r, \\vu r&#39;, \\vu r&#39;&#39;)/v^3\\)</span> gives <span class=\"math display\">\\begin{equation}\n    v^3\\kappa_g = \\sin\\theta\\,(\\theta'\\phi'' - \\theta''\\phi') + \\cos\\theta\\,\\phi'\\,(2\\theta'^2 + \\sin^2\\theta\\,\\phi'^2).\n\\tag{126}\\end{equation}</span> With <span class=\"math inline\">\\(\\theta&#39; = 2\\Delta\\theta\\cos2\\tau\\)</span>, <span class=\"math inline\">\\(\\theta&#39;&#39; = -4\\Delta\\theta\\sin2\\tau\\)</span>, <span class=\"math inline\">\\(\\phi&#39; = \\Delta\\phi\\cos\\tau\\)</span> and <span class=\"math inline\">\\(\\phi&#39;&#39; = -\\Delta\\phi\\sin\\tau\\)</span>, one has <span class=\"math display\">\\begin{equation}\n    \\theta'\\phi'' - \\theta''\\phi' = -2\\Delta\\theta\\Delta\\phi\\cos2\\tau\\sin\\tau + 4\\Delta\\theta\\Delta\\phi\\sin2\\tau\\cos\\tau = 2\\Delta\\theta\\Delta\\phi\\sin\\tau\\,(2+\\cos2\\tau),\n\\tag{127}\\end{equation}</span> since <span class=\"math inline\">\\(4\\cos^2\\tau - \\cos2\\tau = 2 + \\cos2\\tau\\)</span>, and <span class=\"math inline\">\\(2\\theta&#39;^2 = 8\\Delta\\theta^2\\cos^22\\tau\\)</span>, which gives the stated <span class=\"math inline\">\\(v^2\\)</span> and <span class=\"math inline\">\\(\\kappa_g\\)</span>. Since <span class=\"math inline\">\\(\\cos\\tau\\)</span> and <span class=\"math inline\">\\(\\cos2\\tau\\)</span> do not vanish simultaneously, <span class=\"math inline\">\\(v&gt;0\\)</span>. At <span class=\"math inline\">\\(\\tau=\\pi/2\\)</span>: <span class=\"math inline\">\\(\\theta=\\theta_0\\)</span>, <span class=\"math inline\">\\(v = 2\\Delta\\theta\\)</span>, and <span class=\"math inline\">\\(\\kappa_g = \\Delta\\phi\\sin\\theta_0/(4\\Delta\\theta^2)\\)</span>. At <span class=\"math inline\">\\(\\tau = 3\\pi/4\\)</span>: <span class=\"math inline\">\\(\\theta = \\theta_0-\\Delta\\theta\\)</span>, <span class=\"math inline\">\\(\\cos2\\tau=0\\)</span>, <span class=\"math inline\">\\(v = \\Delta\\phi\\sin(\\theta_0-\\Delta\\theta)/\\sqrt2\\)</span>, which gives the stated value.</p>\n<p>To obtain <a href=\"section-4.html#eq:curv-formula\">(63)</a>, work in the frame <span class=\"math inline\">\\((\\vu r, \\vu t, \\vu n)\\)</span>; using <span class=\"math inline\">\\(\\vu r_\\sigma = \\vu t\\)</span> and <span class=\"math inline\">\\(\\vu t_\\sigma = -\\vu r + \\kappa_g\\vu n\\)</span>, <span class=\"math display\">\\begin{equation}\n    \\vb r_\\sigma = r_\\sigma\\,\\vu r + r\\,\\vu t, \\qquad\n    \\vb r_{\\sigma\\sigma} = (r_{\\sigma\\sigma} - r)\\,\\vu r + 2r_\\sigma\\,\\vu t + r\\kappa_g\\,\\vu n .\n\\tag{128}\\end{equation}</span> Then <span class=\"math inline\">\\(\\norm{\\vb r_\\sigma}^2 = r^2 + r_\\sigma^2\\)</span> and <span class=\"math display\">\\begin{equation}\n    \\norm{\\vb r_\\sigma \\times \\vb r_{\\sigma\\sigma}}^2 = r^2\\kappa_g^2\\,(r^2 + r_\\sigma^2) + (r^2 + 2r_\\sigma^2 - r\\,r_{\\sigma\\sigma})^2 .\n\\tag{129}\\end{equation}</span> With <span class=\"math inline\">\\(r_\\sigma = r\\,u_\\sigma\\)</span> and <span class=\"math inline\">\\(r_{\\sigma\\sigma} = r\\,(u_{\\sigma\\sigma} + u_\\sigma^2)\\)</span>, this gives <span class=\"math inline\">\\(\\norm{\\vb r_\\sigma}^2 = r^2(1+u_\\sigma^2)\\)</span> and <span class=\"math display\">\\begin{equation}\n    \\norm{\\vb r_\\sigma \\times \\vb r_{\\sigma\\sigma}}^2 = r^4\\bigl[\\kappa_g^2(1+u_\\sigma^2) + (1+u_\\sigma^2 - u_{\\sigma\\sigma})^2\\bigr],\n\\tag{130}\\end{equation}</span> and <span class=\"math inline\">\\(\\kappa = \\norm{\\vb r_\\sigma\\times\\vb r_{\\sigma\\sigma}}/\\norm{\\vb r_\\sigma}^3\\)</span> is <a href=\"section-4.html#eq:curv-formula\">(63)</a>.</p>\n<p>Parametrise <span class=\"math inline\">\\(\\mathscr C\\)</span> by <span class=\"math inline\">\\(X(r,\\sigma) = r\\,\\vu r(\\sigma)\\)</span>. Then <span class=\"math inline\">\\(X_r = \\vu r\\)</span>, <span class=\"math inline\">\\(X_\\sigma = r\\,\\vu t\\)</span>, the unit normal is <span class=\"math inline\">\\(\\vu n\\)</span>, and <span class=\"math inline\">\\(X_{rr} = 0\\)</span>, <span class=\"math inline\">\\(X_{r\\sigma} = \\vu t\\)</span>, <span class=\"math inline\">\\(X_{\\sigma\\sigma} = r\\,(-\\vu r + \\kappa_g\\vu n)\\)</span>. The fundamental forms are <span class=\"math display\">\\begin{equation}\n    \\mathrm{I} = \\dd r^2 + r^2\\dd\\sigma^2, \\qquad \\mathrm{II} = r\\,\\kappa_g\\,\\dd\\sigma^2,\n\\tag{131}\\end{equation}</span> so the principal curvatures are <span class=\"math inline\">\\(0\\)</span> (direction <span class=\"math inline\">\\(\\vu r\\)</span>) and <span class=\"math inline\">\\(\\kappa_g/r\\)</span> (direction <span class=\"math inline\">\\(\\vu t\\)</span>), and the Gauss curvature vanishes. Since <span class=\"math inline\">\\(\\mathrm I\\)</span> is the Euclidean metric in polar coordinates <span class=\"math inline\">\\((r,\\sigma)\\)</span>, the map <span class=\"math inline\">\\((r,\\sigma)\\mapsto(r\\cos\\sigma, r\\sin\\sigma)\\)</span> is a local isometry onto the plane (the development of the cone). For the trajectory <span class=\"math inline\">\\(\\sigma\\mapsto(r(\\sigma),\\sigma)\\)</span>, by Meusnier’s theorem, <span class=\"math display\">\\begin{equation}\n    \\kappa_n = \\frac{\\mathrm{II}(\\vb r_\\sigma,\\vb r_\\sigma)}{\\mathrm{I}(\\vb r_\\sigma,\\vb r_\\sigma)} = \\frac{r\\kappa_g}{r^2 + r_\\sigma^2} = \\frac{\\kappa_g}{r\\,(1+u_\\sigma^2)},\n\\tag{132}\\end{equation}</span> with <span class=\"math inline\">\\(\\sin^2\\beta = r^2/(r^2+r_\\sigma^2)\\)</span> for the angle <span class=\"math inline\">\\(\\beta\\)</span> between <span class=\"math inline\">\\(\\vb r_\\sigma\\)</span> and <span class=\"math inline\">\\(\\vu r\\)</span>. The geodesic curvature is intrinsic, hence equal to the curvature of the developed planar curve given in polar form by <span class=\"math inline\">\\(r(\\sigma)\\)</span>, namely <span class=\"math display\">\\begin{equation}\n    \\frac{r^2 + 2r_\\sigma^2 - r\\,r_{\\sigma\\sigma}}{(r^2+r_\\sigma^2)^{3/2}} = \\frac{1 + u_\\sigma^2 - u_{\\sigma\\sigma}}{r\\,(1+u_\\sigma^2)^{3/2}}.\n\\tag{133}\\end{equation}</span> Their squares add up to <a href=\"section-4.html#eq:curv-formula\">(63)</a>. For <span class=\"math inline\">\\(a=0\\)</span>, <span class=\"math inline\">\\(r\\equiv\\ell\\)</span>, <span class=\"math inline\">\\(u_\\sigma = u_{\\sigma\\sigma} = 0\\)</span>, and the developed curve is the circle of radius <span class=\"math inline\">\\(\\ell\\)</span>.</p>\n<p>For <span class=\"math inline\">\\(a=0\\)</span>, <span class=\"math inline\">\\(\\kappa = \\sqrt{1+\\kappa_g^2}/\\ell \\ge 1/\\ell\\)</span>. At <span class=\"math inline\">\\(\\tau=0\\)</span> (<span class=\"math inline\">\\(\\theta = \\theta_0\\)</span>, <span class=\"math inline\">\\(\\sin\\tau=0\\)</span>, <span class=\"math inline\">\\(\\cos\\tau=1\\)</span>) the numerator of <span class=\"math inline\">\\(\\kappa_g\\)</span> equals <span class=\"math inline\">\\(\\Delta\\phi\\cos\\theta_0\\,(8\\Delta\\theta^2 + \\Delta\\phi^2\\sin^2\\theta_0)\\)</span>, and at <span class=\"math inline\">\\(\\tau=\\pi\\)</span> its opposite. If <span class=\"math inline\">\\(\\theta_0\\ne\\pi/2\\)</span>, these have opposite signs, so by continuity <span class=\"math inline\">\\(\\kappa_g\\)</span> vanishes on <span class=\"math inline\">\\((0,\\pi)\\)</span>, and likewise on <span class=\"math inline\">\\((\\pi,2\\pi)\\)</span>; if <span class=\"math inline\">\\(\\theta_0 = \\pi/2\\)</span>, it vanishes at <span class=\"math inline\">\\(\\tau = 0,\\pi\\)</span>. Hence <span class=\"math inline\">\\(\\min\\kappa = 1/\\ell\\)</span>.</p>\n<p>We prove <span class=\"math inline\">\\(v\\ge v_*\\)</span> on the box. Put <span class=\"math inline\">\\(x = \\cos^2\\tau\\in[0,1]\\)</span>, <span class=\"math inline\">\\(\\delta = \\Delta\\theta_-\\)</span>, <span class=\"math inline\">\\(\\varpi = m\\Delta\\phi_-\\)</span>. Since <span class=\"math inline\">\\(\\cos^22\\tau = (2x-1)^2\\)</span> and both terms of <span class=\"math inline\">\\(v^2\\)</span> are nondecreasing in <span class=\"math inline\">\\(\\Delta\\theta\\)</span>, <span class=\"math inline\">\\(\\Delta\\phi\\)</span> and <span class=\"math inline\">\\(\\sin\\theta\\ge m\\)</span>, <span class=\"math display\">\\begin{equation}\n    v^2 \\ge q(x) = 4\\delta^2(2x-1)^2 + \\varpi^2 x .\n\\tag{134}\\end{equation}</span> The convex quadratic <span class=\"math inline\">\\(q\\)</span> is minimal at <span class=\"math inline\">\\(x^* = \\tfrac12 - \\varpi^2/(32\\delta^2) &lt; 1\\)</span>. If <span class=\"math inline\">\\(\\varpi\\ge4\\delta\\)</span>, then <span class=\"math inline\">\\(x^*\\le0\\)</span> and <span class=\"math inline\">\\(\\min_{[0,1]}q = q(0) = 4\\delta^2\\)</span>. Otherwise <span class=\"math inline\">\\(x^*\\in(0,1)\\)</span>, <span class=\"math inline\">\\(2x^*-1 = -\\varpi^2/(16\\delta^2)\\)</span>, and <span class=\"math display\">\\begin{equation}\n    q(x^*) = \\frac{\\varpi^4}{64\\delta^2} + \\frac{\\varpi^2}2 - \\frac{\\varpi^4}{32\\delta^2} = \\frac{\\varpi^2}2 - \\frac{\\varpi^4}{64\\delta^2},\n\\tag{135}\\end{equation}</span> which is <span class=\"math inline\">\\(v_*^2\\)</span>.</p>\n<p>We prove <span class=\"math inline\">\\(\\abs{\\kappa_g}\\le\\bar\\kappa_g\\)</span> on the box. With <span class=\"math inline\">\\(y = \\sin\\tau\\)</span>, <span class=\"math inline\">\\(\\abs{\\sin\\tau}\\,(2+\\cos2\\tau) = \\abs{y}\\,(3-2y^2)\\le\\sqrt2\\)</span> on <span class=\"math inline\">\\([-1,1]\\)</span> (maximum at <span class=\"math inline\">\\(y^2 = 1/2\\)</span>). Also <span class=\"math inline\">\\(8\\Delta\\theta^2\\cos^22\\tau + \\Delta\\phi^2\\sin^2\\theta\\cos^2\\tau\\le2v^2\\)</span>. Hence <span class=\"math display\">\\begin{equation}\n    \\abs{\\kappa_g} \\le \\frac{2\\sqrt2\\,M\\,\\Delta\\theta\\Delta\\phi}{v^3} + \\frac{2C\\,\\Delta\\phi\\,\\abs{\\cos\\tau}}{v},\n\\tag{136}\\end{equation}</span> and <span class=\"math inline\">\\(v\\ge\\Delta\\phi\\sin\\theta\\,\\abs{\\cos\\tau}\\ge m\\Delta\\phi\\,\\abs{\\cos\\tau}\\)</span> bounds the last term by <span class=\"math inline\">\\(2C/m\\)</span>; the first is at most <span class=\"math inline\">\\(2\\sqrt2\\,M\\Delta\\theta_+\\Delta\\phi_+/v_*^3\\)</span> by the lower bound <span class=\"math inline\">\\(v\\ge v_*\\)</span>.</p>\n<p>With <span class=\"math inline\">\\(s = u_\\sigma^2\\ge0\\)</span> and <span class=\"math inline\">\\(w = u_{\\sigma\\sigma}\\)</span>, <span class=\"math inline\">\\(\\kappa_g^2(1+s)/(1+s)^3\\le\\kappa_g^2\\)</span> and <span class=\"math display\">\\begin{equation}\n    \\frac{(1+s-w)^2}{(1+s)^3} \\le \\frac{(1+s+\\abs{w})^2}{(1+s)^3} = \\frac{\\bigl(1+\\abs{w}/(1+s)\\bigr)^2}{1+s} \\le (1+\\abs{w})^2,\n\\tag{137}\\end{equation}</span> so that <span class=\"math inline\">\\(r\\kappa\\le\\sqrt{\\kappa_g^2 + (1+\\abs{u_{\\sigma\\sigma}})^2}\\)</span>, and <span class=\"math inline\">\\(r\\ge\\ell-a\\ge\\ell_--a\\)</span>.</p>\n<p>We show <span class=\"math inline\">\\(\\abs{u_{\\sigma\\sigma}}\\le U\\)</span>. Write <span class=\"math inline\">\\(p = a\\,g\\)</span> with <span class=\"math inline\">\\(g = \\sin\\theta\\cos\\psi\\)</span>, <span class=\"math inline\">\\(\\psi = \\phi-\\alpha\\)</span>. Then <span class=\"math display\">\\begin{equation}\n\\begin{split}\n    g' &amp;= \\cos\\theta\\,\\theta'\\cos\\psi - \\sin\\theta\\sin\\psi\\,\\psi', \\\\\n    g'' &amp;= -\\sin\\theta\\,\\theta'^2\\cos\\psi + \\cos\\theta\\,\\theta''\\cos\\psi - 2\\cos\\theta\\,\\theta'\\psi'\\sin\\psi - \\sin\\theta\\cos\\psi\\,\\psi'^2 - \\sin\\theta\\sin\\psi\\,\\psi'' ,\n\\end{split}\n\\tag{138}\\end{equation}</span> and with <span class=\"math inline\">\\(\\abs{\\theta&#39;}\\le2\\Delta\\theta_+\\)</span>, <span class=\"math inline\">\\(\\abs{\\theta&#39;&#39;}\\le4\\Delta\\theta_+\\)</span>, <span class=\"math inline\">\\(\\abs{\\psi&#39;}\\le\\Delta\\phi_++A_1\\)</span>, <span class=\"math inline\">\\(\\abs{\\psi&#39;&#39;}\\le\\Delta\\phi_++A_2\\)</span>, we get <span class=\"math inline\">\\(\\abs{g&#39;}\\le\\abs{\\theta&#39;}+\\abs{\\psi&#39;}\\le\\Gamma_1\\)</span> and <span class=\"math inline\">\\(\\abs{g&#39;&#39;}\\le(\\abs{\\theta&#39;}+\\abs{\\psi&#39;})^2 + \\abs{\\theta&#39;&#39;} + \\abs{\\psi&#39;&#39;}\\le\\Gamma_2\\)</span>. Using <span class=\"math inline\">\\(u_p = 1/R\\)</span> and <span class=\"math inline\">\\(u_{pp} = -p/R^3\\)</span>, <span class=\"math inline\">\\(u&#39; = u_p\\,a g&#39;\\)</span> and <span class=\"math inline\">\\(u&#39;&#39; = u_p\\,a g&#39;&#39; + u_{pp}\\,a^2g&#39;^2\\)</span>, so that <span class=\"math display\">\\begin{equation}\n    \\abs{u'}\\le\\varepsilon'\\,\\Gamma_1, \\qquad \\abs{u''}\\le\\varepsilon'\\,\\Gamma_2 + \\varepsilon'^3\\,\\Gamma_1^2 .\n\\tag{139}\\end{equation}</span> Next, <span class=\"math inline\">\\(v&#39; = (\\vu r&#39;\\vdot\\vu r&#39;&#39;)/v = \\vu t\\vdot\\vu r&#39;&#39;\\)</span> is bounded by the tangential part of <span class=\"math inline\">\\(\\vu r&#39;&#39;\\)</span> computed above: <span class=\"math display\">\\begin{equation}\n    \\abs{v'}\\le\\abs{\\theta''} + \\tfrac12\\phi'^2 + \\abs{\\phi''} + 2\\abs{\\theta'}\\abs{\\phi'}\\le V_1 .\n\\tag{140}\\end{equation}</span> Finally <span class=\"math inline\">\\(\\abs{u_{\\sigma\\sigma}}\\le\\abs{u&#39;&#39;}/v^2 + \\abs{u&#39;}\\abs{v&#39;}/v^3\\)</span>, and <span class=\"math inline\">\\(v\\ge v_*\\)</span> gives <span class=\"math inline\">\\(U\\)</span>.</p>\n<p>Combining the bounds on <span class=\"math inline\">\\(\\kappa_g\\)</span>, on <span class=\"math inline\">\\(r\\kappa\\)</span> and on <span class=\"math inline\">\\(u_{\\sigma\\sigma}\\)</span>, <span class=\"math inline\">\\(\\kappa\\le\\sqrt{\\bar\\kappa_g^2 + (1+U)^2}/r\\le\\sqrt{\\bar\\kappa_g^2 + (1+U)^2}/(\\ell_--a)\\)</span>. For <span class=\"math inline\">\\(a=0\\)</span>, <span class=\"math inline\">\\(U=0\\)</span> and <span class=\"math inline\">\\(r=\\ell\\ge\\ell_-\\)</span>, and the lower bound was proved above. As <span class=\"math inline\">\\(\\varepsilon&#39; = \\varepsilon/\\sqrt{1-\\varepsilon^2}\\)</span>, <span class=\"math inline\">\\(U = O(\\varepsilon)\\)</span>.</p>\n<p>From the expression of <span class=\"math inline\">\\(r\\)</span>, <span class=\"math inline\">\\(r = \\ell\\bigl(\\varepsilon g + \\sqrt{1-\\varepsilon^2+\\varepsilon^2g^2}\\bigr)\\)</span>, so that <span class=\"math inline\">\\(u = \\ln\\ell + \\varepsilon g + O(\\varepsilon^2)\\)</span> and <span class=\"math inline\">\\(1/r = (1-\\varepsilon g)/\\ell + O(\\varepsilon^2)\\)</span>, with <span class=\"math inline\">\\(O(\\varepsilon^2)\\)</span> remainders whose first two <span class=\"math inline\">\\(\\tau\\)</span>-derivatives are <span class=\"math inline\">\\(O(\\varepsilon^2)\\)</span> when <span class=\"math inline\">\\(\\alpha&#39;\\)</span>, <span class=\"math inline\">\\(\\alpha&#39;&#39;\\)</span> are bounded. Since <span class=\"math inline\">\\(v\\ge v_*&gt;0\\)</span>, <span class=\"math inline\">\\(u_\\sigma = O(\\varepsilon)\\)</span> and <span class=\"math inline\">\\(u_{\\sigma\\sigma} = \\varepsilon\\,g_{\\sigma\\sigma} + O(\\varepsilon^2)\\)</span> uniformly. Then <a href=\"section-4.html#eq:curv-formula\">(63)</a> gives <span class=\"math display\">\\begin{equation}\n    r\\kappa = \\sqrt{\\kappa_g^2 + (1-u_{\\sigma\\sigma})^2} + O(\\varepsilon^2) = K - \\varepsilon\\,\\frac{g_{\\sigma\\sigma}}{K} + O(\\varepsilon^2),\n\\tag{141}\\end{equation}</span> and multiplying by <span class=\"math inline\">\\(\\ell/r\\)</span> yields <a href=\"section-4.html#eq:curv-first-order\">(71)</a>.</p>"},{"title":"A 10D model","page":"A 10D model","location":"appendix-A.html#sec:model10D","category":"section","text":""},{"title":"Model description","page":"A 10D model","location":"appendix-A.html#model-description","category":"section","text":"<p>In this appendix, we describe the model designed by Alain Nême inspired by Fagiano PhD thesis and Diehl PhD thesis. The objective is to have an ODE that does not involve a control to simulate a kite flying horizontal eights, or lemniscates, while the arm extracts energy from the system. The kite <span class=\"math inline\">\\(K\\)</span> is attached to the tip of a rotating arm <span class=\"math inline\">\\(A\\)</span> of length <span class=\"math inline\">\\(a\\)</span> with four lines of length <span class=\"math inline\">\\(\\ell\\)</span> (assumed constant), the arm rotates around <span class=\"math inline\">\\(\\vu z\\)</span> at the origin <span class=\"math inline\">\\(O\\)</span>.</p>"},{"title":"Static and kinematics","page":"A 10D model","location":"appendix-A.html#static-and-kinematics","category":"section","text":"<p>Let us define three unit vectors: <span class=\"math inline\">\\(\\vu a\\)</span> follows the arm, <span class=\"math inline\">\\(\\hat{\\boldsymbol{\\ell}}\\)</span> follows the lines and <span class=\"math inline\">\\(\\vu r\\)</span> points to the kite: <a id=\"eq:that-10D\"></a><span class=\"math display\">\\begin{align}\n    \\vu a &amp;= \\frac{\\vb a}{\\norm{\\vb a}} = \\begin{pmatrix}\n        \\cos(\\alpha) \\\\ \\sin(\\alpha) \\\\ 0\n    \\end{pmatrix} \\tag{72}\\\\\n    \\hat{\\boldsymbol{\\ell}} &amp;= \\frac{\\boldsymbol{\\ell}}{\\norm{\\boldsymbol{\\ell}}} = \\begin{pmatrix}\n        \\sin(\\theta_\\ell) \\cos(\\alpha + \\phi_\\ell) \\\\ \\sin(\\theta_\\ell) \\sin(\\alpha + \\phi_\\ell) \\\\ \\cos(\\theta_\\ell)\n    \\end{pmatrix} \\tag{73}\\\\ \\tag{74}\n    \\vu r &amp;= \\frac{\\vb r}{\\norm{\\vb r}} = \\begin{pmatrix}\n        \\sin(\\theta(\\tau)) \\cos(\\phi(\\tau)) \\\\ \\sin(\\theta(\\tau)) \\sin(\\phi(\\tau)) \\\\ \\cos(\\theta(\\tau))\n    \\end{pmatrix} \\text{ with}\n    \\begin{cases}\n        \\theta : \\tau \\mapsto \\theta_0 + \\Delta \\theta \\sin(2\\tau) \\\\\n        \\phi : \\tau \\mapsto \\Delta \\phi \\sin(\\tau)\n    \\end{cases}.\n\\end{align}</span> Here, <span class=\"math inline\">\\(\\alpha\\)</span> is the angle between the arm and the <span class=\"math inline\">\\(x\\)</span>-axis (aligned with the wind), <span class=\"math inline\">\\(\\theta_\\ell\\)</span>, <span class=\"math inline\">\\(\\phi_\\ell\\)</span> are the spherical coordinates of <span class=\"math inline\">\\(K\\)</span> in <span class=\"math inline\">\\((A, \\vu a, \\vu z \\times \\vu a, \\vu z)\\)</span>, and <span class=\"math inline\">\\(R\\)</span>, <span class=\"math inline\">\\(\\theta\\)</span> and <span class=\"math inline\">\\(\\phi\\)</span> are the spherical coordinates of <span class=\"math inline\">\\(K\\)</span> in <span class=\"math inline\">\\((O, \\vu x, \\vu y, \\vu z)\\)</span>. Spherical coordinates use the physics convention also found in ISO 80000-2:2019:</p>\n<ul>\n<li><p><span class=\"math inline\">\\(R\\)</span> is the radius,</p></li>\n<li><p><span class=\"math inline\">\\(\\theta\\)</span> is the polar angle from the <span class=\"math inline\">\\(z\\)</span>-axis,</p></li>\n<li><p><span class=\"math inline\">\\(\\phi\\)</span> is the azimuthal angle from the <span class=\"math inline\">\\(x\\)</span>-axis.</p></li>\n</ul>\n<p>The state of the system at time <span class=\"math inline\">\\(t\\)</span> is given by the configuration vector <a id=\"eq:state_vector\"></a><span class=\"math display\">\\begin{equation}\n \\tag{75}\n    \\vb q(t) = (\\alpha(t), \\theta_\\ell(t), \\phi_\\ell(t), R(t), \\tau(t))\n\\end{equation}</span> and its corresponding velocities <span class=\"math inline\">\\(\\dot{\\vb q}(t)\\)</span>, while <span class=\"math inline\">\\(\\theta_0\\)</span>, <span class=\"math inline\">\\(\\Delta \\theta\\)</span> and <span class=\"math inline\">\\(\\Delta \\phi\\)</span> are the parameters that control the shape of the lemniscate. Note that:</p>\n<ul>\n<li><p><span class=\"math inline\">\\(\\vb a\\)</span> depends only on state <span class=\"math inline\">\\(\\alpha\\)</span>,</p></li>\n<li><p><span class=\"math inline\">\\(\\boldsymbol{\\ell}\\)</span> depends only on state <span class=\"math inline\">\\(\\theta_\\ell\\)</span> and <span class=\"math inline\">\\(\\phi_\\ell\\)</span>,</p></li>\n<li><p><span class=\"math inline\">\\(\\vb r\\)</span> depends only on state <span class=\"math inline\">\\(R\\)</span> and <span class=\"math inline\">\\(\\tau\\)</span>.</p></li>\n</ul>\n<p>Using Chasles’ relation, we get the following loop closure condition: <a id=\"eq:loop_closure_vector\"></a><span class=\"math display\">\\begin{equation}\n \\tag{76}\n    \\vb r = \\vb a + \\boldsymbol{\\ell}.\n\\end{equation}</span> We define <a id=\"eq:func_g\"></a><span class=\"math display\">\\begin{equation}\n \\tag{77}\n\\begin{split}\n    \\vb g : \\vb q\\in \\mathbf{R}^5 \\mapsto\n    \\vb g(\\vb q) &amp;= \\vb r(\\vb q) - \\vb a(\\vb q) - \\boldsymbol{\\ell}(\\vb q) \\\\\n    &amp;= \\begin{pmatrix}\n        R \\sin(\\theta(\\tau)) \\cos(\\phi(\\tau)) - a \\cos(\\alpha) - \\ell \\sin(\\theta_\\ell) \\cos(\\alpha + \\phi_\\ell) \\\\\n        R \\sin(\\theta(\\tau)) \\sin(\\phi(\\tau)) - a \\sin(\\alpha) - \\ell \\sin(\\theta_\\ell) \\sin(\\alpha + \\phi_\\ell) \\\\\n        R \\cos(\\theta(\\tau)) - \\ell \\cos(\\theta_\\ell)\n    \\end{pmatrix} \\in \\mathbf{R}^3\n\\end{split}\n\\end{equation}</span> such that <a href=\"#eq:loop_closure_vector\">(76)</a> rewrites to <a id=\"eq:loop_closure_function\"></a><span class=\"math display\">\\begin{equation}\n \\tag{78}\n    \\vb g(\\vb q) = 0_{\\mathbf{R}^3}\n\\end{equation}</span> We have a five dimensional state (<em>cf.</em> <a href=\"#eq:state_vector\">(75)</a>) subject to three algebraic constraints (<em>cf.</em> <a href=\"#eq:loop_closure_function\">(78)</a>), thus the system has two <span data-acronym-label=\"dof\" data-acronym-form=\"singular+short\">dof</span>.</p>\n<div class=\"remark\">\n<p>The set of acceptable positions for <span class=\"math inline\">\\(K\\)</span> is the intersection between a filled torus (filled <em>spindle</em> torus if the lines are longer than the arm, <em>i.e.</em> <span class=\"math inline\">\\(\\ell &gt; a\\)</span>) and an eight-shaped cone. See Fig. <a href=\"section-1.html#fig:spindle_torus\">4</a> and Section <a href=\"section-1.html#sec:model-geometry\">1.1</a>.</p>\n</div>"},{"title":"A.3 Dynamics","page":"A 10D model","location":"appendix-A.html#sec:model10D-dynamics","category":"section","text":"<p>We assume that all forces apply to the kite at point <span class=\"math inline\">\\(K\\)</span> of mass <span class=\"math inline\">\\(m\\)</span> and all moments apply to the arm which rotates around <span class=\"math inline\">\\(\\vu z\\)</span> at point <span class=\"math inline\">\\(O\\)</span>. We want to determine <span class=\"math inline\">\\(\\ddot{\\vb q}\\)</span> in terms of <span class=\"math inline\">\\(\\vb q\\)</span> and <span class=\"math inline\">\\(\\dot{\\vb q}\\)</span>.</p>\n<p><span id=\"sec:model10D-dyn-aero\" data-label=\"sec:model10D-dyn-aero\"></span></p>\n<p>We choose the 1/7-power-law profile to model the wind, such that the wind speed <span class=\"math inline\">\\(\\vb w\\)</span> at altitude <span class=\"math inline\">\\(z\\)</span> is given by <span class=\"math inline\">\\(\\vb w(z) = w_r \\qty( z / z_r )^{1/7} \\vu x\\)</span>. The apparent wind, the wind which is felt by the kite, is then <span class=\"math inline\">\\(\\vb w_a = \\vb w - \\dot{\\vb r}\\)</span>. The lift <span class=\"math inline\">\\(L\\)</span> and drag <span class=\"math inline\">\\(D\\)</span> of the kite are respectively <span class=\"math display\">\\begin{align}\n    L &amp;= \\frac{1}{2} S \\rho_a C_L \\norm{\\vb w_a}^2 \\tag{79}\\\\\n    D &amp;= \\frac{1}{2} S \\rho_a C_D \\norm{\\vb w_a}^2\n\\tag{80}\\end{align}</span> where <span class=\"math inline\">\\(S\\)</span> is the surface of the kite, <span class=\"math inline\">\\(\\rho_a\\)</span> is the density of the air and <span class=\"math inline\">\\(C_L\\)</span> and <span class=\"math inline\">\\(C_D\\)</span> the lift and drag coefficients. Using the lift-to-drag ratio <span class=\"math inline\">\\(f = L / D\\)</span>, we get the simpler <span class=\"math inline\">\\(D = L/f\\)</span>. realistically, <span class=\"math inline\">\\(C_L\\)</span> and <span class=\"math inline\">\\(C_D\\)</span> should depend on the angle of incidence, but we don’t model this angle and assume of value of <span class=\"math inline\">\\(0\\)</span>. To determine the direction of the lift and drag forces, we assume that the chord of the kite is aligned with the apparent wind, and that its leading edge is perpendicular to the lines, which completely determines the orientation of the kite. Let us define <span class=\"math inline\">\\(\\vu k_b\\)</span> the unit vector aligned with the chord pointing to the <em>back</em> of the kite, <span class=\"math inline\">\\(\\vu k_r\\)</span> the unit vector aligned with the leading edge pointing to the <em>right</em> of the kite, and <span class=\"math inline\">\\(\\vu k_t\\)</span> the unit vector normal to the surface of the kite pointing to its <em>top</em>. We have : <span class=\"math display\">\\begin{align}\n    \\vu k_b &amp;= \\frac{\\vb w_a }{\\norm{\\vb w_a}} \\tag{81}\\\\\n    \\vu k_r &amp;= \\frac{\\hat{\\boldsymbol{\\ell}} \\times \\vu k_b}{\\norm{\\hat{\\boldsymbol{\\ell}} \\times \\vu k_b}} \\tag{82}\\\\\n    \\vu k_t &amp;= \\vu k_b \\times \\vu k_r.\n\\tag{83}\\end{align}</span> We then obtain the aerodynamic forces of the kite <span class=\"math display\">\\begin{align}\n    \\vb L &amp;= L \\vu k_t \\tag{84}\\\\\n    \\vb D &amp;= D \\vu k_b.\n\\tag{85}\\end{align}</span></p>\n<p>To assess the impact of line length on the performance of the device, we also need to model the drag of the lines. Let us first define the apparent wind of the lines at distance <span class=\"math inline\">\\(\\lambda\\)</span> from the attachment point <span class=\"math inline\">\\(A\\)</span>: <span class=\"math display\">\\begin{equation}\n    \\vb w_{a,\\ell}(\\lambda) = \\vb w\\qty(\\frac{\\lambda}{\\ell} K_z) - \\frac{\\lambda}{\\ell} \\dot{\\vb r} - \\qty(1 - \\frac{\\lambda}{\\ell}) \\dot{\\vb a},\n\\tag{86}\\end{equation}</span> and <span class=\"math inline\">\\(\\vu w_a = \\frac{\\vb w_a}{\\norm{\\vb w_a}}\\)</span> is its unit vector. Let <span class=\"math inline\">\\(\\theta_a\\)</span> be the angle between the lines and the apparent wind: <span class=\"math inline\">\\(\\hat{\\boldsymbol{\\ell}} \\cdot \\vu w_{a,\\ell} = \\cos(\\theta_a)\\)</span>, so that <span class=\"math inline\">\\(\\sin(\\theta_a) = \\sqrt{1 - (\\hat{\\boldsymbol{\\ell}} \\cdot \\vu w_{a,\\ell})^2}\\)</span>. Following the cross-flow principle, the drag of an element of line of length <span class=\"math inline\">\\(\\dd{\\lambda}\\)</span> and diameter <span class=\"math inline\">\\(d_\\ell\\)</span> depends only on the component of the apparent wind orthogonal to the lines, <span class=\"math inline\">\\(\\vb w_{a,\\ell}^\\perp = \\vb w_{a,\\ell} - (\\hat{\\boldsymbol{\\ell}} \\cdot \\vb w_{a,\\ell})\\,\\hat{\\boldsymbol{\\ell}}\\)</span>, of norm <span class=\"math inline\">\\(\\norm{\\vb w_{a,\\ell}}\\sin(\\theta_a)\\)</span>, and is directed along it. The drag of the <span class=\"math inline\">\\(n = 4\\)</span> lines with drag coefficient <span class=\"math inline\">\\(C_{D,\\ell}\\)</span> is <span class=\"math display\">\\begin{equation}\n    \\vb D_\\ell\n    = \\int\\limits_{\\lambda = 0}^{\\lambda = \\ell} \\frac{1}{2} n d_\\ell \\rho_a C_{D,\\ell} \\norm{\\vb w_{a,\\ell}^\\perp(\\lambda)}\\, \\vb w_{a,\\ell}^\\perp(\\lambda) \\dd{\\lambda}\n    = \\frac{1}{2} n \\ell d_\\ell \\rho_a C_{D,\\ell} \\int \\limits_{\\xi=0}^{\\xi=1} \\norm{\\vb w_{a,\\ell}^\\perp(\\ell \\xi)}\\, \\vb w_{a,\\ell}^\\perp(\\ell \\xi) \\dd{\\xi}.\n\\tag{87}\\end{equation}</span> We approximate this integral by assuming that the speed of <span class=\"math inline\">\\(A\\)</span> is negligible, <span class=\"math inline\">\\(\\dot{\\vb a} \\approx 0\\)</span>, and that the apparent wind varies linearly along the lines, <span class=\"math inline\">\\(\\vb w_{a,\\ell}(\\ell\\xi) \\approx \\xi\\, \\vb w_a\\)</span>. Then <span class=\"math inline\">\\(\\vb w_{a,\\ell}^\\perp(\\ell\\xi) \\approx \\xi\\, \\vb w_a^\\perp\\)</span>, and the integral of <span class=\"math inline\">\\(\\xi^2\\)</span> over <span class=\"math inline\">\\([0,1]\\)</span> gives the approximated drag of the lines <a id=\"eq:line-drag-10D\"></a><span class=\"math display\">\\begin{equation}\n \\tag{88}\n    \\tilde{\\vb D}_\\ell = \\tilde D_\\ell\\, \\vu w_a^\\perp, \\qquad \\tilde D_\\ell = \\frac{1}{6} n \\ell d_\\ell \\rho_a C_{D,\\ell} \\norm{\\vb w_a^\\perp}^2, \\qquad \\vu w_a^\\perp = \\frac{\\vb w_a^\\perp}{\\norm{\\vb w_a^\\perp}},\n\\end{equation}</span> and the total aerodynamic force of the system is <a id=\"eq:f_aero_10D\"></a><span class=\"math display\">\\begin{equation}\n \\tag{89}\n    \\vb F_a = L \\vu k_t + D \\vu k_b + \\tilde D_\\ell \\vu w_a^\\perp.\n\\end{equation}</span> In all the computations of this paper, <span class=\"math inline\">\\(C_{D,\\ell} = 0\\)</span>: the drag of the lines is lumped into the drag coefficient <span class=\"math inline\">\\(C_D\\)</span> of the kite.</p>\n<p>The kite has mass <span class=\"math inline\">\\(m\\)</span> and the lines have density <span class=\"math inline\">\\(\\rho_\\ell\\)</span>, therefore their mass is <span class=\"math inline\">\\(m_\\ell = n \\pi \\ell \\rho_\\ell d_\\ell^2 / 4\\)</span>. We assume that the kite lifts half of the lines, while the rest is supported by the arm. The total flying mass is then <span class=\"math inline\">\\(m + m_\\ell/2\\)</span> and the total weight is <a id=\"eq:f_grav_10D\"></a><span class=\"math display\">\\begin{equation}\n \\tag{90}\n    \\vb F_g = -\\qty(m + \\frac{m_\\ell}{2}) g \\vu z.\n\\end{equation}</span></p>\n<p>We denote <span class=\"math inline\">\\(\\vb F_\\ell = -F_\\ell \\hat{\\boldsymbol{\\ell}}\\)</span> the tension of the lines on the kite, then, the torque applied by the lines on the arm is <span class=\"math display\">\\begin{equation}\n    \\vb T_\\ell = \\vb a \\times (- \\vb F_\\ell) = a F_\\ell \\vu a \\times \\hat{\\boldsymbol{\\ell}}.\n\\tag{91}\\end{equation}</span> Since the arm rotates around the <span class=\"math inline\">\\(z\\)</span> axis, only the torque in the <span class=\"math inline\">\\(z\\)</span> direction has an effect, therefore we only need the <span class=\"math inline\">\\(z\\)</span> component of <span class=\"math inline\">\\(\\vb T_\\ell\\)</span>. Also, for computing the cross-product, let us rewrite the vectors <span class=\"math inline\">\\(\\vu a\\)</span> and <span class=\"math inline\">\\(\\hat{\\boldsymbol{\\ell}}\\)</span> in the base attached to the arm <span class=\"math inline\">\\(\\mathscr B_a = (\\vu a, \\vu z \\times \\vu a, \\vu z)\\)</span>; trivially, <span class=\"math inline\">\\(\\vu a = 1 \\vu a\\)</span> and <a id=\"eq:lhat-10D\"></a><span class=\"math display\">\\begin{equation}\n \\tag{92}\n    \\hat{\\boldsymbol{\\ell}} = \\sin(\\theta_\\ell) \\cos(\\phi_\\ell) \\vu a + \\sin(\\theta_\\ell) \\sin(\\phi_\\ell) (\\vu z \\times \\vu a) + \\cos(\\theta_\\ell) \\vu z.\n\\end{equation}</span> Let us now compute the cross-product: <span class=\"math display\">\\begin{equation}\n    \\vu z \\cdot (F_\\ell \\vu a \\times \\hat{\\boldsymbol{\\ell}}) = 1 \\cdot \\sin(\\theta_\\ell) \\sin(\\phi_\\ell) - 0 \\cdot \\sin(\\theta_\\ell) \\cos(\\phi_\\ell) = \\sin(\\theta_\\ell) \\sin(\\phi_\\ell),\n\\tag{93}\\end{equation}</span> from which we finally get the expression for the effective torque of the lines: <span class=\"math display\">\\begin{equation}\n    \\vb T_\\ell \\cdot \\vu z = a F_\\ell \\sin(\\theta_\\ell) \\sin(\\phi_\\ell).\n\\tag{94}\\end{equation}</span> The torque of the generator on the arm is <span class=\"math inline\">\\(T : \\omega \\mapsto -b \\omega\\)</span> where <span class=\"math inline\">\\(b\\)</span> is a rotational viscous damping coefficient with dimension of torque per angular velocity, and the arm has inertia <span class=\"math inline\">\\(I\\)</span>, such that using Newton’s second law, we get <a id=\"eq:newton_arm_10D\"></a><span class=\"math display\">\\begin{equation}\n \\tag{95}\n    I \\ddot \\alpha\n    = \\vb T_\\ell \\cdot \\vu z + T(\\dot \\alpha)\n    = a F_\\ell \\sin(\\theta_\\ell) \\sin(\\phi_\\ell) - b \\dot \\alpha,\n\\end{equation}</span> from which we compute <span class=\"math inline\">\\(\\vb F_\\ell\\)</span>, directed by <span class=\"math inline\">\\(-\\hat{\\boldsymbol{\\ell}}\\)</span>: <a id=\"eq:f_lines-10D\"></a><span class=\"math display\">\\begin{equation}\n \\tag{96}\n    \\vb F_\\ell = \\frac{-I \\ddot \\alpha - b \\dot \\alpha}{a \\sin(\\theta_\\ell) \\sin(\\phi_\\ell)} \\hat{\\boldsymbol{\\ell}}.\n\\end{equation}</span> In the above, the lever arm of the tension is <span class=\"math inline\">\\(a \\sin(\\theta_\\ell) \\sin(\\phi_\\ell)\\)</span>. For <span class=\"math inline\">\\(\\sin(\\theta_\\ell)\\)</span> to be zero, the kite would have to fly underground directly below the tip of the arm, which won’t happen, or directly above it, which also won’t happen if <span class=\"math inline\">\\(\\theta_0 - \\Delta \\theta &gt; 0\\)</span>, <em>cf</em>. <a href=\"#eq:lhat-10D\">(92)</a>, which is verified for realistic values of <span class=\"math inline\">\\(\\theta_0\\)</span> and <span class=\"math inline\">\\(\\Delta \\theta\\)</span>. With a typical choice of parameters the kite will never fly directly above the tip of the arm, thus <span class=\"math inline\">\\(\\sin(\\theta_\\ell) &gt; 0\\)</span> at all times. However, <span class=\"math inline\">\\(\\sin(\\phi_\\ell)\\)</span> could very well be null, but the singularity is only in the equations, as we observe no exceptional behavior when the lines and the arm are aligned (<span class=\"math inline\">\\(xy\\)</span>-plane); for the reduced model, it is removed by solving the equation of the arm for <span class=\"math inline\">\\(\\ddot\\alpha\\)</span> instead of the tension (Section <a href=\"section-1.html#sec:model-eom\">1.4</a> and Appendix <a href=\"appendix-B.html#sec:explicit-ddq\">B</a>).</p>\n<p>To understand this section better, let’s picture a train on a railway. The train doesn’t control where by steering (a <em>control</em> in the mathematical sense), instead, the railway exerts a force on the train, always perpendicular to railway/the direction of the train, that keeps the train on the track passively. We want the eight-shaped cone to play the role of the railway to passively steer the kite into eight-shaped trajectories. One way to physically describe this interaction is that the kite glides without friction on the manifold, therefore it feels a fictitious force <span class=\"math inline\">\\(\\vb F_c\\)</span> always perpendicular to the manifold. The cone has two tangent vectors <span class=\"math inline\">\\(\\pdv{\\vb r}{R}\\)</span> and <span class=\"math inline\">\\(\\pdv{\\vb r}{\\tau}\\)</span>, therefore it is normal to both: <a id=\"eq:f_cone_constraint_10D\"></a><span class=\"math display\">\\begin{equation}\n\\begin{cases} \\tag{97}\n    \\vb F_c \\cdot \\pdv{\\vb r}{R} = 0 \\\\\n    \\vb F_c \\cdot \\pdv{\\vb r}{\\tau} = 0.\n\\end{cases}\n\\end{equation}</span></p>"},{"title":"applying Newton’s second law to the kite","page":"A 10D model","location":"appendix-A.html#applying-newtons-second-law-to-the-kite","category":"section","text":"<p>Newton’s second law applied to the kite’s center of mass gives <a id=\"eq:newton_kite_10D\"></a><span class=\"math display\">\\begin{equation}\n \\tag{98}\n    m \\ddot{\\vb r} = \\vb F_a + \\vb F_g + \\vb F_\\ell + \\vb F_c.\n\\end{equation}</span> At this point, we need to choose two equations to keep, while the others will be used at substitutions. For their nice symmetry, we keep <a href=\"#eq:f_cone_constraint_10D\">(97)</a> and use the others to express <span class=\"math inline\">\\(\\vb F_c\\)</span> in terms of <span class=\"math inline\">\\(\\vb q, \\dot{\\vb q}\\)</span>, and <span class=\"math inline\">\\(\\ddot{\\vb q}\\)</span>. From <a href=\"#eq:newton_kite_10D\">(98)</a>, we have that <a id=\"eq:f_cone_newton_10D\"></a><span class=\"math display\">\\begin{equation}\n \\tag{99}\n    \\vb F_c = m \\ddot{\\vb r} - \\vb F_a - \\vb F_g - \\vb F_\\ell.\n\\end{equation}</span> The acceleration of the kite <span class=\"math inline\">\\(\\ddot{\\vb r}\\)</span> obtained by differentiating twice its position <span class=\"math inline\">\\(\\vb r\\)</span>: <span class=\"math display\">\\begin{equation}\n    \\vb r = R \\vu r = R \\begin{pmatrix}\n        \\sin(\\theta) \\cos(\\phi) \\\\\n        \\sin(\\theta) \\sin(\\phi) \\\\\n        \\cos(\\theta)\n    \\end{pmatrix},\n\\tag{100}\\end{equation}</span> <span class=\"math display\">\\begin{equation}\n\\begin{split}\n    \\dot{\\vb r} &amp;= \\dot R \\vu r + R \\dot{\\vu r}\n    = \\dot R \\begin{pmatrix}\n        \\sin(\\theta) \\cos(\\phi) \\\\\n        \\sin(\\theta) \\sin(\\phi) \\\\\n        \\cos(\\theta)\n    \\end{pmatrix} + R \\begin{pmatrix}\n        \\cos(\\theta) \\cos(\\phi) \\dot \\theta - \\sin(\\theta) \\sin(\\phi) \\dot \\phi \\\\\n        \\cos(\\theta) \\sin(\\phi) \\dot \\theta + \\sin(\\theta) \\cos(\\phi) \\dot \\phi \\\\\n        -\\sin(\\theta) \\dot \\theta\n    \\end{pmatrix} \\\\\n    &amp;= \\begin{pmatrix}\n        \\sin(\\theta) \\cos(\\phi) \\dot R + \\cos(\\theta) \\cos(\\phi) \\dot \\theta - \\sin(\\theta) \\sin(\\phi) \\dot \\phi \\\\\n        \\sin(\\theta) \\sin(\\phi) \\dot R + \\cos(\\theta) \\sin(\\phi) \\dot \\theta + \\sin(\\theta) \\cos(\\phi) \\dot \\phi \\\\\n        \\cos(\\theta) \\dot R - \\sin(\\theta) \\dot \\theta\n    \\end{pmatrix},\n\\end{split}\n\\tag{101}\\end{equation}</span> <span class=\"math display\">\\begin{equation}\n\\begin{split}\n    \\ddot{\\vb r} &amp;= \\ddot R \\vu r + \\dot R \\dot{\\vu r} + \\dot R \\dot{\\vu r} + R \\ddot{\\vu r} = \\ddot R \\vu r + 2 \\dot R \\dot{\\vu r} + R \\ddot{\\vu r}.\n\\end{split}\n\\tag{102}\\end{equation}</span> The three forces <span class=\"math inline\">\\(\\vb F_g\\)</span>, <span class=\"math inline\">\\(\\vb F_a(\\vb q, \\dot{\\vb q})\\)</span>, and a<span class=\"math inline\">\\(\\vb F_\\ell(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q})\\)</span> are developed in <a href=\"#eq:f_grav_10D\">(90)</a>, <a href=\"#eq:f_aero_10D\">(89)</a>, and <a href=\"#eq:f_lines-10D\">(96)</a> respectively.</p>\n<p>We have written every quantity in <a href=\"#eq:f_cone_newton_10D\">(99)</a> explicitly in terms of <span class=\"math inline\">\\(\\vb q\\)</span>, <span class=\"math inline\">\\(\\dot{\\vb q}\\)</span>, and <span class=\"math inline\">\\(\\ddot{\\vb q}\\)</span>, thus <a href=\"#eq:f_cone_constraint_10D\">(97)</a> is a system of two second order <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span>s in <span class=\"math inline\">\\(\\vb q\\in \\mathbf{R}^5\\)</span>. By combining <a href=\"#eq:f_cone_constraint_10D\">(97)</a> and <a href=\"#eq:loop_closure_function\">(78)</a>, we obtain the following system of two implicit second order <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span>s and three algebraic equations (or constraints): <span class=\"math display\">\\begin{equation}\n\\begin{cases}\n    \\vb F_c(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) \\cdot {\\pdv{\\vb r}{R}}(\\vb q) = 0 \\\\\n    \\vb F_c(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) \\cdot {\\pdv{\\vb r}{\\tau}}(\\vb q) = 0 \\\\\n    R \\sin(\\theta(\\tau)) \\cos(\\phi(\\tau)) - a \\cos(\\alpha) - \\ell \\sin(\\theta_\\ell) \\cos(\\alpha + \\phi_\\ell) = 0 \\\\\n    R \\sin(\\theta(\\tau)) \\sin(\\phi(\\tau)) - a \\sin(\\alpha) - \\ell \\sin(\\theta_\\ell) \\sin(\\alpha + \\phi_\\ell) = 0 \\\\\n    R \\cos(\\theta(\\tau)) - \\ell \\cos(\\theta_\\ell) = 0,\n\\end{cases}\n\\tag{103}\\end{equation}</span> which can be rewritten as <a id=\"eq:dae\"></a><span class=\"math display\">\\begin{equation}\n\\begin{cases} \\tag{104}\n    \\vb f(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) &amp;= 0_{\\mathbf{R}^2} \\\\\n    \\vb g(\\vb q) &amp;= 0_{\\mathbf{R}^3},\n\\end{cases}\n\\end{equation}</span> with <span class=\"math display\">\\begin{equation}\n    \\vb f(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) = \\begin{pmatrix}\n        \\vb F_c(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) \\cdot {\\pdv{\\vb r}{R}}(\\vb q) \\\\\n        \\vb F_c(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) \\cdot {\\pdv{\\vb r}{\\tau}}(\\vb q)\n    \\end{pmatrix}\n\\tag{105}\\end{equation}</span></p>"},{"title":"Numerical solving","page":"A 10D model","location":"appendix-A.html#numerical-solving","category":"section","text":"<p>The system found in <a href=\"#eq:dae\">(104)</a> consists of two <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span>s and three algebraic equations of <span class=\"math inline\">\\(\\vb q: t \\mapsto \\vb q(t) \\in \\mathbf{R}^5\\)</span>, therefore it is a <span data-acronym-label=\"dae\" data-acronym-form=\"singular+short\">dae</span>. The first step toward a solution is to reduce it to a system of <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span>s, which is called index reduction. It consists in differentiating the algebraic equations with respect to time until we have a system of <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span>s, while adding initial conditions to keep the original algebraic equations valid at all times. The algebraic equation <span class=\"math inline\">\\(\\vb g(\\vb q) = 0\\)</span> is reduced to <span class=\"math display\">\\begin{equation}\n\\begin{cases} \\dot{\\vb g}(\\vb q, \\dot{\\vb q}) = 0 \\\\ \\vb g(\\vb q(t_0)) = 0,\\end{cases}\n\\tag{106}\\end{equation}</span> and differentiating a second time yields <span class=\"math display\">\\begin{equation}\n\\begin{cases} \\ddot{\\vb g}(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) = 0 \\\\ \\dot{\\vb g}(\\vb q(t_0), \\dot{\\vb q}(t_0)) = 0 \\\\ \\vb g(\\vb q(t_0)) = 0,\\end{cases}\n\\tag{107}\\end{equation}</span> which also exhibits three new algebraic equations that were previously hidden: <span class=\"math inline\">\\(\\dot{\\vb g}(\\vb q, \\dot{\\vb q}) = 0\\)</span>, <em>i.e.</em> not only must the configuration be consistent, but the velocities as well. In our particular case, <em>two</em> differentiation steps are required, thus we are working with an <em>index <span class=\"math inline\">\\(2\\)</span></em> <span data-acronym-label=\"dae\" data-acronym-form=\"singular+short\">dae</span>. By doing so, our system is reduced to <span class=\"math inline\">\\(5\\)</span> second order <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span>s and <span class=\"math inline\">\\(6\\)</span> initial conditions: <span class=\"math display\">\\begin{equation}\n\\begin{cases}\n    \\vb f(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) = 0_{\\mathbf{R}^2} \\\\\n    \\ddot{\\vb g}(\\vb q, \\dot{\\vb q}, \\ddot{\\vb q}) = 0_{\\mathbf{R}^3} \\\\\n    \\dot{\\vb g}(\\vb q(t_0), \\dot{\\vb q}(t_0)) = 0_{\\mathbf{R}^3} \\\\\n    \\vb g(\\vb q(t_0)) = 0_{\\mathbf{R}^3},\n\\end{cases}\n\\tag{108}\\end{equation}</span> We introduce <span class=\"math inline\">\\(v = \\dot{\\vb q}\\)</span> and rewrite this previous system with only first order <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span>s and initial conditions: <span class=\"math display\">\\begin{equation}\n\\begin{cases}\n    \\vb f(\\vb q, \\vb v, \\dot{\\vb v}) = 0_{\\mathbf{R}^2} \\\\\n    \\ddot{\\vb g}(\\vb q, \\vb v, \\dot{\\vb v}) = 0_{\\mathbf{R}^3} \\\\\n    \\dot{\\vb q}- \\vb v = 0_{\\mathbf{R}^5} \\\\\n    \\dot{\\vb g}(\\vb q(t_0), \\vb v(t_0)) = 0_{\\mathbf{R}^3} \\\\\n    \\vb g(\\vb q(t_0)) = 0_{\\mathbf{R}^3}.\n\\end{cases}\n\\tag{109}\\end{equation}</span> The first two vector equations are implicit and affine in <span class=\"math inline\">\\(\\dot{\\vb v}\\)</span>: we use a symbolic solver to solve them and have the explicit expression of <span class=\"math inline\">\\(\\dot{\\vb v}\\)</span> directly written into our code. As for the initialization, we have to choose <span class=\"math inline\">\\((\\vb q, \\vb v) \\in \\mathbf{R}^{5+5}\\)</span> verifying the six implicit nonlinear constraints. To make the solving easier, we set <span class=\"math display\">\\begin{equation}\n\\begin{cases}\n    \\alpha(t_0) = 0 \\\\\n    \\dot \\alpha(t_0) = 0,\n\\end{cases}\n\\tag{110}\\end{equation}</span> and let the user choose <span class=\"math inline\">\\((\\tau(t_0), \\dot \\tau) \\in \\mathbf{R}^2\\)</span>. We again use a symbolic solver to determine the rest of the initial conditions as a function of <span class=\"math inline\">\\((\\tau(t_0), \\dot \\tau(t_0))\\)</span>.</p>\n<p>We can finally solve the system numerically using an <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span> solver like Runge-Kutta 5(4) to get the trajectory shown on the left pane of Fig. <a href=\"#fig:traj-10D\">16</a>.</p>\n<p>On the left pane, over a short horizon, <span class=\"math inline\">\\(\\vb a + \\boldsymbol{\\ell}\\)</span> seems to coincide with <span class=\"math inline\">\\(\\vb r\\)</span>; yet on the middle pane, by integrating for longer, the two trajectories diverge. Even though we initialize such that <span class=\"math inline\">\\(\\dot{\\vb g}(\\vb q(t_0)) = 0\\)</span> and the <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span> part enforces <span class=\"math inline\">\\(\\ddot{\\vb g}(\\vb q, \\vb v, \\dot{\\vb v}) = 0\\)</span>, the slight integration error made at each time step accumulate and make <span class=\"math inline\">\\(\\dot{\\vb g}\\)</span>, and eventually <span class=\"math inline\">\\(\\vb g\\)</span>, drift away from zero (Fig. <a href=\"#fig:residuals-10D\">17</a>).</p>"},{"title":"Limitations of this approach","page":"A 10D model","location":"appendix-A.html#limitations-of-this-approach","category":"section","text":"<p>We just saw that the method in not stable for longer integration periods.</p>\n<p>This can be avoided by using a callback to project <span class=\"math inline\">\\((\\vb q, \\vb v)\\)</span> on the acceptable manifold <span class=\"math display\">\\begin{equation}\n    \\left\\{ (\\vb q, \\vb v) \\in \\mathbf{R}^{5+5} \\mid \\vb g(\\vb q) = 0 \\land \\dot{\\vb g}(\\vb q, \\vb v) = 0 \\right\\}\n\\tag{111}\\end{equation}</span> using one or multiple steps of Newton’s method. The state then stays coherent at all times (right pane of Fig. <a href=\"#fig:traj-10D\">16</a>, and Fig. <a href=\"#fig:residuals-10D\">17</a>) but the running time is multiplied by two. Another limitation of this approach include the reliance on an external symbolic solver, whose output is copy pasted into the code, therefore the code is unreadable and hard to maintain, and a small change in the model requires re-running the symbolic solver.</p>\n<figure id=\"fig:traj-10D\" data-latex-placement=\"thpb\">\n<img src=\"figs/trajectory_10D_short_long_cb.png\" />\n<figcaption><strong>Figure 16:</strong> Kite trajectory of the 10D model integrated with a loose tolerance: short horizon (left), long horizon (middle), long horizon with the manifold projection callback (right). Without the callback, the positions given by <span class=\"math inline\">\\(\\vb r\\)</span> and by <span class=\"math inline\">\\(\\vb a + \\boldsymbol{\\ell}\\)</span> drift apart.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/numerics10d.jl (region setup10d), see also the full file.\n\n    ## Setup\n    p = PMP.build_para()\n    τ0, dτ0 = 1e-10, 10\n    u0_10 = PM10.init_u(τ0, dτ0, p)\n\n    # Projection callback: its tolerance is independent of the integrator tolerance.\n    cb_tol = 1e-10\n    callback = PM10.build_manifold_projection(u0_10; save=true, tol=cb_tol)\n    callback_no_save = PM10.build_manifold_projection(u0_10; save=false, tol=cb_tol)\n\nsrc/numerics10d.jl (region traj10d), see also the full file.\n\n    # Physical plots at loose tolerance, to exaggerate the drift of the raw 10D model.\n    tf_short, tf, tol = 20, 100, 1e-3\n    sol10 = PM10.integrate(u0_10, tf, p, Tsit5(); save_everystep=true, tol)\n    sol10_cb = PM10.integrate(u0_10, tf, p, Tsit5(); save_everystep=true, tol, callback=callback_no_save)\n\n    ## 10D, Tsit5, tol=1e-3, tf = 20 vs 100 s vs callback\n    points_per_second = 30\n    fig_traj_short = VIZ.plot_trajectory_10D(sol10; tspan=(0, tf_short), points_per_second)\n    fig_traj = VIZ.plot_trajectory_10D(sol10; points_per_second)\n    fig_traj_cb = VIZ.plot_trajectory_10D(sol10_cb; points_per_second)\n    params = (; xlabel=\"x (m)\", ylabel=\"y (m)\", zlabel=\"z (m)\", legend=false, widen=false)\n    plot!(fig_traj_short; title=\"tf = 20 s\", params..., legend=:topleft)\n    plot!(fig_traj; title=\"tf = 100 s\", params...)\n    plot!(fig_traj_cb; title=\"tf = 100 s + callback\", params...)\n    tf_fig = plot(fig_traj_short, fig_traj, fig_traj_cb, layout=(1, 3), size=SIZE_FULL)\n    # one tick at each end of each axis, plus 0 when it is interior\n    for i in 1:3\n        plot!(tf_fig, subplot=i,\n            xticks=edge_ticks(tf_fig[i], :x; include_zero=true),\n            yticks=edge_ticks(tf_fig[i], :y; include_zero=true),\n            zticks=edge_ticks(tf_fig[i], :z; include_zero=true))\n    end\n    files = save_figure(tf_fig, \"trajectory_10D_short_long_cb\")\n\n</details>\n\n<figure id=\"fig:residuals-10D\" data-latex-placement=\"thpb\">\n<img src=\"figs/residuals_10D_interp.png\" />\n<figcaption><strong>Figure 17:</strong> Residuals of the configuration constraints of the 10D model on position (top) and on velocity (bottom) along the trajectory, without and with the manifold projection callback.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/numerics10d.jl (region setup10d), see also the full file.\n\n    ## Setup\n    p = PMP.build_para()\n    τ0, dτ0 = 1e-10, 10\n    u0_10 = PM10.init_u(τ0, dτ0, p)\n\n    # Projection callback: its tolerance is independent of the integrator tolerance.\n    cb_tol = 1e-10\n    callback = PM10.build_manifold_projection(u0_10; save=true, tol=cb_tol)\n    callback_no_save = PM10.build_manifold_projection(u0_10; save=false, tol=cb_tol)\n\nsrc/numerics10d.jl (region residuals10d), see also the full file.\n\n    ## Interpolated residuals\n    tf_long = fast ? 100 : 1000\n    sol10 = PM10.integrate(u0_10, tf_long, p, Tsit5(); save_everystep=true, tol=1e-6)\n    sol10_cb_t = PM10.integrate(u0_10, tf_long, p, Tsit5(); save_everystep=true, tol=1e-6, callback=callback_no_save)\n\n    ts = logrange(1, sol10.prob.tspan[2], 501)\n    res = [PM10.manifold_residuals!(similar(u0_10, 6), sol10(t), p) for t in ts]\n    res_cb = [PM10.manifold_residuals!(similar(u0_10, 6), sol10_cb_t(t), p) for t in ts]\n    ylim = exp10.((-9.5, 0.5))\n    xticks_ = exp10.(-18:1:10)\n    yticks_ = exp10.(-18:3:10)\n\n    plot(; xscale=:log10, xticks=xticks_, xformatter=x -> \"\", ylim, yscale=:log10, yticks=yticks_, ylabel=\"Residual on position (m)\", legend=:topleft)\n    plot!(ts, norm.(getindex.(res, Ref(1:3))), label=\"Without callback\")\n    fig_pos = plot!(ts, norm.(getindex.(res_cb, Ref(1:3))), label=\"With callback\")\n\n    plot(; xscale=:log10, xticks=xticks_, xlabel=\"Time (s)\", ylim, yscale=:log10, yticks=yticks_, ylabel=\"Residual on speed (m/s)\")\n    plot!(ts, norm.(getindex.(res, Ref(4:6))))\n    fig_speed = plot!(ts, norm.(getindex.(res_cb, Ref(4:6))))\n    plot(fig_pos, fig_speed, layout=(2, 1), size=SIZE_HALF .* (1, 1.5))\n    plot!(bottommargin=3Plots.mm, leftmargin=6Plots.mm)\n    append!(files, save_figure(current(), \"residuals_10D_interp\"))\n\n</details>\n\n<p>As previously mentioned, this model has five states but only two degrees of freedom; this observation motivates the main result of the paper, which is a whole rewrite of the model by having only two states and no configuration constraint. The pure <span data-acronym-label=\"ode\" data-acronym-form=\"singular+short\">ode</span> form makes the analytical work much easier, the numerical solution has no drift and is computed much faster because of the reduced number of dimensions, no symbolic solver is required, nor is a callback.</p>"},{"title":"1 Mathematical model of KEEP","page":"1 Mathematical model of KEEP","location":"section-1.html#sec:model","category":"section","text":""},{"title":"1.1 Geometry of the configuration","page":"1 Mathematical model of KEEP","location":"section-1.html#sec:model-geometry","category":"section","text":"<p>The system, depicted in Fig. <a href=\"#fig:config\">1</a>, consists of a rigid arm <span class=\"math inline\">\\(OA\\)</span> of length <span class=\"math inline\">\\(a\\)</span>, rotating in the horizontal plane about the vertical axis <span class=\"math inline\">\\(\\Delta = (O,\\vu z)\\)</span>, and of a kite <span class=\"math inline\">\\(K\\)</span> attached to the tip <span class=\"math inline\">\\(A\\)</span> of the arm by lines of fixed length <span class=\"math inline\">\\(\\ell\\)</span>. We use a direct orthonormal frame <span class=\"math inline\">\\((O,\\vu x,\\vu y,\\vu z)\\)</span>, where <span class=\"math inline\">\\(\\vu x\\)</span> and <span class=\"math inline\">\\(\\vu z\\)</span> point respectively downwind and upward. For a better handling of the kite, the lines are longer than 10 m, while the arm is 2 m long, so that <a id=\"eq:ineq-l-a\"></a><span class=\"math display\">\\begin{equation}\n \\tag{1}\n    \\ell &gt; a.\n\\end{equation}</span> The position of the arm tip is <span class=\"math display\">\\begin{equation}\n    \\vb a = a\\,\\vu a(\\alpha), \\qquad \\vu a(\\alpha) = \\begin{pmatrix} \\cos\\alpha \\\\ \\sin\\alpha \\\\ 0 \\end{pmatrix},\n\\tag{2}\\end{equation}</span> where <span class=\"math inline\">\\(\\alpha\\in\\mathbf{S}^1\\)</span> is the angle of the arm with the <span class=\"math inline\">\\(x\\)</span>-axis. As <span class=\"math inline\">\\(\\alpha\\)</span> varies, <span class=\"math inline\">\\(A\\)</span> runs along the horizontal circle <span class=\"math inline\">\\(\\mathscr{A}\\)</span> of centre <span class=\"math inline\">\\(O\\)</span> and radius <span class=\"math inline\">\\(a\\)</span>. The position of the kite, <span class=\"math inline\">\\(\\vb r\\)</span>, is restricted by two geometric constraints of a different nature: a prescribed one, which forces the kite to fly along a figure eight, and a mechanical one, due to the arm and the lines.</p>\n<figure id=\"fig:config\">\n<img src=\"figs/configuration.svg\" />\n<figcaption><strong>Figure 1:</strong> Configuration of the system. The vector <span class=\"math inline\">\\(\\vb a\\)</span> represents the arm, connected at point <span class=\"math inline\">\\(A\\)</span> (tip of the arm) to the kite <span class=\"math inline\">\\(K\\)</span> by the lines <span class=\"math inline\">\\(\\boldsymbol{\\ell}\\)</span>.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nfigs/configuration.tex, see also the full file.\n\n\\documentclass{standalone}\n\\usepackage[dvipsnames]{xcolor}\n\\usepackage{tikz}\n\\usetikzlibrary{3d}\n\\usepackage{tikz-3dplot}\n\\begin{document}\n\n% Set main 3D view (z-up, y-in)\n\\tdplotsetmaincoords{70}{-10}\n\n\\begin{tikzpicture}[tdplot_main_coords, scale=2]\n\n% ==== ORIGIN AND AXES ====\n\\coordinate (O) at (0,0,0);\n\\node[circle,fill,inner sep=1pt] at (O) {};\n\\node[below] at (O) {O};\n\n\\draw[->] (0,0,0) -- (3,0,0) node[anchor=west]{$x$};\n\\draw[->] (0,0,0) -- (0,1,0) node[anchor=south]{$y$};\n\\draw[->] (0,0,0) -- (0,0,2) node[anchor=west]{$z$};\n\n% ==== POINT A IN XY-PLANE ====\n\\def\\a{2}\n\\def\\alphaA{20}\n\\pgfmathsetmacro{\\xA}{\\a*cos(\\alphaA)}\n\\pgfmathsetmacro{\\yA}{\\a*sin(\\alphaA)}\n\\coordinate (A) at (\\xA, \\yA, 0);\n\\node[circle,fill,inner sep=1pt] at (A) {};\n\\node[below] at (A) {A};\n\n% Projections of A\n\\coordinate (Ax) at (\\xA, 0, 0);\n\\coordinate (Ay) at (0, \\yA, 0);\n\n% Lines from O\n\\draw (O) -- (A) node[midway, sloped, above] {$a$};\n\\draw (O) -- (Ax);\n\\draw (O) -- (Ay);\n\n% ==== POINT K ====\n\\def\\l{2}\n\\def\\thetaZero{70}\n\\def\\DeltaTheta{5}\n\\def\\DeltaPhi{30}\n\\def\\tauK{90}\n\n\\pgfmathdeclarefunction{thetaFunc}{1}{\\pgfmathparse{\\thetaZero + \\DeltaTheta * sin(2*#1)}}\n\\pgfmathdeclarefunction{phiFunc}{1}  {\\pgfmathparse{\\DeltaPhi * sin(#1)}}\n\\pgfmathdeclarefunction{xTauFunc}{1} {\\pgfmathparse{sin(thetaFunc(#1)) * cos(phiFunc(#1))}}\n\\pgfmathdeclarefunction{yTauFunc}{1} {\\pgfmathparse{sin(thetaFunc(#1)) * sin(phiFunc(#1))}}\n\\pgfmathdeclarefunction{zTauFunc}{1} {\\pgfmathparse{cos(thetaFunc(#1))}}\n\n\\pgfmathsetmacro{\\dotprod}{\\xA * xTauFunc(\\tauK) + \\yA * yTauFunc(\\tauK)}\n\\pgfmathsetmacro{\\rK}{\\dotprod + sqrt(\\dotprod * \\dotprod + \\l^2 - \\a^2)}\n\n\\pgfmathsetmacro{\\xK}{\\rK * xTauFunc(\\tauK)}\n\\pgfmathsetmacro{\\yK}{\\rK * yTauFunc(\\tauK)}\n\\pgfmathsetmacro{\\zK}{\\rK * zTauFunc(\\tauK)}\n\n\\coordinate (K) at (\\xK, \\yK, \\zK);\n\\coordinate (K_xy) at (\\xK, \\yK, 0);\n\n% Helper points from A\n\\pgfmathsetmacro{\\xAel}{\\xA}\n\\pgfmathsetmacro{\\yAel}{\\yA}\n\\pgfmathsetmacro{\\zAel}{1.5}\n\\coordinate (A_el) at (\\xAel, \\yAel, \\zAel);\n\n\\pgfmathsetmacro{\\xAext}{1.5*\\xA}\n\\pgfmathsetmacro{\\yAext}{1.5*\\yA}\n\\coordinate (A_ext) at (\\xAext, \\yAext, 0);\n\n% Draw K and lines\n\\node[circle,fill,inner sep=1pt] at (K) {};\n\\node[above] at (K) {K};\n\n\\draw (A) -- (K) node[midway, sloped, below] {$\\ell$};\n\\draw[dotted, blue] (O) -- (K) node[pos=0.5, sloped, above] {$r(\\alpha, \\tau)$};\n\n%\\draw[dotted] (A) -- (A_ext);\n\\draw[dotted] (K) -- (K_xy) -- (A);\n\\draw[dotted, blue] (K_xy) -- (O);\n%\\draw[dotted] (A) -- (A_el);\n\n% ==== ANGLES ====\n% alpha\n\\tdplotdefinepoints(0,0,0)(1,0,0)(\\xA,\\yA,0)\n\\tdplotdrawpolytopearc[->, OrangeRed, thick]{1.3}{right, OrangeRed}{$\\alpha$}\n\n% phi\n\\tdplotdefinepoints(0,0,0)(1,0,0)(\\xK,\\yK,0)\n\\tdplotdrawpolytopearc[->, blue, thick]{2.7}{above right, blue}{$\\phi(\\tau)$}\n\n% theta\n\\tdplotdefinepoints(0,0,0)(0,0,1)(\\xK,\\yK,\\zK)\n\\tdplotdrawpolytopearc[->, blue, thick]{1}{above, blue}{$\\theta(\\tau)$}\n\n% % phi_ℓ\n% \\tdplotdefinepoints(\\xA,\\yA,0)(\\xAext,\\yAext,0)(\\xK,\\yK,0)\n% \\tdplotdrawpolytopearc[->]{1}{anchor=south west}{$\\phi_\\ell$}\n\n% % theta_ℓ\n% \\tdplotdefinepoints(\\xA,\\yA,0)(\\xAel,\\yAel,\\zAel)(\\xK,\\yK,\\zK)\n% \\tdplotdrawpolytopearc[->]{0.8}{anchor=north}{$\\theta_\\ell$}\n\n\\newcommand{\\KCoord}[2]{({#1 * xTauFunc(#2)}, {#1 * yTauFunc(#2)}, {#1 * zTauFunc(#2)})}\n\n% tau and eight\n\\draw[domain = 0:360, samples = 20, smooth, dashed, variable = \\t]\n    plot (\\KCoord{\\rK}{\\t});\n\\draw[->, domain = 0:\\tauK, samples = 10, smooth, OrangeRed, thick, variable = \\t]\n    plot (\\KCoord{\\rK}{\\t});\n\n\n\\node[below, OrangeRed] at \\KCoord{\\rK}{\\tauK/2} {$\\tau$};\n\n\n\\end{tikzpicture}\n\n\\end{document}\n\n</details>\n\n<p>Let <span class=\"math inline\">\\(\\vu r(\\tau)\\in\\mathbf{S}^2\\)</span> be the point of the unit sphere with polar angle <span class=\"math inline\">\\(\\theta(\\tau)\\)</span> and azimuth <span class=\"math inline\">\\(\\phi(\\tau)\\)</span>, <a id=\"eq:sphere_Model_Deriv\"></a><span class=\"math display\">\\begin{equation}\n \\tag{3}\n    \\vu r(\\tau) = \\begin{pmatrix} \\sin\\theta(\\tau)\\cos\\phi(\\tau) \\\\ \\sin\\theta(\\tau)\\sin\\phi(\\tau) \\\\ \\cos\\theta(\\tau) \\end{pmatrix},\n\\end{equation}</span> where <a id=\"eq:traject_Model_Deriv\"></a><span class=\"math display\">\\begin{equation}\n \\tag{4}\n    \\theta(\\tau) = \\theta_0 + \\Delta\\theta \\sin(2\\tau), \\qquad \\phi(\\tau) = \\Delta\\phi \\sin\\tau, \\qquad \\tau\\in\\mathbf{S}^1.\n\\end{equation}</span> The curve <span class=\"math inline\">\\(\\mathscr{E} = \\vu r(\\mathbf{S}^1)\\)</span> is a figure eight drawn on <span class=\"math inline\">\\(\\mathbf{S}^2\\)</span> (Figs. <a href=\"#fig:eight_plot\">2</a> and <a href=\"#fig:cone_eight\">3</a>). It is centred at the point of polar angle <span class=\"math inline\">\\(\\theta_0\\)</span> in the vertical plane <span class=\"math inline\">\\((O,\\vu x,\\vu z)\\)</span> that contains the wind, and its shape is controlled by two amplitudes: <span class=\"math inline\">\\(\\Delta\\phi\\)</span> is its half-width in azimuth, and <span class=\"math inline\">\\(\\Delta\\theta\\)</span> its half-height in polar angle. We assume <span class=\"math inline\">\\(\\Delta\\theta&gt;0\\)</span>, <span class=\"math inline\">\\(0&lt;\\Delta\\phi&lt;\\pi\\)</span> and <span class=\"math inline\">\\(0&lt;\\theta_0-\\Delta\\theta&lt;\\theta_0+\\Delta\\theta&lt;\\pi/2\\)</span>, so that the eight lies in the upper hemisphere. Then <span class=\"math inline\">\\(\\mathscr{E}\\)</span> is a regular closed curve: its speed <span class=\"math inline\">\\(v = \\norm{\\vu r&#39;}\\)</span>, given by <span class=\"math display\">\\begin{equation}\n    v^2 = 4\\Delta\\theta^2\\cos^2 2\\tau + \\Delta\\phi^2\\sin^2\\theta\\cos^2\\tau,\n\\tag{5}\\end{equation}</span> does not vanish, since <span class=\"math inline\">\\(\\cos\\tau\\)</span> and <span class=\"math inline\">\\(\\cos2\\tau\\)</span> never vanish together. It has a single double point, its centre <span class=\"math inline\">\\(\\vu r(0) = \\vu r(\\pi)\\)</span>, where the kite crosses the plane of the wind. Indeed, <span class=\"math inline\">\\(\\vu r(\\tau_1) = \\vu r(\\tau_2)\\)</span> with <span class=\"math inline\">\\(\\tau_1\\neq\\tau_2\\)</span> requires <span class=\"math inline\">\\(\\sin\\tau_1 = \\sin\\tau_2\\)</span> (as <span class=\"math inline\">\\(\\Delta\\phi&lt;\\pi\\)</span>), i.e. <span class=\"math inline\">\\(\\tau_2 = \\pi-\\tau_1\\)</span>, and then <span class=\"math inline\">\\(\\sin2\\tau_1 = \\sin2\\tau_2 = -\\sin2\\tau_1\\)</span>, i.e. <span class=\"math inline\">\\(\\{\\tau_1,\\tau_2\\} = \\{0,\\pi\\}\\)</span>.</p>\n<figure id=\"fig:eight_plot\">\n<img src=\"figs/eight_plot.png\" />\n<figcaption><strong>Figure 2:</strong> The spherical eight <span class=\"math inline\">\\(\\mathscr{E}\\)</span>, parameterized by <span class=\"math inline\">\\(\\tau\\)</span>, in the coordinates <span class=\"math inline\">\\((\\phi,\\theta)\\)</span>; its shape is controlled by the design parameters <span class=\"math inline\">\\(\\theta_0\\)</span>, <span class=\"math inline\">\\(\\Delta\\theta\\)</span>, and <span class=\"math inline\">\\(\\Delta\\phi\\)</span>. Trajectories with increasing <span class=\"math inline\">\\(\\tau\\)</span> (blue) result in a flight path that descends in the middle and ascends at the sides, while decreasing <span class=\"math inline\">\\(\\tau\\)</span> (orange) produces the inverse motion. The <span class=\"math inline\">\\(\\theta\\)</span>-axis is inverted to align with the orientation of the kite’s trajectory.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/modelling.jl (region eight_plot), see also the full file.\n\n    ## Parametrisation in tau\n    τ_φ = 90.0\n    τ_θ = 225.0\n    dx, dy = 1 / 4, 1 / 2\n    up_col, down_col = 1, 2\n\n    τ = range(0, 360, length=501)\n    θ = τ -> sind(2 * τ)\n    φ = τ -> sind(τ)\n\n    plot(xmirror=true)\n    plot!(xticks=([-1, 0, 1], (raw\"$-Δφ$\", raw\"$φ = 0$\", raw\"$Δφ$\")),\n        yticks=([-1, 0, 1], (raw\"$θ_0 + Δθ$\", raw\"$θ = θ_0$\", raw\"$θ_0 - Δθ$\"))\n    )\n\n    plot!(φ.(τ), θ.(τ), c=:grey)\n\n    plot!(φ.([0, τ_φ]), θ.([τ_φ, τ_φ]), color=:black)\n    annotate!(sum(φ.([0, τ_φ])) / 2, sum(θ.([τ_φ, τ_φ])) / 2 - 0.1, (raw\"$Δφ$\", ANNOTATIONFONTSIZE, :black, :top))\n\n    plot!(φ.([τ_θ, τ_θ]), θ.([τ_θ, 0]), color=:black)\n    annotate!(sum(φ.([τ_θ, τ_θ])) / 2 + 0.05, sum(θ.([τ_θ, 0])) / 2, (raw\"$Δθ$\", ANNOTATIONFONTSIZE, :black, :left))\n    quiver!([0], [0], quiver=([dx], [-dy]), c=up_col)\n    quiver!([0], [0], quiver=([-dx], [dy]), c=down_col)\n    annotate!(dx - 0.05, -dy - 0.25, (raw\"$\\dot{\\tau} > 0$\", ANNOTATIONFONTSIZE, :center, PALETTE[up_col]))\n    annotate!(-dx + 0.05, dy + 0.25, (raw\"$\\dot{\\tau} < 0$\", ANNOTATIONFONTSIZE, :center, PALETTE[down_col]))\n    plot!(size=SIZE_HALF .* (1, 0.5), topmargin=1Plots.mm, leftmargin=5Plots.mm)\n    append!(files, save_figure(current(), \"eight_plot\"))\n\n</details>\n\n<p>The kite is constrained to fly on the conical hull of the eight, <span class=\"math display\">\\begin{equation}\n    \\mathscr{C} = \\{\\, r\\,\\vu r(\\tau) \\mid r&gt;0,\\ \\tau\\in\\mathbf{S}^1 \\,\\},\n\\tag{6}\\end{equation}</span> a cone of vertex <span class=\"math inline\">\\(O\\)</span> whose generators are the rays through the points of <span class=\"math inline\">\\(\\mathscr{E}\\)</span>. It is a ruled, developable surface (see Section <a href=\"section-4.html#sec:opt-curvature\">4.3</a>), smooth away from <span class=\"math inline\">\\(O\\)</span> and from the ray through the centre of the eight, along which it crosses itself.</p>\n<figure id=\"fig:cone_eight\">\n<img src=\"figs/cone_eight.svg\" />\n<figcaption><strong>Figure 3:</strong> The cone <span class=\"math inline\">\\(\\mathscr{C}\\)</span> (light blue) over the spherical eight <span class=\"math inline\">\\(\\mathscr{E}\\)</span> (black) and a trajectory of the kite drawn on it (red). Each generator of the cone, such as the dashed one, meets <span class=\"math inline\">\\(\\mathscr{E}\\)</span> at <span class=\"math inline\">\\(\\vu r(\\tau)\\)</span> and the trajectory at <span class=\"math inline\">\\(K = r\\,\\vu r(\\tau)\\)</span>. The trajectory is open and its distance to <span class=\"math inline\">\\(O\\)</span> varies. Not to scale.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nfigs/cone_eight.tex, see also the full file.\n\n\\documentclass[tikz,border=2pt]{standalone}\n\\usepackage[dvipsnames]{xcolor}\n\\usepackage{mathrsfs}\n\\usepackage{tikz-3dplot}\n\\begin{document}\n% Cone over the spherical eight, and a kite trajectory drawn on it (not to scale).\n\\tdplotsetmaincoords{78}{100}\n\\begin{tikzpicture}[tdplot_main_coords, scale=2.4, line join=round]\n\n% ---- parameters (angles in degrees; exaggerated for readability) ----\n\\def\\thetaZero{55} \\def\\DeltaTheta{16} \\def\\DeltaPhi{42}\n\\def\\ell{1.9} \\def\\a{0.7} \\def\\Rmax{2.9}\n\n\\pgfmathdeclarefunction{thf}{1}{\\pgfmathparse{\\thetaZero + \\DeltaTheta*sin(2*#1)}}\n\\pgfmathdeclarefunction{phf}{1}{\\pgfmathparse{\\DeltaPhi*sin(#1)}}\n\\pgfmathdeclarefunction{ux}{1}{\\pgfmathparse{sin(thf(#1))*cos(phf(#1))}}\n\\pgfmathdeclarefunction{uy}{1}{\\pgfmathparse{sin(thf(#1))*sin(phf(#1))}}\n\\pgfmathdeclarefunction{uz}{1}{\\pgfmathparse{cos(thf(#1))}}\n% arm angle along the orbit (any smooth law; only the shape of r matters here)\n\\pgfmathdeclarefunction{alf}{1}{\\pgfmathparse{40 + 60*sin(#1) + 0.14*#1}}\n\\pgfmathdeclarefunction{pf}{1}{\\pgfmathparse{\\a*sin(thf(#1))*cos(phf(#1)-alf(#1))}}\n\\pgfmathdeclarefunction{rf}{1}{\\pgfmathparse{pf(#1) + sqrt(pf(#1)*pf(#1) + \\ell*\\ell - \\a*\\a)}}\n\n% ---- axes ----\n\\draw[->,gray] (0,0,0) -- (1.5,0,0) node[below left,black]{$x$};\n\\draw[->,gray] (0,0,0) -- (0,1.5,0) node[right,black]{$y$};\n\\draw[->,gray] (0,0,0) -- (0,0,1.6) node[above,black]{$z$};\n\n% ---- the unit sphere carrying the eight (very light) ----\n\\begin{scope}[tdplot_screen_coords]\n  \\shade[ball color=gray!35,opacity=0.28] (0,0) circle (1);\n  \\draw[gray!55,opacity=0.5,thin] (0,0) circle (1);\n\\end{scope}\n\\foreach \\p in {-60,-30,...,60}{\n  \\draw[gray!60,opacity=0.35,very thin,domain=0:360,samples=121,variable=\\t]\n    plot ({cos(\\p)*cos(\\t)},{cos(\\p)*sin(\\t)},{sin(\\p)});\n}\n\\foreach \\m in {0,30,...,150}{\n  \\draw[gray!60,opacity=0.35,very thin,domain=0:360,samples=121,variable=\\t]\n    plot ({cos(\\t)*cos(\\m)},{cos(\\t)*sin(\\m)},{sin(\\t)});\n}\n\n% ---- cone: one translucent fill (no seams) and generators ----\n\\foreach \\ta/\\tb in {0/180,180/360}{\n  \\fill[SkyBlue,opacity=0.22]\n    (0,0,0) -- plot[domain=\\ta:\\tb,samples=361,variable=\\t]\n    ({\\Rmax*ux(\\t)},{\\Rmax*uy(\\t)},{\\Rmax*uz(\\t)}) -- cycle;\n}\n% generators\n\\foreach \\t in {0,6,...,354}{\n  \\draw[SkyBlue!80!black,opacity=0.5,very thin]\n    (0,0,0) -- ({\\Rmax*ux(\\t)},{\\Rmax*uy(\\t)},{\\Rmax*uz(\\t)});\n}\n% rim of the cone at r = Rmax\n\\draw[SkyBlue!80!black,opacity=0.7]\n  plot[domain=0:360,samples=721,variable=\\t] ({\\Rmax*ux(\\t)},{\\Rmax*uy(\\t)},{\\Rmax*uz(\\t)});\n\n% ---- the eight on the unit sphere ----\n\\draw[very thick,black]\n  plot[domain=0:360,samples=721,variable=\\t] ({ux(\\t)},{uy(\\t)},{uz(\\t)});\n\\node[black] at ({ux(270)},{uy(270)},{uz(270)-0.13}) {$\\mathscr{E}$};\n\n% ---- kite trajectory on the cone ----\n\\draw[very thick,BrickRed,-latex]\n  plot[domain=0:500,samples=1001,variable=\\t] ({rf(\\t)*ux(\\t)},{rf(\\t)*uy(\\t)},{rf(\\t)*uz(\\t)});\n\n% one generator highlighted: eight point, kite position\n\\def\\tk{62}\n\\draw[dashed,black] (0,0,0) -- ({rf(\\tk)*ux(\\tk)},{rf(\\tk)*uy(\\tk)},{rf(\\tk)*uz(\\tk)});\n\\fill[black]  ({ux(\\tk)},{uy(\\tk)},{uz(\\tk)}) circle (0.7pt);\n\\fill[BrickRed] ({rf(\\tk)*ux(\\tk)},{rf(\\tk)*uy(\\tk)},{rf(\\tk)*uz(\\tk)}) circle (1.2pt)\n  node[above right]{$K$};\n\\fill (0,0,0) circle (0.8pt) node[below left]{$O$};\n\n% label of the cone\n\\node[SkyBlue!60!black] at ({1.04*\\Rmax*ux(120)},{1.04*\\Rmax*uy(120)},{1.04*\\Rmax*uz(120)}) {$\\mathscr{C}$};\n\\end{tikzpicture}\n\\end{document}\n\n</details>\n\n<p>The pair <span class=\"math inline\">\\((r,\\tau)\\)</span> provides coordinates on <span class=\"math inline\">\\(\\mathscr{C}\\)</span>: <span class=\"math inline\">\\(r = \\norm{\\vb r}\\)</span> is the distance to <span class=\"math inline\">\\(O\\)</span>, and <span class=\"math inline\">\\(\\tau\\)</span> labels the generator. At <span class=\"math inline\">\\(K = r\\,\\vu r(\\tau)\\)</span>, the tangent plane to <span class=\"math inline\">\\(\\mathscr{C}\\)</span> is spanned by <span class=\"math inline\">\\(\\vu r\\)</span> and <span class=\"math inline\">\\(\\vu r&#39;\\)</span>, which are orthogonal, and the unit normal is <a id=\"eq:cone-normal\"></a><span class=\"math display\">\\begin{equation}\n \\tag{7}\n    \\vu n = \\frac{\\vu r\\times\\vu r'}{v}.\n\\end{equation}</span> Thus, the trajectory <span class=\"math inline\">\\(t\\mapsto\\vb r(t) = r(t)\\,\\vu r(\\tau(t))\\)</span> of the kite is a curve drawn on <span class=\"math inline\">\\(\\mathscr{C}\\)</span>. Its radial projection <span class=\"math inline\">\\(\\vu r(\\tau(t))\\)</span> onto the unit sphere runs along the eight, with the time law <span class=\"math inline\">\\(t\\mapsto\\tau(t)\\)</span>, whereas its distance <span class=\"math inline\">\\(r(t)\\)</span> to <span class=\"math inline\">\\(O\\)</span> is fixed by the arm and the lines, as we now explain.</p>\n<p>The lines impose <span class=\"math inline\">\\(\\norm{\\vb r - \\vb a} = \\ell\\)</span>: the kite lies on the sphere of radius <span class=\"math inline\">\\(\\ell\\)</span> centred at <span class=\"math inline\">\\(A\\)</span>. As <span class=\"math inline\">\\(A\\)</span> runs along <span class=\"math inline\">\\(\\mathscr{A}\\)</span>, this sphere sweeps a torus of revolution <span class=\"math inline\">\\(\\mathscr{T}\\)</span> about <span class=\"math inline\">\\(\\Delta\\)</span>, of major radius <span class=\"math inline\">\\(a\\)</span> and minor radius <span class=\"math inline\">\\(\\ell\\)</span>. By <a href=\"#eq:ineq-l-a\">(1)</a>, its generating circle crosses the axis: <span class=\"math inline\">\\(\\mathscr{T}\\)</span> is a <em>spindle torus</em> (Fig. <a href=\"#fig:spindle_torus\">4</a>). In a meridian half-plane, with <span class=\"math inline\">\\(\\rho\\geq0\\)</span> the distance to the axis and <span class=\"math inline\">\\(z\\)</span> the altitude, it consists of two sheets that meet at the poles <span class=\"math inline\">\\((\\rho,z) = (0,\\pm\\sqrt{\\ell^2-a^2})\\)</span>: the outer one, <span class=\"math inline\">\\(\\mathscr{T}_+\\)</span>, shaped like an apple, <span class=\"math display\">\\begin{equation}\n    (\\rho-a)^2 + z^2 = \\ell^2,\n\\tag{8}\\end{equation}</span> and the inner one, <span class=\"math inline\">\\(\\mathscr{T}_-\\)</span>, shaped like a lemon, <span class=\"math display\">\\begin{equation}\n    (\\rho+a)^2 + z^2 = \\ell^2.\n\\tag{9}\\end{equation}</span> Since the distance from a point at <span class=\"math inline\">\\((\\rho,z)\\)</span> to the points of <span class=\"math inline\">\\(\\mathscr{A}\\)</span> takes all values between <span class=\"math inline\">\\(\\sqrt{(\\rho-a)^2+z^2}\\)</span> and <span class=\"math inline\">\\(\\sqrt{(\\rho+a)^2+z^2}\\)</span>, the positions of the kite allowed by the arm and the lines, for some value of <span class=\"math inline\">\\(\\alpha\\)</span>, fill the closed solid <span class=\"math display\">\\begin{equation}\n    \\mathscr{S} = \\{\\, (\\rho-a)^2 + z^2 \\leq \\ell^2 \\leq (\\rho+a)^2 + z^2 \\,\\}\n\\tag{10}\\end{equation}</span> bounded by <span class=\"math inline\">\\(\\mathscr{T}\\)</span>: the kite is inside the apple and outside the lemon. The kite is on the boundary of <span class=\"math inline\">\\(\\mathscr{S}\\)</span> when the arm and the lines are in the same vertical plane, namely on the apple when <span class=\"math inline\">\\(A\\)</span> lies on the same side of the axis as <span class=\"math inline\">\\(K\\)</span>, and on the lemon when it lies on the opposite side. For <span class=\"math inline\">\\(a=0\\)</span>, both sheets reduce to the sphere of radius <span class=\"math inline\">\\(\\ell\\)</span>, and so does <span class=\"math inline\">\\(\\mathscr{S}\\)</span>.</p>\n<figure id=\"fig:spindle_torus\">\n<img src=\"figs/spindle_torus.png\" />\n<figcaption><strong>Figure 4:</strong> The spindle torus <span class=\"math inline\">\\(\\mathscr{T}\\)</span> swept by the sphere of radius <span class=\"math inline\">\\(\\ell\\)</span> centred at the arm tip, with its outer sheet (apple) and its inner sheet (lemon). The kite lies in the solid <span class=\"math inline\">\\(\\mathscr{S}\\)</span> between the two sheets. The trajectory is open and its distance to <span class=\"math inline\">\\(O\\)</span> varies. Not to scale.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/modelling.jl (region spindle_torus), see also the full file.\n\n    ## Spindle torus\n    a, l = 2, 3\n\n    # sanity check: a sampled point is exactly l from its arm tip\n    β0 = deg2rad(30)  # line elevation\n    kite_pos = [a + l * cos(β0), 0, l * sin(β0)]\n    @assert isapprox(norm(kite_pos - [a, 0, 0]), l; atol=1e-8)\n\n    # mesh as flat line segments (GR's wireframe chokes on matrix grids); a mesh\n    # rather than a surface so the self-intersecting interior stays visible\n    lg = range(0, 2π, length=120)  # points along each grid line\n    lk = range(0, 2π, length=40)   # grid lines\n    xs = Float64[]\n    ys = Float64[]\n    zs = Float64[]\n    for βj in lk\n        for αi in lg\n            push!(xs, (a + l * cos(βj)) * cos(αi))\n            push!(ys, (a + l * cos(βj)) * sin(αi))\n            push!(zs, l * sin(βj))\n        end\n        push!(xs, NaN)\n        push!(ys, NaN)\n        push!(zs, NaN)\n    end\n    for αj in lk\n        for βi in lg\n            push!(xs, (a + l * cos(βi)) * cos(αj))\n            push!(ys, (a + l * cos(βi)) * sin(αj))\n            push!(zs, l * sin(βi))\n        end\n        push!(xs, NaN)\n        push!(ys, NaN)\n        push!(zs, NaN)\n    end\n\n    fig = plot(xs, ys, zs; c=:black, alpha=0.4, lw=0.5, aspect_ratio=:equal,\n        xlabel=\"x (m)\", ylabel=\"y (m)\", zlabel=\"z (m)\",\n        title=\"Spindle torus, not to scale\", label=\"\", legend=:outerright)\n\n    # set of possible arm-tip positions: circle of radius a in the xy-plane\n    θc = range(0, 2π, length=200)\n    arm_tip_pars = (; c=:blue, lw=3, label=\"Arm-tip locus\")\n    plot!(fig, a * cos.(θc), a * sin.(θc), zero(θc); arm_tip_pars..., label=\"\")\n\n    # example arm and kite at α = 0, β = 30°\n    arm_and_lines_pars = (; c=:black, lw=3, label=\"Arm and lines\")\n    plot!(fig, [0, a], [0, 0], [0, 0]; arm_and_lines_pars..., label=\"\")\n    plot!(fig, [a, kite_pos[1]], [0, 0], [0, kite_pos[3]]; arm_and_lines_pars..., label=\"\")\n\n    longitude_pars = (; c=:orange, lw=2, label=\"Kite longitude\")\n    latitude_pars = (; c=:green, lw=2, label=\"Kite latitude\")\n    plot!(fig, a .+ l .* cos.(θc), zero(θc), l .* sin.(θc); longitude_pars..., label=\"\")\n    plot!(fig, (a + l * cos(β0)) .* cos.(θc), (a + l * cos(β0)) .* sin.(θc), fill(l * sin(β0), length(θc)); latitude_pars..., label=\"\")\n\n    kite_pars = (; c=:red, ms=7, label=\"Kite\")\n    scatter!(fig, [kite_pos[1]], [0], [kite_pos[3]]; kite_pars..., label=\"\")\n\n    scatter!([]; kite_pars..., msw=20, msc=:red)\n    plot!([]; arm_and_lines_pars..., lw=default(:lw))\n    plot!([]; arm_tip_pars..., lw=default(:lw))\n    plot!([]; longitude_pars..., lw=default(:lw))\n    plot!([]; latitude_pars..., lw=default(:lw))\n    plot!(leftmargin=-4Plots.mm, rightmargin=-20Plots.mm)\n    plot!(size=plot_size(1, 1.06))\n    # one tick at each end of each axis, plus 0 when it is interior\n    plot!(fig, xticks=edge_ticks(fig[1], :x; include_zero=true),\n        yticks=edge_ticks(fig[1], :y; include_zero=true),\n        zticks=edge_ticks(fig[1], :z; include_zero=true))\n\n    files = save_figure(fig, \"spindle_torus\")\n\n</details>\n\n<p>The kite therefore lies on the intersection <span class=\"math inline\">\\(\\mathscr{C}\\cap\\mathscr{S}\\)</span>. Its distance to <span class=\"math inline\">\\(O\\)</span> follows from the loop closure: with <span class=\"math inline\">\\(\\boldsymbol{\\ell}\\)</span> the vector from <span class=\"math inline\">\\(A\\)</span> to <span class=\"math inline\">\\(K\\)</span>, <a id=\"eq:loop\"></a><span class=\"math display\">\\begin{equation}\n \\tag{11}\n    \\boldsymbol{\\ell} = \\vb r - \\vb a, \\qquad \\norm{\\boldsymbol{\\ell}} = \\ell,\n\\end{equation}</span> and <span class=\"math inline\">\\(\\vb r = r\\,\\vu r(\\tau)\\)</span>, one gets <a id=\"eq:radial-quadratic\"></a><span class=\"math display\">\\begin{equation}\n \\tag{12}\n    r^2 - 2p\\,r + a^2 - \\ell^2 = 0, \\qquad p(\\alpha,\\tau) = \\vu r(\\tau)\\vdot\\vb a = a\\sin\\theta(\\tau)\\cos(\\phi(\\tau)-\\alpha),\n\\end{equation}</span> where <span class=\"math inline\">\\(p\\)</span> is the projection of the arm onto the generator of the kite. By <a href=\"#eq:ineq-l-a\">(1)</a>, the product of the roots, <span class=\"math inline\">\\(a^2-\\ell^2\\)</span>, is negative, so there is exactly one positive root, <a id=\"eq:radial\"></a><span class=\"math display\">\\begin{equation}\n \\tag{13}\n    r(\\alpha,\\tau) = p + R, \\qquad R = \\sqrt{p^2+\\ell^2-a^2},\n\\end{equation}</span> the negative one corresponding to the opposite ray, which is not on <span class=\"math inline\">\\(\\mathscr{C}\\)</span>. The position of the kite is thus given by the kinematic map <a id=\"eq:kinematic-map\"></a><span class=\"math display\">\\begin{equation}\n \\tag{14}\n    \\Phi : \\mathbf{T}^2 \\to \\mathscr{C}\\cap\\mathscr{S}, \\qquad (\\alpha,\\tau) \\mapsto \\vb r(\\alpha,\\tau) = r(\\alpha,\\tau)\\,\\vu r(\\tau),\n\\end{equation}</span> and we choose <span class=\"math inline\">\\(\\vb q= (\\alpha,\\tau)\\in\\mathbf{T}^2\\)</span> as generalized coordinates.</p>\n<p>For a fixed generator <span class=\"math inline\">\\(\\tau\\)</span>, as <span class=\"math inline\">\\(\\alpha\\)</span> varies, <span class=\"math inline\">\\(p\\)</span> sweeps <span class=\"math inline\">\\([-a\\sin\\theta, a\\sin\\theta]\\)</span>, and <span class=\"math inline\">\\(r\\)</span> increases with <span class=\"math inline\">\\(p\\)</span> since <span class=\"math inline\">\\(\\dv*{r}{p} = r/R &gt; 0\\)</span>. Hence <span class=\"math inline\">\\(r\\)</span> sweeps the interval <span class=\"math inline\">\\([r_-(\\theta), r_+(\\theta)]\\)</span>, with <span class=\"math display\">\\begin{equation}\n    r_\\pm(\\theta) = \\pm a\\sin\\theta + \\sqrt{\\ell^2 - a^2\\cos^2\\theta},\n\\tag{15}\\end{equation}</span> where <span class=\"math inline\">\\(r_+\\vu r\\)</span> lies on the apple and <span class=\"math inline\">\\(r_-\\vu r\\)</span> on the lemon, and in particular <span class=\"math inline\">\\(\\ell - a \\leq r \\leq \\ell + a\\)</span>. The image of <span class=\"math inline\">\\(\\Phi\\)</span> is the whole of <span class=\"math inline\">\\(\\mathscr{C}\\cap\\mathscr{S}\\)</span>: a band of the cone, bounded by the two closed curves <span class=\"math inline\">\\(\\Gamma_\\pm = \\mathscr{C}\\cap\\mathscr{T}_\\pm\\)</span>, along which the trajectory of the kite is drawn.</p>\n<p>The map <span class=\"math inline\">\\(\\Phi\\)</span> is not one-to-one. Its partial derivatives are <span class=\"math display\">\\begin{equation}\n    \\pdv{\\vb r}{\\alpha} = \\pdv{r}{\\alpha}\\,\\vu r, \\qquad \\pdv{\\vb r}{\\tau} = \\pdv{r}{\\tau}\\,\\vu r + r\\,\\vu r',\n    \\qquad\\text{with}\\qquad\n    \\pdv{r}{\\alpha} = \\frac{r}{R}\\,a\\sin\\theta\\sin(\\phi-\\alpha).\n\\tag{16}\\end{equation}</span> As <span class=\"math inline\">\\(\\vu r&#39;\\neq0\\)</span> is orthogonal to <span class=\"math inline\">\\(\\vu r\\)</span>, <span class=\"math inline\">\\(\\Phi\\)</span> is a local diffeomorphism except on the two closed curves <span class=\"math inline\">\\(\\alpha = \\phi(\\tau)\\)</span> and <span class=\"math inline\">\\(\\alpha = \\phi(\\tau)+\\pi\\)</span> of <span class=\"math inline\">\\(\\mathbf{T}^2\\)</span>, which are mapped onto <span class=\"math inline\">\\(\\Gamma_+\\)</span> and <span class=\"math inline\">\\(\\Gamma_-\\)</span>, respectively. Away from these curves and from the self-intersection of the cone, each point of the band has exactly two preimages, <span class=\"math inline\">\\(\\alpha\\)</span> and its mirror image <span class=\"math inline\">\\(2\\phi(\\tau)-\\alpha\\)</span> with respect to the vertical plane of the kite. The torus <span class=\"math inline\">\\(\\mathbf{T}^2\\)</span> of configurations is therefore a double cover of the band, folded along its two edges. In particular, the position of the kite does not determine the angle of the arm, which is why <span class=\"math inline\">\\(\\alpha\\)</span>, rather than <span class=\"math inline\">\\(r\\)</span>, is used as the second coordinate.</p>"},{"title":"1.2 Velocities","page":"1 Mathematical model of KEEP","location":"section-1.html#sec:model-velocities","category":"section","text":"<p>The generalized velocities are <span class=\"math inline\">\\(\\dot{\\vb q}= (\\dot\\alpha,\\dot\\tau)\\)</span>. The velocity of the arm tip is <span class=\"math display\">\\begin{equation}\n    \\dot{\\vb a} = a\\,\\dot\\alpha\\,\\vu z\\times\\vu a,\n\\tag{17}\\end{equation}</span> and that of the kite decomposes along the generator and along the eight, which span the tangent plane to <span class=\"math inline\">\\(\\mathscr{C}\\)</span>: <a id=\"eq:kite-velocity\"></a><span class=\"math display\">\\begin{equation}\n \\tag{18}\n    \\dot{\\vb r} = \\dot r\\,\\vu r + r\\,\\dot\\tau\\,\\vu r'.\n\\end{equation}</span> Differentiating <a href=\"#eq:radial-quadratic\">(12)</a> in time, <span class=\"math inline\">\\(\\dot r = r\\,\\dot p/R\\)</span>, where <span class=\"math display\">\\begin{equation}\n    \\dot p = \\vu r\\vdot\\dot{\\vb a} + \\dot\\tau\\,\\vu r'\\vdot\\vb a = a\\,\\dot\\alpha\\,\\vu r\\vdot(\\vu z\\times\\vu a) + \\dot\\tau\\,\\vu r'\\vdot\\vb a.\n\\tag{19}\\end{equation}</span> Second-order derivatives, needed for the accelerations, can be obtained for numerical purposes by <span data-acronym-label=\"ad\" data-acronym-form=\"singular+short\">ad</span>.</p>"},{"title":"1.3 Force model","page":"1 Mathematical model of KEEP","location":"section-1.html#sec:model-forces","category":"section","text":"<p>We model the wind velocity profile <span class=\"math inline\">\\(\\vb w\\)</span> using a standard power-law wind shear model. Since the unit vector <span class=\"math inline\">\\(\\vu x\\)</span> points downwind, the wind field is given by <span class=\"math display\">\\begin{equation}\n    \\vb w(z) = w_{\\text{ref}} \\qty(\\frac{z}{z_{\\text{ref}}})^{1/7} \\vu x,\n\\tag{20}\\end{equation}</span> where <span class=\"math inline\">\\(w_{\\text{ref}}\\)</span> is the reference wind speed at altitude <span class=\"math inline\">\\(z_{\\text{ref}}\\)</span>. The altitude of the kite is <span class=\"math display\">\\begin{equation}\n    z = \\vb r \\vdot \\vu z = r(\\alpha, \\tau) \\cos\\theta(\\tau),\n\\tag{21}\\end{equation}</span> which is positive under the assumption <span class=\"math inline\">\\(\\theta_0+\\Delta\\theta&lt;\\pi/2\\)</span>. The apparent wind velocity experienced by the kite is <span class=\"math display\">\\begin{equation}\n    \\vb w_a = \\vb w(z) - \\dot{\\vb r}.\n\\tag{22}\\end{equation}</span></p>\n<p>The kite is subject to gravity, to the aerodynamic force, to the tension of the lines, and to the reaction of the cone, which enforces the prescribed motion. Gravity is modeled as <a id=\"eq:f_grav\"></a><span class=\"math display\">\\begin{equation}\n \\tag{23}\n    \\vb F_g = -\\qty(m + \\frac{m_\\ell}{2}) g \\vu z,\n\\end{equation}</span> where <span class=\"math inline\">\\(m_\\ell = n \\pi \\ell \\rho_\\ell d_\\ell^2 / 4\\)</span> is the total mass of the lines, half of which is assumed to be lifted by the kite. The aerodynamic resultant is computed from the apparent wind using the same model detailed in Section <a href=\"appendix-A.html#sec:model10D-dyn-aero\">A.3</a>, namely <a id=\"eq:f_aero\"></a><span class=\"math display\">\\begin{equation}\n \\tag{24}\n    \\vb F_a = L \\vu k_t + D \\vu k_b + \\tilde D_\\ell \\vu w_a^\\perp,\n\\end{equation}</span> where the lift <span class=\"math inline\">\\(L\\)</span> and drag <span class=\"math inline\">\\(D\\)</span> are proportional to <span class=\"math inline\">\\(\\norm{\\vb w_a}^2\\)</span>, and the line drag <span class=\"math inline\">\\(\\tilde D_\\ell\\)</span>, along the component <span class=\"math inline\">\\(\\vu w_a^\\perp\\)</span> of the apparent wind orthogonal to the lines, is given by the integral approximation <a href=\"appendix-A.html#eq:line-drag-10D\">(88)</a> of Appendix <a href=\"appendix-A.html#sec:model10D\">A</a>. In all the computations of this paper, the drag coefficient of the lines is <span class=\"math inline\">\\(C_{D,\\ell} = 0\\)</span>: their drag is lumped into the drag coefficient <span class=\"math inline\">\\(C_D\\)</span> of the kite, independently of the length <span class=\"math inline\">\\(\\ell\\)</span>. As the drag of the lines grows linearly with <span class=\"math inline\">\\(\\ell\\)</span>, accounting for it separately would penalize long lines, and would tend to lower the optimal length found in Section <a href=\"section-4.html#sec:optimization\">4</a>.</p>\n<p>The lines pull the kite towards <span class=\"math inline\">\\(A\\)</span>: with <span class=\"math inline\">\\(\\hat{\\boldsymbol{\\ell}} = \\boldsymbol{\\ell}/\\ell\\)</span> and <span class=\"math inline\">\\(F_\\ell\\)</span> the tension, the force they exert on the kite is <span class=\"math inline\">\\(\\vb F_\\ell = -F_\\ell\\,\\hat{\\boldsymbol{\\ell}}\\)</span>, and the force they exert on the arm at <span class=\"math inline\">\\(A\\)</span> is <span class=\"math inline\">\\(-\\vb F_\\ell\\)</span>. The arm has moment of inertia <span class=\"math inline\">\\(I\\)</span> about <span class=\"math inline\">\\(\\Delta\\)</span>, and the generator exerts on it the resistive torque <span class=\"math display\">\\begin{equation}\n    T(\\dot\\alpha) = -b\\,\\dot\\alpha, \\qquad b&gt;0.\n\\tag{25}\\end{equation}</span> The moment of <span class=\"math inline\">\\(-\\vb F_\\ell\\)</span> about <span class=\"math inline\">\\(\\Delta\\)</span> is <a id=\"eq:moment_fell\"></a><span class=\"math display\">\\begin{equation}\n \\tag{26}\n    M_\\Delta(-\\vb F_\\ell) = \\qty(\\vb a\\times F_\\ell\\,\\hat{\\boldsymbol{\\ell}})\\vdot\\vu z = a F_\\ell\\,\\hat{\\boldsymbol{\\ell}} \\vdot (\\vu z \\times \\vu a),\n\\end{equation}</span> so that Newton’s second law for the arm yields <a id=\"eq:newton_arm\"></a><span class=\"math display\">\\begin{equation}\n \\tag{27}\n    I \\ddot\\alpha = a F_\\ell\\,\\hat{\\boldsymbol{\\ell}} \\vdot (\\vu z \\times \\vu a) + T(\\dot \\alpha),\n\\end{equation}</span> where the tension <span class=\"math inline\">\\(F_\\ell\\)</span> is an unknown of the problem, determined together with the accelerations: it is the reaction of the lines, which enforce the spindle torus constraint. The lever arm <span class=\"math inline\">\\(a\\lambda\\)</span> of the tension has a geometric meaning: as <span class=\"math inline\">\\(\\vb a\\vdot(\\vu z\\times\\vu a) = 0\\)</span>, <a id=\"eq:lever-arm\"></a><span class=\"math display\">\\begin{equation}\n \\tag{28}\n    \\lambda := \\hat{\\boldsymbol{\\ell}} \\vdot (\\vu z \\times \\vu a) = \\frac{r}{\\ell}\\,\\vu r\\vdot(\\vu z\\times\\vu a) = \\frac{r}{\\ell}\\sin\\theta\\sin(\\phi-\\alpha),\n\\end{equation}</span> which vanishes exactly on the fold curves <span class=\"math inline\">\\(\\alpha = \\phi\\)</span> and <span class=\"math inline\">\\(\\alpha = \\phi+\\pi\\)</span> of <span class=\"math inline\">\\(\\Phi\\)</span>: when the kite reaches an edge <span class=\"math inline\">\\(\\Gamma_\\pm\\)</span> of the band, i.e. the spindle torus, the lines and the arm are in the same vertical plane, the lines exert no torque on the arm, and the arm is only braked by the generator, <span class=\"math inline\">\\(I\\ddot\\alpha = T(\\dot\\alpha)\\)</span>. Since lines can only pull, physically admissible motions moreover require <span class=\"math inline\">\\(F_\\ell\\geq0\\)</span>; this condition is not imposed by the model and must be checked a posteriori.</p>"},{"title":"1.4 Equations of motion","page":"1 Mathematical model of KEEP","location":"section-1.html#sec:model-eom","category":"section","text":"<p>The prescribed trajectory of the kite is enforced through a frictionless geometric constraint: the reaction <span class=\"math inline\">\\(\\vb F_c\\)</span> of the cone performs no virtual work along the admissible displacements, which span the tangent plane to <span class=\"math inline\">\\(\\mathscr{C}\\)</span>. Equivalently, <span class=\"math inline\">\\(\\vb F_c\\)</span> is normal to the cone, <span class=\"math inline\">\\(\\vb F_c = F_c\\,\\vu n\\)</span> with <span class=\"math inline\">\\(\\vu n\\)</span> given by <a href=\"#eq:cone-normal\">(7)</a>, that is <a id=\"eq:cone_constraint\"></a><span class=\"math display\">\\begin{equation}\n \\tag{29}\n    \\vb F_c \\vdot \\vu r = 0, \\qquad\n    \\vb F_c \\vdot \\vu r' = 0.\n\\end{equation}</span> The spindle torus constraint, on the other hand, is enforced by the lines, through the tension <span class=\"math inline\">\\(F_\\ell\\)</span>. Newton’s second law for the kite reads <a id=\"eq:newton_kite\"></a><span class=\"math display\">\\begin{equation}\n \\tag{30}\n    m \\ddot{\\vb r} = \\vb F_a + \\vb F_g + \\vb F_\\ell + \\vb F_c.\n\\end{equation}</span> Projecting it onto the tangent plane of the cone, that is, onto <span class=\"math inline\">\\(\\vu r\\)</span> and <span class=\"math inline\">\\(\\vu r&#39;\\)</span>, eliminates the constraint force by <a href=\"#eq:cone_constraint\">(29)</a>. Since <span class=\"math inline\">\\(\\ddot{\\vb r}\\)</span> is affine in <span class=\"math inline\">\\(\\ddot{\\vb q}\\)</span>, these two projections and the equation <a href=\"#eq:newton_arm\">(27)</a> of the arm form a <span class=\"math inline\">\\(3\\times3\\)</span> linear system in <span class=\"math inline\">\\((\\ddot\\alpha, \\ddot\\tau, F_\\ell)\\)</span>, with coefficients that depend on <span class=\"math inline\">\\(\\vb q\\)</span> only. Solving the equation of the arm for the tension, <span class=\"math inline\">\\(F_\\ell = (I\\ddot\\alpha - T(\\dot\\alpha))/(a\\lambda)\\)</span>, would leave a <span class=\"math inline\">\\(2\\times2\\)</span> system for <span class=\"math inline\">\\(\\ddot{\\vb q}\\)</span> whose matrix and right-hand side both blow up on the fold curves, where the accelerations would be obtained as <span class=\"math inline\">\\(0/0\\)</span>. We solve it for the acceleration of the arm instead, dividing by <span class=\"math inline\">\\(I&gt;0\\)</span>: <a id=\"eq:ddalpha\"></a><span class=\"math display\">\\begin{equation}\n \\tag{31}\n    \\ddot\\alpha = \\frac{a\\lambda F_\\ell + T(\\dot\\alpha)}{I},\n\\end{equation}</span> which leaves a <span class=\"math inline\">\\(2\\times2\\)</span> linear system for the acceleration of the kite and the tension, <a id=\"eq:eom_regular\"></a><span class=\"math display\">\\begin{equation}\n \\tag{32}\n    N(\\vb q) \\mqty(\\ddot\\tau \\\\ F_\\ell) = \\vb h(\\vb q, \\dot{\\vb q}),\n\\end{equation}</span> given in Appendix <a href=\"appendix-B.html#sec:explicit-ddq\">B</a>, together with its explicit solution. The determinant of <span class=\"math inline\">\\(N(\\vb q)\\)</span> is negative on the whole torus <span class=\"math inline\">\\(\\mathbf{T}^2\\)</span> of configurations, and bounded away from zero. Hence the accelerations <span class=\"math inline\">\\(\\ddot{\\vb q}\\)</span> and the tension <span class=\"math inline\">\\(F_\\ell\\)</span> are analytic functions of <span class=\"math inline\">\\((\\vb q, \\dot{\\vb q})\\)</span> wherever the forces are, including on the fold curves. The only singularities of the model are aerodynamic: a vanishing apparent wind, <span class=\"math inline\">\\(\\vb w_a = 0\\)</span>, and an apparent wind parallel to the lines, where the frame of the kite of Section <a href=\"appendix-A.html#sec:model10D-dyn-aero\">A.3</a> is undefined.</p>\n<p>The state of the dynamical system is <span class=\"math inline\">\\(\\vb x = (\\vb q, \\dot{\\vb q}) = (\\alpha, \\tau, \\dot \\alpha, \\dot \\tau) \\in \\mathbf{T}^2\\times\\mathbf{R}^2\\)</span>, and the evolution function <span class=\"math inline\">\\(f\\)</span> is defined by <span class=\"math display\">\\begin{equation}\n    f(\\vb x) = f(\\vb q, \\dot{\\vb q}) = (\\dot{\\vb q}, \\ddot{\\vb q}),\n\\tag{33}\\end{equation}</span> where <span class=\"math inline\">\\(\\ddot{\\vb q}\\)</span> is given by <a href=\"#eq:ddalpha\">(31)</a> and <a href=\"#eq:eom_regular\">(32)</a>. The system is symmetric through the map <a id=\"eq:symmetry\"></a><span class=\"math display\">\\begin{equation}\n \\tag{34}\n    \\sigma: (\\alpha, \\tau, \\dot \\alpha, \\dot \\tau) \\mapsto (-\\alpha, \\tau + \\pi, -\\dot \\alpha, \\dot \\tau).\n\\end{equation}</span> Geometrically, <span class=\"math inline\">\\(\\sigma\\)</span> is induced by the reflection through the vertical plane <span class=\"math inline\">\\((O,\\vu x,\\vu z)\\)</span> that contains the wind: this reflection maps <span class=\"math inline\">\\(\\vu a(\\alpha)\\)</span> to <span class=\"math inline\">\\(\\vu a(-\\alpha)\\)</span> and <span class=\"math inline\">\\(\\vu r(\\tau)\\)</span> to <span class=\"math inline\">\\(\\vu r(\\tau+\\pi)\\)</span>, since <span class=\"math inline\">\\(\\theta(\\tau+\\pi) = \\theta(\\tau)\\)</span> and <span class=\"math inline\">\\(\\phi(\\tau+\\pi) = -\\phi(\\tau)\\)</span>, and it leaves the circle <span class=\"math inline\">\\(\\mathscr{A}\\)</span>, the eight <span class=\"math inline\">\\(\\mathscr{E}\\)</span>, the cone <span class=\"math inline\">\\(\\mathscr{C}\\)</span>, the spindle torus <span class=\"math inline\">\\(\\mathscr{T}\\)</span> and the wind field invariant.</p>\n<p>The mechanical power extracted by the generator is <span class=\"math display\">\\begin{equation}\n    \\dot W(t)\n    = -\\dot\\alpha\\,T(\\dot\\alpha)\n    = b\\dot\\alpha^2\\geq0,\n\\tag{35}\\end{equation}</span> where <span class=\"math inline\">\\(W(0)=0\\)</span>. The average power of a solution spanning <span class=\"math inline\">\\([0, t_f]\\)</span> is <span class=\"math display\">\\begin{equation}\n    \\bar P=\\frac{W_f}{t_f},\n\\tag{36}\\end{equation}</span> where <span class=\"math inline\">\\(W_f=W(t_f)\\)</span> is the total extracted work.</p>"},{"title":"B Explicit dynamics","page":"B Explicit dynamics","location":"appendix-B.html#sec:explicit-ddq","category":"section","text":"<p>This appendix gives the system <a href=\"section-1.html#eq:eom_regular\">(32)</a> and its solution. We use the notation of Section <a href=\"section-1.html#sec:model-geometry\">1.1</a>: <span class=\"math inline\">\\(p = \\vu r\\vdot\\vb a\\)</span>, <span class=\"math inline\">\\(r = p + R\\)</span> with <span class=\"math inline\">\\(R = \\sqrt{p^2+\\ell^2-a^2}\\)</span>, <span class=\"math inline\">\\(\\ell\\hat{\\boldsymbol{\\ell}} = r\\vu r - a\\vu a\\)</span>, the lever arm <span class=\"math inline\">\\(\\lambda\\)</span> of <a href=\"section-1.html#eq:lever-arm\">(28)</a>, and <span class=\"math display\">\\begin{equation}\n    v = \\norm{\\vu r'} &gt; 0, \\qquad r_\\alpha = \\pdv{r}{\\alpha}, \\qquad r_\\tau = \\pdv{r}{\\tau},\n\\tag{112}\\end{equation}</span> with <span class=\"math inline\">\\(\\nabla^2 r\\)</span> the Hessian of <span class=\"math inline\">\\(r(\\alpha,\\tau)\\)</span>. The force <span class=\"math inline\">\\(\\vb F = \\vb F_a + \\vb F_g\\)</span> depends on <span class=\"math inline\">\\((\\vb q, \\dot{\\vb q})\\)</span> only.</p>\n<ol>\n<li><p><span class=\"math inline\">\\(\\hat{\\boldsymbol{\\ell}}\\vdot\\vu r = R/\\ell\\)</span>, since <span class=\"math inline\">\\(\\ell\\hat{\\boldsymbol{\\ell}}\\vdot\\vu r = r - p = R\\)</span>.</p></li>\n<li><p><span class=\"math inline\">\\(r_\\alpha = (a\\ell/R)\\,\\lambda\\)</span>: indeed <span class=\"math inline\">\\(\\pdv*{p}{\\alpha} = a\\,\\vu r\\vdot(\\vu z\\times\\vu a)\\)</span>, <span class=\"math inline\">\\(\\vu r\\vdot(\\vu z\\times\\vu a) = \\ell\\lambda/r\\)</span> by <a href=\"section-1.html#eq:lever-arm\">(28)</a>, and <span class=\"math inline\">\\(\\dv*{r}{p} = r/R\\)</span>. So <span class=\"math inline\">\\(r_\\alpha\\)</span> vanishes on the fold curves at the same rate as <span class=\"math inline\">\\(\\lambda\\)</span>.</p></li>\n<li><p><span class=\"math inline\">\\(r_\\tau = (r/R)\\,a\\,\\vu a\\vdot\\vu r&#39;\\)</span> and, as <span class=\"math inline\">\\(\\vu r\\vdot\\vu r&#39; = 0\\)</span>, <span class=\"math inline\">\\(\\hat{\\boldsymbol{\\ell}}\\vdot\\vu r&#39; = -(a/\\ell)\\,\\vu a\\vdot\\vu r&#39; = -R\\,r_\\tau/(r\\ell)\\)</span>.</p></li>\n</ol>\n<p>With <span class=\"math inline\">\\(\\vb r = r\\vu r(\\tau)\\)</span>, <span class=\"math inline\">\\(\\vu r\\vdot\\vu r&#39; = 0\\)</span> and <span class=\"math inline\">\\(\\vu r\\vdot\\vu r&#39;&#39; = -v^2\\)</span>, <span class=\"math display\">\\begin{align}\n    \\ddot{\\vb r}\\vdot\\vu r &amp;= r_\\alpha\\ddot\\alpha + r_\\tau\\ddot\\tau + \\dot{\\vb q}\\vdot\\nabla^2 r\\,\\dot{\\vb q}- r v^2\\dot\\tau^2, \\tag{113}\\\\\n    \\ddot{\\vb r}\\vdot\\vu r' &amp;= r v^2\\ddot\\tau + 2\\dot r v^2\\dot\\tau + r\\,(\\vu r'\\vdot\\vu r'')\\,\\dot\\tau^2.\n\\tag{114}\\end{align}</span> The projections of <a href=\"section-1.html#eq:newton_kite\">(30)</a> onto <span class=\"math inline\">\\(\\vu r\\)</span> and <span class=\"math inline\">\\(\\vu r&#39;\\)</span>, with <span class=\"math inline\">\\(\\vb F_\\ell = -F_\\ell\\hat{\\boldsymbol{\\ell}}\\)</span> and the first identity, and the equation <a href=\"section-1.html#eq:newton_arm\">(27)</a> of the arm read <a id=\"eq:K1\"></a><a id=\"eq:K2\"></a><a id=\"eq:A\"></a><span class=\"math display\">\\begin{align}\n    m\\,(r_\\alpha\\ddot\\alpha + r_\\tau\\ddot\\tau) + \\frac{R}{\\ell}F_\\ell &amp;= c_1, &amp;\n    c_1 &amp;= -m\\,(\\dot{\\vb q}\\vdot\\nabla^2 r\\,\\dot{\\vb q}- r v^2\\dot\\tau^2) + \\vu r\\vdot\\vb F, \\tag{115} \\\\\n    m r v^2\\ddot\\tau + (\\hat{\\boldsymbol{\\ell}}\\vdot\\vu r')\\,F_\\ell &amp;= c_2, &amp;\n    c_2 &amp;= -m\\,(2\\dot r v^2\\dot\\tau + r\\,(\\vu r'\\vdot\\vu r'')\\,\\dot\\tau^2) + \\vu r'\\vdot\\vb F, \\tag{116} \\\\\n    I\\ddot\\alpha - a\\lambda F_\\ell &amp;= T(\\dot\\alpha). \\tag{117}\n\\end{align}</span></p>\n<p>Substituting <a href=\"section-1.html#eq:ddalpha\">(31)</a>, that is <a href=\"#eq:A\">(117)</a> solved for <span class=\"math inline\">\\(\\ddot\\alpha\\)</span>, into <a href=\"#eq:K1\">(115)</a>, and using the second identity, <span class=\"math inline\">\\(m r_\\alpha a\\lambda/I = m a^2\\ell\\lambda^2/(IR)\\)</span>, gives <a href=\"section-1.html#eq:eom_regular\">(32)</a> with <span class=\"math display\">\\begin{equation}\n    N(\\vb q) = \\mqty(m r_\\tau &amp; \\dfrac{R}{\\ell} + \\dfrac{m a^2\\ell\\lambda^2}{IR} \\\\ m r v^2 &amp; \\hat{\\boldsymbol{\\ell}}\\vdot\\vu r'),\n    \\qquad\n    \\vb h(\\vb q,\\dot{\\vb q}) = \\mqty(c_1 - m r_\\alpha T(\\dot\\alpha)/I \\\\ c_2).\n\\tag{118}\\end{equation}</span> By the third identity, <a id=\"eq:detN\"></a><span class=\"math display\">\\begin{equation}\n \\tag{119}\n    \\det N = -\\frac{m R\\,r_\\tau^2}{r\\ell} - \\frac{m r v^2 R}{\\ell} - \\frac{m^2 a^2\\ell r v^2\\lambda^2}{IR} \\leq -\\frac{m r v^2 R}{\\ell} &lt; 0.\n\\end{equation}</span> As <span class=\"math inline\">\\(r\\geq\\ell-a\\)</span>, <span class=\"math inline\">\\(R\\geq\\sqrt{\\ell^2-a^2}\\)</span> and <span class=\"math inline\">\\(v\\geq v_*\\)</span> (Appendix <a href=\"appendix-D.html#app:curv\">D</a>), <span class=\"math display\">\\begin{equation}\n    \\abs{\\det N} \\geq \\frac{m\\,(\\ell-a)\\,v_*^2\\sqrt{\\ell^2-a^2}}{\\ell} &gt; 0\n\\tag{120}\\end{equation}</span> on the whole torus of configurations. By Cramer’s rule, with <span class=\"math inline\">\\(h_1 = c_1 - m r_\\alpha T(\\dot\\alpha)/I\\)</span>, <span class=\"math display\">\\begin{align}\n    \\ddot\\tau &amp;= \\frac{1}{\\det N}\\qty[h_1\\,(\\hat{\\boldsymbol{\\ell}}\\vdot\\vu r') - c_2\\qty(\\frac{R}{\\ell} + \\frac{m a^2\\ell\\lambda^2}{IR})], \\tag{121}\\\\\n    F_\\ell &amp;= \\frac{1}{\\det N}\\qty[m r_\\tau c_2 - m r v^2 h_1], \\tag{122}\\\\\n    \\ddot\\alpha &amp;= \\frac{a\\lambda F_\\ell + T(\\dot\\alpha)}{I}.\n\\tag{123}\\end{align}</span> These expressions are analytic wherever the force <span class=\"math inline\">\\(\\vb F\\)</span> is, since the kinematic quantities <span class=\"math inline\">\\(r\\)</span>, <span class=\"math inline\">\\(R\\)</span>, <span class=\"math inline\">\\(v\\)</span> are positive and analytic on the whole torus. Off the fold curves (<span class=\"math inline\">\\(\\lambda\\neq0\\)</span>), they are equivalent to the elimination of the tension through <a href=\"#eq:A\">(117)</a>, and define the same flow; on the fold curves, the arm is free of the lines, <span class=\"math inline\">\\(I\\ddot\\alpha = T(\\dot\\alpha)\\)</span>, and the tension is fixed by the balance <a href=\"#eq:K1\">(115)</a>–<a href=\"#eq:K2\">(116)</a> of the kite. They are implemented as such in the code (<code>PointMass4.dynamics</code>), at the cost of one <span class=\"math inline\">\\(2\\times2\\)</span> solve per evaluation, and the tension along a trajectory is given by the same solve.</p>"},{"title":"4 Optimization","page":"4 Optimization","location":"section-4.html#sec:optimization","category":"section","text":"<p>We designed this model to evaluate the average power output of KEEP. In the previous section, we computed limit cycles for a given set of environment and design parameters. We now fix the environment, mainly the reference wind speed <span class=\"math inline\">\\(w_0\\)</span>, and maximize the average power output over one revolution of a periodic orbit by tuning a selection of design parameters.</p>"},{"title":"4.1 Optimizing for maximum average power","page":"4 Optimization","location":"section-4.html#sec:opt-power","category":"section","text":"<p>To assess the quality of a set of parameters, we measure the total work done by the generator, <em>i.e.</em> the amount of energy extracted from the system. We obtain this information by augmenting the state with the work <span class=\"math inline\">\\(W\\)</span> done since the start of the simulation, whose time derivative is the instantaneous power, namely the product of (the opposite of) the torque and the arm angular velocity: <a id=\"eq:work\"></a><span class=\"math display\">\\begin{equation}\n \\tag{56}\n    W(0) = 0, \\qquad\n    \\dot W = P = - \\dot \\alpha \\, T(\\dot \\alpha) = b \\, \\dot \\alpha^2 \\geq 0.\n\\end{equation}</span> The work is integrated concurrently with <span class=\"math inline\">\\(\\vb x = (\\alpha, \\tau, \\dot \\alpha, \\dot \\tau)\\)</span>, using the same numerical scheme, and we denote the augmented state <span class=\"math inline\">\\(\\tilde{\\vb x} = (\\vb x, W)\\)</span>. The average power over a periodic orbit of period <span class=\"math inline\">\\(t_f\\)</span> is then <span class=\"math display\">\\begin{equation}\n    \\bar P = W_f / t_f, \\qquad W_f = W(t_f).\n\\tag{57}\\end{equation}</span> Since the trajectory converges to the same periodic orbit (given <span class=\"math inline\">\\(\\dot \\tau &gt; 0\\)</span>), maximizing the average power as <span class=\"math inline\">\\(t \\to \\infty\\)</span> is equivalent to maximizing it over one period of this orbit.</p>\n<p>For the solution of the <span data-acronym-label=\"ivp\" data-acronym-form=\"singular+short\">ivp</span> to be a periodic orbit, looping constraints must be enforced at <span class=\"math inline\">\\(t_f\\)</span>, which yields a <span data-acronym-label=\"bvp\" data-acronym-form=\"singular+short\">bvp</span>. Without loss of generality, we fix the phase by imposing <span class=\"math inline\">\\(\\tau(0) = 0\\)</span>, so that <span class=\"math inline\">\\(\\tau(t_f) = \\pm 2\\pi\\)</span>. The sign determines the direction of travel of the kite: it rises either on the sides of the eight (<span class=\"math inline\">\\(\\tau(t_f) = +2\\pi\\)</span>) or in its center (<span class=\"math inline\">\\(\\tau(t_f) = -2\\pi\\)</span>). To avoid the lines sliding against each other, we choose the former.</p>\n<p>We optimize the line length <span class=\"math inline\">\\(\\ell\\)</span>, the arm inertia <span class=\"math inline\">\\(I\\)</span>, the braking coefficient <span class=\"math inline\">\\(b\\)</span> of the generator and the half-width <span class=\"math inline\">\\(\\Delta\\varphi\\)</span> of the eight, and denote by <span class=\"math inline\">\\(\\Theta = (\\ell, I, b, \\Delta\\varphi)\\)</span> the vector of design parameters; the half-height <span class=\"math inline\">\\(\\Delta\\theta = 6.0^\\circ\\)</span> of the eight is held fixed. The optimization problem reads <a id=\"eq:opt-problem\"></a><span class=\"math display\">\\begin{equation}\n \\tag{58}\nW_f / t_f \\underset{\\substack{\\alpha_0, \\dot{\\alpha}_0, \\dot{\\tau}_0 \\\\ W_f, t_f \\\\ \\Theta}}{\\longrightarrow} \\max\n\\end{equation}</span> subject to constraints <a id=\"eq:opt-constraints\"></a><span class=\"math display\">\\begin{equation}\n \\tag{59}\n\\begin{split}\n    &amp;\\alpha(t_f, \\Theta) = \\alpha_0 \\\\\n    &amp;\\tau(t_f, \\Theta) = 2\\pi \\\\\n    &amp;\\dot \\alpha(t_f, \\Theta) = \\dot \\alpha_0 \\\\\n    &amp;\\dot \\tau(t_f, \\Theta) = \\dot \\tau_0 \\\\\n    &amp;W(t_f, \\Theta) = W_f,\n\\end{split}\n\\end{equation}</span> where the components of <span class=\"math inline\">\\(\\tilde{\\vb x}(t_f, \\Theta)\\)</span> are obtained by integrating the <span data-acronym-label=\"ivp\" data-acronym-form=\"singular+short\">ivp</span> from <span class=\"math inline\">\\(\\tilde{\\vb x}_0 = (\\alpha_0, 0, \\dot \\alpha_0, \\dot \\tau_0, 0)\\)</span> with parameters <span class=\"math inline\">\\(\\Theta\\)</span>, and <span class=\"math inline\">\\(W_f\\)</span> is a slack variable for the final work. In the search for parameters that provide more power, the solver thus also determines the corresponding initial condition lying on the periodic orbit.</p>\n<p>We reuse our work on equilibria and limit cycles to provide the solver with an initial guess that satisfies the constraints. Starting from a physically reasonable set of parameters <span class=\"math inline\">\\(\\Theta_0\\)</span>, we compute the corresponding limit cycle (with the correct direction of travel), from which we extract <span class=\"math inline\">\\(\\alpha_0, \\dot \\alpha_0, \\dot \\tau_0, t_f\\)</span> and <span class=\"math inline\">\\(W_f\\)</span>; this results into a feasible point.</p>\n<p>The problem is modelled with ADNLPModels.jl <span class=\"citation\" data-cites=\"migot2021adnlpmodels\">(<a href=\"references.html#ref-migot2021adnlpmodels\">Migot et al. 2021</a>)</span>, which computes all required derivatives algorithmically with ForwardDiff.jl <span class=\"citation\" data-cites=\"RevelsLubinPapamarkou2016\">(<a href=\"references.html#ref-RevelsLubinPapamarkou2016\">Revels et al. 2016</a>)</span>. It is solved by the interior point method implemented in Ipopt <span class=\"citation\" data-cites=\"WachterBiegler2006\">(<a href=\"references.html#ref-WachterBiegler2006\">Wächter and Biegler 2006</a>)</span> (tolerance <span class=\"math inline\">\\(10^{-5}\\)</span>), called through NLPModelsIpopt.jl, with linear solver MUMPS <span class=\"citation\" data-cites=\"amestoy2001mumps\">(<a href=\"references.html#ref-amestoy2001mumps\">Amestoy et al. 2001</a>)</span>. The <span data-acronym-label=\"ivp\" data-acronym-form=\"singular+short\">ivp</span> appearing in the nonlinear constraints is solved at tolerance <span class=\"math inline\">\\(10^{-6}\\)</span> with Vern9, Verner’s Runge–Kutta 9(8) method from DifferentialEquations.jl <span class=\"citation\" data-cites=\"rackauckas2017differentialequations\">(<a href=\"references.html#ref-rackauckas2017differentialequations\">Rackauckas and Nie 2017</a>)</span>. The limit cycles from which the tables, figures and numbers of this section are computed are recomputed from the parameters, by settling and Newton’s method (Section <a href=\"section-3.html#sec:analysis-cycles\">3.2</a>), with integration tolerance <span class=\"math inline\">\\(10^{-5}\\)</span>. The parameters and their bounds are described in Table <a href=\"#tab:opt_descr\">3</a>, while the result of the optimization is presented in Table <a href=\"#tab:opt_results\">4</a>. Ipopt solves the problem in 20 iterations; as for any interior point method, the solution is a local optimum. The pipeline stops if Ipopt does not reach its tolerance, or if the power of its periodic orbit differs from that of the cycle recomputed at the optimum by settling and Newton’s method (Section <a href=\"section-3.html#sec:analysis-cycles\">3.2</a>). Figure <a href=\"#fig:opt-landscape\">15</a> shows the average power along one-dimensional slices through the optimum, each parameter varying while the others are held. The optimized cycle remains attracting, but less strongly: the largest modulus of its non-trivial Floquet multipliers is <span class=\"math inline\">\\(2.2 \\times 10^{-1}\\)</span>, against <span class=\"math inline\">\\(8.5 \\times 10^{-3}\\)</span> for the initial guess. We show the limit cycles before and after optimization in Figure <a href=\"#fig:time_series\">10</a>: the period goes from 2.83 s to 0.95 s, and the average power from 9.64 kW to 12.25 kW (<span class=\"math inline\">\\(+27\\%\\)</span>). These powers depend strongly on the glide ratio of the kite, <span class=\"math inline\">\\(G = C_L/C_D = 7\\)</span> here: with <span class=\"math inline\">\\(G = 5\\)</span>, a value more typical of soft kites, the optimized design produces 5.38 kW.</p>\n<table id=\"tab:opt_descr\">\n<caption><strong>Table 3:</strong> Description of the optimized parameters (<span class=\"math inline\">\\(\\Delta\\theta = 6.0{}^\\circ\\)</span> fixed).</caption>\n<thead>\n<tr>\n<th style=\"text-align: left;\"><span>Symbol (Unit)</span></th>\n<th style=\"text-align: right;\"><span>Lower bound</span></th>\n<th style=\"text-align: right;\"><span>Upper bound</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\ell\\)</span> (m)</td>\n<td style=\"text-align: right;\">15.0</td>\n<td style=\"text-align: right;\">200.0</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(I\\)</span> (kg m<sup>2</sup>)</td>\n<td style=\"text-align: right;\">62.0</td>\n<td style=\"text-align: right;\">1000000.0</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(b\\)</span> (N m s °<sup>−1</sup>)</td>\n<td style=\"text-align: right;\">0.0175</td>\n<td style=\"text-align: right;\">17453.3</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\Delta\\varphi\\)</span> (°)</td>\n<td style=\"text-align: right;\">10.0</td>\n<td style=\"text-align: right;\">90.0</td>\n</tr>\n</tbody>\n</table>\n\n<details class=\"web-code\"><summary>Code that produced this table</summary>\n\nsrc/optimization.jl (region opt_setup), see also the full file.\n\n    p_start = PMP.build_para(w0=WIND_REF)\n    p_start.b = PMP.optimal_torque_slope(p_start; tol=1e-9, rtol=1e-9, maxiter=50)  # b = I ω\n    lower = [first(L_BOUNDS), first(I_BOUNDS), first(B_BOUNDS), first(DPHI_BOUNDS)]\n    upper = [last(L_BOUNDS), last(I_BOUNDS), last(B_BOUNDS), last(DPHI_BOUNDS)]\n\n    @info \"opt: reference at $(WIND_REF) m/s over Θ = ($(join(SYMS, \", \")))\"\n    opt_ref = opt_step(p_start, SYMS, lower, upper; iters=it_ref, strict=!fast)\n    p_ref = opt_ref.p  # the Θ optimum at the reference wind speed\n    # the power of the solver's orbit must be that of the cycle recomputed from p_ref\n    # (settling + Newton), which every table and figure uses\n    let Pc = cycle_report(p_ref).P, gap = abs(opt_ref.P - Pc) / abs(Pc)\n        msg = \"optimum: solver power $(opt_ref.P) vs recomputed cycle $Pc (rel. gap $gap)\"\n        gap < 1e-3 || (fast ? @warn(msg) : error(msg))\n    end\n\nsrc/optimization.jl (region opt_tables), see also the full file.\n\n    ## Tables\n    table_descr, table_opt = latex_tables(p_start, p_ref, lower, upper)\n    push!(files, write_table(\"table2\", table_descr), write_table(\"table3\", table_opt))\n    @warn \"table4: values to be checked vs. Alain's computation\"\n    push!(files, write_table(\"table4\", comparison_table(p_start, p_ref)))\n    push!(files, write_table(\"numbers\", numbers_tex(; p_start, p_ref, opt_iter=opt_ref.iter, winds, sweep, dtheta, dtheta_opt, dtheta_lost)))\n\n</details>\n\n<p><span id=\"tab:opt_descr\" data-label=\"tab:opt_descr\"></span></p>\n<table id=\"tab:opt_results\">\n<caption><strong>Table 4:</strong> Optimization results at <span class=\"math inline\">\\(w_0 = 9\\,\\mathrm{m}\\,\\mathrm{s}^{-1}\\)</span>.</caption>\n<thead>\n<tr>\n<th style=\"text-align: left;\"><span>Symbol (Unit)</span></th>\n<th style=\"text-align: right;\"><span>Initial Guess</span></th>\n<th style=\"text-align: right;\"><span>Solution</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\ell\\)</span> (m)</td>\n<td style=\"text-align: right;\">31.0</td>\n<td style=\"text-align: right;\">27.0</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(I\\)</span> (kg m<sup>2</sup>)</td>\n<td style=\"text-align: right;\">1300.0</td>\n<td style=\"text-align: right;\">351.6</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(b\\)</span> (N m s °<sup>−1</sup>)</td>\n<td style=\"text-align: right;\">50.4</td>\n<td style=\"text-align: right;\">12.9</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\Delta\\varphi\\)</span> (°)</td>\n<td style=\"text-align: right;\">50.0</td>\n<td style=\"text-align: right;\">16.6</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Average power (kW)</td>\n<td style=\"text-align: right;\">9.64</td>\n<td style=\"text-align: right;\">12.25</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Period (s)</td>\n<td style=\"text-align: right;\">2.83</td>\n<td style=\"text-align: right;\">0.95</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Min line tension (kN)</td>\n<td style=\"text-align: right;\">3.36</td>\n<td style=\"text-align: right;\">5.75</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Max line tension (kN)</td>\n<td style=\"text-align: right;\">8.86</td>\n<td style=\"text-align: right;\">10.83</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Norm of residual</td>\n<td style=\"text-align: right;\"><span><span class=\"math inline\">\\(5.6\\times10^{-8}\\)</span></span></td>\n<td style=\"text-align: right;\"><span><span class=\"math inline\">\\(1.2\\times10^{-8}\\)</span></span></td>\n</tr>\n</tbody>\n</table>\n\n<details class=\"web-code\"><summary>Code that produced this table</summary>\n\nsrc/optimization.jl (region opt_setup), see also the full file.\n\n    p_start = PMP.build_para(w0=WIND_REF)\n    p_start.b = PMP.optimal_torque_slope(p_start; tol=1e-9, rtol=1e-9, maxiter=50)  # b = I ω\n    lower = [first(L_BOUNDS), first(I_BOUNDS), first(B_BOUNDS), first(DPHI_BOUNDS)]\n    upper = [last(L_BOUNDS), last(I_BOUNDS), last(B_BOUNDS), last(DPHI_BOUNDS)]\n\n    @info \"opt: reference at $(WIND_REF) m/s over Θ = ($(join(SYMS, \", \")))\"\n    opt_ref = opt_step(p_start, SYMS, lower, upper; iters=it_ref, strict=!fast)\n    p_ref = opt_ref.p  # the Θ optimum at the reference wind speed\n    # the power of the solver's orbit must be that of the cycle recomputed from p_ref\n    # (settling + Newton), which every table and figure uses\n    let Pc = cycle_report(p_ref).P, gap = abs(opt_ref.P - Pc) / abs(Pc)\n        msg = \"optimum: solver power $(opt_ref.P) vs recomputed cycle $Pc (rel. gap $gap)\"\n        gap < 1e-3 || (fast ? @warn(msg) : error(msg))\n    end\n\nsrc/optimization.jl (region opt_tables), see also the full file.\n\n    ## Tables\n    table_descr, table_opt = latex_tables(p_start, p_ref, lower, upper)\n    push!(files, write_table(\"table2\", table_descr), write_table(\"table3\", table_opt))\n    @warn \"table4: values to be checked vs. Alain's computation\"\n    push!(files, write_table(\"table4\", comparison_table(p_start, p_ref)))\n    push!(files, write_table(\"numbers\", numbers_tex(; p_start, p_ref, opt_iter=opt_ref.iter, winds, sweep, dtheta, dtheta_opt, dtheta_lost)))\n\n</details>\n\n<p><span id=\"tab:opt_results\" data-label=\"tab:opt_results\"></span></p>\n<figure id=\"fig:time_series\" data-latex-placement=\"thpb\">\n<img src=\"figs/optimization_timeseries_all.png\" />\n<figcaption><strong>Figure 10:</strong> Limit cycles for the initial guess (left) and the optimized parameters (dynamic optimum, right): angles and angular velocities (top), instantaneous and average power (middle), line tension (bottom). The period goes from 2.83 s to 0.95 s, and the average power increases by <span class=\"math inline\">\\(27\\%\\)</span>.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/optimization.jl (region opt_setup), see also the full file.\n\n    p_start = PMP.build_para(w0=WIND_REF)\n    p_start.b = PMP.optimal_torque_slope(p_start; tol=1e-9, rtol=1e-9, maxiter=50)  # b = I ω\n    lower = [first(L_BOUNDS), first(I_BOUNDS), first(B_BOUNDS), first(DPHI_BOUNDS)]\n    upper = [last(L_BOUNDS), last(I_BOUNDS), last(B_BOUNDS), last(DPHI_BOUNDS)]\n\n    @info \"opt: reference at $(WIND_REF) m/s over Θ = ($(join(SYMS, \", \")))\"\n    opt_ref = opt_step(p_start, SYMS, lower, upper; iters=it_ref, strict=!fast)\n    p_ref = opt_ref.p  # the Θ optimum at the reference wind speed\n    # the power of the solver's orbit must be that of the cycle recomputed from p_ref\n    # (settling + Newton), which every table and figure uses\n    let Pc = cycle_report(p_ref).P, gap = abs(opt_ref.P - Pc) / abs(Pc)\n        msg = \"optimum: solver power $(opt_ref.P) vs recomputed cycle $Pc (rel. gap $gap)\"\n        gap < 1e-3 || (fast ? @warn(msg) : error(msg))\n    end\n\nsrc/optimization.jl (region fig_timeseries), see also the full file.\n\n    sols = map((p_start, p_ref)) do p\n        LC.compute_limit_cycle(PMP.build_vbpara(p); sense=SENSE, tol=TOL, save_everystep=true)\n    end\n    # initial guess (I = 1300, b = Iω; not the PTO optimum of section C) and the same\n    # system optimized for average power\n    fig_ts = plot_time_series_grid(sols; titles=(\"Initial guess\", \"Dynamic optimum\"))\n    append!(files, save_figure(fig_ts, \"optimization_timeseries_all\"))\n\n</details>"},{"title":"4.2 Optimal design as a function of wind speed","page":"4 Optimization","location":"section-4.html#sec:opt-wind","category":"section","text":"<p>Since the optimization converges quickly, we repeat the procedure for a range of reference wind speeds <span class=\"math inline\">\\(w_0\\)</span>. For each integer wind speed from 5 m s<sup>−1</sup>–15 m s<sup>−1</sup>, we find the set of parameters (Figure <a href=\"#fig:parameterized_optimization_params\">13</a>) that maximizes power (Figure <a href=\"#fig:parameterized_optimization_power\">11</a>) and show the corresponding minimum and maximum line tension over the limit cycle (Figure <a href=\"#fig:parameterized_optimization_tension\">12</a>). For comparison, we also compute the power and line tension extrema using the set of parameters obtained in Section <a href=\"#sec:opt-power\">4.1</a>, optimized for a wind speed of 9 m s<sup>−1</sup>. Over this whole range, this fixed set of parameters yields at most <span class=\"math inline\">\\(11.9\\%\\)</span> less power than the actual optimum, with a maximum line tension at most <span class=\"math inline\">\\(11.7\\%\\)</span> higher. The system exhibits quasilinear scaling along this parameterized optimization, even though the length of the arm (and other parameters) is kept constant, which makes it impossible to scale the model perfectly to wind speed. Least-squares power laws along the optimized sweep give the following trends:</p>\n<ul>\n<li><p>the average power grows like <span class=\"math inline\">\\(w_0^{3.0}\\)</span>, to be compared with the <span class=\"math inline\">\\(w_0^3\\)</span> scaling of wind power;</p></li>\n<li><p>the maximum line tension grows like <span class=\"math inline\">\\(w_0^{2.0}\\)</span>;</p></li>\n<li><p>the line length <span class=\"math inline\">\\(\\ell\\)</span> and the arm inertia <span class=\"math inline\">\\(I\\)</span> vary as shown in Figure <a href=\"#fig:parameterized_optimization_params\">13</a>;</p></li>\n<li><p>the arm braking coefficient <span class=\"math inline\">\\(b\\)</span> grows like <span class=\"math inline\">\\(w_0^{0.8}\\)</span>;</p></li>\n<li><p>(not shown) the period varies like <span class=\"math inline\">\\(w_0^{-1.1}\\)</span>.</p></li>\n</ul>\n<p>The maximum line tension defines the strength requirements for the kite fabric and lines. Furthermore, the minimum line tension remains above 1.72 kN over the whole sweep, confirming <em>a posteriori</em> the modeling assumption that the lines are always in tension and never exert compression on the arm.</p>\n<figure id=\"fig:parameterized_optimization_power\" data-latex-placement=\"thpb\">\n<img src=\"figs/optimization_wind_sweep_power.png\" />\n<figcaption><strong>Figure 11:</strong> Average generated power for optimized (blue) and reference (black) parameters when the reference wind speed <span class=\"math inline\">\\(w_0\\)</span> is varied. The reference curve is generated by fixing the design parameters to the optimal values for <span class=\"math inline\">\\(w_0 = 9\\,\\mathrm{m}\\,\\mathrm{s}^{-1}\\)</span>.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/optimization.jl (region optwindsweep), see also the full file.\n\n    winds = range(5, 15, length=fast ? 3 : 11)\n    i_ref = findfirst(x -> x >= WIND_REF, winds)\n    @info \"opt: wind sweep, $(length(winds)) speeds from $(first(winds)) to $(last(winds)) m/s\"\n    sweep = wind_sweep(SYMS, p_ref, winds, lower, upper, i_ref; iters=it_sweep, strict=!fast)\n\nsrc/optimization.jl (region figwindsweep), see also the full file.\n\n    (; fig, panels) = plot_wind_sweep(winds, sweep, i_ref, GUIDES)\n    for (f, panel) in zip(panels, (\"power\", \"tension\", \"params\"))\n        plot!(f, size=plot_size(1, 1), leftmargin=10Plots.mm, bottommargin=6Plots.mm)\n        append!(files, save_figure(f, \"optimization_wind_sweep_$(panel)\"))\n    end\n\n</details>\n\n<figure id=\"fig:parameterized_optimization_tension\" data-latex-placement=\"thpb\">\n<img src=\"figs/optimization_wind_sweep_tension.png\" />\n<figcaption><strong>Figure 12:</strong> Minimum and maximum line tension <span class=\"math inline\">\\(\\vb F_\\ell\\)</span> for optimized (blue) and reference (black) parameters.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/optimization.jl (region optwindsweep), see also the full file.\n\n    winds = range(5, 15, length=fast ? 3 : 11)\n    i_ref = findfirst(x -> x >= WIND_REF, winds)\n    @info \"opt: wind sweep, $(length(winds)) speeds from $(first(winds)) to $(last(winds)) m/s\"\n    sweep = wind_sweep(SYMS, p_ref, winds, lower, upper, i_ref; iters=it_sweep, strict=!fast)\n\nsrc/optimization.jl (region figwindsweep), see also the full file.\n\n    (; fig, panels) = plot_wind_sweep(winds, sweep, i_ref, GUIDES)\n    for (f, panel) in zip(panels, (\"power\", \"tension\", \"params\"))\n        plot!(f, size=plot_size(1, 1), leftmargin=10Plots.mm, bottommargin=6Plots.mm)\n        append!(files, save_figure(f, \"optimization_wind_sweep_$(panel)\"))\n    end\n\n</details>\n\n<figure id=\"fig:parameterized_optimization_params\" data-latex-placement=\"thpb\">\n<img src=\"figs/optimization_wind_sweep_params.png\" />\n<figcaption><strong>Figure 13:</strong> Optimal parameters for each wind speed (color) and reference parameters fixed at the optimum for <span class=\"math inline\">\\(w_0 = 9\\,\\mathrm{m}\\,\\mathrm{s}^{-1}\\)</span> (black dashed lines).</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/optimization.jl (region optwindsweep), see also the full file.\n\n    winds = range(5, 15, length=fast ? 3 : 11)\n    i_ref = findfirst(x -> x >= WIND_REF, winds)\n    @info \"opt: wind sweep, $(length(winds)) speeds from $(first(winds)) to $(last(winds)) m/s\"\n    sweep = wind_sweep(SYMS, p_ref, winds, lower, upper, i_ref; iters=it_sweep, strict=!fast)\n\nsrc/optimization.jl (region figwindsweep), see also the full file.\n\n    (; fig, panels) = plot_wind_sweep(winds, sweep, i_ref, GUIDES)\n    for (f, panel) in zip(panels, (\"power\", \"tension\", \"params\"))\n        plot!(f, size=plot_size(1, 1), leftmargin=10Plots.mm, bottommargin=6Plots.mm)\n        append!(files, save_figure(f, \"optimization_wind_sweep_$(panel)\"))\n    end\n\n</details>\n\n<p>The half-height <span class=\"math inline\">\\(\\Delta\\theta\\)</span> of the eight, held fixed in the optimization, is varied in Figure <a href=\"#fig:opt-dtheta\">14</a>, with <span class=\"math inline\">\\(\\Theta\\)</span> either held at the optimum or re-optimized at each angle.</p>"},{"title":"4.3 Curvature of the kite trajectory","page":"4 Optimization","location":"section-4.html#sec:opt-curvature","category":"section","text":"<p>Besides power, a design has to be compatible with the flight of the kite: the turns of the curve <span class=\"math inline\">\\(t\\mapsto\\vb r(t)\\)</span> it describes must not be too strong. We therefore derive upper bounds on the curvature <span class=\"math inline\">\\(\\kappa\\)</span> of this curve; the computations and proofs are given in Appendix <a href=\"appendix-D.html#app:curv\">D</a>.</p>\n<p>Recall that the kite position is <span class=\"math inline\">\\(\\vb r = r\\,\\vu r(\\tau)\\)</span>, where <span class=\"math inline\">\\(\\vu r\\)</span> is the spherical eight <a href=\"section-1.html#eq:sphere_Model_Deriv\">(3)</a>–<a href=\"section-1.html#eq:traject_Model_Deriv\">(4)</a>, a closed curve on the unit sphere with <span class=\"math inline\">\\(0&lt;\\theta_0-\\Delta\\theta\\)</span> and <span class=\"math inline\">\\(\\theta_0+\\Delta\\theta&lt;\\pi\\)</span>, and where <span class=\"math inline\">\\(r\\)</span> solves the line-length constraint: <span class=\"math display\">\\begin{equation}\n    r = p + \\sqrt{p^2+\\ell^2-a^2}, \\qquad p = a\\,g, \\qquad g = \\sin\\theta\\cos(\\phi-\\alpha),\n\\tag{60}\\end{equation}</span> so that <span class=\"math inline\">\\(\\ell-a\\le r\\le\\ell+a\\)</span>, and <span class=\"math inline\">\\(r\\equiv\\ell\\)</span> when <span class=\"math inline\">\\(a=0\\)</span>. We write <span class=\"math inline\">\\(\\varepsilon = a/\\ell\\)</span> and <span class=\"math inline\">\\(\\varepsilon&#39; = a/\\sqrt{\\ell^2-a^2}\\)</span>. The kite trajectory is drawn on the <em>cone</em> <span class=\"math inline\">\\(\\mathscr C = \\{r\\,\\vu r(\\tau) : r&gt;0,\\ \\tau\\in\\mathbf{S}^1\\}\\)</span>, the conical hull of the spherical eight. Along a periodic orbit with <span class=\"math inline\">\\(\\dot\\tau\\ne0\\)</span>, the arm angle is a function <span class=\"math inline\">\\(\\alpha(\\tau)\\)</span>, and since curvature does not depend on the parametrisation, the curvature <span class=\"math inline\">\\(\\kappa = \\norm{\\vb r&#39;\\times\\vb r&#39;&#39;}/\\norm{\\vb r&#39;}^3\\)</span> of the space curve (prime <span class=\"math inline\">\\(=\\dv*{}{\\tau}\\)</span>) does not depend on the time law <span class=\"math inline\">\\(\\tau(t)\\)</span>: <span class=\"math inline\">\\(\\kappa(t) = \\kappa(\\tau(t))\\)</span>. It depends on <span class=\"math inline\">\\(\\ell\\)</span>, <span class=\"math inline\">\\(\\Delta\\theta\\)</span>, <span class=\"math inline\">\\(\\Delta\\phi\\)</span>, <span class=\"math inline\">\\(\\theta_0\\)</span>, <span class=\"math inline\">\\(a\\)</span>, and on the arm law through <span class=\"math inline\">\\(\\alpha,\\alpha&#39;,\\alpha&#39;&#39;\\)</span>; for <span class=\"math inline\">\\(a=0\\)</span>, only on <span class=\"math inline\">\\(\\ell,\\Delta\\theta,\\Delta\\phi,\\theta_0\\)</span>.</p>\n<p>Let <span class=\"math inline\">\\(v = \\norm{\\vu r&#39;}\\)</span> be the speed on the sphere, <span class=\"math display\">\\begin{equation}\n    v^2 = 4\\Delta\\theta^2\\cos^22\\tau + \\Delta\\phi^2\\sin^2\\theta\\cos^2\\tau &gt; 0,\n\\tag{61}\\end{equation}</span> <span class=\"math inline\">\\(\\sigma(\\tau) = \\int_0^\\tau v\\)</span> its arclength (so that <span class=\"math inline\">\\(f_\\sigma = f&#39;/v\\)</span> and <span class=\"math inline\">\\(f_{\\sigma\\sigma} = (f&#39;&#39;v-f&#39;v&#39;)/v^3\\)</span> for any function <span class=\"math inline\">\\(f\\)</span> of <span class=\"math inline\">\\(\\tau\\)</span>), <span class=\"math inline\">\\(\\vu t = \\vu r_\\sigma\\)</span> its unit tangent, <span class=\"math inline\">\\(\\vu n = \\vu r\\times\\vu t\\)</span>, and <span class=\"math inline\">\\(\\kappa_g\\)</span> its geodesic curvature on the sphere, defined by <span class=\"math inline\">\\(\\vu t_\\sigma = -\\vu r + \\kappa_g\\vu n\\)</span>: <a id=\"eq:curv-kg\"></a><span class=\"math display\">\\begin{equation}\n \\tag{62}\n    \\kappa_g = \\frac{2\\Delta\\theta\\Delta\\phi\\sin\\theta\\,\\sin\\tau\\,(2+\\cos2\\tau) + \\Delta\\phi\\cos\\theta\\cos\\tau\\,\\bigl(8\\Delta\\theta^2\\cos^22\\tau + \\Delta\\phi^2\\sin^2\\theta\\cos^2\\tau\\bigr)}{v^3}.\n\\end{equation}</span> Finally let <span class=\"math inline\">\\(u = \\ln r\\)</span>. For every <span class=\"math inline\">\\(\\tau\\)</span>, <a id=\"eq:curv-formula\"></a><span class=\"math display\">\\begin{equation}\n \\tag{63}\n    r\\,\\kappa = \\frac{\\sqrt{\\kappa_g^2\\,(1+u_\\sigma^2) + (1+u_\\sigma^2-u_{\\sigma\\sigma})^2}}{(1+u_\\sigma^2)^{3/2}}.\n\\end{equation}</span> The cone <span class=\"math inline\">\\(\\mathscr C\\)</span> is a developable surface, with principal curvatures <span class=\"math inline\">\\(0\\)</span> along the generators and <span class=\"math inline\">\\(\\kappa_g/r\\)</span> across them. Formula <a href=\"#eq:curv-formula\">(63)</a> is the decomposition <span class=\"math inline\">\\(\\kappa^2 = \\kappa_n^2 + (\\kappa_g^{\\mathscr C})^2\\)</span> of the curvature of a curve drawn on <span class=\"math inline\">\\(\\mathscr C\\)</span> into its normal and geodesic parts: <span class=\"math display\">\\begin{equation}\n    \\kappa_n = \\frac{\\kappa_g}{r}\\sin^2\\beta = \\frac{\\kappa_g}{r\\,(1+u_\\sigma^2)}, \\qquad \\kappa_g^{\\mathscr C} = \\frac{1+u_\\sigma^2-u_{\\sigma\\sigma}}{r\\,(1+u_\\sigma^2)^{3/2}},\n\\tag{64}\\end{equation}</span> where <span class=\"math inline\">\\(\\beta\\)</span> is the angle between the trajectory and the generator. The normal part is controlled by the curvature of the surface, <span class=\"math inline\">\\(\\abs{\\kappa_n}\\le\\abs{\\kappa_g}/r\\)</span>, and is entirely due to the bending of the spherical eight; the geodesic part is the curvature of the planar polar curve <span class=\"math inline\">\\(\\sigma\\mapsto r(\\sigma)\\)</span> obtained by unrolling the cone, and is due to the variation of <span class=\"math inline\">\\(r=\\norm{\\vb r}\\)</span> along the cycle. The surface therefore bounds <span class=\"math inline\">\\(\\kappa\\)</span> from below only, by <span class=\"math inline\">\\(\\abs{\\kappa_n}\\)</span>; this lower bound vanishes at the inflection points of the eight, where <span class=\"math inline\">\\(\\kappa_g=0\\)</span>, and it gives no upper bound.</p>\n<p>For <span class=\"math inline\">\\(a=0\\)</span>, the trajectory lies on the sphere of radius <span class=\"math inline\">\\(\\ell\\)</span>, the unrolled curve is a circle of radius <span class=\"math inline\">\\(\\ell\\)</span>, and <span class=\"math display\">\\begin{equation}\n    \\kappa = \\frac{\\sqrt{1+\\kappa_g^2}}{\\ell} \\ \\ge\\ \\frac1\\ell,\n\\tag{65}\\end{equation}</span> with equality at the inflection points of the eight, which exist on each lobe. In particular, the floor <span class=\"math inline\">\\(1/\\ell\\)</span> is a property of the trajectory in the cone, not of the cone. Large curvature is produced where the spherical eight turns sharply, <em>i.e.</em> where <span class=\"math inline\">\\(v\\)</span> is small compared with the bending of the eight: at the lobe tips <span class=\"math inline\">\\(\\tau=\\pi/2,3\\pi/2\\)</span> for a wide eight (<span class=\"math inline\">\\(\\Delta\\theta\\)</span> small compared with <span class=\"math inline\">\\(\\Delta\\phi\\sin\\theta_0\\)</span>), and at the top and bottom <span class=\"math inline\">\\(\\tau=\\pi/4,3\\pi/4\\)</span> for a tall eight. Indeed, exactly, <span class=\"math display\">\\begin{equation}\n    \\kappa_g(\\pi/2) = \\frac{\\Delta\\phi\\sin\\theta_0}{4\\Delta\\theta^2}, \\qquad\n    \\kappa_g(3\\pi/4) = \\frac{8\\Delta\\theta}{\\Delta\\phi^2\\sin^2(\\theta_0-\\Delta\\theta)} - \\cot(\\theta_0-\\Delta\\theta),\n\\tag{66}\\end{equation}</span> so that, for <span class=\"math inline\">\\(a=0\\)</span>, <span class=\"math inline\">\\(\\max\\kappa\\to\\infty\\)</span> as <span class=\"math inline\">\\(\\Delta\\theta\\to0\\)</span> or as <span class=\"math inline\">\\(\\Delta\\phi\\to0\\)</span>, the other parameters being fixed.</p>\n<p>Consider a box of parameters: let <span class=\"math inline\">\\(\\ell\\ge\\ell_-&gt;a\\)</span>, <span class=\"math inline\">\\(\\Delta\\theta\\in[\\Delta\\theta_-,\\Delta\\theta_+]\\)</span>, <span class=\"math inline\">\\(\\Delta\\phi\\in[\\Delta\\phi_-,\\Delta\\phi_+]\\)</span> with <span class=\"math inline\">\\(\\Delta\\theta_-&gt;0\\)</span>, <span class=\"math inline\">\\(\\Delta\\phi_-&gt;0\\)</span>, and <span class=\"math inline\">\\(\\theta_0\\in[\\theta_{0-},\\theta_{0+}]\\)</span> with <span class=\"math inline\">\\(\\mathscr J = [\\theta_{0-}-\\Delta\\theta_+,\\ \\theta_{0+}+\\Delta\\theta_+]\\subset(0,\\pi)\\)</span>. Set <span class=\"math display\">\\begin{equation}\n    m = \\min_{\\mathscr J}\\sin, \\qquad M = \\max_{\\mathscr J}\\sin, \\qquad C = \\max_{\\mathscr J}\\abs{\\cos},\n\\tag{67}\\end{equation}</span> <span class=\"math display\">\\begin{equation}\n    v_* = \\begin{cases}\n        2\\Delta\\theta_- &amp; \\text{if } m\\Delta\\phi_-\\ge4\\Delta\\theta_-, \\\\[2pt]\n        m\\Delta\\phi_-\\sqrt{\\dfrac12 - \\dfrac{m^2\\Delta\\phi_-^2}{64\\,\\Delta\\theta_-^2}} &amp; \\text{otherwise,}\n    \\end{cases}\n    \\qquad\n    \\bar\\kappa_g = \\frac{2\\sqrt2\\,M\\,\\Delta\\theta_+\\Delta\\phi_+}{v_*^3} + \\frac{2C}{m}.\n\\tag{68}\\end{equation}</span> Let the arm law satisfy <span class=\"math inline\">\\(\\abs{\\alpha&#39;}\\le A_1\\)</span> and <span class=\"math inline\">\\(\\abs{\\alpha&#39;&#39;}\\le A_2\\)</span>, and set <span class=\"math display\">\\begin{equation}\n\\begin{split}\n    &amp;\\Gamma_1 = 2\\Delta\\theta_+ + \\Delta\\phi_+ + A_1, \\qquad \\Gamma_2 = \\Gamma_1^2 + 4\\Delta\\theta_+ + \\Delta\\phi_+ + A_2, \\\\\n    &amp;V_1 = 4\\Delta\\theta_+ + \\Delta\\phi_+ + \\tfrac12\\Delta\\phi_+^2 + 4\\Delta\\theta_+\\Delta\\phi_+, \\qquad\n    U = \\varepsilon'\\,\\frac{\\Gamma_2 + \\varepsilon'^2\\,\\Gamma_1^2}{v_*^2} + \\varepsilon'\\,\\frac{\\Gamma_1V_1}{v_*^3}.\n\\end{split}\n\\tag{69}\\end{equation}</span> Then, for all parameters in the box, every such arm law, and every <span class=\"math inline\">\\(\\tau\\)</span>, <a id=\"eq:curv-bound\"></a><span class=\"math display\">\\begin{equation}\n \\tag{70}\n    \\kappa \\le \\frac{\\sqrt{\\bar\\kappa_g^2 + (1+U)^2}}{\\ell_--a},\n\\end{equation}</span> and, without arm (<span class=\"math inline\">\\(a=0\\)</span>, <span class=\"math inline\">\\(U=0\\)</span>), <span class=\"math inline\">\\(1/\\ell\\le\\kappa\\le\\sqrt{1+\\bar\\kappa_g^2}/\\ell_-\\)</span>. Since <span class=\"math inline\">\\(U = O(\\varepsilon)\\)</span>, the bound is <span class=\"math inline\">\\(\\sqrt{1+\\bar\\kappa_g^2}/\\ell_- + O(\\varepsilon)\\)</span>, uniformly on the box. The bound degenerates only when <span class=\"math inline\">\\(\\Delta\\theta_-\\to0\\)</span>, <span class=\"math inline\">\\(\\Delta\\phi_-\\to0\\)</span>, or <span class=\"math inline\">\\(\\mathscr J\\)</span> reaches a pole, which is unavoidable by the exact tip and bottom values above; and, when <span class=\"math inline\">\\(a&gt;0\\)</span>, the bound on <span class=\"math inline\">\\(\\alpha&#39;&#39;\\)</span> cannot be dispensed with, since <span class=\"math inline\">\\(u_{\\sigma\\sigma}\\)</span>, which contains <span class=\"math inline\">\\(\\alpha&#39;&#39;\\)</span> linearly, enters <a href=\"#eq:curv-formula\">(63)</a> through <span class=\"math inline\">\\(\\abs{1+u_\\sigma^2-u_{\\sigma\\sigma}}\\)</span>. The purpose of this bound is to control the curvature of the trajectory by the bounds of the design parameters alone: in the optimization above, the lower bound on <span class=\"math inline\">\\(\\ell\\)</span> and the bounds on <span class=\"math inline\">\\(\\Delta\\varphi\\)</span> of Table <a href=\"#tab:opt_descr\">3</a> play the role of <span class=\"math inline\">\\(\\ell_-\\)</span> and <span class=\"math inline\">\\(\\Delta\\phi_\\pm\\)</span>, with <span class=\"math inline\">\\(\\Delta\\theta_\\pm = \\Delta\\theta\\)</span> and <span class=\"math inline\">\\(\\theta_{0\\pm} = \\theta_0\\)</span> fixed. Without arm, this gives a bound valid for every design of the box. With the arm, the bound also involves the bounds <span class=\"math inline\">\\(A_1\\)</span> and <span class=\"math inline\">\\(A_2\\)</span> on the arm law, which are not design parameters but properties of the periodic orbit: they are evaluated on the computed orbit, which makes the bound an a posteriori check rather than an a priori estimate. On the optimized cycle, <span class=\"math inline\">\\(A_1 = 1.01\\)</span> and <span class=\"math inline\">\\(A_2 = 1.33\\)</span>, and the smallest radius of curvature computed along the cycle, arm included, is 1.72 m. Evaluated on the whole box of Table <a href=\"#tab:opt_descr\">3</a>, the bound <a href=\"#eq:curv-bound\">(70)</a> only guarantees a radius of 8.3 mm: it holds, but it is far from sharp, as the box contains narrow eights (<span class=\"math inline\">\\(\\Delta\\phi_- = 10^\\circ\\)</span>) for which <span class=\"math inline\">\\(v_*\\)</span> is small and the bound, of order <span class=\"math inline\">\\(1/v_*^3\\)</span>, is large. Evaluated at the optimized design itself (<span class=\"math inline\">\\(\\ell_- = \\ell\\)</span>, <span class=\"math inline\">\\(\\Delta\\phi_\\pm = \\Delta\\phi\\)</span>), it guarantees 0.58 m.</p>\n<p>With <span class=\"math inline\">\\(K = \\sqrt{1+\\kappa_g^2}\\)</span>, for a fixed eight and a fixed arm law with bounded <span class=\"math inline\">\\(\\alpha&#39;,\\alpha&#39;&#39;\\)</span>, <a id=\"eq:curv-first-order\"></a><span class=\"math display\">\\begin{equation}\n \\tag{71}\n    \\ell\\,\\kappa = K\\,(1-\\varepsilon g) - \\varepsilon\\,\\frac{g_{\\sigma\\sigma}}{K} + O(\\varepsilon^2)\n\\end{equation}</span> uniformly in <span class=\"math inline\">\\(\\tau\\)</span>: the arm rescales the arm-free curvature by <span class=\"math inline\">\\(\\ell/r\\)</span> and adds the contribution of the second derivative of <span class=\"math inline\">\\(g\\)</span> (hence of <span class=\"math inline\">\\(\\alpha&#39;&#39;\\)</span>) along the eight.</p>\n<p>For the optimized eight of Table <a href=\"#tab:opt_results\">4</a> (<span class=\"math inline\">\\(\\Delta\\theta=6.0^\\circ\\)</span>, <span class=\"math inline\">\\(\\Delta\\phi=16.6^\\circ\\)</span>, <span class=\"math inline\">\\(\\theta_0=65.0^\\circ\\)</span>), the exact value above gives <span class=\"math inline\">\\(\\kappa_g(\\pi/2)\\simeq5.99\\)</span>, hence <span class=\"math inline\">\\(\\ell\\kappa(\\pi/2) = \\sqrt{1+\\kappa_g(\\pi/2)^2} \\simeq 6.07\\)</span> at the lobe tips for <span class=\"math inline\">\\(a=0\\)</span>. This value at the tip is exact: it follows from the formulas above, with no approximation. The tips are not necessarily where the turn is sharpest: sampling <span class=\"math inline\">\\(\\tau\\)</span> on a fine grid gives <span class=\"math inline\">\\(\\max_\\tau\\ell\\kappa\\simeq16.77\\)</span>, reached at <span class=\"math inline\">\\(\\tau\\simeq2.200\\)</span> and, by symmetry, at <span class=\"math inline\">\\(\\tau+\\pi\\)</span>; the smallest radius of curvature of the trajectory is thus about <span class=\"math inline\">\\(\\ell/16.77\\)</span>, <em>i.e.</em> about 1.6 m for the optimized length <span class=\"math inline\">\\(\\ell=27.0\\,\\mathrm{m}\\)</span>. For <span class=\"math inline\">\\(a&gt;0\\)</span>, see the a posteriori check above.</p>\n<table id=\"tab:parameter_comparison\">\n<caption><strong>Table 5:</strong> Comparison of initial and optimized parameters</caption>\n<thead>\n<tr>\n<th style=\"text-align: left;\">Parameter</th>\n<th style=\"text-align: center;\">Initial guess</th>\n<th style=\"text-align: center;\">Dynamic optimization</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\ell\\)</span> (m)</td>\n<td style=\"text-align: right;\">31.0</td>\n<td style=\"text-align: right;\">26.9679</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(I\\)</span> (kg m<sup>2</sup>)</td>\n<td style=\"text-align: right;\">1300.0</td>\n<td style=\"text-align: right;\">351.628</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(b\\)</span> (N m s °<sup>−1</sup>)</td>\n<td style=\"text-align: right;\">50.4091</td>\n<td style=\"text-align: right;\">12.8643</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\Delta\\varphi\\)</span> (°)</td>\n<td style=\"text-align: right;\">50.0</td>\n<td style=\"text-align: right;\">16.6158</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Period (s)</td>\n<td style=\"text-align: right;\">2.82808</td>\n<td style=\"text-align: right;\">0.949267</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Objective <span class=\"math inline\">\\(P\\)</span> (kW)</td>\n<td style=\"text-align: right;\">9.63888</td>\n<td style=\"text-align: right;\">12.2534</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Min tension (kN)</td>\n<td style=\"text-align: right;\">3.35558</td>\n<td style=\"text-align: right;\">5.74767</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Max tension (kN)</td>\n<td style=\"text-align: right;\">8.85565</td>\n<td style=\"text-align: right;\">10.8269</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\">Max acceleration (m s<sup>−2</sup>)</td>\n<td style=\"text-align: right;\">517.084</td>\n<td style=\"text-align: right;\">938.602</td>\n</tr>\n</tbody>\n</table>\n\n<details class=\"web-code\"><summary>Code that produced this table</summary>\n\nsrc/optimization.jl (region opt_tables), see also the full file.\n\n    ## Tables\n    table_descr, table_opt = latex_tables(p_start, p_ref, lower, upper)\n    push!(files, write_table(\"table2\", table_descr), write_table(\"table3\", table_opt))\n    @warn \"table4: values to be checked vs. Alain's computation\"\n    push!(files, write_table(\"table4\", comparison_table(p_start, p_ref)))\n    push!(files, write_table(\"numbers\", numbers_tex(; p_start, p_ref, opt_iter=opt_ref.iter, winds, sweep, dtheta, dtheta_opt, dtheta_lost)))\n\n</details>\n\n<figure id=\"fig:opt-dtheta\" data-latex-placement=\"thpb\">\n<img src=\"figs/optimization_dtheta.png\" />\n<figcaption><strong>Figure 14:</strong> Average power (left, normalized by its value <span class=\"math inline\">\\(P^*\\)</span> at the nominal <span class=\"math inline\">\\(\\Delta\\theta=6.0^\\circ\\)</span>) and min–max line tension (right) as <span class=\"math inline\">\\(\\Delta\\theta\\)</span> varies, with <span class=\"math inline\">\\(\\Theta\\)</span> held at the optimum (points) and re-optimized at each angle (line with triangles, shaded envelope). <span class=\"math inline\">\\(\\Theta\\)</span> is re-optimized by continuation from the nominal angle, in warm-started steps of at most 0.5 °; the continuation reaches the whole range, and the re-optimized power peaks, among the sampled angles, at <span class=\"math inline\">\\(4.0^\\circ\\)</span>, 4.2 % above its nominal value. With <span class=\"math inline\">\\(\\Theta\\)</span> held, the power peaks at the nominal angle and loses 94 % at <span class=\"math inline\">\\(20^\\circ\\)</span>; re-optimized, it decreases steadily above the nominal angle and loses 32.5 % at <span class=\"math inline\">\\(20^\\circ\\)</span>.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/optimization.jl (region opt_dtheta), see also the full file.\n\n    dtheta_angles = collect(range(DTHETA_RANGE..., length=fast ? 3 : 10))\n    @info \"opt: Δθ sweep with Θ fixed, $(length(dtheta_angles)) angles\"\n    dtheta = dtheta_study(p_ref, dtheta_angles)\n\n    dsweep = dtheta_opt_sweep(p_ref, SYMS, dtheta_angles, lower, upper;\n        nominal=rad2deg(p_ref.Δθ), iters=it_dtheta, step=fast ? 3.0 : DTHETA_STEP)\n    dtheta_opt, dtheta_lost = dsweep.stats, dsweep.lost_below\n\nsrc/optimization.jl (region fig_dtheta), see also the full file.\n\n    fig_dtheta = plot_dtheta(dtheta, dtheta_opt, GUIDES, rad2deg(p_ref.Δθ))\n    append!(files, save_figure(fig_dtheta, \"optimization_dtheta\"))\n\n</details>\n\n<figure id=\"fig:opt-landscape\" data-latex-placement=\"thpb\">\n<img src=\"figs/optimization_landscape.png\" />\n<figcaption><strong>Figure 15:</strong> Average power as the optimization parameters vary. Along these one-dimensional slices, the objective is smooth around the optimum; this does not exclude other local optima.</figcaption>\n</figure>\n\n<details class=\"web-code\"><summary>Code that produced this figure</summary>\n\nsrc/optimization.jl (region opt_landscape), see also the full file.\n\n    LANDSCAPE = landscape(p_ref, SYMS; lower, upper, npoints=fast ? 5 : 21)\n\nsrc/optimization.jl (region fig_landscape), see also the full file.\n\n    fig_land = plot_landscape(LANDSCAPE, GUIDES)\n    append!(files, save_figure(fig_land, \"optimization_landscape\"))\n\n</details>"},{"title":"src/analysis.jl","page":"src/analysis.jl","location":"code/src-analysis-jl.html#src/analysis.jl","category":"section","text":"View on GitHub (commit 2cfaacd).\n\n# Section 2 figures and Table 1: equilibria, one simulation and the convergence of\n# the two limit cycles of the 4D point-mass model, plus the parameter table.\n#\n# Outputs: figs/{equilibria_phase_space,equilibria_eight_circle,time_series_4D,\n# limit_cycle_convergence,yz_limit_cycles}.{pdf,png} and tables/table1.tex.\n#\n# Not part of the paper build (kept in applications/jtcam/Section_Numerical_analysis.jl):\n# the eigenvalue and equilibrium-trajectory figures, the Floquet check of the\n# convergence slopes and the limit-cycle inventory (deflated shooting vs\n# quasi-Monte-Carlo), which print diagnostics only.\nusing KEEP: PointMass4 as PM4\nusing KEEP: PointMassPara as PMP\nusing KEEP: SteadyState\nusing KEEP: Visualization as VIZ\nusing KEEP: LimitCycle as LC\nusing KEEP: DEFAULT_TOLERANCE, TAU0\n\nusing Plots\nusing LinearAlgebra: norm, eigvals, eigen, ⋅\nimport ForwardDiff\nusing SplitApplyCombine: invert\nusing QuasiMonteCarlo: sample, HaltonSample\nusing PyFormattedStrings: @f_str\nusing Roots\nconst SA = PM4.SA  # StaticArrays, through KEEP\n\ninclude(joinpath(@__DIR__, \"helpers.jl\"))\n\n## Parameter table for the paper\n# LaTeX table of the parameter set used here, sorted alphabetically by symbol.\n# b is the optimized PTO slope (kinetic criterion); angles are in degrees\n# and b per degree, so b·dα is a torque when dα is read in deg/s.\n\nstruct Parameter\n    key::Symbol\n    sym::String\n    descr::String\n    unit::String\n    value_override::Union{String,Nothing}\nend\n\nconst LATEX_TO_UNICODE = Dict(\n    raw\"\\ell\" => \"l\",\n    raw\"\\rho\" => \"ρ\",\n    raw\"\\theta\" => \"θ\",\n    raw\"\\Delta\" => \"Δ\",\n    raw\"\\phi\" => \"φ\"\n)\n\nfunction eor_transform(sym)\n    s = sym\n    for (k, v) in LATEX_TO_UNICODE\n        s = replace(s, k => v)\n    end\n    s = replace(s, raw\"_\" => \"\", raw\"{\" => \"\", raw\"}\" => \"\", raw\"\\\\\" => \"\")\n    return lowercase(s)\nend\n\n#region param_table\nfunction param_table(p)\n    # symbol, description, unit, optional value override\n    params = [\n        Parameter(:a, \"a\", \"Arm length\", raw\"\\meter\", nothing),\n        Parameter(:l, raw\"\\ell\", \"Line length\", raw\"\\meter\", nothing),\n        Parameter(:m, \"m\", \"Kite mass\", raw\"\\kg\", nothing),\n        Parameter(:I, \"I\", \"Arm inertia\", raw\"\\kg\\square\\meter\", nothing),\n        Parameter(:ρ_a, raw\"\\rho_a\", \"Air density\", raw\"\\kg\\per\\cubic\\meter\", nothing),\n        Parameter(:d_l, raw\"d_\\ell\", \"Line diameter\", raw\"\\meter\", nothing),\n        Parameter(:S, \"S\", \"Kite surface\", raw\"\\square\\meter\", nothing),\n        Parameter(:C_L, \"C_L\", \"Kite lift coefficient\", \"\", nothing),\n        Parameter(:C_D, \"C_D\", \"Kite drag coefficient\", \"\", \"C_L / 7\"),\n        Parameter(:C_D_l, raw\"C_{D,\\ell}\", \"Line drag coefficient\", \"\", nothing),\n        Parameter(:ρ_l, raw\"\\rho_\\ell\", \"Line density\", raw\"\\kg\\per\\cubic\\meter\", nothing),\n        Parameter(:g, \"g\", \"Gravity\", raw\"\\meter\\per\\square\\second\", nothing),\n        Parameter(:z0, \"z_0\", \"Wind reference altitude\", raw\"\\meter\", nothing),\n        Parameter(:w0, \"w_0\", \"Wind reference speed\", raw\"\\meter\\per\\second\", nothing),\n        Parameter(:b, \"b\", \"Arm braking coefficient\",\n            raw\"\\newton\\meter\\second\\per\\degree\", f\"{p.b / rad2deg(1):.4g}\"),  # 4 digits: fixed point b = I ω\n        Parameter(:θ0, raw\"\\theta_0\", \"Lemniscate mean polar angle\",\n            raw\"\\degree\", f\"{rad2deg(p.θ0):.0f}\"),\n        Parameter(:Δθ, raw\"\\Delta\\theta\", \"Lemniscate polar half-height\",\n            raw\"\\degree\", f\"{rad2deg(p.Δθ):.0f}\"),\n        Parameter(:Δφ, raw\"\\Delta\\phi\", \"Lemniscate azimuthal half-width\",\n            raw\"\\degree\", f\"{rad2deg(p.Δφ):.0f}\"),\n    ]\n\n    sort!(params, by=x -> eor_transform(x.sym))\n    table_rows = map(params) do p_item\n        val = isnothing(p_item.value_override) ? f\"{p[p_item.key]:.9g}\" : p_item.value_override\n        unit_col = isempty(p_item.unit) ? \"\" : raw\"\\si{\" * p_item.unit * \"}\"\n        f\"    ${p_item.sym}$ & {p_item.descr} & ${val}$ & {unit_col} \\\\\\\\ \"\n    end\n\n\n    table_str = raw\"\"\"\n\\begin{table}[thpb]\n\\centering\n\\caption{Parameter Description and Values}\n\\label{tab:params}\n\\begin{tabular}{l p{3.2cm} r l}\n    \\toprule\n    {Symbol} & {Description} & {Value} & {Unit} \\\\\n    \\midrule\n\"\"\" * join(table_rows, \"\\n\") * raw\"\"\"\n\n    \\bottomrule\n\\end{tabular}\n\\end{table}\"\"\"\n    return table_str\nend\n#endregion\n\n\n\"\"\"\nPort of Makie's streamplot_impl (src/basic_recipes/streamplot.jl), 2D.\n\nA visited-cell mask covers the domain; seeds are drawn at cell centers from a\nquasirandom (plastic-number) low-discrepancy sequence; from each unvisited seed\nthe NORMALIZED field is RK4-integrated with fixed `stepsize` forward and\nbackward, stopping on domain exit, on a near-zero field (equilibrium), or on\nentering any visited cell (which also terminates closed loops). Repeat until\n`density` of the cells are visited.\nSeeding and one-arrow-per-streamline follow Makie's streamplot, which steps\nexplicit Euler on the unit field; the RK4 integration here is a deliberate\ndeviation, as Euler chatters across the attracting ddτ = 0 nullcline near\nequilibria.\n\nReturns (line_x, line_y, ax, ay, au, av): NaN-separated polyline coordinates\nand seed positions / unit field directions for the arrows.\n\"\"\"\nfunction streamlines(f, xlims, ylims; gridsize=(20, 20), stepsize=0.1, maxsteps=10, density=1.0)\n    gx, gy = gridsize\n    xmin, xmax = xlims\n    ymin, ymax = ylims\n    rx, ry = LinRange(xmin, xmax, gx + 1), LinRange(ymin, ymax, gy + 1)\n    dx, dy = step(rx), step(ry)\n    mask = trues(gx, gy)  # unvisited cells\n    φ = 1.324717957244746  # plastic number\n    acoeff = (φ^-1, φ^-2)\n    # Unit field; nothing near an equilibrium (norm < 1e-12), which terminates\n    # the integration instead of dividing 0/0.\n    unit = x -> begin\n        v = f(x)\n        n = norm(v)\n        n < 1e-12 ? nothing : (v[1] / n, v[2] / n)\n    end\n    # One RK4 step of size h along (or against, d = -1) the unit field.\n    function step_rk4(x, d, h)\n        k1 = unit(x)\n        k1 === nothing && return nothing\n        k2 = unit((x[1] + d * h / 2 * k1[1], x[2] + d * h / 2 * k1[2]))\n        k2 === nothing && return nothing\n        k3 = unit((x[1] + d * h / 2 * k2[1], x[2] + d * h / 2 * k2[2]))\n        k3 === nothing && return nothing\n        k4 = unit((x[1] + d * h * k3[1], x[2] + d * h * k3[2]))\n        k4 === nothing && return nothing\n        (x[1] + d * h / 6 * (k1[1] + 2k2[1] + 2k3[1] + k4[1]),\n            x[2] + d * h / 6 * (k1[2] + 2k2[2] + 2k3[2] + k4[2]))\n    end\n    line_x, line_y = Float32[], Float32[]\n    ax, ay, au, av = Float32[], Float32[], Float32[], Float32[]\n    visited = 0\n    ind = 0\n    while visited < gx * gy * min(1.0, density)\n        cind = ind\n        ind += 1\n        ci = clamp(ceil(Int, ((0.5 + acoeff[1] * cind) % 1) * gx), 1, gx)\n        cj = clamp(ceil(Int, ((0.5 + acoeff[2] * cind) % 1) * gy), 1, gy)\n        mask[ci, cj] || continue\n        x0 = (xmin + (ci - 0.5) * dx, ymin + (cj - 0.5) * dy)\n        v0 = f(x0)\n        n0 = norm(v0)\n        push!(ax, x0[1])\n        push!(ay, x0[2])\n        push!(au, v0[1] / n0)\n        push!(av, v0[2] / n0)\n        mask[ci, cj] = false\n        visited += 1\n        for d in (-1, 1)\n            x = x0\n            ccur = (ci, cj)\n            push!(line_x, NaN)\n            push!(line_y, NaN)\n            push!(line_x, x[1])\n            push!(line_y, x[2])\n            npts = 1\n            while xmin ≤ x[1] ≤ xmax && ymin ≤ x[2] ≤ ymax && npts < maxsteps\n                x = step_rk4(x, d, stepsize)\n                x === nothing && break\n                (xmin ≤ x[1] ≤ xmax && ymin ≤ x[2] ≤ ymax) || break\n                idx = (clamp(searchsortedlast(rx, x[1]), 1, gx), clamp(searchsortedlast(ry, x[2]), 1, gy))\n                if idx != ccur\n                    mask[idx...] || break\n                    mask[idx...] = false\n                    visited += 1\n                    ccur = idx\n                end\n                push!(line_x, x[1])\n                push!(line_y, x[2])\n                npts += 1\n            end\n        end\n    end\n    return (line_x, line_y, ax, ay, au, av)\nend\n\n## Convergence rate of the two cycles (helpers)\nconst LC_CONV_TOL = 1e-13\nconst EQ_SEEDS = 100      # initial values of τ per fold curve for SteadyState.all_steady_states\nconst DTAU_INIT = 1.0     # |dτ(0)| (rad/s) of the initial states x0± (KEEP's LC.compute_limit_cycle default)\nconst TS_DURATION = 10    # duration (s) of the time series of fig:timeseries\nconst CB = LC.build_poincare_callback(eps(1.0))\n\nfunction get_slope(distances; tol_start, tol_end)\n    i1 = findfirst(<(tol_start), distances)\n    i2 = findlast(>(tol_end), distances)\n    return -(log10(distances[i2]) - log10(distances[i1])) / (i2 - i1)\nend\n\nfunction plot_convergence_panel(p, dτ, color; tf=50, ntrace=5, legend=true, tol=LC_CONV_TOL)\n    sol = PM4.integrate(PM4.build_u(; dτ), tf, p; callback=CB, save_end=false, tol)\n    u_infty = sol.u[end]\n    n_max = 11\n    distances = [LC.distance_on_section(u, u_infty) for u in sol.u[1:(end-1)]][1:min(end, n_max-1)]\n\n    tol_start, tol_end = 1e-2, 10tol\n    slope = get_slope(distances; tol_start, tol_end)\n    i1 = findfirst(<(tol_start), distances)\n\n    plt = plot(; yscale=:log10, xlim=(0, n_max), xticks=0:2:100,\n        ylim=(1e-16, 1e2), yticks=10.0 .^ (0:-3:-16),\n        xlabel=f\"\"\"Lemniscate revolutions, D(τ) {dτ>0 ? \">\" : \"<\"} 0\"\"\",\n    )\n\n    perturbed_params = (; ls=:dot, lw=2, alpha=0.4, c=:gray, label=\"Perturbed trajectories\")\n    plot!(i -> distances[i1] * exp10(-slope * (i - i1)); c=:black)\n    if ntrace > 0\n        for (α, τ) in eachcol(sample(ntrace, Float64[-π, -π], Float64[π, π], HaltonSample()))\n            s = PM4.integrate(PM4.build_u(; α, τ, dτ), tf, p; callback=CB, save_end=false, tol)\n            plot!([LC.distance_on_section(u, u_infty) for u in s.u] .+ 1e-16;\n                perturbed_params..., label=\"\")\n        end\n    end\n\n    annotate!((5, 1e-11, (f\"slope = {slope:.2f}\", :right, ANNOTATIONFONTSIZE, colorant\"black\")))\n    distance_style = (; c=color, ls=:dot, marker=:circle)\n    plot!(distances .+ 1e-16; distance_style...)\n\n    if legend\n        plot!([NaN]; distance_style..., label=raw\"$|| x_i - x_\\infty  ||$\")\n        ntrace > 0 && plot!([NaN]; perturbed_params...)\n    end\n    return (; plt, slope)\nend\n\n## Spectra of the equilibria and Floquet multipliers of the cycles (numbers of the text)\n\n\"Jacobian of the 4D vector field f(x) = (dq, ddq) at the state `x`.\"\nstate_jacobian(x, vbp) = ForwardDiff.jacobian(\n    y -> PM4.dynamics(PM4.build_u(y[1], y[2], y[3], y[4], zero(y[1])), vbp, 0)[1:4], collect(x))\n\n\"Monodromy matrix of the cycle `lc`: derivative of the time-T flow at its initial state.\"\nfunction monodromy(lc, vbp; tol=DEFAULT_TOLERANCE)\n    T = lc.t[end]\n    flow = y -> PM4.integrate(PM4.build_u(y[1], y[2], y[3], y[4], zero(y[1])), T, vbp; tol).u[end][1:4]\n    return ForwardDiff.jacobian(flow, collect(lc.u[1][1:4]))\nend\n\nfmt_complex(z) = abs(imag(z)) < 1e-8 ? f\"{real(z):.2f}\" :\n    f\"{real(z):.2f} \\\\pm {abs(imag(z)):.2f}\\\\,i\"\n\n\"\"\"\nSpectra of the equilibria, grouped by σ-pairs (σ(α, τ) = (-α, τ + π) conjugates the\nvector field, so both members of a pair have the same spectrum). The vector field is in\nregular form (`PM4._accelerations_tension`, no division by the lever arm of the lines),\nso its AD Jacobian is exact to rounding on the fold curves, where the equilibria lie:\nboth members of each pair are computed and required to agree.\nReturns a vector of named tuples, one per pair, sorted by arm side then zone.\n\"\"\"\nfunction equilibrium_spectra(ss, vbp; is_down, is_center)\n    spec = [eigvals(state_jacobian((q[1], q[2], 0.0, 0.0), vbp)) for q in ss]\n    all(s -> all(isfinite, s), spec) || error(\"non-finite Jacobian at an equilibrium\")\n    pairs = []\n    used = falses(length(ss))\n    for i in eachindex(ss)\n        used[i] && continue\n        qi = ss[i]\n        j = findfirst(k -> !used[k] && k != i &&\n            abs(rem2pi(ss[k][1] + qi[1], RoundNearest)) < 1e-6 &&\n            abs(rem2pi(ss[k][2] - qi[2] - π, RoundNearest)) < 1e-6, eachindex(ss))\n        j === nothing && error(\"equilibrium $(rad2deg.(qi)) deg has no σ-twin\")\n        used[i] = used[j] = true\n        d = maximum(abs, sort(spec[i]; by=reim) - sort(spec[j]; by=reim))\n        d < 1e-6 || @warn \"σ-twins with different spectra\" rad2deg.(qi) d\n        # representative with τ in [0, π), as in the figures' description\n        r = rem2pi(ss[i][2], RoundDown) < π ? i : j\n        λ = sort(spec[r]; by=z -> (real(z), imag(z)))\n        # weight of the arm (α, dα) in the unstable eigenvectors: the text says they\n        # move the kite along the eight, the arm staying at rest to first order\n        E = eigen(state_jacobian((ss[r][1], ss[r][2], 0.0, 0.0), vbp))\n        armw(k) = (v = E.vectors[:, k]; max(abs(v[1]), abs(v[3])) / maximum(abs, v))\n        iun = findall(z -> real(z) > 0, E.values)\n        kdom = iun[argmax(real.(E.values[iun]))]\n        arm = armw(kdom)                                    # dominant unstable mode\n        others = setdiff(iun, findall(==(E.values[kdom]), E.values), findall(==(conj(E.values[kdom])), E.values))\n        armslow = isempty(others) ? NaN : minimum(armw, others)  # extra slow unstable mode (upwind)\n        push!(pairs, (; q=ss[r], down=is_down(ss[r]), center=is_center(ss[r]), λ,\n            nunstable=count(z -> real(z) > 0, λ), remax=maximum(real, λ), arm, armslow))\n    end\n    sort!(pairs; by=p -> (!p.down, !p.center))\n    return pairs\nend\n\n\"\"\"\nEquilibria as roots of one scalar function per fold curve. At rest on the fold\nα = φ(τ) + s (s = 0: downwind arm, s = π: upwind arm) the lever arm of the lines vanishes,\nso α̈ = 0 identically, and the equilibria are the zeros of g_s(τ) = τ̈(φ(τ) + s, τ, 0, 0).\nThey are bracketed by the sign changes of g_s on a grid of `n` values of τ, then refined.\nReturns the roots as [α, τ] (angles in (-π, π]).\n\"\"\"\nfunction fold_roots(vbp; n=3600)\n    roots = Vector{Float64}[]\n    for s in (0.0, π)\n        q(τ) = (PM4.τ_to_θφ(τ, vbp)[2] + s, τ)\n        g(τ) = PM4.dynamics(SA[q(τ)..., 0.0, 0.0, 0.0], vbp)[4]\n        τs = range(0, 2π, n + 1)\n        gs = g.(τs)\n        for i in 1:n\n            sign(gs[i]) != sign(gs[i+1]) || continue\n            τ0 = find_zero(g, (τs[i], τs[i+1]))\n            push!(roots, rem2pi.(collect(q(τ0)), RoundNearest))\n        end\n    end\n    return roots\nend\n\n\"\"\"\nPendulum model of the arm at the equilibrium `q` (on a fold curve): the kite frozen and\nthe tension F_ℓ held at its value at rest, the arm equation linearized in δα reads\nI δα̈ + b δα̇ = k δα with k = a F_ℓ ∂λ/∂α = -a F_ℓ (r/ℓ) sinθ cos(φ - α): k > 0 for an\nupwind arm (inverted pendulum), k < 0 for a downwind arm. Returns the largest real root `s` of I s² + b s - k = 0, and the relative\ngap `rel` to the closest real eigenvalue of the Jacobian of the full system.\n\"\"\"\nfunction pendulum_rate(q, vbp, p)\n    k = PM4._kinematics(q[1], q[2], vbp)\n    F = PM4.compute_line_tension(SA[q[1], q[2], 0.0, 0.0], vbp)\n    stiff = -k.A * F * (k.R / k.ELL) * sin(k.θ) * cos(k.φ - q[1])\n    s = (-p.b + sqrt(p.b^2 + 4p.I * stiff)) / (2p.I)\n    λ = eigvals(state_jacobian((q[1], q[2], 0.0, 0.0), vbp))\n    real_λ = real.(filter(z -> abs(imag(z)) < 1e-10, λ))\n    μ = real_λ[argmin(abs.(real_λ .- s))]\n    return (; s, μ, rel=abs(s - μ) / abs(μ), upwind=cos(q[1]) < 0)\nend\n\n\"\"\"\nLower bound, over an `n`×`n` grid of the torus of configurations, of the ratio between\nthe tangential part (on the plane of the cone) of F_a + F_g at rest and its norm. Off the\nfold curves, slack lines at rest require this tangential part to vanish (projections of\nNewton's law for the kite on r̂ and r̂'), so a positive minimum excludes equilibria with\nslack lines.\n\"\"\"\nfunction slack_ratio(vbp; n=721)\n    minimum(Iterators.product(range(-π, π, n), range(0, 2π, n))) do (α, τ)\n        k = PM4._kinematics(α, τ, vbp)\n        F_a, F_g, _, _ = PM4._forces(k, SA[0.0, 0.0], vbp)\n        F = F_a + F_g\n        sqrt((F ⋅ k.rhat)^2 + (F ⋅ k.rhatp)^2 / k.nrhatp2) / norm(F)\n    end\nend\n\n\"\"\"\nEnergy balance of the cycle `lc` over one lap, by time averages on `n` points. Gravity does\nno net work over a lap, so the generator power equals the power of the aerodynamic force,\nF_a⋅ṙ = F_a⋅w - F_a⋅w_a: the power taken from the wind (`capture`) minus the power\ndissipated by the drag (`loss`). Also the mean speed of the kite, over the lap (`V`) and\nnear the tips of the eight (`Vtip`, |τ| in [π/4, 3π/4] mod 2π, around τ = ±π/2), and\nthe relative closure error of the balance (`err`).\n\"\"\"\nfunction energy_balance(lc, vbp; n=4000)\n    L, _, T = PM4.lmt(vbp)\n    rows = map(range(0, lc.t[end], n + 1)[1:end-1]) do t\n        u = lc(t)\n        dq = SA[u[3], u[4]]\n        k = PM4._kinematics(u[1], u[2], vbp)\n        F_a, _, torque, Rdot = PM4._forces(k, dq, vbp)\n        v = Rdot * k.rhat + k.R * u[4] * k.rhatp\n        z = k.R * k.rhat[3]\n        w = SA[abs(z / (vbp.z0 * L))^(1 / vbp.n_wind), 0, 0] * L / T   # as in PM4._forces\n        τ = abs(rem2pi(u[2], RoundNearest))                            # in [0, π]\n        (; capture=F_a ⋅ w, loss=F_a ⋅ (w - v), gen=torque * u[3], V=norm(v), tip=π / 4 <= τ <= 3π / 4)\n    end\n    m(f, r=rows) = sum(f, r) / length(r)\n    tips = filter(r -> r.tip, rows)\n    capture, loss, gen = m(r -> r.capture), m(r -> r.loss), m(r -> r.gen)\n    return (; capture, loss, gen, V=m(r -> r.V), Vtip=m(r -> r.V, tips),\n        err=abs(capture - loss - gen) / gen)\nend\n\n\"\"\"\nGap between the cycle `lc` and its image by σ shifted by the time `th` at which τ has\nmoved by ±π (max over the cycle, angles mod 2π); returns (; gap, half = th / T).\n\"\"\"\nfunction sigma_gap(lc; n=200)\n    σ(u) = (-u[1], u[2] + π, -u[3], u[4])\n    T, u0 = lc.t[end], lc.u[1]\n    th = find_zero(t -> lc(t)[2] - (u0[2] + sign(u0[4]) * π), (0.0, T))\n    gap = maximum(range(0, T, n)) do t\n        y, z = σ(lc(t)), lc(mod(t + th, T))\n        maximum(abs, (rem2pi(y[1] - z[1], RoundNearest), rem2pi(y[2] - z[2], RoundNearest),\n            y[3] - z[3], y[4] - z[4]))\n    end\n    return (; gap, half=th / T)\nend\n\nfunction equilibria_table(pairs)\n    rows = map(pairs) do p\n        λs = String[]\n        λ = p.λ\n        k = 1\n        while k <= length(λ)  # a complex pair once, with ±\n            push!(λs, fmt_complex(λ[k]))\n            k += abs(imag(λ[k])) < 1e-8 ? 1 : 2\n        end\n        arm, zone = p.down ? \"downwind\" : \"upwind\", p.center ? \"centre\" : \"tip\"\n        α, τ = rad2deg(p.q[1]), rad2deg(rem2pi(p.q[2], RoundDown))\n        ev = join(λs, raw\",\\ \")\n        \"    $arm & $zone & \\$($(f\"{α:.1f}\"), $(f\"{τ:.1f}\"))\\$ & \\$$ev\\$ & $(p.nunstable) \\\\\\\\\"\n    end\n    return raw\"\"\"\n\\begin{table}[thpb]\n\\centering\n\\caption{Equilibria of the system for the parameters of Table~\\ref{tab:params}, by pairs exchanged by the symmetry~\\eqref{eq:symmetry}: one representative \\((\\alpha, \\tau)\\) of each pair (in degrees, \\(0 \\leq \\tau < 180\\)), eigenvalues of the Jacobian of \\(f\\) (in \\si{\\per\\second}) and number of eigenvalues with positive real part.}\n\\label{tab:equilibria}\n\\begin{tabular}{l l c l c}\n    \\toprule\n    {Arm} & {Kite} & {\\((\\alpha, \\tau)\\)} & {Eigenvalues} & {Unstable} \\\\\n    \\midrule\n\"\"\" * join(rows, \"\\n\") * raw\"\"\"\n\n    \\bottomrule\n\\end{tabular}\n\\end{table}\"\"\"\nend\n\nfunction run_analysis(; fast::Bool=false)\n    #region setup_analysis\n    ## Determine optimal parameters using kinetic model\n    p0 = PMP.build_para()\n    p0.b = PMP.optimal_torque_slope(p0; sense=(+), tol=1e-9, rtol=1e-9, maxiter=50)  # errors if not converged\n    vbp = PMP.build_vbpara(p0)\n    #endregion\n\n    #region table1\n    write_table(\"table1\", param_table(p0))\n    #endregion\n    files = String[]\n\n    #region equilibria_style\n    #! format: off\n    my_theme = (;\n        downwind        = (; c=plot_color(:grey, 0.08)),\n        upwind          = (; c=plot_color(:red, 0.08)),\n        streamlines     = (; c=:black, alpha=0.7, lw=default(:lw) / 6),\n        heads           = (; c=:black, alpha=0.5, lw=0),\n        nullcline_tau   = (; c=1, ls=:solid),\n        nullcline_alpha = (; c=2, ls=:solid),\n        eq_legend       = (; c=:black, shape=:circle, ms=default(:ms), msw=20),\n    )\n\n    # Equilibrium characteristics: the symmetry (α, τ) -> (-α, τ+π) flips the kite\n    # left↔right (φ = φ0 + Δφ·sin(τ)) and preserves the arm wind region and the\n    # center/side zone, so the 8 equilibria realize all 2×2×2 combinations.\n    φkite(τ) = vbp.φ0 + vbp.Δφ * sin(τ)                     # kite azimuth (PM4.τ_to_θφ)\n    is_down(q) = cos(q[1]) > 0                              # arm downwind\n    is_left(q) = φkite(q[2]) > vbp.φ0                       # kite left of window center\n    is_center(q) = abs(φkite(q[2]) - vbp.φ0) < vbp.Δφ / 2   # closer to φ0 than to ±Δφ\n\n    \"Marker style from the equilibrium characteristics: fill = arm wind, shape = zone, stroke = kite side.\"\n    ss_style(q) = (\n        c = is_down(q) ? :white : :black,\n        markerstrokecolor = is_down(q) ? :black : :white,\n        shape = is_center(q) ? :circle : :diamond,\n        ms = default(:ms),\n        markerstrokewidth = is_down(q) ? 8 : 10,\n        # markerstrokewidth = 10,\n    )\n    #! format: on\n\n    theme = my_theme\n\n    f = q -> SteadyState.ddq_partial(q, vbp)\n    #endregion\n\n    #region equilibria_phase_space\n    # Canvas & Layout\n    δ = 0\n    plot(xlims=(-180 - δ, 180 + δ), ylims=(-180 - δ, 180 + δ), aspect_ratio=:equal,\n        xticks=([-180, 0, 180], [\"-180\", \"0\", \"180\"]),\n        yticks=([-180, 0, 180], [\"-180\", \"0\", \"180\"]),\n        xlabel=\"α (deg)\", ylabel=\"τ (deg)\",\n        grid=false, framestyle=:semi, legend=:outerright, colorbar=false)\n    # Background wind spans\n    vspan!([-180, -90]; theme.upwind..., label=\"Upwind arm\")\n    vspan!([90, 180]; theme.upwind...)\n    vspan!([-90, 90]; theme.downwind...) #, label=\"Downwind arm\")\n\n    # Streamlines & Arrowheads\n    line_x, line_y, ax, ay, au, av = streamlines(f, (-π, π), (-π, π))\n    plot!(rad2deg.(line_x), rad2deg.(line_y); theme.streamlines...)\n\n    ax, ay = rad2deg.(ax), rad2deg.(ay)\n    L, W = rad2deg(0.2), rad2deg(0.06)\n    heads = [Shape([(s[1] + L / 2 * u, s[2] + L / 2 * v),\n        (s[1] - L / 2 * u - W * v, s[2] - L / 2 * v + W * u),\n        (s[1] - L / 2 * u + W * v, s[2] - L / 2 * v - W * u)])\n             for (s, u, v) in zip(zip(ax, ay), au, av)]\n    plot!(heads; theme.heads...)\n\n    # Nullclines (splatting reuses line properties for both contour and the GR legend fix)\n    N = 20\n    αs = range(-π, π, N + 1)\n    τs = range(-π, π, 2N + 1)\n    dd = [f((α, τ)) for τ in τs, α in αs]\n\n    contour!(rad2deg.(αs), rad2deg.(τs), last.(dd); levels=[0], theme.nullcline_tau...)\n    contour!(rad2deg.(αs), rad2deg.(τs), first.(dd); levels=[0], theme.nullcline_alpha...)\n    plot!([NaN], [NaN]; theme.nullcline_tau..., label=\"D²(τ) = 0\")\n    plot!([NaN], [NaN]; theme.nullcline_alpha..., label=\"D²(α) = 0\")\n\n    # Equilibria\n    ss = SteadyState.all_steady_states(vbp; N=EQ_SEEDS)\n\n    styles = ss_style.(ss)\n    scatter!(rad2deg.(first.(ss)), rad2deg.(last.(ss));\n        c=getproperty.(styles, :c),\n        markerstrokecolor=getproperty.(styles, :markerstrokecolor),\n        shape=getproperty.(styles, :shape),\n        ms=getproperty.(styles, :ms),\n        markerstrokewidth=getproperty.(styles, :markerstrokewidth))\n    scatter!([NaN], [NaN]; theme.eq_legend..., label=\"Equilibrium\")\n    plot!(widen=1.06)\n    plot!(leftmargin=6Plots.mm, bottommargin=5Plots.mm, rightmargin=5Plots.mm,\n        topmargin=5Plots.mm, size=plot_size(1, 1.14))\n    append!(files, save_figure(current(), \"equilibria_phase_space\"))\n    #endregion\n\n    #region equilibria_eight_circle\n    ss_downwind = [_ss for _ss in ss if cos(_ss[1]) > 0]\n    ss_upwind = [_ss for _ss in ss if cos(_ss[1]) <= 0]\n    p_downwind = VIZ.plot_eight_circle(ss_downwind, vbp; plot_kwargs=(; color=:black, lw=2),\n        marker_kwargs=ss_style.(ss_downwind), project_eight=true)\n    plot!(title=\"Downwind arm\", background_color_subplot=theme.downwind.c)\n    p_upwind = VIZ.plot_eight_circle(ss_upwind, vbp; plot_kwargs=(; color=:black, lw=2),\n        marker_kwargs=ss_style.(ss_upwind), project_eight=true)\n    plot!(title=\"Upwind arm\", background_color_subplot=theme.upwind.c)\n\n    plot(p_downwind, p_upwind; layout=(1, 2), size=plot_size(16 / 15, 2))\n    append!(files, save_figure(current(), \"equilibria_eight_circle\"))\n    #endregion\n\n    #region time_series_4D\n    u0 = PM4.build_u(; dτ=DTAU_INIT)\n    sol = PM4.integrate(u0, TS_DURATION, vbp; save_everystep=true)\n\n    sim_4D_fig = plot_time_series(sol)\n    append!(files, save_figure(sim_4D_fig, \"time_series_4D\"))\n    #endregion\n\n    #region limit_cycle_convergence\n    (p_conv_p, slope_p) = plot_convergence_panel(vbp, +1, 1; ntrace=0, legend=false)\n    (p_conv_m, slope_m) = plot_convergence_panel(vbp, -1, 2; ntrace=0)\n    plot!(p_conv_p, leftmargin=11Plots.mm)\n    plot!(p_conv_m, leftmargin=5Plots.mm)\n    plot!(p_conv_p, ylabel=\"Distance to limit\")\n    conv_two = plot(p_conv_p, p_conv_m; layout=(1, 2), size=SIZE_FULL)\n    plot!(bottommargin=7Plots.mm)\n    append!(files, save_figure(conv_two, \"limit_cycle_convergence\"))\n    #endregion\n\n    #region yz_limit_cycles\n    r_vec = (t, sol) -> PM4.compute_OK(PM4.compute_Rτ(sol(t), sol.prob.p), sol.prob.p)\n    lc_p = LC.compute_limit_cycle(PM4.build_u(; dτ=+DTAU_INIT), vbp; save_everystep=true)\n    lc_m = LC.compute_limit_cycle(PM4.build_u(; dτ=-DTAU_INIT), vbp; save_everystep=true)\n    (lc_p === nothing || lc_m === nothing) && error(\"no limit cycle from x0±\")\n    function compute_lens(lc_p, lc_m, τ, δ_factor; idxs=2:3)\n        # τ(t) is monotone along a cycle and spans TAU0 ± 2π: find the time where\n        # the τ state hits τ mod 2π, mapped into the cycle's τ range.\n        function phase_time(sol, τ)\n            t0, t1 = sol.prob.tspan\n            lo, hi = minmax(sol(t0)[2], sol(t1)[2])\n            τ_target = clamp(τ + 2π * ceil((lo - τ) / 2π), lo, hi)\n            return find_zero(t -> sol(t)[2] - τ_target, (t0, t1))\n        end\n        yz(sol, t) = r_vec(t, sol)[idxs]\n        r_p = yz(lc_p, phase_time(lc_p, τ))\n        r_m = yz(lc_m, phase_time(lc_m, τ))\n        c = (r_p + r_m) / 2\n        δ = δ_factor * norm(r_p - r_m)\n        return c, δ\n    end\n\n    function yz_split(sol, n_splits)\n        t = range(sol.prob.tspan..., 300)\n        yz = [r_vec(t, sol)[2:3] for t in t]\n        Δt = (t[end] - t[1]) / (n_splits + 1)\n        for i in 1:n_splits\n            t_split = (i - 0.2) * Δt\n            ind = searchsortedfirst(t, t_split)\n            insert!(yz, ind + i - 1, [NaN, NaN])\n        end\n        return yz\n    end\n    n_splits = 4\n    # arrows = [permutedims(repeat([true], n_splits - 1)) false]\n    plot(aspect_ratio=:equal, xlabel=\"y (m)\", ylabel=\"z (m)\", xtick=-40:10:40, ytick=10:5:20)\n    plot!(invert(yz_split(lc_m, n_splits))..., lw=4, c=2, arrows=true)\n    plot!(invert(yz_split(lc_p, n_splits))..., lw=2, c=1, arrows=true)\n    plot!([NaN], [NaN], c=1, label=\"D(τ) > 0\")\n    plot!([NaN], [NaN], c=2, label=\"D(τ) < 0\")\n    plot!([0], [26])\n    c, δ = compute_lens(lc_p, lc_m, 2.6, 3)  # lens focus phase τ was set by hand\n    lens!([c[1] - δ, c[1] + δ], [c[2] - δ, c[2] + δ], inset=(1, bbox(0.3, 0.05, 0.3, 0.4)), lw=1.5, lc=:grey)\n    l = plot!().inset_subplots[1]\n    xticks_ = (c[1]-δ):δ:(c[1]+δ)\n    yticks_ = (c[2]-δ):δ:(c[2]+δ)\n    xticks!(l, xticks_, [f\"{t:.1f}\" for t in xticks_])\n    yticks!(l, yticks_, [f\"{t:.1f}\" for t in yticks_])\n    plot!(l, tickfontsize=TICKFONTSIZE - 1)\n    plot!(; leftmargin=5Plots.mm, bottommargin=5Plots.mm, size=plot_size(2 / 3, 1))\n    append!(files, save_figure(current(), \"yz_limit_cycles\"))\n    #endregion\n\n    ## Numbers of the text: equilibria, cycles, inventory\n    #region table5\n    pairs = equilibrium_spectra(ss, vbp; is_down, is_center)\n    push!(files, write_table(\"table5\", equilibria_table(pairs)))\n    #endregion\n    length(ss) == 8 || @warn \"the text describes 8 equilibria\" n = length(ss)\n    all(p -> p.nunstable > 0, pairs) || @warn \"the text says that all equilibria are unstable\"\n    all(p -> p.arm < 1e-2, pairs) || @warn \"the text says the dominant unstable mode of every equilibrium is along the eight\" getproperty.(pairs, :arm)\n    pend = [pendulum_rate(p.q, vbp, p0) for p in pairs]\n    all(x -> x.upwind == (x.s > 0), pend) && maximum(x -> x.rel, pend) < 0.1 ||\n        @warn \"the text says the pendulum model predicts the slow arm eigenvalue (unstable upwind, stable downwind)\" pend\n    all(p -> p.down ? isnan(p.armslow) : p.armslow > 0.5, pairs) ||\n        @warn \"the text says the extra unstable mode of the upwind equilibria is a mode of the arm\" getproperty.(pairs, :armslow)\n    pick(down, center) = only(filter(p -> p.down == down && p.center == center, pairs))\n    all(c -> pick(false, c).nunstable == pick(true, c).nunstable + 1, (true, false)) ||\n        @warn \"the text says that an upwind equilibrium has one more unstable eigenvalue than its downwind counterpart\"\n    cyc = map((lc_p, lc_m)) do lc\n        μ = eigvals(monodromy(lc, vbp))\n        itriv = argmin(abs.(μ .- 1))\n        μnt = sort(μ[setdiff(eachindex(μ), itriv)]; by=abs, rev=true)  # non-trivial multipliers\n        μn = abs(μnt[1])                                     # largest non-trivial modulus\n        (; T=lc.t[end], P=lc.u[end][end] / lc.t[end], μn, μerr=abs(μ[itriv] - 1),\n            μ1real=abs(imag(μnt[1])) < 1e-12, μpair=abs(μnt[2]),  # dominant real; then a complex pair\n            αmax=rad2deg(maximum(u -> abs(u[1]), lc.u)), dτ0=lc.u[1][4])\n    end\n    eb = energy_balance.((lc_p, lc_m), Ref(vbp))\n    all(e -> e.err < 1e-6, eb) || @warn \"energy balance of the cycles does not close\" eb\n    eb[2].V > eb[1].V && eb[2].Vtip > eb[1].Vtip && eb[2].capture > eb[1].capture && eb[2].loss > eb[1].loss ||\n        @warn \"the text says the cycle with dτ < 0 is faster (lap and tips), takes more power from the wind and loses more to drag\" eb\n    cyc[1].T > cyc[2].T && cyc[1].P > cyc[2].P ||\n        @warn \"the text says the cycle with dτ > 0 has the longer period and the larger power\" cyc\n    for (c, s) in zip(cyc, (slope_p, slope_m))\n        abs(-log10(c.μn) - s) < 0.2 || @warn \"convergence rate not close to the Floquet multiplier\" s -log10(c.μn)\n        c.αmax < 90 || @warn \"the text says |α| stays below 90 deg\" c.αmax\n        c.μ1real && c.μpair < c.μn ||\n            @warn \"the text says the dominant multiplier is real, followed by a complex pair\" c\n        s > -log10(c.μn) || @warn \"the text says the measured rate is above the Floquet rate\" s -log10(c.μn)\n    end\n    # tension at rest, exact on the fold curves (regular form)\n    ten = [(; Fl=PM4.compute_line_tension(SA[q[1], q[2], 0.0, 0.0], vbp)) for q in ss]\n    roots = fold_roots(vbp; n=fast ? 720 : 3600)\n    length(roots) == length(ss) && all(q -> any(r -> maximum(abs, rem2pi.(r - q, RoundNearest)) < 1e-6, roots), ss) ||\n        @warn \"the text says the equilibria are the roots of g± on the fold curves\" roots ss\n    slack = slack_ratio(vbp; n=fast ? 181 : 721)\n    slack > 0.1 || @warn \"the text says no equilibrium has slack lines (tangential force bounded below)\" slack\n    all(t -> t.Fl > 0, ten) || @warn \"the text says the lines are taut at the equilibria\"\n    sig = sigma_gap.((lc_p, lc_m))\n    all(g -> g.gap < 1e-7 && abs(g.half - 0.5) < 1e-7, sig) ||\n        @warn \"the text says each cycle is invariant under σ with a half-period shift\" sig\n    Fl_cyc = [[PM4.compute_line_tension(lc(t), vbp) for t in range(lc.t[1], lc.t[end], 400)] for lc in (lc_p, lc_m)]\n    all(F -> minimum(F) > 0, Fl_cyc) || @warn \"the text says the lines stay taut along the cycles\"\n    n_inv, vmax_inv = 200, 10  # α sampled in [-π, π]: σ maps Σ onto {τ = π}, not onto Σ\n    lcs = LC.all_limit_cycles(vbp; αmin=-π, αmax=π, N=n_inv, vmax=vmax_inv)\n    length(lcs) == 2 || @warn \"the text says the inventory finds the two cycles only\" n = length(lcs)\n    sci(x) = (e = floor(Int, log10(x)); f\"{x / exp10(e):.1f} \\\\times 10^{{{e}}}\")\n    expo(x) = \"10^{$(ceil(Int, log10(x)))}\"\n    # numbers quoted in the text of the analysis section (`tables/numbers.tex` belongs\n    # to the optimization section); the rates with the precision of the figure's annotations\n    push!(files, write_table(\"numbers_analysis\", join([\n        \"% Generated by main.jl (analysis section): numbers quoted in the text.\",\n        \"\\\\newcommand{\\\\ConvRatePlus}{$(f\"{slope_p:.2f}\")}\",\n        \"\\\\newcommand{\\\\ConvRateMinus}{$(f\"{slope_m:.2f}\")}\",\n        \"\\\\newcommand{\\\\ConvTol}{10^{$(round(Int, log10(LC_CONV_TOL)))}}\",\n        \"\\\\newcommand{\\\\IntTol}{10^{$(round(Int, log10(DEFAULT_TOLERANCE)))}}\",\n        \"\\\\newcommand{\\\\EqCount}{$(length(ss))}\",\n        \"\\\\newcommand{\\\\EqReCenterMin}{$(f\"{min(pick(true, true).remax, pick(false, true).remax):.1f}\")}\",\n        \"\\\\newcommand{\\\\EqReCenterMax}{$(f\"{max(pick(true, true).remax, pick(false, true).remax):.1f}\")}\",\n        \"\\\\newcommand{\\\\EqReTipMin}{$(f\"{min(pick(true, false).remax, pick(false, false).remax):.2f}\")}\",\n        \"\\\\newcommand{\\\\EqReTipMax}{$(f\"{max(pick(true, false).remax, pick(false, false).remax):.2f}\")}\",\n        \"\\\\newcommand{\\\\LcPeriodPlus}{$(f\"{cyc[1].T:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcPeriodMinus}{$(f\"{cyc[2].T:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcPowerPlus}{$(f\"{cyc[1].P / 1000:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcPowerMinus}{$(f\"{cyc[2].P / 1000:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcAlphaMaxPlus}{$(f\"{cyc[1].αmax:.0f}\")}\",\n        \"\\\\newcommand{\\\\LcAlphaMaxMinus}{$(f\"{cyc[2].αmax:.0f}\")}\",\n        \"\\\\newcommand{\\\\LcDtauPlus}{$(f\"{cyc[1].dτ0:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcDtauMinus}{$(f\"{cyc[2].dτ0:.2f}\")}\",\n        \"\\\\newcommand{\\\\FloquetPlus}{$(sci(cyc[1].μn))}\",\n        \"\\\\newcommand{\\\\FloquetMinus}{$(sci(cyc[2].μn))}\",\n        \"\\\\newcommand{\\\\FloquetRatePlus}{$(f\"{-log10(cyc[1].μn):.2f}\")}\",\n        \"\\\\newcommand{\\\\FloquetRateMinus}{$(f\"{-log10(cyc[2].μn):.2f}\")}\",\n        \"\\\\newcommand{\\\\FloquetPairRatePlus}{$(f\"{-log10(cyc[1].μpair):.2f}\")}\",\n        \"\\\\newcommand{\\\\FloquetPairRateMinus}{$(f\"{-log10(cyc[2].μpair):.2f}\")}\",\n        \"\\\\newcommand{\\\\FloquetTrivialErr}{$(expo(max(cyc[1].μerr, cyc[2].μerr)))}\",\n        \"\\\\newcommand{\\\\EqTensionMin}{$(f\"{minimum(t -> t.Fl, ten):.0f}\")}\",\n        \"\\\\newcommand{\\\\SlackRatio}{$(f\"{floor(slack, digits=2):.2f}\")}\",\n        \"\\\\newcommand{\\\\FoldGrid}{$(fast ? 720 : 3600)}\",\n        \"\\\\newcommand{\\\\SlackGrid}{$(fast ? 181 : 721)}\",\n        \"\\\\newcommand{\\\\EqTensionMax}{$(f\"{maximum(t -> t.Fl, ten):.0f}\")}\",\n        \"\\\\newcommand{\\\\SigmaGap}{$(expo(maximum(g -> g.gap, sig)))}\",\n        \"\\\\newcommand{\\\\LcTensionMinPlus}{$(f\"{minimum(Fl_cyc[1]) / 1000:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcTensionMaxPlus}{$(f\"{maximum(Fl_cyc[1]) / 1000:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcTensionMinMinus}{$(f\"{minimum(Fl_cyc[2]) / 1000:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcTensionMaxMinus}{$(f\"{maximum(Fl_cyc[2]) / 1000:.2f}\")}\",\n        \"\\\\newcommand{\\\\LcCapturePlus}{$(f\"{eb[1].capture / 1000:.1f}\")}\",\n        \"\\\\newcommand{\\\\LcCaptureMinus}{$(f\"{eb[2].capture / 1000:.1f}\")}\",\n        \"\\\\newcommand{\\\\LcLossPlus}{$(f\"{eb[1].loss / 1000:.1f}\")}\",\n        \"\\\\newcommand{\\\\LcLossMinus}{$(f\"{eb[2].loss / 1000:.1f}\")}\",\n        \"\\\\newcommand{\\\\LcSpeedPlus}{$(f\"{eb[1].V:.1f}\")}\",\n        \"\\\\newcommand{\\\\LcSpeedMinus}{$(f\"{eb[2].V:.1f}\")}\",\n        \"\\\\newcommand{\\\\LcSpeedTipPlus}{$(f\"{eb[1].Vtip:.1f}\")}\",\n        \"\\\\newcommand{\\\\LcSpeedTipMinus}{$(f\"{eb[2].Vtip:.1f}\")}\",\n        \"\\\\newcommand{\\\\EqSeeds}{$EQ_SEEDS}\",\n        \"\\\\newcommand{\\\\DtauInit}{$(f\"{DTAU_INIT:g}\")}\",\n        \"\\\\newcommand{\\\\TsDuration}{$TS_DURATION}\",\n        \"\\\\newcommand{\\\\ArmLength}{$(f\"{p0.a:g}\")}\",\n        \"\\\\newcommand{\\\\PendRelErr}{$(round(Int, ceil(100 * maximum(x -> x.rel, pend))))}\",\n        \"\\\\newcommand{\\\\InvSeeds}{$n_inv}\",\n        \"\\\\newcommand{\\\\InvVmax}{$vmax_inv}\",\n        \"\\\\newcommand{\\\\InvCount}{$(length(lcs))}\",\n    ], \"\\n\")))\n    return files\nend\n\nif abspath(PROGRAM_FILE) == @__FILE__\n    run_analysis()\nend"},{"title":"Rocking Arm Model for Kite Power Generation, KEEP project","page":"Home","location":"index.html#Rocking-Arm-Model-for-Kite-Power-Generation,-KEEP-project","category":"section","text":"Antonin Bavoil, Author 2\n\nKeywords: dynamical system, parametric optimization, limit cycle, airborne wind energy, kite, power generation\n\nThis is the web version of the paper, built from the same sources as the PDF: the text of main.tex and the results of main.jl (every figure, table and number quoted in the text). Under each figure and table, Code that produced this shows the Julia code that computed it; the code pages give the full sources and Reproducing the results the commands to rerun them.\n\nBuilt from commit 2cfaacd."},{"title":"Contents","page":"Home","location":"index.html#Contents","category":"section","text":"Introduction\n1 Mathematical model of KEEP\n2 Estimation of power take-off\n3 Analysis of the dynamics: equilibria and periodic orbits\n4 Optimization\nA 10D model\nB Explicit dynamics\nC Estimate of the eight length\nD Curvature of the kite trajectory: computations and proofs\nReferences"},{"title":"Reproducing the results","page":"Reproducing the results","location":"reproduce.html#Reproducing-the-results","category":"section","text":"Every figure (figs/*.png, figs/*.pdf), table (tables/table*.tex) and number quoted in the text (tables/numbers.tex, tables/numbers_analysis.tex) is written by main.jl. From the root of the KEEP.jl repository, at commit 2cfaacdcb1a149754d4b7e47f48fc6847394bc30:\n\ngit checkout 2cfaacdcb1a149754d4b7e47f48fc6847394bc30\njulia --project=applications/jtcam-tex -e 'import Pkg; Pkg.instantiate()'\njulia --project=applications/jtcam-tex applications/jtcam-tex/main.jl            # all sections, about 15 min\njulia --project=applications/jtcam-tex applications/jtcam-tex/main.jl analysis   # one section: modelling, 10d, analysis, optimization\n\nJulia 1.13.4 built this site. The package versions are pinned by Manifest.toml; the environment is\n\n[deps]\nBenchmarkTools = \"6e4b80f9-dd63-53aa-95a3-0cdb28fa8baf\"\nBifurcationKit = \"0f109fa4-8a5d-4b75-95aa-f515264e7665\"\nForwardDiff = \"f6369f11-7733-5829-9624-2563aa707210\"\nKEEP = \"43413fff-ad5b-4266-9485-4ac3dd215f36\"\nLiterate = \"98b081ad-f1c9-55d3-8b20-4c87d4299306\"\nOrdinaryDiffEqTsit5 = \"b1df2697-797e-41e3-8120-5422d3b24e4a\"\nOrdinaryDiffEqVerner = \"79d7bb75-1356-48c1-b8c0-6832512096c2\"\nPlots = \"91a5bcdd-55d7-5caf-9e0b-520d859cae80\"\nPyFormattedStrings = \"5f89f4a4-a228-4886-b223-c468a82ed5b9\"\nQuasiMonteCarlo = \"8a4e6c94-4038-4cdc-81c3-7e6ffdb2a71b\"\nRoots = \"f2b01f46-fcfa-551c-844a-d8ac1e96c665\"\nSplitApplyCombine = \"03a91e81-4c3e-53e1-a0a4-9c0c8f19dd66\"\n\n[sources]\nKEEP = {path = \"../..\"}\n\nThe paper itself: latexmk -pdf main.tex in applications/jtcam-tex (biber and makeglossaries needed)."},{"title":"C Estimate of the eight length","page":"C Estimate of the eight length","location":"appendix-C.html#app8","category":"section","text":"<p>Let <span class=\"math inline\">\\(D:=2\\Delta\\theta/\\Delta\\phi\\)</span>, <span class=\"math inline\">\\(s:=\\sin\\theta_0\\)</span>, <span class=\"math inline\">\\(\\alpha:=2\\Delta\\theta=D\\,\\Delta\\phi\\)</span>, <span class=\"math inline\">\\(\\beta:=\\Delta\\phi\\,s\\)</span>; recall that <span class=\"math display\">\\[L_{81}=\\int_0^{2\\pi}\\sqrt{[2\\Delta\\theta\\cos2\\tau]^2+\\sin^2(\\theta_0+\\Delta\\theta\\sin2\\tau)\\,[\\Delta\\phi\\cos\\tau]^2}\\,\\dd\\tau,\\]</span> and let <span class=\"math inline\">\\(\\widetilde L_{81}\\)</span> be the quantity obtained by replacing <span class=\"math inline\">\\(\\sin^2(\\theta_0+\\Delta\\theta\\sin2\\tau)\\)</span> by <span class=\"math inline\">\\(\\sin^2\\theta_0\\)</span>: <span class=\"math display\">\\[\\widetilde L_{81}:=\\int_0^{2\\pi}\\sqrt{\\alpha^2\\cos^22\\tau+\\beta^2\\cos^2\\tau}\\,\\dd\\tau .\\]</span> The error of this approximation is analysed as follows, with <span class=\"math inline\">\\(x:=\\Delta\\theta\\)</span> and <span class=\"math inline\">\\(E(x):=L_{81}-\\widetilde L_{81}\\)</span>. Decoupling the coefficient of <span class=\"math inline\">\\(\\cos2\\tau\\)</span> from the amplitude in the sine, put, for <span class=\"math inline\">\\(a\\in\\mathbf{R}\\)</span> and <span class=\"math inline\">\\(\\varepsilon\\)</span> small (only <span class=\"math inline\">\\(a^2\\)</span> enters, so <span class=\"math inline\">\\(\\Lambda\\)</span> is even in <span class=\"math inline\">\\(a\\)</span>), <span class=\"math display\">\\[\\Lambda(a,\\varepsilon):=\\int_0^{2\\pi}\\sqrt{a^2\\cos^22\\tau+\\Delta\\phi^2\\cos^2\\tau\\,\\sin^2(\\theta_0+\\varepsilon\\sin2\\tau)}\\,\\dd\\tau,\\]</span> so that <span class=\"math inline\">\\(L_{81}=\\Lambda(2x,x)\\)</span>, <span class=\"math inline\">\\(\\widetilde L_{81}=\\Lambda(2x,0)\\)</span> and <span class=\"math inline\">\\(E(x)=\\Lambda(2x,x)-\\Lambda(2x,0)\\)</span>. Then <span class=\"math inline\">\\(E\\)</span> is twice differentiable at <span class=\"math inline\">\\(0\\)</span>, with <span class=\"math inline\">\\(E(0)=0\\)</span> and <span class=\"math inline\">\\(E&#39;(0)=0\\)</span>, the latter because <span class=\"math inline\">\\(\\partial_\\varepsilon\\Lambda(a,0)=0\\)</span> for every <span class=\"math inline\">\\(a\\in\\mathbf{R}\\)</span> (the integrand of <span class=\"math inline\">\\(\\partial_\\varepsilon\\Lambda(a,0)\\)</span> is odd under <span class=\"math inline\">\\(\\tau\\mapsto\\pi-\\tau\\)</span> whereas the radicand is even), and <span class=\"math inline\">\\(E&#39;&#39;(0)=\\Lambda_{\\varepsilon\\varepsilon}(0,0)\\)</span>. The latter is computable in closed form because at <span class=\"math inline\">\\(a=0\\)</span> the integrand collapses to <span class=\"math inline\">\\(\\Delta\\phi\\,|\\cos\\tau|\\sin(\\theta_0+\\varepsilon\\sin2\\tau)\\)</span>, whose second derivative at <span class=\"math inline\">\\(\\varepsilon=0\\)</span> is <span class=\"math inline\">\\(-\\Delta\\phi\\,s\\,|\\cos\\tau|\\sin^22\\tau\\)</span>, whence <span class=\"math display\">\\[E&#39;&#39;(0)=-\\Delta\\phi\\,s\\int_0^{2\\pi}|\\cos\\tau|\\sin^22\\tau\\,\\dd\\tau=-\\frac{32}{15}\\,\\Delta\\phi\\,s\\ne0 .\\]</span> The Taylor–Young formula <span class=\"math inline\">\\(E(x)=\\tfrac12E&#39;&#39;(0)x^2+o(x^2)\\)</span> therefore gives <span class=\"math display\">\\[L_{81}=\\widetilde L_{81}-\\frac{16}{15}\\,\\Delta\\phi\\,s\\,\\Delta\\theta^2+o(\\Delta\\theta^2),\\]</span> and the approximation is of order exactly two. Set <span class=\"math display\">\\[C:=\\frac{\\alpha^2}{\\alpha^2+\\beta^2}=\\frac{D^2}{D^2+s^2}\\in(0,1).\\]</span> By the symmetries of the integrand, and with <span class=\"math inline\">\\(S:=\\sin^2\\tau\\)</span> (so <span class=\"math inline\">\\(\\dd S=2\\sqrt{S(1-S)}\\,\\dd\\tau\\)</span> and <span class=\"math inline\">\\(\\cos2\\tau=1-2S\\)</span>), <span class=\"math display\">\\[\\begin{gathered}\\widetilde L_{81}=4\\alpha\\int_0^1\\frac{N(S)\\,\\dd S}{w},\\qquad w^2:=S(1-S)\\,N(S),\\\\ N(S):=S^2-\\sigma S+\\varpi,\\qquad \\sigma:=\\frac{1+3C}{4C},\\qquad \\varpi:=\\frac1{4C},\\end{gathered}\\]</span> where <span class=\"math inline\">\\(N&gt;0\\)</span> on <span class=\"math inline\">\\([0,1]\\)</span>, since <span class=\"math inline\">\\(N(0)=\\varpi\\)</span> and <span class=\"math inline\">\\(N(1)=1/4\\)</span>. The curve <span class=\"math inline\">\\(w^2=S(1-S)N(S)\\)</span> is a quartic with four simple roots for <span class=\"math inline\">\\(C\\ne1/9\\)</span>, hence of genus one, and the limits <span class=\"math inline\">\\(0\\)</span> and <span class=\"math inline\">\\(1\\)</span> are two of its roots, so <span class=\"math inline\">\\(\\widetilde L_{81}\\)</span> is a complete elliptic integral. Sending the root <span class=\"math inline\">\\(S=0\\)</span> to infinity with <span class=\"math inline\">\\(t:=1/S\\)</span>, and removing the quadratic term with <span class=\"math display\">\\[x:=\\frac{t-\\tfrac13(2+3C)}{16\\,C},\\qquad y:=\\frac{w}{16\\,C\\,S^2},\\]</span> the curve becomes <span class=\"math inline\">\\(y^2=4x^3-g_2x-g_3\\)</span> with <span class=\"math display\">\\[g_2:=\\frac{9C^2-9C+1}{192\\,C^2},\\qquad g_3:=\\frac{(3C-1)(18C^2-21C+2)}{27648\\,C^3},\\qquad g_2^3-27g_3^2=\\frac{(C-1)(9C-1)}{1048576\\,C^4},\\]</span> which are rational in <span class=\"math inline\">\\(C\\)</span>, hence in <span class=\"math inline\">\\(D^2\\)</span> and <span class=\"math inline\">\\(s^2\\)</span>. The root <span class=\"math inline\">\\(S=1\\)</span> becomes <span class=\"math inline\">\\(x=e_r:=(1-3C)/(48C)\\)</span>, and the point <span class=\"math inline\">\\(S=\\infty\\)</span> becomes <span class=\"math inline\">\\(x=x_0:=-(2+3C)/(48C)\\)</span>. Let <span class=\"math inline\">\\(\\wp\\)</span> be the Weierstrass function of <span class=\"math inline\">\\((g_2,g_3)\\)</span>, with period lattice generated by <span class=\"math inline\">\\(2\\omega\\)</span> and <span class=\"math inline\">\\(2\\omega&#39;\\)</span>, and let <span class=\"math inline\">\\(\\zeta\\)</span> be defined by <span class=\"math inline\">\\(\\zeta&#39;=-\\wp\\)</span> and <span class=\"math inline\">\\(\\zeta(z)-1/z\\to0\\)</span> as <span class=\"math inline\">\\(z\\to0\\)</span>, so that <span class=\"math inline\">\\(\\zeta(z+2\\omega)=\\zeta(z)+2\\eta\\)</span>. Parametrising <span class=\"math inline\">\\(x=\\wp(u)\\)</span>, <span class=\"math inline\">\\(y=-\\wp&#39;(u)\\)</span>, one has <span class=\"math inline\">\\(\\dd S/w=\\dd u\\)</span>, and <span class=\"math inline\">\\(S\\in[0,1]\\)</span> corresponds to <span class=\"math inline\">\\(u\\in[0,\\omega]\\)</span>, where <span class=\"math display\">\\[\\begin{gathered}\\omega:=\\int_{e_r}^{\\infty}\\frac{\\dd x}{\\sqrt{4x^3-g_2x-g_3}},\\qquad \\eta:=\\zeta(\\omega),\\\\ b:=\\int_{-\\infty}^{x_0}\\frac{\\dd x}{\\sqrt{g_3+g_2x-4x^3}},\\qquad a:=-ib,\\end{gathered}\\]</span> so that <span class=\"math inline\">\\(\\omega\\)</span> is the real <em>half</em>-period (<span class=\"math inline\">\\(\\wp(\\omega)=e_r\\)</span> and <span class=\"math inline\">\\(\\wp&#39;(\\omega)=0\\)</span>), and <span class=\"math inline\">\\(\\wp(a)=x_0\\)</span>, <span class=\"math inline\">\\(\\wp&#39;(a)=i/(16C)\\)</span>. The lattice is rectangular iff <span class=\"math inline\">\\(g_2^3-27g_3^2&gt;0\\)</span>, i.e. iff <span class=\"math inline\">\\(C&lt;1/9\\)</span> (equivalently <span class=\"math inline\">\\(s&gt;2\\sqrt2\\,D\\)</span>), in which case <span class=\"math inline\">\\(\\omega&#39;\\)</span> is purely imaginary. It is rhombic (non-rectangular) for <span class=\"math inline\">\\(1/9&lt;C&lt;1\\)</span>, and degenerate for <span class=\"math inline\">\\(C=1/9\\)</span>. In terms of <span class=\"math inline\">\\(u\\)</span>, with <span class=\"math inline\">\\(t=16C(\\wp(u)-x_0)\\)</span>, <span class=\"math display\">\\[\\frac{N\\,\\dd S}{w}=\\Bigl(\\varpi-\\frac{\\sigma}{t}+\\frac1{t^2}\\Bigr)\\dd u,\\]</span> and the classical identity <span class=\"math inline\">\\(\\wp&#39;(a)/(\\wp(u)-\\wp(a))=\\zeta(u-a)-\\zeta(u+a)+2\\zeta(a)\\)</span> gives <span class=\"math display\">\\[\\int_0^\\omega\\frac{\\dd u}{\\wp(u)-\\wp(a)}=\\frac{2\\bigl(\\omega\\,\\zeta(a)-\\eta\\,a\\bigr)-i\\pi}{\\wp&#39;(a)},\\]</span> where the constant <span class=\"math inline\">\\(-i\\pi\\)</span> is the branch fixed by the behaviour for <span class=\"math inline\">\\(b\\to0^+\\)</span>, and the integral with a squared denominator is obtained by differentiating with respect to <span class=\"math inline\">\\(a\\)</span>, using <span class=\"math inline\">\\(\\wp&#39;(a)^2=-1/(256C^2)\\)</span> and <span class=\"math inline\">\\(\\wp&#39;&#39;(a)=(1+7C)/(128C^2)\\)</span>. Collecting the three kinds of terms, only <span class=\"math inline\">\\(\\omega\\)</span>, <span class=\"math inline\">\\(\\eta\\)</span> and <span class=\"math inline\">\\(\\zeta(a)\\)</span> remain: <span class=\"math display\">\\[\\widetilde L_{81}=4\\alpha\\,I(C),\\qquad I(C):=\\frac{(4-3C)\\,\\omega}{24\\,C}+2\\eta+\\frac{1-C}{8\\,C}\\Bigl[\\pi+2i\\bigl(\\omega\\,\\zeta(a)-\\eta\\,a\\bigr)\\Bigr],\\]</span> which is real since <span class=\"math inline\">\\(a\\in i\\mathbf{R}\\)</span>. The third-kind term has coefficient <span class=\"math inline\">\\((1-C)/(8C)\\)</span>, which vanishes only at <span class=\"math inline\">\\(C=1\\)</span>, and the limit <span class=\"math inline\">\\(C\\to1\\)</span> (<span class=\"math inline\">\\(\\theta_0\\to0\\)</span> or <span class=\"math inline\">\\(\\Delta\\phi\\to0\\)</span>) gives <span class=\"math inline\">\\(I\\to1\\)</span>, i.e. <span class=\"math inline\">\\(\\widetilde L_{81}\\to4\\alpha=8\\Delta\\theta\\)</span>. For small <span class=\"math inline\">\\(D\\)</span> (i.e. <span class=\"math inline\">\\(C\\)</span>, that is <span class=\"math inline\">\\(\\Delta\\theta\\)</span>, small) the four terms of <span class=\"math inline\">\\(I(C)\\)</span> are individually of order <span class=\"math inline\">\\(1/C\\)</span> and cancel down to <span class=\"math display\">\\[I(C)=\\frac1{\\sqrt C}\\Bigl[1+\\frac C4\\Bigl(\\ln\\frac{16}{C}-\\frac{11}{3}\\Bigr)+O(C^2\\ln C)\\Bigr],\\]</span> equivalently <span class=\"math inline\">\\(\\widetilde L_{81}=4\\rho\\bigl[1+\\tfrac C4(\\ln\\tfrac{16}{C}-\\tfrac{11}3)+\\dots\\bigr]\\)</span> with <span class=\"math inline\">\\(\\rho:=\\sqrt{\\alpha^2+\\beta^2}=\\Delta\\phi\\sqrt{D^2+s^2}\\)</span>, and in terms of the original parameters <span class=\"math display\">\\[\\widetilde L_{81}\\simeq\\Delta\\phi\\Bigl\\{4s+\\frac{2D^2}{s}\\Bigl[\\ln\\frac{4s}{D}-\\frac56\\Bigr]\\Bigr\\}.\\]</span> Since <span class=\"math inline\">\\(\\widetilde L_{81}-4\\Delta\\phi\\,s\\)</span> is of order <span class=\"math inline\">\\(\\Delta\\theta^2\\ln\\Delta\\theta\\)</span>, which dominates the <span class=\"math inline\">\\(\\Delta\\theta^2\\)</span> term of the Taylor formula above, one obtains by adding the two the expansion of <span class=\"math inline\">\\(L_{81}\\)</span> itself up to order <span class=\"math inline\">\\(\\Delta\\theta^2\\)</span> on a logarithmic scale, <span class=\"math display\">\\[L_{81}=4\\Delta\\phi\\sin\\theta_0+\\frac{8\\,\\Delta\\theta^2}{\\Delta\\phi\\sin\\theta_0}\\Bigl[\\ln\\frac{2\\Delta\\phi\\sin\\theta_0}{\\Delta\\theta}-\\frac56-\\frac2{15}\\Delta\\phi^2\\sin^2\\theta_0\\Bigr]+o(\\Delta\\theta^2),\\]</span> in which <span class=\"math inline\">\\(\\widetilde L_{81}\\)</span> already accounts for the logarithmic term and the constant <span class=\"math inline\">\\(-5/6\\)</span>, and the correction <span class=\"math inline\">\\(E&#39;&#39;(0)\\)</span> only shifts the constant. For the values <span class=\"math inline\">\\(\\Delta\\theta=6\\pi/180\\)</span>, <span class=\"math inline\">\\(\\Delta\\phi=50\\pi/180\\)</span> and <span class=\"math inline\">\\(\\theta_0=65\\pi/180\\)</span> one has <span class=\"math inline\">\\(D=0.24\\)</span>, <span class=\"math inline\">\\(s\\simeq0.90631\\)</span>, <span class=\"math inline\">\\(\\alpha\\simeq0.20944\\)</span> and <span class=\"math inline\">\\(C\\simeq0.065529&lt;1/9\\)</span>, so the lattice is rectangular, with <span class=\"math inline\">\\(g_2\\simeq0.54445\\)</span>, <span class=\"math inline\">\\(g_3\\simeq-0.072409\\)</span>, <span class=\"math inline\">\\(e_r\\simeq0.25542\\)</span>, <span class=\"math inline\">\\(\\omega\\simeq2.98311\\)</span>, <span class=\"math inline\">\\(\\omega&#39;\\simeq1.97382\\,i\\)</span>, <span class=\"math inline\">\\(\\eta\\simeq0.16719\\)</span>, <span class=\"math inline\">\\(a\\simeq-1.24106\\,i\\)</span> and <span class=\"math inline\">\\(I(C)\\simeq4.04218\\)</span>. Hence <span class=\"math inline\">\\(\\widetilde L_{81}=4\\alpha I(C)\\simeq3.38637\\)</span>, while numerical quadrature of the original integral gives <span class=\"math inline\">\\(L_{81}\\simeq3.37739\\)</span> (a relative difference of about <span class=\"math inline\">\\(-2.7\\cdot10^{-3}\\)</span>), and the small-<span class=\"math inline\">\\(D\\)</span> expansion gives <span class=\"math inline\">\\(I\\simeq4.0236\\)</span> and <span class=\"math inline\">\\(\\widetilde L_{81}\\simeq3.3708\\)</span>. The Taylor correction is <span class=\"math inline\">\\(-\\tfrac{16}{15}\\Delta\\phi\\,s\\,\\Delta\\theta^2\\simeq-0.00925\\)</span>, so that <span class=\"math inline\">\\(\\widetilde L_{81}-\\tfrac{16}{15}\\Delta\\phi\\,s\\,\\Delta\\theta^2\\simeq3.37711\\)</span> matches <span class=\"math inline\">\\(L_{81}\\)</span> to <span class=\"math inline\">\\(8\\cdot10^{-5}\\)</span> in relative value.</p>"},{"title":"2 Estimation of power take-off","page":"2 Estimation of power take-off","location":"section-2.html#sec:1D-PTO","category":"section","text":"<p>A simple 1D dynamic model is derived in order to estimate the <span data-acronym-label=\"pto\" data-acronym-form=\"singular+short\">pto</span> by the KEEP device, that is the mechanical power extracted from the rotation of the arm by the generator, modelled as a viscous torque <span class=\"math inline\">\\(-b\\dot\\alpha\\)</span> (average of <span class=\"math inline\">\\(b\\dot\\alpha^2\\)</span>). Significant assumptions are made. An <span class=\"math inline\">\\(\\omega\\)</span>-pulsation harmonic couple around <span class=\"math inline\">\\(\\vu z\\)</span>, caused by the tether attached to the end of the arm, is modelled by <span class=\"math inline\">\\(C_M\\,\\cos(\\omega\\,t)\\)</span>, where <span class=\"math inline\">\\(C_M=F_s\\,a \\sin \\theta_0\\)</span> and <span class=\"math inline\">\\(F_s\\)</span> is a constant tension in the line. Thus, the variation of the aerodynamics forces along the kite’s figure-of-eight trajectory is averaged and projected onto the horizontal plane (<span class=\"math inline\">\\(z=0\\)</span>). The Newton’s second law for the arm <a href=\"section-1.html#eq:newton_arm\">(27)</a> yields <a id=\"eq:newton_arm_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{37}\n    I \\ddot\\alpha = C_M\\,\\cos(\\omega\\,t) -b \\dot\\alpha.\n\\end{equation}</span> The following non dimensional parameters <span class=\"math inline\">\\(\\overline{b}=b/(I\\,\\omega)\\)</span>, <span class=\"math inline\">\\(\\overline{C_M}=C_M/(I\\,\\omega^2)\\)</span> and <span class=\"math inline\">\\(\\tau=\\omega\\,t\\)</span> are defined. The derivative of <span class=\"math inline\">\\(\\alpha\\)</span> with respect to <span class=\"math inline\">\\(\\tau\\)</span> is denoted by <span class=\"math inline\">\\(\\alpha&#39;\\)</span>, such that <span class=\"math inline\">\\(\\alpha&#39;=\\dot{\\alpha}/\\omega\\)</span>. The Newton’s second law for the arm <a href=\"#eq:newton_arm_PTO\">(37)</a> simplifies as follows <a id=\"eq:newton_arm_PTO_adim\"></a><span class=\"math display\">\\begin{equation}\n \\tag{38}\n    \\alpha''+\\overline{b}\\, \\alpha' = \\overline{C_M}\\,\\cos(\\tau).\n\\end{equation}</span> The steady-state harmonic solution of <a href=\"#eq:newton_arm_PTO_adim\">(38)</a> is <a id=\"eq:sol_alpha_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{39}\n    \\alpha = -\\frac{\\overline{C_M}}{B}\\,\\cos(\\tau+\\delta),\n\\end{equation}</span> where <span class=\"math inline\">\\(B=(1+\\overline{b}^2)^{1/2}\\)</span> and <span class=\"math inline\">\\(\\delta=\\arctan \\overline{b}\\)</span>. This last relationship shows that the phase difference between the angular position of the arm and that of the kite is closely linked to the rotor resistance <span class=\"math inline\">\\(b\\)</span>. The mechanical power produced by the device is expressed as <a id=\"eq:inst_power_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{40}\n    \\dot{W} = b \\, \\dot \\alpha^2=I\\,\\omega^3\\,\\overline{b}\\,\\alpha'^2.\n\\end{equation}</span> Consequently, the average power produced over a steady-state operating cycle of the KEEP system is given by <a id=\"eq:power_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{41}\n    W_a =  \\frac{1}{2\\pi}\\,\\int \\limits_{\\tau=0}^{\\tau=2\\pi} \\dot{W} \\dd{\\tau}=\\frac{\\overline{b}}{2\\,\\left(1+\\overline{b}^2\\right)}\\, \\frac{{C_M}^2}{I\\,\\omega}.\n\\end{equation}</span> A maximum tension condition is imposed on the cable whilst seeking to preserve the structural integrity of the kite (maximum stress, local buckling of the inflatable tubes, etc.) <span class=\"citation\" data-cites=\"Desenclos2023MCM\">(<a href=\"references.html#ref-Desenclos2023MCM\">Desenclos et al. 2023</a>)</span>. Denoting <span class=\"math inline\">\\(F_s\\)</span> the maximum tension, it is generally expressed as <span class=\"math inline\">\\(F_s=T_s\\, S\\)</span>, where <span class=\"math inline\">\\(T_s\\)</span> is a maximum wing loading independent of the kite’s surface area <span class=\"math inline\">\\(S\\)</span>. Thus, the amplitude of the harmonic couple <span class=\"math inline\">\\(C_M\\)</span> can be expressed as follows: <a id=\"eq:C_M_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{42}\n    C_M=T_s\\, S\\,a \\sin(\\theta_0).\n\\end{equation}</span> Furthermore, the pulsation <span class=\"math inline\">\\(\\omega\\)</span> introduced in the simple formulation <a href=\"#eq:newton_arm_PTO\">(37)</a> can be determined using a zero-mass model of the kite <span class=\"citation\" data-cites=\"Leloup2014OE\">(<a href=\"references.html#ref-Leloup2014OE\">Leloup et al. 2014</a>)</span>. We consider line length <span class=\"math inline\">\\(\\ell\\)</span> that are much greater than the arm length <span class=\"math inline\">\\(a\\)</span>, so that <span class=\"math inline\">\\(r=\\ell\\)</span> is a reasonable assumption. Futhermore, assuming a constant kite speed <span class=\"math inline\">\\(V_k=\\lVert \\dot{\\boldsymbol{r}} \\rVert\\)</span> along its figure-of-eight trajectory, equal to the value at the center <span class=\"math inline\">\\((x,y,z)=(\\ell\\,\\sin(\\theta_0),0,\\ell\\,\\cos(\\theta_0))\\)</span>, it can be shown that <a id=\"eq:Vk_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{43}\n    V_k=w_\\ell\\,\\left(\\frac{\\ell\\,\\cos(\\theta_0)}{z_r}\\right)^{1/7}\\,\\sqrt{\\left(1+G^2\\right)\\,{\\sin(\\theta_0)}^2-1},\n\\end{equation}</span> where <span class=\"math inline\">\\(G=C_L/C_D\\)</span> is the glide ratio of the kite. According to <a href=\"section-1.html#eq:sphere_Model_Deriv\">(3)</a> and <a href=\"section-1.html#eq:traject_Model_Deriv\">(4)</a>, the total length of the figure-of-eight trajectory <span class=\"math inline\">\\(L_{81}\\)</span> on the unit sphere (<span class=\"math inline\">\\(\\ell=1\\)</span>) is given by <a id=\"eq:L81_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{44}\n    L_{81}=\\int \\limits_{\\tau=0}^{\\tau=2\\pi} \\sqrt{\\left[2 \\, \\Delta\\theta\\, \\cos(2\\,\\tau)\\right]^2+{\\sin(\\theta_0 + \\Delta\\theta \\sin(2\\tau))}^2\\,\\left[\\Delta\\phi\\, \\cos(\\tau)\\right]^2} \\dd{\\tau},\n\\end{equation}</span> hence the following expression of the pulsation <a id=\"eq:Omega_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{45}\n    \\omega=\\frac{2\\,\\pi\\,V_k}{\\ell\\,L_{81}}.\n\\end{equation}</span> As detailed in appendix <a href=\"appendix-C.html#app8\">C</a>, one has the following estimate: <a id=\"eq:L81_PTO_approx\"></a><span class=\"math display\">\\begin{equation}\n \\tag{46}\nL_{81}=4\\Delta\\phi\\sin\\theta_0+\\frac{8\\,\\Delta\\theta^2}{\\Delta\\phi\\sin\\theta_0}\\Bigl[\\ln\\frac{2\\Delta\\phi\\sin\\theta_0}{\\Delta\\theta}-\\frac56-\\frac2{15}\\Delta\\phi^2\\sin^2\\theta_0\\Bigr]+o(\\Delta\\theta^2).\n\\end{equation}</span> Assuming that the values of the aerodynamics parameters <span class=\"math inline\">\\(G\\)</span>, <span class=\"math inline\">\\(w_r\\)</span> and <span class=\"math inline\">\\(z_r\\)</span>, of the geometry parameters <span class=\"math inline\">\\(a\\)</span>, <span class=\"math inline\">\\(\\ell\\)</span>, <span class=\"math inline\">\\(\\theta_0\\)</span>, <span class=\"math inline\">\\(\\Delta \\theta\\)</span> and <span class=\"math inline\">\\(\\Delta \\phi\\)</span>, as well as those of the kite properties <span class=\"math inline\">\\(S\\)</span> and <span class=\"math inline\">\\(T_s\\)</span>, have been selected, the independent parameters <span class=\"math inline\">\\(b\\)</span> and <span class=\"math inline\">\\(I\\)</span> can be optimized. At fixed inertia <span class=\"math inline\">\\(I\\)</span>, the last term of the relationship <a href=\"#eq:power_PTO\">(41)</a> reaches its maximum value for <span class=\"math inline\">\\(\\overline{b}=1\\)</span>, that is <a id=\"pto_optimality_constraint\"></a><span class=\"math display\">\\begin{equation}\n \\tag{47}\n    b=I\\,\\omega,\n\\end{equation}</span> which gives the average power <span class=\"math inline\">\\(W_a = C_M^2/(4I\\omega)\\)</span>. For operating reasons, the magnitude of the angle <span class=\"math inline\">\\(\\alpha\\)</span> is limited to <span class=\"math inline\">\\(\\pi/2\\)</span>. By <a href=\"#eq:sol_alpha_PTO\">(39)</a>, the amplitude is <span class=\"math inline\">\\(\\overline{C_M}/B = C_M/(\\omega\\sqrt{I^2\\omega^2+b^2})\\)</span>, hence the condition <a id=\"eq:opti_I_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{48}\n    \\omega^2\\qty(I^2\\omega^2 + b^2) \\geqslant \\qty(\\frac{2\\,C_M}{\\pi})^2,\n\\end{equation}</span> which depends on both parameters. With <span class=\"math inline\">\\(Z = I^2\\omega^2+b^2\\)</span>, the power <a href=\"#eq:power_PTO\">(41)</a> reads <span class=\"math inline\">\\(W_a = b\\,C_M^2/(2Z)\\)</span>. At fixed <span class=\"math inline\">\\(Z\\)</span>, it increases with <span class=\"math inline\">\\(b\\)</span>, that is as <span class=\"math inline\">\\(I\\)</span> decreases, and at fixed <span class=\"math inline\">\\(b\\)</span> it decreases with <span class=\"math inline\">\\(Z\\)</span>: in this model, the inertia of the arm only costs power, and the supremum <span class=\"math inline\">\\(\\pi C_M\\omega/4\\)</span> is approached as <span class=\"math inline\">\\(I\\to0\\)</span>, with <a href=\"#eq:opti_I_PTO\">(48)</a> active. The inertia is bounded below by the structure of the arm, <span class=\"math inline\">\\(I\\geq I_{\\min}\\)</span>, with <span class=\"math inline\">\\(I_{\\min} = 62\\,\\mathrm{kg}\\,\\mathrm{m}^{2}\\)</span> the lower bound of Table <a href=\"section-4.html#tab:opt_descr\">3</a> (a tube that withstands the maximum tension of the lines). As long as <span class=\"math inline\">\\(I_{\\min} &lt; \\sqrt2\\,C_M/(\\pi\\omega^2)\\)</span>, which holds here, the condition <a href=\"#eq:opti_I_PTO\">(48)</a> is active at the optimum, and the parameters <span class=\"math inline\">\\(b\\)</span> and <span class=\"math inline\">\\(I\\)</span> are optimal when <a id=\"eq:opti_b_I_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{49}\n    I = I_{\\min}, \\qquad b = \\frac{2\\,C_M}{\\pi\\,\\omega}\\sqrt{1-\\varepsilon^2}, \\qquad \\varepsilon = \\frac{\\pi\\,\\omega^2 I_{\\min}}{2\\,C_M},\n\\end{equation}</span> where <span class=\"math inline\">\\(C_M\\)</span> and <span class=\"math inline\">\\(\\omega\\)</span> are given by <a href=\"#eq:C_M_PTO\">(42)</a> and <a href=\"#eq:Omega_PTO\">(45)</a> respectively, which leads to the following average power: <a id=\"eq:opti_power_PTO_final\"></a><span class=\"math display\">\\begin{equation}\n \\tag{50}\n    W_a =\\frac{\\pi\\,C_M\\,\\omega}{4}\\sqrt{1-\\varepsilon^2}.\n\\end{equation}</span> The design <span class=\"math inline\">\\(b = I\\omega\\)</span> with the smallest admissible <span class=\"math inline\">\\(I\\)</span>, <span class=\"math inline\">\\(I = \\sqrt2\\,C_M/(\\pi\\omega^2) = 646\\,\\mathrm{kg}\\,\\mathrm{m}^{2}\\)</span>, satisfies the constraint but gives only <span class=\"math inline\">\\(\\pi C_M\\omega/(4\\sqrt2)\\)</span>: the condition <a href=\"#pto_optimality_constraint\">(47)</a> is optimal at fixed <span class=\"math inline\">\\(I\\)</span>, not jointly, and the optimum <a href=\"#eq:opti_b_I_PTO\">(49)</a> gives <span class=\"math inline\">\\(41\\,\\%\\)</span> more power. Thus, the power take-off per unit area of kite <span class=\"math inline\">\\(pto\\)</span> by the KEEP device can be estimated as follows: <a id=\"eq:pto_PTO\"></a><span class=\"math display\">\\begin{equation}\n \\tag{51}\n    pto=\\frac{W_a}{S}=\\left(\\frac{\\pi^2\\,\\sin(\\theta_0)\\,\\sqrt{\\left(1+G^2\\right)\\,{\\sin(\\theta_0)}^2-1}}{2\\,L_{81}}\\right)\\,\\left(\\frac{T_s\\,a\\,w_r}{\\ell}\\right)\\,\\left(\\frac{\\ell\\,\\cos(\\theta_0)}{z_r}\\right)^{1/7}\\sqrt{1-\\varepsilon^2}.\n\\end{equation}</span> The maximum power take-off varies almost linearly with the glide ratio of the kite. The linear dependence of <span class=\"math inline\">\\(pto\\)</span> on wind speed <span class=\"math inline\">\\(w_r\\)</span> is due to the structural constraint <span class=\"math inline\">\\(T_s\\)</span>. Without this constraint, the dependence of <span class=\"math inline\">\\(pto\\)</span> on wind speed <span class=\"math inline\">\\(w_r\\)</span> is normally of the third order, since the aerodynamic pressures – and therefore the wing loading – are of the second order. The <span class=\"math inline\">\\(pto\\)</span> appears to increase linearly as the arm length <span class=\"math inline\">\\(a\\)</span> increases. The shorter the length of the line <span class=\"math inline\">\\(\\ell\\)</span>, the higher <span class=\"math inline\">\\(pto\\)</span> is, even if the wind speed at the height of the kite decreases. However, the inertia of the kite is not taken into account in this estimate of the power take-off. Taking it into account could alter the value of the pulsation <span class=\"math inline\">\\(\\omega\\)</span> and, consequently, lead to an optimal value for the length of the line. Taking the nominal parameters of Table <a href=\"#tab:params\">1</a> with <span class=\"math inline\">\\(T_s = 1000\\,\\mathrm{N}\\,\\mathrm{m}^{-2}\\)</span>, <span class=\"math inline\">\\(\\varepsilon = 0.068\\)</span>, and the KEEP device achieves a maximum power take-off of about <span class=\"math inline\">\\(5.0\\,\\mathrm{kW}\\,\\mathrm{m}^{-2}\\)</span> (5.1 kW m<sup>−2</sup> as <span class=\"math inline\">\\(I_{\\min}\\to0\\)</span>), regardless of whether expression <a href=\"#eq:L81_PTO\">(44)</a> or <a href=\"#eq:L81_PTO_approx\">(46)</a> is used for <span class=\"math inline\">\\(L_{81}\\)</span>. This estimate assumes a glide ratio <span class=\"math inline\">\\(G = 7\\)</span> (Table <a href=\"#tab:params\">1</a>); with <span class=\"math inline\">\\(G = 5\\)</span>, a value more typical of soft kites, it drops to <span class=\"math inline\">\\(3.6\\,\\mathrm{kW}\\,\\mathrm{m}^{-2}\\)</span>.</p>\n<table id=\"tab:params\">\n<caption><strong>Table 1:</strong> Parameter Description and Values</caption>\n<thead>\n<tr>\n<th style=\"text-align: left;\"><span>Symbol</span></th>\n<th style=\"text-align: left;\"><span>Description</span></th>\n<th style=\"text-align: right;\"><span>Value</span></th>\n<th style=\"text-align: left;\"><span>Unit</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(a\\)</span></td>\n<td style=\"text-align: left;\">Arm length</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(2\\)</span></td>\n<td style=\"text-align: left;\">m</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(b\\)</span></td>\n<td style=\"text-align: left;\">Arm braking coefficient</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(50.41\\)</span></td>\n<td style=\"text-align: left;\">N m s °<sup>−1</sup></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(C_D\\)</span></td>\n<td style=\"text-align: left;\">Kite drag coefficient</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(C_L / 7\\)</span></td>\n<td style=\"text-align: left;\"></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(C_{D,\\ell}\\)</span></td>\n<td style=\"text-align: left;\">Line drag coefficient</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(0\\)</span></td>\n<td style=\"text-align: left;\"></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(C_L\\)</span></td>\n<td style=\"text-align: left;\">Kite lift coefficient</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(0.6\\)</span></td>\n<td style=\"text-align: left;\"></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(d_\\ell\\)</span></td>\n<td style=\"text-align: left;\">Line diameter</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(0.003\\)</span></td>\n<td style=\"text-align: left;\">m</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(g\\)</span></td>\n<td style=\"text-align: left;\">Gravity</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(9.81\\)</span></td>\n<td style=\"text-align: left;\">m s<sup>−2</sup></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(I\\)</span></td>\n<td style=\"text-align: left;\">Arm inertia</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(1300\\)</span></td>\n<td style=\"text-align: left;\">kg m<sup>2</sup></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\ell\\)</span></td>\n<td style=\"text-align: left;\">Line length</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(31\\)</span></td>\n<td style=\"text-align: left;\">m</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(m\\)</span></td>\n<td style=\"text-align: left;\">Kite mass</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(6\\)</span></td>\n<td style=\"text-align: left;\">kg</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(S\\)</span></td>\n<td style=\"text-align: left;\">Kite surface</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(10\\)</span></td>\n<td style=\"text-align: left;\">m<sup>2</sup></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(w_0\\)</span></td>\n<td style=\"text-align: left;\">Wind reference speed</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(9\\)</span></td>\n<td style=\"text-align: left;\">m s<sup>−1</sup></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(z_0\\)</span></td>\n<td style=\"text-align: left;\">Wind reference altitude</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(10\\)</span></td>\n<td style=\"text-align: left;\">m</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\Delta\\theta\\)</span></td>\n<td style=\"text-align: left;\">Lemniscate polar half-height</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(6\\)</span></td>\n<td style=\"text-align: left;\">°</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\Delta\\phi\\)</span></td>\n<td style=\"text-align: left;\">Lemniscate azimuthal half-width</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(50\\)</span></td>\n<td style=\"text-align: left;\">°</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\theta_0\\)</span></td>\n<td style=\"text-align: left;\">Lemniscate mean polar angle</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(65\\)</span></td>\n<td style=\"text-align: left;\">°</td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\rho_a\\)</span></td>\n<td style=\"text-align: left;\">Air density</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(1.225\\)</span></td>\n<td style=\"text-align: left;\">kg m<sup>−3</sup></td>\n</tr>\n<tr>\n<td style=\"text-align: left;\"><span class=\"math inline\">\\(\\rho_\\ell\\)</span></td>\n<td style=\"text-align: left;\">Line density</td>\n<td style=\"text-align: right;\"><span class=\"math inline\">\\(707\\)</span></td>\n<td style=\"text-align: left;\">kg m<sup>−3</sup></td>\n</tr>\n</tbody>\n</table>\n\n<details class=\"web-code\"><summary>Code that produced this table</summary>\n\nsrc/analysis.jl (region setup_analysis), see also the full file.\n\n    ## Determine optimal parameters using kinetic model\n    p0 = PMP.build_para()\n    p0.b = PMP.optimal_torque_slope(p0; sense=(+), tol=1e-9, rtol=1e-9, maxiter=50)  # errors if not converged\n    vbp = PMP.build_vbpara(p0)\n\nsrc/analysis.jl (region param_table), see also the full file.\n\nfunction param_table(p)\n    # symbol, description, unit, optional value override\n    params = [\n        Parameter(:a, \"a\", \"Arm length\", raw\"\\meter\", nothing),\n        Parameter(:l, raw\"\\ell\", \"Line length\", raw\"\\meter\", nothing),\n        Parameter(:m, \"m\", \"Kite mass\", raw\"\\kg\", nothing),\n        Parameter(:I, \"I\", \"Arm inertia\", raw\"\\kg\\square\\meter\", nothing),\n        Parameter(:ρ_a, raw\"\\rho_a\", \"Air density\", raw\"\\kg\\per\\cubic\\meter\", nothing),\n        Parameter(:d_l, raw\"d_\\ell\", \"Line diameter\", raw\"\\meter\", nothing),\n        Parameter(:S, \"S\", \"Kite surface\", raw\"\\square\\meter\", nothing),\n        Parameter(:C_L, \"C_L\", \"Kite lift coefficient\", \"\", nothing),\n        Parameter(:C_D, \"C_D\", \"Kite drag coefficient\", \"\", \"C_L / 7\"),\n        Parameter(:C_D_l, raw\"C_{D,\\ell}\", \"Line drag coefficient\", \"\", nothing),\n        Parameter(:ρ_l, raw\"\\rho_\\ell\", \"Line density\", raw\"\\kg\\per\\cubic\\meter\", nothing),\n        Parameter(:g, \"g\", \"Gravity\", raw\"\\meter\\per\\square\\second\", nothing),\n        Parameter(:z0, \"z_0\", \"Wind reference altitude\", raw\"\\meter\", nothing),\n        Parameter(:w0, \"w_0\", \"Wind reference speed\", raw\"\\meter\\per\\second\", nothing),\n        Parameter(:b, \"b\", \"Arm braking coefficient\",\n            raw\"\\newton\\meter\\second\\per\\degree\", f\"{p.b / rad2deg(1):.4g}\"),  # 4 digits: fixed point b = I ω\n        Parameter(:θ0, raw\"\\theta_0\", \"Lemniscate mean polar angle\",\n            raw\"\\degree\", f\"{rad2deg(p.θ0):.0f}\"),\n        Parameter(:Δθ, raw\"\\Delta\\theta\", \"Lemniscate polar half-height\",\n            raw\"\\degree\", f\"{rad2deg(p.Δθ):.0f}\"),\n        Parameter(:Δφ, raw\"\\Delta\\phi\", \"Lemniscate azimuthal half-width\",\n            raw\"\\degree\", f\"{rad2deg(p.Δφ):.0f}\"),\n    ]\n\n    sort!(params, by=x -> eor_transform(x.sym))\n    table_rows = map(params) do p_item\n        val = isnothing(p_item.value_override) ? f\"{p[p_item.key]:.9g}\" : p_item.value_override\n        unit_col = isempty(p_item.unit) ? \"\" : raw\"\\si{\" * p_item.unit * \"}\"\n        f\"    ${p_item.sym}$ & {p_item.descr} & ${val}$ & {unit_col} \\\\\\\\ \"\n    end\n\n\n    table_str = raw\"\"\"\n\\begin{table}[thpb]\n\\centering\n\\caption{Parameter Description and Values}\n\\label{tab:params}\n\\begin{tabular}{l p{3.2cm} r l}\n    \\toprule\n    {Symbol} & {Description} & {Value} & {Unit} \\\\\n    \\midrule\n\"\"\" * join(table_rows, \"\\n\") * raw\"\"\"\n\n    \\bottomrule\n\\end{tabular}\n\\end{table}\"\"\"\n    return table_str\nend\n\nsrc/analysis.jl (region table1), see also the full file.\n\n    write_table(\"table1\", param_table(p0))\n\n</details>"},{"title":"References","page":"References","location":"references.html#references","category":"section","text":"<div id=\"refs\" class=\"references csl-bib-body hanging-indent\" role=\"list\">\n<div id=\"ref-amestoy2001mumps\" class=\"csl-entry\" role=\"listitem\">\nAmestoy, Patrick R., Iain S. Duff, Jean-Yves L’Excellent, and Jacko Koster. 2001. <span>“A Fully Asynchronous Multifrontal Solver Using Distributed Dynamic Scheduling.”</span> <em>SIAM Journal on Matrix Analysis and Applications</em> 23 (1): 15–41. <a href=\"https://doi.org/10.1137/S0895479899358194\">https://doi.org/10.1137/S0895479899358194</a>.\n</div>\n<div id=\"ref-Bavoil2024KEEP\" class=\"csl-entry\" role=\"listitem\">\nBavoil, Antonin. 2024. <em>Rapport Technique Du Projet <span>KEEP</span></em>. Technical report. Universit<span>é</span> C<span>ô</span>te d’Azur, CNRS, Inria, LJAD. <a href=\"https://hal.science/hal-04513387v2\">https://hal.science/hal-04513387v2</a>.\n</div>\n<div id=\"ref-Desenclos2023MCM\" class=\"csl-entry\" role=\"listitem\">\nDesenclos, K., A. Nême, J.-B. Leroux, and C. Jochum. 2023. <span>“A Novel Composite Modeling Method to Analyze the Woven Fabric Structures of Leading-Edge Inflatable Kites.”</span> <em>Mechanics of Composite Materials</em> 58 (6): 867–82. <a href=\"https://doi.org/10.1007/s11029-023-10075-0\">https://doi.org/10.1007/s11029-023-10075-0</a>.\n</div>\n<div id=\"ref-Leloup2014OE\" class=\"csl-entry\" role=\"listitem\">\nLeloup, R., K. Roncin, G. Bles, J.-B. Leroux, C. Jochum, and Y. Parlier. 2014. <span>“Kite and Classical Rig Sailing Performance Comparison on a One Design Keel Boat.”</span> <em>Ocean Engineering</em> 90: 39–48. <a href=\"https://doi.org/10.1016/j.oceaneng.2014.06.043\">https://doi.org/10.1016/j.oceaneng.2014.06.043</a>.\n</div>\n<div id=\"ref-migot2021adnlpmodels\" class=\"csl-entry\" role=\"listitem\">\nMigot, Tangi, Alexis Montoison, Dominique Orban, and Abel Soares Siqueira. 2021. <em><span class=\"nocase\">ADNLPModels.jl</span>: Automatic Differentiation Models Implementing the <span>NLPModels</span> <span>API</span></em>. Released. <a href=\"https://doi.org/10.5281/zenodo.4605982\">https://doi.org/10.5281/zenodo.4605982</a>.\n</div>\n<div id=\"ref-rackauckas2017differentialequations\" class=\"csl-entry\" role=\"listitem\">\nRackauckas, Christopher, and Qing Nie. 2017. <span>“<span class=\"nocase\">DifferentialEquations.jl</span> – a Performant and Feature-Rich Ecosystem for Solving Differential Equations in <span>Julia</span>.”</span> <em>Journal of Open Research Software</em> 5 (1): 15. <a href=\"https://doi.org/10.5334/jors.151\">https://doi.org/10.5334/jors.151</a>.\n</div>\n<div id=\"ref-RevelsLubinPapamarkou2016\" class=\"csl-entry\" role=\"listitem\">\nRevels, Jarrett, Miles Lubin, and Theodore Papamarkou. 2016. <span>“Forward-Mode Automatic Differentiation in <span>Julia</span>.”</span> <em>arXiv Preprint</em>. <a href=\"https://arxiv.org/abs/1607.07892\">https://arxiv.org/abs/1607.07892</a>.\n</div>\n<div id=\"ref-Verner2010\" class=\"csl-entry\" role=\"listitem\">\nVerner, J. H. 2010. <span>“Numerically Optimal <span>Runge–Kutta</span> Pairs with Interpolants.”</span> <em>Numerical Algorithms</em> 53: 383–96. <a href=\"https://doi.org/10.1007/s11075-009-9290-3\">https://doi.org/10.1007/s11075-009-9290-3</a>.\n</div>\n<div id=\"ref-vanderVlugt2019RE\" class=\"csl-entry\" role=\"listitem\">\nVlugt, Rolf van der, Anna Bley, Michael Noom, and Roland Schmehl. 2019. <span>“Quasi-Steady Model of a Pumping Kite Power System.”</span> <em>Renewable Energy</em> 131: 83–99. <a href=\"https://doi.org/10.1016/j.renene.2018.07.023\">https://doi.org/10.1016/j.renene.2018.07.023</a>.\n</div>\n<div id=\"ref-WachterBiegler2006\" class=\"csl-entry\" role=\"listitem\">\nWächter, Andreas, and Lorenz T. Biegler. 2006. <span>“On the Implementation of an Interior-Point Filter Line-Search Algorithm for Large-Scale Nonlinear Programming.”</span> <em>Mathematical Programming</em> 106 (1): 25–57. <a href=\"https://doi.org/10.1007/s10107-004-0559-y\">https://doi.org/10.1007/s10107-004-0559-y</a>.\n</div>\n</div>"},{"title":"main.jl","page":"main.jl","location":"code/main-jl.html#main.jl","category":"section","text":"View on GitHub (commit 2cfaacd).\n\n# Regenerates the figures (figs/*.pdf and *.png) and tables (tables/*.tex) of the paper.\n#\n#   julia --project=applications/jtcam-tex applications/jtcam-tex/main.jl [sections...] [--fast]\n#\n# sections: modelling, 10d, analysis, optimization (default: all of them).\n# --fast: reduced iteration limits and grids, to test the workflow quickly\n#         (the figures and tables are then NOT the ones of the paper).\nENV[\"GKSwstype\"] = get(ENV, \"GKSwstype\", \"100\")  # headless GR\n\nconst SECTIONS = [\"modelling\", \"10d\", \"analysis\", \"optimization\"]\n\nfunction main(args=ARGS)\n    fast = \"--fast\" in args\n    wanted = filter(a -> !startswith(a, \"--\"), args)\n    isempty(wanted) && (wanted = SECTIONS)\n    unknown = setdiff(wanted, SECTIONS)\n    isempty(unknown) || error(\"unknown section(s): $(join(unknown, \", \")); expected $(join(SECTIONS, \", \"))\")\n    # section name => (source file, entry function)\n    entry = Dict(\"modelling\" => (\"modelling.jl\", :run_modelling),\n        \"10d\" => (\"numerics_10d.jl\", :run_10d),\n        \"analysis\" => (\"analysis.jl\", :run_analysis),\n        \"optimization\" => (\"optimization.jl\", :run_optimization))\n    for name in SECTIONS\n        name in wanted || continue\n        @info \"=== section: $name (fast=$fast)\"\n        file, fname = entry[name]\n        t = @elapsed begin\n            include(joinpath(@__DIR__, \"src\", file))\n            run = Base.invokelatest(getglobal, Main, fname)  # defined after main() started\n            Base.invokelatest(run; fast)\n        end\n        @info \"=== done: $name in $(round(t; digits=1)) s\"\n    end\n    return nothing\nend\n\nmain()"}]
}
